import { randomUUID } from "node:crypto";

import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import { WORKER_STATE } from "../lifecycle/states.ts";
import {
  IPC_MESSAGE_TYPE,
  createCorrelationId,
  createMessageId,
  type IpcEnvelopeV1,
  type MessageId,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import type {
  TaskWorkerId,
  WorkerGeneration,
  WorkerId,
} from "../protocol/worker-id.ts";
import type {
  ProcessBus,
  ProcessBusPeerUnavailableHandler,
  ProcessBusSendOptions,
} from "../process/process-bus.ts";
import {
  WorkerRegistry,
  type WorkerRecordSnapshot,
} from "../process/worker-registry.ts";
import {
  decodeTaskFinishPayload,
  decodeWorkerTaskDispatchPayload,
  encodeScheduledTaskDispatchPayload,
  encodeTaskFinishPayload,
  type TaskFinishPayload,
  type TaskKey,
  type TaskSelection,
  type WorkerTaskDispatchPayload,
} from "./task-protocol.ts";
import { TaskScheduler } from "./task-scheduler.ts";

export const DEFAULT_MASTER_TASK_ROUTER_TOMBSTONE_LIMIT = 4_096;
export const DEFAULT_MASTER_TASK_ROUTER_MAX_PENDING_ASSIGNMENTS = 4_096;

export type MasterTaskRouterBus = Pick<
  ProcessBus,
  "localIdentity" | "enqueue" | "onMessage" | "onPeerUnavailable" | "drain"
>;

export interface MasterTaskRouterOptions {
  readonly bus: MasterTaskRouterBus;
  readonly registry: WorkerRegistry;
  readonly scheduler: TaskScheduler;
  readonly onDeliveryError?: (error: unknown) => void;
  readonly tombstoneLimit?: number;
  readonly maxPendingAssignments?: number;
}

export interface MasterTaskRouterStats {
  readonly closed: boolean;
  readonly accepted: number;
  readonly rejected: number;
  readonly pending: number;
  readonly maxPendingAssignments: number;
  readonly pendingAssignmentRejections: number;
  readonly finished: number;
  readonly abandoned: number;
  readonly stale: number;
  readonly duplicate: number;
  readonly deliveryErrors: number;
  readonly ignored: number;
}

interface TaskAssignment extends TaskKey, TaskSelection {
  readonly key: string;
  readonly sourceDispatchMessageId: MessageId;
  readonly assignmentMessageId: MessageId;
}

interface CompletionTombstone {
  readonly key: string;
  readonly assignmentMessageId: MessageId | null;
}

function assertNonNegativeSafeInteger(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function taskKey(task: TaskKey): string {
  return `${task.sourceWorkerId}:${task.sourceGeneration}:${task.taskId}`;
}

function canReceiveTaskCompletion(record: WorkerRecordSnapshot): boolean {
  return record.state === WORKER_STATE.READY ||
    record.state === WORKER_STATE.RUNNING ||
    record.state === WORKER_STATE.DRAINING;
}

function sameTask(left: TaskKey, right: TaskKey): boolean {
  return left.taskId === right.taskId &&
    left.sourceWorkerId === right.sourceWorkerId &&
    left.sourceGeneration === right.sourceGeneration;
}

function sameSelection(left: TaskSelection, right: TaskSelection): boolean {
  return left.selectedTaskWorkerId === right.selectedTaskWorkerId &&
    left.selectedWorkerId === right.selectedWorkerId &&
    left.selectedGeneration === right.selectedGeneration;
}

function hasSelection(payload: TaskFinishPayload): payload is TaskFinishPayload & TaskSelection {
  return payload.selectedTaskWorkerId !== null &&
    payload.selectedWorkerId !== null &&
    payload.selectedGeneration !== null;
}

function asTaskSelection(record: WorkerRecordSnapshot): TaskSelection {
  if (record.role !== PROCESS_ROLE.TASK_WORKER || record.taskWorkerId === null) {
    throw new FrameworkError(
      FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
      `Worker ${record.workerId} is not a Task Worker`,
      { workerId: record.workerId, role: record.role },
    );
  }
  return Object.freeze({
    selectedTaskWorkerId: record.taskWorkerId,
    selectedWorkerId: record.workerId,
    selectedGeneration: record.generation,
  });
}

export class MasterTaskRouter {
  readonly #bus: MasterTaskRouterBus;
  readonly #registry: WorkerRegistry;
  readonly #scheduler: TaskScheduler;
  readonly #onDeliveryError: ((error: unknown) => void) | undefined;
  readonly #tombstoneLimit: number;
  readonly #maxPendingAssignments: number;
  readonly #assignmentsByKey = new Map<string, TaskAssignment>();
  readonly #assignmentsByMessageId = new Map<MessageId, TaskAssignment>();
  readonly #completedTaskKeys = new Set<string>();
  readonly #completedAssignmentIds = new Set<MessageId>();
  readonly #tombstones: CompletionTombstone[] = [];
  #peerCleanupTail: Promise<void> = Promise.resolve();
  #completionRetryTail: Promise<void> = Promise.resolve();
  #disposeMessage: () => void;
  #disposePeerUnavailable: () => void;
  #closed = false;
  #accepted = 0;
  #rejected = 0;
  #pendingAssignmentRejections = 0;
  #finished = 0;
  #abandoned = 0;
  #stale = 0;
  #duplicate = 0;
  #deliveryErrors = 0;
  #ignored = 0;

  constructor(options: MasterTaskRouterOptions) {
    if (
      options.bus.localIdentity.role !== PROCESS_ROLE.MASTER ||
      options.bus.localIdentity.workerId !== null ||
      options.bus.localIdentity.generation !== null
    ) {
      throw new TypeError("MasterTaskRouter requires a Master ProcessBus");
    }
    if (!(options.registry instanceof WorkerRegistry)) {
      throw new TypeError("MasterTaskRouter requires a WorkerRegistry");
    }
    if (!(options.scheduler instanceof TaskScheduler)) {
      throw new TypeError("MasterTaskRouter requires a TaskScheduler");
    }
    const tombstoneLimit = options.tombstoneLimit ?? DEFAULT_MASTER_TASK_ROUTER_TOMBSTONE_LIMIT;
    assertNonNegativeSafeInteger("tombstoneLimit", tombstoneLimit);
    const maxPendingAssignments = options.maxPendingAssignments ??
      DEFAULT_MASTER_TASK_ROUTER_MAX_PENDING_ASSIGNMENTS;
    assertNonNegativeSafeInteger("maxPendingAssignments", maxPendingAssignments);

    this.#bus = options.bus;
    this.#registry = options.registry;
    this.#scheduler = options.scheduler;
    this.#onDeliveryError = options.onDeliveryError;
    this.#tombstoneLimit = tombstoneLimit;
    this.#maxPendingAssignments = maxPendingAssignments;
    this.#disposeMessage = this.#bus.onMessage(this.#handleEnvelope);
    this.#disposePeerUnavailable = this.#bus.onPeerUnavailable(this.#handlePeerUnavailable);
  }

  stats(): Readonly<MasterTaskRouterStats> {
    return Object.freeze({
      closed: this.#closed,
      accepted: this.#accepted,
      rejected: this.#rejected,
      pending: this.#assignmentsByKey.size,
      maxPendingAssignments: this.#maxPendingAssignments,
      pendingAssignmentRejections: this.#pendingAssignmentRejections,
      finished: this.#finished,
      abandoned: this.#abandoned,
      stale: this.#stale,
      duplicate: this.#duplicate,
      deliveryErrors: this.#deliveryErrors,
      ignored: this.#ignored,
    });
  }

  async drain(): Promise<void> {
    while (true) {
      const peerCleanup = this.#peerCleanupTail;
      const completionRetry = this.#completionRetryTail;
      await Promise.all([peerCleanup, completionRetry]);
      if (
        peerCleanup === this.#peerCleanupTail &&
        completionRetry === this.#completionRetryTail
      ) {
        return;
      }
    }
  }

  close(_reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#closed = true;
    this.#disposeMessage();
    this.#disposePeerUnavailable();
    this.#disposeMessage = () => {};
    this.#disposePeerUnavailable = () => {};
    this.#abandoned += this.#assignmentsByKey.size;
    this.#assignmentsByKey.clear();
    this.#assignmentsByMessageId.clear();
    this.#completedTaskKeys.clear();
    this.#completedAssignmentIds.clear();
    this.#tombstones.length = 0;
  }

  readonly #handleEnvelope = (envelope: Readonly<IpcEnvelopeV1>): void => {
    if (this.#closed) {
      return;
    }
    if (envelope.messageType === IPC_MESSAGE_TYPE.TASK_DISPATCH) {
      this.#handleDispatch(envelope);
      return;
    }
    if (envelope.messageType === IPC_MESSAGE_TYPE.TASK_FINISH) {
      this.#handleFinish(envelope);
      return;
    }
    this.#ignored += 1;
  };

  readonly #handlePeerUnavailable: ProcessBusPeerUnavailableHandler = (identity): void => {
    if (
      this.#closed ||
      identity.role === PROCESS_ROLE.MASTER ||
      identity.role === PROCESS_ROLE.USER_TASK_WORKER ||
      identity.workerId === null ||
      identity.generation === null
    ) {
      return;
    }
    const unavailableIdentity = Object.freeze({
      role: identity.role,
      workerId: identity.workerId,
      generation: identity.generation,
    });

    this.#peerCleanupTail = this.#peerCleanupTail.then(async () => {
      try {
        await this.#bus.drain();
      } catch (error) {
        this.#deliveryFailed(error);
      }
      if (this.#closed) {
        return;
      }
      this.#cleanupUnavailablePeer(unavailableIdentity);
    });
    void this.#peerCleanupTail.catch(() => undefined);
  };

  #cleanupUnavailablePeer(identity: Readonly<{
    readonly role: typeof PROCESS_ROLE.WORKER | typeof PROCESS_ROLE.TASK_WORKER;
    readonly workerId: WorkerId;
    readonly generation: WorkerGeneration;
  }>): void {
    for (const assignment of [...this.#assignmentsByKey.values()]) {
      if (
        identity.role === PROCESS_ROLE.WORKER &&
        assignment.sourceWorkerId === identity.workerId &&
        assignment.sourceGeneration === identity.generation
      ) {
        this.#removeAssignment(assignment);
        this.#rememberCompletion(assignment.key, assignment.assignmentMessageId);
        this.#abandoned += 1;
        continue;
      }
      if (
        identity.role === PROCESS_ROLE.TASK_WORKER &&
        assignment.selectedWorkerId === identity.workerId &&
        assignment.selectedGeneration === identity.generation
      ) {
        this.#removeAssignment(assignment);
        this.#rememberCompletion(assignment.key, assignment.assignmentMessageId);
        this.#abandoned += 1;
        this.#sendCompletion(
          assignment,
          assignment,
          false,
          assignment.sourceDispatchMessageId,
        );
      }
    }
  }

  #handleDispatch(envelope: Readonly<IpcEnvelopeV1>): void {
    let payload: Readonly<WorkerTaskDispatchPayload>;
    try {
      this.#assertDispatchEnvelope(envelope);
      payload = decodeWorkerTaskDispatchPayload(envelope.payload);
    } catch {
      this.#rejected += 1;
      return;
    }

    if (
      payload.sourceWorkerId !== envelope.sourceWorkerId ||
      payload.sourceGeneration !== envelope.sourceGeneration
    ) {
      this.#rejected += 1;
      return;
    }
    if (!this.#isCurrentSource(payload)) {
      this.#rejected += 1;
      this.#stale += 1;
      return;
    }

    const key = taskKey(payload);
    if (this.#assignmentsByKey.has(key) || this.#completedTaskKeys.has(key)) {
      this.#rejected += 1;
      this.#duplicate += 1;
      return;
    }
    if (this.#assignmentsByKey.size >= this.#maxPendingAssignments) {
      this.#rejected += 1;
      this.#pendingAssignmentRejections += 1;
      this.#abandoned += 1;
      this.#rememberCompletion(key, null);
      this.#sendCompletion(
        payload,
        null,
        false,
        envelope.messageId,
        undefined,
        false,
        false,
      );
      return;
    }

    let selected: Readonly<WorkerRecordSnapshot>;
    try {
      selected = this.#scheduler.select(payload.requestedTaskWorkerId ?? undefined);
    } catch {
      this.#rejected += 1;
      this.#abandoned += 1;
      this.#rememberCompletion(key, null);
      this.#sendCompletion(payload, null, false, envelope.messageId);
      return;
    }

    let selection: TaskSelection;
    let assignmentMessageId: MessageId;
    let scheduledPayload: Buffer;
    try {
      selection = asTaskSelection(selected);
      assignmentMessageId = createMessageId(`task-assignment:${randomUUID()}`);
      scheduledPayload = encodeScheduledTaskDispatchPayload({
        taskId: payload.taskId,
        sourceWorkerId: payload.sourceWorkerId,
        sourceGeneration: payload.sourceGeneration,
        requestedTaskWorkerId: payload.requestedTaskWorkerId,
        ...selection,
        data: payload.data,
      });
    } catch {
      this.#rejected += 1;
      this.#abandoned += 1;
      this.#rememberCompletion(key, null);
      this.#sendCompletion(payload, null, false, envelope.messageId);
      return;
    }

    const assignment: TaskAssignment = Object.freeze({
      key,
      taskId: payload.taskId,
      sourceWorkerId: payload.sourceWorkerId,
      sourceGeneration: payload.sourceGeneration,
      sourceDispatchMessageId: envelope.messageId,
      assignmentMessageId,
      ...selection,
    });
    let completion: Promise<void>;
    try {
      completion = this.#bus.enqueue({
        messageType: IPC_MESSAGE_TYPE.TASK_DISPATCH,
        targetRole: PROCESS_ROLE.TASK_WORKER,
        targetWorkerId: assignment.selectedWorkerId,
        messageId: assignment.assignmentMessageId,
        correlationId: createCorrelationId(envelope.messageId),
        payload: scheduledPayload,
      }).completion;
    } catch (error) {
      this.#rejected += 1;
      this.#abandoned += 1;
      this.#deliveryFailed(error);
      this.#rememberCompletion(key, assignment.assignmentMessageId);
      this.#sendCompletion(assignment, assignment, false, envelope.messageId);
      return;
    }

    this.#assignmentsByKey.set(key, assignment);
    this.#assignmentsByMessageId.set(assignment.assignmentMessageId, assignment);
    this.#accepted += 1;
    void completion.catch((error: unknown) => {
      if (this.#assignmentsByKey.get(key) !== assignment) {
        return;
      }
      this.#removeAssignment(assignment);
      this.#rememberCompletion(key, assignment.assignmentMessageId);
      this.#abandoned += 1;
      this.#deliveryFailed(error);
      this.#sendCompletion(
        assignment,
        assignment,
        false,
        assignment.sourceDispatchMessageId,
      );
    });
  }

  #handleFinish(envelope: Readonly<IpcEnvelopeV1>): void {
    let payload: Readonly<TaskFinishPayload>;
    try {
      this.#assertFinishEnvelope(envelope);
      payload = decodeTaskFinishPayload(envelope.payload);
    } catch {
      this.#rejected += 1;
      return;
    }
    const correlationId = envelope.correlationId!;
    const assignmentMessageId = correlationId as unknown as MessageId;
    if (this.#completedAssignmentIds.has(assignmentMessageId)) {
      this.#rejected += 1;
      this.#duplicate += 1;
      return;
    }
    const assignment = this.#assignmentsByMessageId.get(assignmentMessageId);
    if (assignment === undefined) {
      this.#rejected += 1;
      return;
    }
    if (!hasSelection(payload)) {
      this.#rejected += 1;
      return;
    }
    if (
      !sameTask(payload, assignment) ||
      !sameSelection(payload, assignment) ||
      envelope.sourceWorkerId !== assignment.selectedWorkerId ||
      envelope.sourceGeneration !== assignment.selectedGeneration
    ) {
      this.#rejected += 1;
      if (
        envelope.sourceWorkerId === assignment.selectedWorkerId &&
        envelope.sourceGeneration !== assignment.selectedGeneration
      ) {
        this.#stale += 1;
      }
      return;
    }

    this.#removeAssignment(assignment);
    this.#rememberCompletion(assignment.key, assignment.assignmentMessageId);
    this.#finished += 1;
    if (!this.#sendCompletion(
      payload,
      assignment,
      payload.hasResult,
      assignment.sourceDispatchMessageId,
      payload,
      true,
    )) {
      this.#abandoned += 1;
    }
  }

  #assertDispatchEnvelope(envelope: Readonly<IpcEnvelopeV1>): void {
    if (
      envelope.sourceRole !== PROCESS_ROLE.WORKER ||
      envelope.sourceWorkerId === null ||
      envelope.sourceGeneration === null ||
      envelope.targetRole !== PROCESS_ROLE.MASTER ||
      envelope.targetWorkerId !== null ||
      envelope.flags !== 0 ||
      envelope.correlationId !== null ||
      envelope.sessionId !== null
    ) {
      throw new TypeError("TASK_DISPATCH has invalid source, target, or metadata");
    }
  }

  #assertFinishEnvelope(envelope: Readonly<IpcEnvelopeV1>): void {
    if (
      envelope.sourceRole !== PROCESS_ROLE.TASK_WORKER ||
      envelope.sourceWorkerId === null ||
      envelope.sourceGeneration === null ||
      envelope.targetRole !== PROCESS_ROLE.MASTER ||
      envelope.targetWorkerId !== null ||
      envelope.flags !== 0 ||
      envelope.correlationId === null ||
      envelope.sessionId !== null
    ) {
      throw new TypeError("TASK_FINISH has invalid source, target, or metadata");
    }
  }

  #isCurrentSource(task: TaskKey): boolean {
    const source = this.#registry.get(task.sourceWorkerId);
    return source !== undefined &&
      source.role === PROCESS_ROLE.WORKER &&
      source.generation === task.sourceGeneration;
  }

  #sendCompletion(
    task: TaskKey,
    selection: TaskSelection | null,
    hasResult: boolean,
    sourceDispatchMessageId: MessageId,
    resultPayload?: TaskFinishPayload,
    countAsyncFailureAsAbandoned = false,
    retryOnFailure = true,
  ): boolean {
    const source = this.#registry.get(task.sourceWorkerId);
    if (
      source === undefined ||
      source.role !== PROCESS_ROLE.WORKER ||
      source.generation !== task.sourceGeneration ||
      !canReceiveTaskCompletion(source)
    ) {
      this.#stale += 1;
      return false;
    }

    const completionPayload = hasResult && resultPayload?.hasResult === true
      ? encodeTaskFinishPayload({
        taskId: task.taskId,
        sourceWorkerId: task.sourceWorkerId,
        sourceGeneration: task.sourceGeneration,
        ...(selection ?? resultPayload),
        hasResult: true,
        result: resultPayload.result,
      })
      : encodeTaskFinishPayload({
        taskId: task.taskId,
        sourceWorkerId: task.sourceWorkerId,
        sourceGeneration: task.sourceGeneration,
        ...(selection ?? {
          selectedTaskWorkerId: null,
          selectedWorkerId: null,
          selectedGeneration: null,
        }),
        hasResult: false,
      });
    const sendOptions: ProcessBusSendOptions = {
      messageType: IPC_MESSAGE_TYPE.TASK_FINISH,
      targetRole: PROCESS_ROLE.WORKER,
      targetWorkerId: task.sourceWorkerId,
      correlationId: createCorrelationId(sourceDispatchMessageId),
      payload: completionPayload,
    };
    let completion: Promise<void>;
    try {
      completion = this.#bus.enqueue(sendOptions).completion;
    } catch (error) {
      this.#deliveryFailed(error);
      if (retryOnFailure) {
        this.#scheduleCompletionRetry(
          sendOptions,
          task.sourceWorkerId,
          task.sourceGeneration,
          countAsyncFailureAsAbandoned,
        );
      }
      return true;
    }
    void completion.catch((error: unknown) => {
      this.#deliveryFailed(error);
      if (retryOnFailure) {
        this.#scheduleCompletionRetry(
          sendOptions,
          task.sourceWorkerId,
          task.sourceGeneration,
          countAsyncFailureAsAbandoned,
        );
      }
    });
    return true;
  }

  #scheduleCompletionRetry(
    options: ProcessBusSendOptions,
    sourceWorkerId: WorkerId,
    sourceGeneration: WorkerGeneration,
    countFailureAsAbandoned: boolean,
  ): void {
    this.#completionRetryTail = this.#completionRetryTail.then(async () => {
      try {
        await this.#bus.drain();
      } catch (error) {
        this.#deliveryFailed(error);
      }
      if (this.#closed) {
        if (countFailureAsAbandoned) {
          this.#abandoned += 1;
        }
        return;
      }
      const source = this.#registry.get(sourceWorkerId);
      if (
        source === undefined ||
        source.role !== PROCESS_ROLE.WORKER ||
        source.generation !== sourceGeneration ||
        !canReceiveTaskCompletion(source)
      ) {
        this.#stale += 1;
        if (countFailureAsAbandoned) {
          this.#abandoned += 1;
        }
        return;
      }

      try {
        const retry = this.#bus.enqueue(options);
        await retry.completion;
      } catch (error) {
        if (countFailureAsAbandoned) {
          this.#abandoned += 1;
        }
        this.#deliveryFailed(error);
      }
    });
    void this.#completionRetryTail.catch(() => undefined);
  }

  #removeAssignment(assignment: TaskAssignment): void {
    if (this.#assignmentsByKey.get(assignment.key) === assignment) {
      this.#assignmentsByKey.delete(assignment.key);
    }
    if (
      this.#assignmentsByMessageId.get(assignment.assignmentMessageId) === assignment
    ) {
      this.#assignmentsByMessageId.delete(assignment.assignmentMessageId);
    }
  }

  #rememberCompletion(key: string, assignmentMessageId: MessageId | null): void {
    if (this.#tombstoneLimit === 0) {
      return;
    }
    this.#completedTaskKeys.add(key);
    if (assignmentMessageId !== null) {
      this.#completedAssignmentIds.add(assignmentMessageId);
    }
    this.#tombstones.push({ key, assignmentMessageId });
    while (this.#tombstones.length > this.#tombstoneLimit) {
      const expired = this.#tombstones.shift();
      if (expired === undefined) {
        break;
      }
      this.#completedTaskKeys.delete(expired.key);
      if (expired.assignmentMessageId !== null) {
        this.#completedAssignmentIds.delete(expired.assignmentMessageId);
      }
    }
  }

  #deliveryFailed(error: unknown): void {
    this.#deliveryErrors += 1;
    try {
      this.#onDeliveryError?.(error);
    } catch {
      // Delivery observers cannot alter Router state.
    }
  }
}
