import { SESSION_ID_LAYOUT } from "../protocol/session-id.ts";
import {
  createProcessPid,
  type ProcessPid,
} from "../protocol/worker-id.ts";

export const SHARED_RUNTIME_SCHEMA_VERSION = 1 as const;
export const SHARED_RUNTIME_REGION_NAME_MAX_BYTES = 255;
export const SHARED_RUNTIME_CAPABILITY_TOKEN_MAX_BYTES = 128;
export const SHARED_RUNTIME_LAYOUT_HASH_MAX_BYTES = 128;

const SHARED_RUNTIME_DESCRIPTOR_KEYS = Object.freeze([
  "schemaVersion",
  "layoutHash",
  "regionName",
  "regionBytes",
  "capabilityToken",
  "masterPid",
  "masterGeneration",
  "connectionCapacity",
  "workerCapacity",
] as const);

const textEncoder = new TextEncoder();

export interface SharedRuntimeDescriptor {
  readonly schemaVersion: typeof SHARED_RUNTIME_SCHEMA_VERSION;
  readonly layoutHash: string;
  readonly regionName: string;
  readonly regionBytes: number;
  readonly capabilityToken: string;
  readonly masterPid: ProcessPid;
  readonly masterGeneration: number;
  readonly connectionCapacity: number;
  readonly workerCapacity: number;
}

export interface SharedRuntimeDescriptorExpectation {
  readonly layoutHash?: string;
  readonly regionName?: string;
  readonly regionBytes?: number;
  readonly capabilityToken?: string;
  readonly masterPid?: ProcessPid;
  readonly masterGeneration?: number;
  readonly connectionCapacity?: number;
  readonly workerCapacity?: number;
}

export interface DetachedSharedRuntimeDescriptorOptions {
  readonly masterPid: ProcessPid;
  readonly masterGeneration: number;
  readonly connectionCapacity: number;
  readonly workerCapacity: number;
}

function assertPlainExactRecord(
  value: unknown,
): Readonly<Record<string, unknown>> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError("SharedRuntimeDescriptor must be a plain object");
  }
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError("SharedRuntimeDescriptor must be a plain object");
  }
  const keys = Reflect.ownKeys(value);
  if (keys.some((key) => typeof key !== "string")) {
    throw new TypeError("SharedRuntimeDescriptor must not contain symbol keys");
  }
  const stringKeys = keys as string[];
  if (
    stringKeys.length !== SHARED_RUNTIME_DESCRIPTOR_KEYS.length ||
    SHARED_RUNTIME_DESCRIPTOR_KEYS.some((key) => !Object.hasOwn(value, key))
  ) {
    throw new TypeError(
      `SharedRuntimeDescriptor must contain exactly: ${
        SHARED_RUNTIME_DESCRIPTOR_KEYS.join(", ")
      }`,
    );
  }
  return value as Readonly<Record<string, unknown>>;
}

function byteLength(value: string): number {
  return textEncoder.encode(value).byteLength;
}

function assertBoundedVisibleAscii(
  name: string,
  value: unknown,
  maximumBytes: number,
): string {
  if (
    typeof value !== "string" ||
    value.length === 0 ||
    byteLength(value) > maximumBytes ||
    !/^[\x21-\x7e]+$/.test(value)
  ) {
    throw new TypeError(
      `${name} must contain 1 to ${maximumBytes} bytes of visible ASCII`,
    );
  }
  return value;
}

function assertRegionName(value: unknown): string {
  const regionName = assertBoundedVisibleAscii(
    "regionName",
    value,
    SHARED_RUNTIME_REGION_NAME_MAX_BYTES,
  );
  if (
    regionName.length < 2 ||
    regionName[0] !== "/" ||
    regionName.slice(1).includes("/")
  ) {
    throw new TypeError(
      "regionName must be a POSIX shared-memory name beginning with one slash",
    );
  }
  return regionName;
}

function assertPositiveSafeInteger(name: string, value: unknown): number {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 1) {
    throw new TypeError(`${name} must be a positive safe integer`);
  }
  return value;
}

function assertMasterGeneration(value: unknown): number {
  if (
    typeof value !== "number" ||
    !Number.isSafeInteger(value) ||
    value < 0 ||
    value > SESSION_ID_LAYOUT.maxMasterGeneration
  ) {
    throw new TypeError(
      `masterGeneration must be a safe integer in [0, ${
        SESSION_ID_LAYOUT.maxMasterGeneration
      }]`,
    );
  }
  return value;
}

function assertConnectionCapacity(value: unknown): number {
  const capacity = assertPositiveSafeInteger("connectionCapacity", value);
  const maximum = SESSION_ID_LAYOUT.maxSlotIndex + 1;
  if (capacity > maximum) {
    throw new TypeError(`connectionCapacity must not exceed ${maximum}`);
  }
  return capacity;
}

function assertExpected(
  descriptor: Readonly<SharedRuntimeDescriptor>,
  expected: Readonly<SharedRuntimeDescriptorExpectation>,
): void {
  for (const key of Object.keys(expected) as (keyof SharedRuntimeDescriptorExpectation)[]) {
    const expectedValue = expected[key];
    if (expectedValue !== undefined && descriptor[key] !== expectedValue) {
      throw new TypeError(`${key} does not match the expected shared runtime`);
    }
  }
}

export function validateSharedRuntimeDescriptor(
  value: unknown,
  expected: Readonly<SharedRuntimeDescriptorExpectation> = {},
): Readonly<SharedRuntimeDescriptor> {
  const descriptor = assertPlainExactRecord(value);
  if (descriptor.schemaVersion !== SHARED_RUNTIME_SCHEMA_VERSION) {
    throw new TypeError(
      `schemaVersion must be ${SHARED_RUNTIME_SCHEMA_VERSION}`,
    );
  }

  const validated = Object.freeze({
    schemaVersion: SHARED_RUNTIME_SCHEMA_VERSION,
    layoutHash: assertBoundedVisibleAscii(
      "layoutHash",
      descriptor.layoutHash,
      SHARED_RUNTIME_LAYOUT_HASH_MAX_BYTES,
    ),
    regionName: assertRegionName(descriptor.regionName),
    regionBytes: assertPositiveSafeInteger("regionBytes", descriptor.regionBytes),
    capabilityToken: assertBoundedVisibleAscii(
      "capabilityToken",
      descriptor.capabilityToken,
      SHARED_RUNTIME_CAPABILITY_TOKEN_MAX_BYTES,
    ),
    masterPid: createProcessPid(
      typeof descriptor.masterPid === "number" ? descriptor.masterPid : Number.NaN,
    ),
    masterGeneration: assertMasterGeneration(descriptor.masterGeneration),
    connectionCapacity: assertConnectionCapacity(descriptor.connectionCapacity),
    workerCapacity: assertPositiveSafeInteger(
      "workerCapacity",
      descriptor.workerCapacity,
    ),
  });
  assertExpected(validated, expected);
  return validated;
}

export function createDetachedSharedRuntimeDescriptor(
  options: DetachedSharedRuntimeDescriptorOptions,
): Readonly<SharedRuntimeDescriptor> {
  return validateSharedRuntimeDescriptor({
    schemaVersion: SHARED_RUNTIME_SCHEMA_VERSION,
    layoutHash: "detached-test-runtime-v1",
    regionName: `/ts_swoole_detached_${options.masterPid}_${options.masterGeneration}`,
    regionBytes: 1,
    capabilityToken: "detached-test-runtime",
    masterPid: options.masterPid,
    masterGeneration: options.masterGeneration,
    connectionCapacity: options.connectionCapacity,
    workerCapacity: options.workerCapacity,
  });
}
