import {
  IPC_MESSAGE_TYPE,
  type IpcEnvelopeV1,
  type IpcMessageType,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import type { SessionId } from "../protocol/session-id.ts";
import type { ProcessBus } from "../process/process-bus.ts";
import type { RuntimeContext } from "../runtime/runtime-context.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import {
  decodeNetworkCloseCommandPayload,
  decodeNetworkSendCommandPayload,
} from "./network-command-protocol.ts";
import {
  NETWORK_COMMAND_WRITE_REJECTION_REASON,
  type MasterNetworkCommandWriter,
  type NetworkCommandWriteResult,
} from "./network-command-writer.ts";

const NETWORK_COMMAND_MESSAGE_TYPES: ReadonlySet<IpcMessageType> = new Set([
  IPC_MESSAGE_TYPE.NET_SEND,
  IPC_MESSAGE_TYPE.NET_CLOSE_COMMAND,
]);

const DEFAULT_CLOSE_TOMBSTONE_LIMIT = 4_096;

export const MASTER_NETWORK_COMMAND_REJECTION_REASON = Object.freeze({
  INVALID_SOURCE: "INVALID_SOURCE",
  INVALID_TARGET: "INVALID_TARGET",
  INVALID_METADATA: "INVALID_METADATA",
  MISSING_SESSION: "MISSING_SESSION",
  ...NETWORK_COMMAND_WRITE_REJECTION_REASON,
} as const);

export type MasterNetworkCommandRejectionReason =
  (typeof MASTER_NETWORK_COMMAND_REJECTION_REASON)[
    keyof typeof MASTER_NETWORK_COMMAND_REJECTION_REASON
  ];

export type MasterNetworkCommandBus = Pick<
  ProcessBus,
  "localIdentity" | "onMessage"
>;

export interface MasterNetworkCommandReceiverOptions {
  readonly context: RuntimeContext;
  readonly bus: MasterNetworkCommandBus;
  readonly writer: MasterNetworkCommandWriter;
  readonly closeTombstoneLimit?: number;
}

export interface MasterNetworkCommandReceiverStats {
  readonly closed: boolean;
  readonly acceptedCommands: number;
  readonly acceptedSends: number;
  readonly acceptedCloses: number;
  readonly idempotentCloses: number;
  readonly backpressuredWrites: number;
  readonly ignoredMessages: number;
  readonly rejectedCommands: number;
  readonly rejectionCounts: Readonly<
    Partial<Record<MasterNetworkCommandRejectionReason, number>>
  >;
}

function assertNonNegativeSafeInteger(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function readString(read: () => unknown, fallback: string): string {
  try {
    return String(read());
  } catch {
    return fallback;
  }
}

function describeError(error: unknown): Readonly<Record<string, string>> {
  try {
    if (error instanceof Error) {
      return {
        errorName: readString(() => error.name, "Error"),
        errorMessage: readString(() => error.message, "<unreadable error message>"),
      };
    }
  } catch {
    // Hostile thrown values must remain inside the receiver isolation boundary.
  }
  return {
    errorName: "UnknownError",
    errorMessage: readString(() => error, "<unprintable thrown value>"),
  };
}

function isReceiverRejection(error: unknown): boolean {
  try {
    return error instanceof MasterNetworkCommandRejectedError;
  } catch {
    return false;
  }
}

export class MasterNetworkCommandReceiver implements RuntimeResource {
  readonly #context: RuntimeContext;
  readonly #writer: MasterNetworkCommandWriter;
  readonly #closeTombstoneLimit: number;
  readonly #closeTombstones = new Set<SessionId>();
  readonly #closeTombstoneOrder: SessionId[] = [];
  readonly #rejectionCounts = new Map<MasterNetworkCommandRejectionReason, number>();
  #disposeBusMessage: () => void;
  #closed = false;
  #acceptedSends = 0;
  #acceptedCloses = 0;
  #idempotentCloses = 0;
  #backpressuredWrites = 0;
  #ignoredMessages = 0;
  #rejectedCommands = 0;

  constructor(options: MasterNetworkCommandReceiverOptions) {
    const identity = options.bus.localIdentity;
    if (
      identity.role !== PROCESS_ROLE.MASTER ||
      identity.workerId !== null ||
      identity.generation !== null
    ) {
      throw new TypeError("MasterNetworkCommandReceiver requires a Master ProcessBus");
    }
    const closeTombstoneLimit = options.closeTombstoneLimit ??
      DEFAULT_CLOSE_TOMBSTONE_LIMIT;
    assertNonNegativeSafeInteger("closeTombstoneLimit", closeTombstoneLimit);
    this.#context = options.context;
    this.#writer = options.writer;
    this.#closeTombstoneLimit = closeTombstoneLimit;
    this.#disposeBusMessage = options.bus.onMessage(this.#handleEnvelope);
  }

  stats(): Readonly<MasterNetworkCommandReceiverStats> {
    return Object.freeze({
      closed: this.#closed,
      acceptedCommands: this.#acceptedSends + this.#acceptedCloses,
      acceptedSends: this.#acceptedSends,
      acceptedCloses: this.#acceptedCloses,
      idempotentCloses: this.#idempotentCloses,
      backpressuredWrites: this.#backpressuredWrites,
      ignoredMessages: this.#ignoredMessages,
      rejectedCommands: this.#rejectedCommands,
      rejectionCounts: Object.freeze(
        Object.fromEntries(this.#rejectionCounts) as Partial<
          Record<MasterNetworkCommandRejectionReason, number>
        >,
      ),
    });
  }

  close(_reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#closed = true;
    this.#disposeBusMessage();
    this.#disposeBusMessage = () => {};
    this.#closeTombstones.clear();
    this.#closeTombstoneOrder.length = 0;
  }

  readonly #handleEnvelope = (envelope: Readonly<IpcEnvelopeV1>): void => {
    if (this.#closed) {
      return;
    }
    if (!NETWORK_COMMAND_MESSAGE_TYPES.has(envelope.messageType)) {
      this.#ignoredMessages += 1;
      return;
    }

    try {
      this.#assertAddress(envelope);
      const sessionId = envelope.sessionId;
      if (sessionId === null) {
        this.#reject(
          MASTER_NETWORK_COMMAND_REJECTION_REASON.MISSING_SESSION,
          envelope,
          `${envelope.messageType} requires a Session ID`,
        );
      }

      if (envelope.messageType === IPC_MESSAGE_TYPE.NET_SEND) {
        this.#acceptSend(envelope, sessionId);
      } else {
        this.#acceptClose(envelope, sessionId);
      }
    } catch (error) {
      if (!isReceiverRejection(error)) {
        this.#recordRejection(
          MASTER_NETWORK_COMMAND_REJECTION_REASON.WRITE_FAILED,
          envelope,
          "network command receiver failed unexpectedly",
          error,
        );
      }
    }
  };

  #assertAddress(envelope: Readonly<IpcEnvelopeV1>): void {
    if (
      (envelope.sourceRole !== PROCESS_ROLE.WORKER &&
        envelope.sourceRole !== PROCESS_ROLE.TASK_WORKER &&
        envelope.sourceRole !== PROCESS_ROLE.USER_TASK_WORKER) ||
      envelope.sourceWorkerId === null ||
      envelope.sourceGeneration === null
    ) {
      this.#reject(
        MASTER_NETWORK_COMMAND_REJECTION_REASON.INVALID_SOURCE,
        envelope,
        `${envelope.messageType} must originate from a supervised Worker`,
      );
    }
    if (
      envelope.targetRole !== PROCESS_ROLE.MASTER ||
      envelope.targetWorkerId !== null
    ) {
      this.#reject(
        MASTER_NETWORK_COMMAND_REJECTION_REASON.INVALID_TARGET,
        envelope,
        `${envelope.messageType} must target Master`,
      );
    }
    if (envelope.correlationId !== null || envelope.flags !== 0) {
      this.#reject(
        MASTER_NETWORK_COMMAND_REJECTION_REASON.INVALID_METADATA,
        envelope,
        `${envelope.messageType} cannot carry correlation or response flags`,
      );
    }
  }

  #acceptSend(envelope: Readonly<IpcEnvelopeV1>, sessionId: SessionId): void {
    let command;
    try {
      command = decodeNetworkSendCommandPayload(envelope.payload);
    } catch (error) {
      this.#reject(
        MASTER_NETWORK_COMMAND_REJECTION_REASON.INVALID_PAYLOAD,
        envelope,
        "NET_SEND payload is invalid",
        error,
      );
    }

    const result = command.protocol === "tcp"
      ? this.#writer.sendSession(sessionId, command.data)
      : this.#writer.pushSession(sessionId, command.data, command.opcode);
    if (!result.accepted) {
      this.#rejectWrite(envelope, result);
    }
    this.#acceptedSends += 1;
    if (result.backpressured) {
      this.#backpressuredWrites += 1;
    }
    this.#context.metrics.recordNetworkCommandAccepted(result.backpressured);
  }

  #acceptClose(envelope: Readonly<IpcEnvelopeV1>, sessionId: SessionId): void {
    let command;
    try {
      command = decodeNetworkCloseCommandPayload(envelope.payload);
    } catch (error) {
      this.#reject(
        MASTER_NETWORK_COMMAND_REJECTION_REASON.INVALID_PAYLOAD,
        envelope,
        "NET_CLOSE_COMMAND payload is invalid",
        error,
      );
    }

    if (this.#closeTombstones.has(sessionId)) {
      this.#acceptedCloses += 1;
      this.#idempotentCloses += 1;
      this.#context.metrics.recordNetworkCommandAccepted(false);
      return;
    }
    const result = this.#writer.closeSession(sessionId, command.code, command.reason);
    if (!result.accepted) {
      this.#rejectWrite(envelope, result);
    }
    this.#rememberClosed(sessionId);
    this.#acceptedCloses += 1;
    this.#context.metrics.recordNetworkCommandAccepted(false);
  }

  #rejectWrite(
    envelope: Readonly<IpcEnvelopeV1>,
    result: Extract<NetworkCommandWriteResult, { readonly accepted: false }>,
  ): never {
    this.#reject(
      result.reason,
      envelope,
      `${envelope.messageType} was rejected by the Master writer: ${result.reason}`,
      result.error,
    );
  }

  #rememberClosed(sessionId: SessionId): void {
    if (this.#closeTombstoneLimit === 0 || this.#closeTombstones.has(sessionId)) {
      return;
    }
    this.#closeTombstones.add(sessionId);
    this.#closeTombstoneOrder.push(sessionId);
    while (this.#closeTombstoneOrder.length > this.#closeTombstoneLimit) {
      const expired = this.#closeTombstoneOrder.shift();
      if (expired !== undefined) {
        this.#closeTombstones.delete(expired);
      }
    }
  }

  #reject(
    reason: MasterNetworkCommandRejectionReason,
    envelope: Readonly<IpcEnvelopeV1>,
    message: string,
    cause?: unknown,
  ): never {
    this.#recordRejection(reason, envelope, message, cause);
    throw new MasterNetworkCommandRejectedError(
      reason,
      envelope.messageType,
      envelope.sessionId,
      message,
      cause,
    );
  }

  #recordRejection(
    reason: MasterNetworkCommandRejectionReason,
    envelope: Readonly<IpcEnvelopeV1>,
    message: string,
    error?: unknown,
  ): void {
    this.#rejectedCommands += 1;
    this.#rejectionCounts.set(reason, (this.#rejectionCounts.get(reason) ?? 0) + 1);
    this.#context.metrics.recordNetworkCommandRejected(
      reason === MASTER_NETWORK_COMMAND_REJECTION_REASON.WRITE_FAILED ||
        reason === MASTER_NETWORK_COMMAND_REJECTION_REASON.OUTPUT_SEQUENCE_EXHAUSTED,
    );
    this.#context.log("warn", "runtime.network.command_rejected", {
      reason,
      messageType: envelope.messageType,
      sourceRole: envelope.sourceRole,
      sourceWorkerId: envelope.sourceWorkerId,
      sessionId: envelope.sessionId,
      message,
      ...(error === undefined ? {} : describeError(error)),
    });
  }
}

export class MasterNetworkCommandRejectedError extends Error {
  readonly reason: MasterNetworkCommandRejectionReason;
  readonly messageType: IpcMessageType;
  readonly sessionId: SessionId | null;

  constructor(
    reason: MasterNetworkCommandRejectionReason,
    messageType: IpcMessageType,
    sessionId: SessionId | null,
    message: string,
    cause?: unknown,
  ) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = "MasterNetworkCommandRejectedError";
    this.reason = reason;
    this.messageType = messageType;
    this.sessionId = sessionId;
  }
}
