import type {
  RawIpcEndpoint,
  RawIpcMessageListener,
  RawIpcSendOperation,
} from "./process-transport.ts";
import {
  decodeNodeIpcWireMessage,
  encodeNodeIpcWireMessage,
} from "./node-ipc-wire.ts";

export interface NodeParentProcessLike {
  readonly connected: boolean;
  readonly send?: (
    message: unknown,
    callback: (error: Error | null) => void,
  ) => boolean;

  on(event: "message", listener: (message: unknown) => void): this;
  once(event: "disconnect", listener: () => void): this;
  removeListener(event: "message", listener: (message: unknown) => void): this;
  removeListener(event: "disconnect", listener: () => void): this;
  disconnect(): void;
}

export interface NodeParentProcessCloseResult {
  readonly reason: "disconnect" | "not-connected" | "disconnect-failed";
  readonly error?: unknown;
}

interface Deferred<Value> {
  readonly promise: Promise<Value>;
  readonly resolve: (value: Value) => void;
  readonly reject: (reason?: unknown) => void;
}

function createDeferred<Value>(): Deferred<Value> {
  let resolve!: (value: Value) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<Value>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function channelClosedError(cause?: unknown): Error {
  return cause === undefined
    ? new Error("parent IPC channel is closed")
    : new Error("parent IPC channel is closed", { cause });
}

export function hasActiveParentProcessChannel(
  parent: NodeParentProcessLike = process as NodeParentProcessLike,
): boolean {
  return parent.connected && parent.send !== undefined;
}

export class NodeParentProcessEndpoint implements RawIpcEndpoint {
  readonly closed: Promise<Readonly<NodeParentProcessCloseResult>>;
  readonly ownsReceivedMessages = true;

  readonly #parent: NodeParentProcessLike;
  readonly #compactIpcEnvelopes: boolean;
  readonly #closedDeferred = createDeferred<Readonly<NodeParentProcessCloseResult>>();
  readonly #messageListeners = new Set<RawIpcMessageListener>();
  readonly #pendingSends = new Set<Deferred<void>>();
  #closedSettled = false;

  constructor(
    parent: NodeParentProcessLike = process as NodeParentProcessLike,
    compactIpcEnvelopes = parent === process && process.env.ALLOY_CORE_COMPACT_IPC === "1",
  ) {
    this.#parent = parent;
    this.#compactIpcEnvelopes = compactIpcEnvelopes;
    this.closed = this.#closedDeferred.promise;

    if (!hasActiveParentProcessChannel(parent)) {
      this.#settleClosed({ reason: "not-connected" });
      return;
    }

    parent.on("message", this.#onMessage);
    parent.once("disconnect", this.#onDisconnect);
    if (!parent.connected) {
      this.#onDisconnect();
    }
  }

  get connected(): boolean {
    return !this.#closedSettled && this.#parent.connected;
  }

  startSend(message: unknown): RawIpcSendOperation {
    const send = this.#parent.send;
    if (!this.connected || send === undefined) {
      return Object.freeze({
        backpressured: false,
        completed: Promise.reject(channelClosedError()),
      });
    }

    const deferred = createDeferred<void>();
    this.#pendingSends.add(deferred);
    let settled = false;
    const settle = (error: Error | null): void => {
      if (settled) {
        return;
      }
      settled = true;
      this.#pendingSends.delete(deferred);
      if (error === null) {
        deferred.resolve();
      } else {
        deferred.reject(error);
      }
    };

    let accepted = true;
    try {
      accepted = send.call(
        this.#parent,
        this.#compactIpcEnvelopes ? encodeNodeIpcWireMessage(message) : message,
        settle,
      );
    } catch (error) {
      settle(error instanceof Error ? error : new Error("parent IPC send failed", {
        cause: error,
      }));
    }

    return Object.freeze({
      backpressured: !accepted,
      completed: deferred.promise,
    });
  }

  onMessage(listener: RawIpcMessageListener): () => void {
    if (this.#closedSettled) {
      return () => {};
    }
    this.#messageListeners.add(listener);
    return () => {
      this.#messageListeners.delete(listener);
    };
  }

  disconnect(): void {
    if (this.#closedSettled) {
      return;
    }
    if (!this.#parent.connected) {
      this.#settleClosed({ reason: "disconnect" });
      return;
    }

    try {
      this.#parent.disconnect();
    } catch (error) {
      this.#settleClosed({ reason: "disconnect-failed", error });
    }
  }

  readonly #onMessage = (message: unknown): void => {
    if (this.#closedSettled) {
      return;
    }
    const decoded = this.#compactIpcEnvelopes
      ? decodeNodeIpcWireMessage(message)
      : message;
    for (const listener of [...this.#messageListeners]) {
      listener(decoded);
    }
  };

  readonly #onDisconnect = (): void => {
    this.#settleClosed({ reason: "disconnect" });
  };

  #settleClosed(result: Readonly<NodeParentProcessCloseResult>): void {
    if (this.#closedSettled) {
      return;
    }
    this.#closedSettled = true;
    this.#parent.removeListener("message", this.#onMessage);
    this.#parent.removeListener("disconnect", this.#onDisconnect);
    this.#messageListeners.clear();
    const error = channelClosedError(result.error);
    for (const pending of this.#pendingSends) {
      pending.reject(error);
    }
    this.#pendingSends.clear();
    this.#closedDeferred.resolve(Object.freeze({ ...result }));
  }
}
