import {
  fork,
  type ChildProcess,
  type Serializable,
} from "node:child_process";

import {
  type ManagedChildCloseResult,
  type ManagedChildDisconnectListener,
  type ManagedChildListenerDisposer,
  type ManagedChildMessageListener,
  type ManagedChildProcess,
  type ManagedChildSendOperation,
  type ManagedChildSpawner,
  type ManagedChildSpawnOptions,
} from "./managed-child-process.ts";
import {
  createProcessPid,
  type WorkerPid,
} from "../protocol/worker-id.ts";
import {
  decodeNodeIpcWireMessage,
  encodeNodeIpcWireMessage,
} from "./node-ipc-wire.ts";

interface Deferred<Value> {
  readonly promise: Promise<Value>;
  readonly resolve: (value: Value) => void;
  readonly reject: (reason?: unknown) => void;
}

function createDeferred<Value>(): Deferred<Value> {
  let resolve!: (value: Value) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<Value>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function spawnFailure(entrypoint: URL | string, cause: unknown): Error {
  return new Error(`failed to spawn managed child ${String(entrypoint)}`, { cause });
}

class NodeManagedChildProcess implements ManagedChildProcess {
  readonly spawned: Promise<WorkerPid>;
  readonly closed: Promise<ManagedChildCloseResult>;
  readonly ownsReceivedMessages = true;

  readonly #child: ChildProcess;
  readonly #entrypoint: URL | string;
  readonly #compactIpcEnvelopes: boolean;
  readonly #spawnedDeferred = createDeferred<WorkerPid>();
  readonly #closedDeferred = createDeferred<ManagedChildCloseResult>();
  readonly #messageListeners = new Map<ManagedChildMessageListener, (message: unknown) => void>();
  readonly #disconnectListeners = new Map<ManagedChildDisconnectListener, () => void>();
  #spawnSettled = false;
  #closedSettled = false;
  #firstError: unknown;

  constructor(
    child: ChildProcess,
    entrypoint: URL | string,
    compactIpcEnvelopes: boolean,
  ) {
    this.#child = child;
    this.#entrypoint = entrypoint;
    this.#compactIpcEnvelopes = compactIpcEnvelopes;
    this.spawned = this.#spawnedDeferred.promise;
    this.closed = this.#closedDeferred.promise;
    void this.spawned.catch(() => undefined);

    child.once("spawn", this.#onSpawn);
    child.on("error", this.#onError);
    child.once("close", this.#onClose);
  }

  get connected(): boolean {
    return this.#child.connected;
  }

  startSend(message: unknown): ManagedChildSendOperation {
    if (!this.#child.connected) {
      const completed = Promise.reject<void>(
        new Error("managed child IPC channel is closed"),
      );
      return Object.freeze({ backpressured: false, completed });
    }

    const completedDeferred = createDeferred<void>();
    let accepted = true;
    try {
      const wireMessage = this.#compactIpcEnvelopes
        ? encodeNodeIpcWireMessage(message)
        : message;
      accepted = this.#child.send(wireMessage as Serializable, (error) => {
        if (error === null) {
          completedDeferred.resolve();
        } else {
          completedDeferred.reject(error);
        }
      });
    } catch (error) {
      completedDeferred.reject(error);
    }
    return Object.freeze({
      backpressured: !accepted,
      completed: completedDeferred.promise,
    });
  }

  send(message: unknown): Promise<void> {
    return this.startSend(message).completed;
  }

  onMessage(listener: ManagedChildMessageListener): ManagedChildListenerDisposer {
    if (this.#closedSettled) {
      return () => {};
    }

    const existing = this.#messageListeners.get(listener);
    if (existing !== undefined) {
      return () => this.#removeMessageListener(listener, existing);
    }

    const wrapped = (message: unknown): void => listener(
      this.#compactIpcEnvelopes ? decodeNodeIpcWireMessage(message) : message,
    );
    this.#messageListeners.set(listener, wrapped);
    this.#child.on("message", wrapped);
    return () => this.#removeMessageListener(listener, wrapped);
  }

  onDisconnect(listener: ManagedChildDisconnectListener): ManagedChildListenerDisposer {
    if (this.#closedSettled || !this.#child.connected) {
      return () => {};
    }

    const existing = this.#disconnectListeners.get(listener);
    if (existing !== undefined) {
      return () => this.#removeDisconnectListener(listener, existing);
    }

    const wrapped = (): void => listener();
    this.#disconnectListeners.set(listener, wrapped);
    this.#child.on("disconnect", wrapped);
    return () => this.#removeDisconnectListener(listener, wrapped);
  }

  kill(signal: NodeJS.Signals): boolean {
    return this.#child.kill(signal);
  }

  readonly #onSpawn = (): void => {
    if (this.#spawnSettled) {
      return;
    }

    const pid = this.#child.pid;
    if (pid === undefined) {
      const error = spawnFailure(
        this.#entrypoint,
        new Error("child emitted spawn without a process id"),
      );
      this.#firstError ??= error;
      this.#spawnSettled = true;
      this.#spawnedDeferred.reject(error);
      return;
    }

    this.#spawnSettled = true;
    this.#spawnedDeferred.resolve(createProcessPid(pid));
  };

  readonly #onError = (error: Error): void => {
    this.#firstError ??= error;
    if (!this.#spawnSettled) {
      this.#spawnSettled = true;
      this.#spawnedDeferred.reject(spawnFailure(this.#entrypoint, error));
    }
  };

  readonly #onClose = (
    code: number | null,
    signal: NodeJS.Signals | null,
  ): void => {
    if (this.#closedSettled) {
      return;
    }
    this.#closedSettled = true;

    if (!this.#spawnSettled) {
      const error = spawnFailure(
        this.#entrypoint,
        this.#firstError ?? new Error("child closed before emitting spawn"),
      );
      this.#firstError ??= error;
      this.#spawnSettled = true;
      this.#spawnedDeferred.reject(error);
    }

    this.#removeUserListeners();
    this.#child.off("error", this.#onError);

    const result: ManagedChildCloseResult = this.#firstError === undefined
      ? Object.freeze({ code, signal })
      : Object.freeze({ code, signal, error: this.#firstError });
    this.#closedDeferred.resolve(result);
  };

  #removeMessageListener(
    listener: ManagedChildMessageListener,
    wrapped: (message: unknown) => void,
  ): void {
    if (this.#messageListeners.get(listener) !== wrapped) {
      return;
    }
    this.#messageListeners.delete(listener);
    this.#child.off("message", wrapped);
  }

  #removeDisconnectListener(
    listener: ManagedChildDisconnectListener,
    wrapped: () => void,
  ): void {
    if (this.#disconnectListeners.get(listener) !== wrapped) {
      return;
    }
    this.#disconnectListeners.delete(listener);
    this.#child.off("disconnect", wrapped);
  }

  #removeUserListeners(): void {
    for (const wrapped of this.#messageListeners.values()) {
      this.#child.off("message", wrapped);
    }
    this.#messageListeners.clear();
    for (const wrapped of this.#disconnectListeners.values()) {
      this.#child.off("disconnect", wrapped);
    }
    this.#disconnectListeners.clear();
  }
}

export class NodeChildProcessSpawner implements ManagedChildSpawner {
  spawn(options: ManagedChildSpawnOptions): ManagedChildProcess {
    const compactIpcEnvelopes = options.compactIpcEnvelopes === true;
    const child = fork(options.entrypoint, [], {
      env: {
        ...process.env,
        ...options.env,
        ...(compactIpcEnvelopes ? { ALLOY_CORE_COMPACT_IPC: "1" } : {}),
      },
      execArgv: [],
      serialization: "advanced",
      stdio: ["ignore", "inherit", "inherit", "ipc"],
    });
    return new NodeManagedChildProcess(
      child,
      options.entrypoint,
      compactIpcEnvelopes,
    );
  }
}
