import {
  createServer,
  type AddressInfo,
  type Server,
  type Socket,
} from "node:net";

import type {
  NetworkAdapter,
  NetworkAdapterEvents,
  NetworkConnectionHandle,
  NetworkListenOptions,
  NetworkListenerInfo,
  NetworkPeerInfo,
  NetworkWriteResult,
} from "./network-adapter.ts";

export const DEFAULT_NETWORK_READ_CHUNK_BYTES = 64 * 1024;

export function forEachNetworkReadChunk(
  data: Uint8Array,
  listener: (chunk: Uint8Array) => void,
  maxChunkBytes = DEFAULT_NETWORK_READ_CHUNK_BYTES,
): void {
  if (!Number.isSafeInteger(maxChunkBytes) || maxChunkBytes < 1) {
    throw new RangeError("maxChunkBytes must be a positive safe integer");
  }
  for (let offset = 0; offset < data.byteLength; offset += maxChunkBytes) {
    listener(data.subarray(offset, Math.min(data.byteLength, offset + maxChunkBytes)));
  }
}

class NodeNetworkConnection implements NetworkConnectionHandle {
  readonly adapterConnectionId = Symbol("node-network-connection");
  readonly peerInfo: Readonly<NetworkPeerInfo>;

  readonly #socket: Socket;
  #closing = false;

  constructor(socket: Socket) {
    this.#socket = socket;
    this.peerInfo = Object.freeze({
      remoteAddress: socket.remoteAddress ?? "",
      remotePort: socket.remotePort ?? 0,
      localAddress: socket.localAddress ?? "",
      localPort: socket.localPort ?? 0,
    });
  }

  get destroyed(): boolean {
    return this.#socket.destroyed;
  }

  pause(): void {
    this.#socket.pause();
  }

  resume(): void {
    this.#socket.resume();
  }

  write(data: Uint8Array): Readonly<NetworkWriteResult> {
    if (
      this.#closing ||
      this.#socket.destroyed ||
      this.#socket.writableEnded ||
      !this.#socket.writable
    ) {
      throw new Error("Node network connection is not writable");
    }
    const accepted = this.#socket.write(
      Buffer.from(data.buffer, data.byteOffset, data.byteLength),
    );
    return Object.freeze({
      backpressured: !accepted,
      bufferedBytes: this.#socket.writableLength,
    });
  }

  close(reason?: unknown): void {
    if (this.#closing || this.#socket.destroyed) {
      return;
    }
    this.#closing = true;

    if (!this.#socket.writable) {
      this.#socket.destroy(reason instanceof Error ? reason : undefined);
      return;
    }

    this.#socket.end();
    this.#socket.destroySoon();
  }

  forceClose(reason?: unknown): void {
    if (this.#socket.destroyed) {
      return;
    }
    this.#closing = true;
    this.#socket.destroy(reason instanceof Error ? reason : undefined);
  }

  setNoDelay(noDelay: boolean): void {
    this.#socket.setNoDelay(noDelay);
  }

  onData(listener: (data: Buffer) => void): void {
    this.#socket.on("data", listener);
  }

  onDrain(listener: () => void): void {
    this.#socket.on("drain", listener);
  }

  onEnd(listener: () => void): void {
    this.#socket.on("end", listener);
  }

  onError(listener: (error: Error) => void): void {
    this.#socket.on("error", listener);
  }

  onClose(listener: (hadError: boolean) => void): void {
    this.#socket.on("close", listener);
  }
}

function listenerInfo(address: AddressInfo | string | null): NetworkListenerInfo {
  if (address === null || typeof address === "string") {
    throw new Error("Node network listener did not expose a TCP address");
  }
  return Object.freeze({
    host: address.address,
    port: address.port,
    family: address.family,
  });
}

function isServerNotRunning(error: unknown): boolean {
  return (
    error instanceof Error &&
    "code" in error &&
    error.code === "ERR_SERVER_NOT_RUNNING"
  );
}

export class NodeNetworkAdapter
  implements NetworkAdapter<NodeNetworkConnection>
{
  readonly #connections = new Set<NodeNetworkConnection>();
  #server: Server | undefined;
  #events: NetworkAdapterEvents<NodeNetworkConnection> | undefined;
  #listenPromise: Promise<NetworkListenerInfo> | undefined;
  #closePromise: Promise<void> | undefined;
  #listenResolved = false;
  #closeRequested = false;
  #noDelay = false;

  get activeConnectionCount(): number {
    return this.#connections.size;
  }

  listen(
    options: NetworkListenOptions,
    events: NetworkAdapterEvents<NodeNetworkConnection>,
  ): Promise<NetworkListenerInfo> {
    if (this.#listenPromise !== undefined) {
      return this.#listenPromise;
    }
    if (this.#closeRequested) {
      return Promise.reject(new Error("Node network adapter is closing"));
    }

    this.#events = events;
    this.#noDelay = options.noDelay ?? false;
    const server = createServer({ allowHalfOpen: false }, (socket) => {
      this.#accept(socket);
    });
    this.#server = server;

    this.#listenPromise = new Promise<NetworkListenerInfo>((resolve, reject) => {
      let settled = false;
      server.on("error", (error) => {
        if (!settled) {
          settled = true;
          reject(error);
          return;
        }
        try {
          this.#events?.onListenerError(error);
        } catch {
          // Listener error observers must not escape EventEmitter callbacks.
        }
      });

      const listenOptions = options.backlog === undefined
        ? { host: options.host, port: options.port }
        : { host: options.host, port: options.port, backlog: options.backlog };
      server.listen(listenOptions, () => {
        if (settled) {
          return;
        }
        if (this.#closeRequested) {
          settled = true;
          void this.#closeNativeListener().finally(() => {
            reject(new Error("Node network adapter closed while listening"));
          });
          return;
        }
        settled = true;
        this.#listenResolved = true;
        resolve(listenerInfo(server.address()));
      });
    });
    void this.#listenPromise.catch(() => {});
    return this.#listenPromise;
  }

  closeListener(): Promise<void> {
    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }
    this.#closeRequested = true;
    this.#closePromise = (async () => {
      const listenPromise = this.#listenPromise;
      if (listenPromise !== undefined && !this.#listenResolved) {
        await listenPromise.catch(() => {});
      }
      await this.#closeNativeListener();
    })();
    return this.#closePromise;
  }

  pauseConnection(connection: NodeNetworkConnection): void {
    this.#requireConnection(connection).pause();
  }

  resumeConnection(connection: NodeNetworkConnection): void {
    this.#requireConnection(connection).resume();
  }

  write(
    connection: NodeNetworkConnection,
    data: Uint8Array,
  ): Readonly<NetworkWriteResult> {
    return this.#requireConnection(connection).write(data);
  }

  closeConnection(connection: NodeNetworkConnection, reason?: unknown): void {
    if (!this.#connections.has(connection)) {
      throw new Error("Node network connection belongs to another adapter");
    }
    connection.close(reason);
  }

  getPeerInfo(connection: NodeNetworkConnection): Readonly<NetworkPeerInfo> {
    return this.#requireConnection(connection).peerInfo;
  }

  async close(reason?: unknown): Promise<void> {
    const listenerClose = this.closeListener();
    for (const connection of [...this.#connections]) {
      connection.forceClose(reason);
    }
    await listenerClose;
  }

  [Symbol.asyncDispose](): Promise<void> {
    return this.close();
  }

  #accept(socket: Socket): void {
    const connection = new NodeNetworkConnection(socket);
    connection.setNoDelay(this.#noDelay);
    this.#connections.add(connection);

    connection.onData((data) => {
      this.#invokeConnectionCallback(connection, () => {
        forEachNetworkReadChunk(data, (chunk) => {
          this.#events?.onData(connection, chunk);
        });
      });
    });
    connection.onDrain(() => {
      this.#invokeConnectionCallback(connection, () => {
        this.#events?.onDrain(connection);
      });
    });
    connection.onEnd(() => {
      this.#invokeConnectionCallback(connection, () => {
        this.#events?.onEnd(connection);
      });
    });
    connection.onError((error) => {
      this.#reportConnectionError(connection, error);
    });
    connection.onClose((hadError) => {
      this.#connections.delete(connection);
      try {
        this.#events?.onClose(connection, hadError);
      } catch {
        // A close observer cannot be allowed to become an uncaught socket callback.
      }
    });

    if (this.#closeRequested) {
      connection.forceClose();
      return;
    }
    this.#invokeConnectionCallback(connection, () => {
      this.#events?.onConnection(connection);
    });
  }

  #invokeConnectionCallback(
    connection: NodeNetworkConnection,
    callback: () => void,
  ): void {
    try {
      callback();
    } catch (error) {
      this.#reportConnectionError(connection, error);
      connection.forceClose(error);
    }
  }

  #reportConnectionError(
    connection: NodeNetworkConnection,
    error: unknown,
  ): void {
    try {
      this.#events?.onError(connection, error);
    } catch {
      // Error observers are isolated from EventEmitter callbacks.
    }
  }

  #requireConnection(connection: NodeNetworkConnection): NodeNetworkConnection {
    if (!this.#connections.has(connection) || connection.destroyed) {
      throw new Error("Node network connection is closed or belongs to another adapter");
    }
    return connection;
  }

  #closeNativeListener(): Promise<void> {
    const server = this.#server;
    if (server === undefined || !server.listening) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve, reject) => {
      server.close((error) => {
        if (error !== undefined && !isServerNotRunning(error)) {
          reject(error);
          return;
        }
        resolve();
      });
    });
  }
}

export type NodeNetworkConnectionHandle = NodeNetworkConnection;
