import {
  loadRustDataPlaneBinding,
  type NativeWorkerDataPlaneHandle,
  type NativeWorkerDataPlaneSendResult,
} from "../native/rust-data-plane-binding.ts";
import { createIpcSequence } from "../protocol/ipc-envelope.ts";
import { createWorkerId } from "../protocol/worker-id.ts";
import { isSessionId, type SessionId } from "../protocol/session-id.ts";
import type { WorkerNetworkEventReceiver } from "../dispatch/worker-network-event-receiver.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import type { WorkerRuntimeContext } from "../runtime/worker-runtime-context.ts";

const BATCH_HEADER_BYTES = 4;
const EVENT_RECORD_BYTES = 24;
const EVENT_DATA = 1;
const EVENT_BARRIER = 2;
const EVENT_CONNECT = 3;
const EVENT_CLOSE = 4;
const EVENT_BUFFER = 5;
const POLL_MAX_EVENTS = 4_096;
const POLL_MAX_BYTES = 8 * 1024 * 1024;

export interface RustWorkerDataPlaneOptions {
  readonly context: WorkerRuntimeContext;
  readonly path: string;
  readonly receiver?: WorkerNetworkEventReceiver;
  readonly queueMessages?: number;
  readonly native?: NativeWorkerDataPlaneHandle;
}

function readSafeUInt64BE(buffer: Buffer, offset: number): number {
  const value = buffer.readUInt32BE(offset) * 0x1_0000_0000 +
    buffer.readUInt32BE(offset + 4);
  if (!Number.isSafeInteger(value)) {
    throw new TypeError("Rust Worker data-plane integer exceeds JavaScript safe range");
  }
  return value;
}

function writeSafeUInt64BE(buffer: Buffer, value: number, offset: number): void {
  const high = Math.floor(value / 0x1_0000_0000);
  buffer.writeUInt32BE(high, offset);
  buffer.writeUInt32BE(value - high * 0x1_0000_0000, offset + 4);
}

export class RustWorkerDataPlane implements RuntimeResource {
  readonly #context: WorkerRuntimeContext;
  readonly #receiver: WorkerNetworkEventReceiver | undefined;
  readonly #native: NativeWorkerDataPlaneHandle;
  #closePromise: Promise<void> | undefined;
  #drainPromise: Promise<void> | undefined;
  #resolveDrain: (() => void) | undefined;
  #rejectDrain: ((error: unknown) => void) | undefined;
  #drainBarrierId: number | undefined;
  #activeMessages = 0;
  #closing = false;

  constructor(options: RustWorkerDataPlaneOptions) {
    this.#context = options.context;
    this.#receiver = options.receiver;
    this.#native = options.native ??
      new (loadRustDataPlaneBinding().NativeWorkerDataPlane)();
    this.#native.start({
      path: options.path,
      workerId: createWorkerId(options.context.worker_id),
      generation: options.context.generation,
      queueMessages: options.queueMessages ?? 4_096,
      reconnectDelayMs: 5,
    });
    void this.#pump();
  }

  get connected(): boolean {
    return this.#native.connected;
  }

  send(sessionId: SessionId, data: Uint8Array): NativeWorkerDataPlaneSendResult {
    return this.#native.send(sessionId, data);
  }

  closeSession(sessionId: SessionId): NativeWorkerDataPlaneSendResult {
    return this.#native.closeSession(sessionId);
  }

  drain(): Promise<void> {
    if (this.#closing) {
      return Promise.resolve();
    }
    if (this.#drainPromise !== undefined) {
      return this.#drainPromise;
    }
    this.#drainPromise = new Promise<void>((resolve, reject) => {
      this.#resolveDrain = resolve;
      this.#rejectDrain = reject;
    });
    const drainPromise = this.#drainPromise;
    this.#maintainDrainBarrier();
    return drainPromise;
  }

  close(_reason?: unknown): Promise<void> {
    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }
    this.#closing = true;
    this.#settleDrain();
    this.#closePromise = Promise.resolve().then(() => {
      this.#native.close();
    });
    return this.#closePromise;
  }

  async #pump(): Promise<void> {
    try {
      while (!this.#closing && this.#native.running) {
        const batch = await this.#native.waitEvents(
          POLL_MAX_EVENTS,
          POLL_MAX_BYTES,
          100,
        );
        if (batch.byteLength < BATCH_HEADER_BYTES) {
          throw new TypeError("Rust Worker data-plane batch is truncated");
        }
        const count = batch.readUInt32BE(0);
        const acknowledgements = new Map<SessionId, number>();
        const sessionTails = new Map<SessionId, Promise<void>>();
        let failed = false;
        let firstFailure: unknown;
        const schedule = (
          sessionId: SessionId,
          operation: () => void | Promise<void>,
        ): void => {
          const previous = sessionTails.get(sessionId);
          let completion: void | Promise<void>;
          if (previous === undefined) {
            try {
              completion = operation();
            } catch (error) {
              completion = Promise.reject(error);
            }
          } else {
            completion = previous.then(operation);
          }
          if (completion === undefined) {
            return;
          }
          sessionTails.set(sessionId, completion);
          void completion.catch((error: unknown) => {
            if (!failed) {
              failed = true;
              firstFailure = error;
            }
          });
        };
        let offset = BATCH_HEADER_BYTES;
        let completedDrainBarrier = false;
        for (let index = 0; index < count; index += 1) {
          if (batch.byteLength - offset < EVENT_RECORD_BYTES) {
            throw new TypeError("Rust Worker data-plane event is truncated");
          }
          const kind = batch[offset];
          if (
            kind !== EVENT_DATA &&
            kind !== EVENT_BARRIER &&
            kind !== EVENT_CONNECT &&
            kind !== EVENT_CLOSE &&
            kind !== EVENT_BUFFER
          ) {
            throw new TypeError(`Rust Worker data-plane event kind ${kind} is invalid`);
          }
          const sessionId = readSafeUInt64BE(batch, offset + 4);
          const sequence = readSafeUInt64BE(batch, offset + 12);
          const payloadBytes = batch.readUInt32BE(offset + 20);
          const payloadStart = offset + EVENT_RECORD_BYTES;
          const payloadEnd = payloadStart + payloadBytes;
          if (payloadEnd > batch.byteLength) {
            throw new TypeError("Rust Worker data-plane event payload is truncated");
          }
          if (kind === EVENT_BARRIER) {
            if (sessionId !== 0 || sequence < 1 || payloadBytes !== 0) {
              throw new TypeError("Rust Worker data-plane barrier is invalid");
            }
            if (sequence === this.#drainBarrierId) {
              completedDrainBarrier = true;
            }
            offset = payloadEnd;
            continue;
          }
          if (!isSessionId(sessionId)) {
            throw new TypeError("Rust Worker data-plane Session ID is invalid");
          }
          if (this.#receiver === undefined) {
            throw new Error("Task Worker received an inbound native network event");
          }
          if (kind === EVENT_CONNECT || kind === EVENT_CLOSE || kind === EVENT_BUFFER) {
            if (payloadBytes <= 8) {
              throw new TypeError("Rust Worker control event identity is invalid");
            }
            const controlId = readSafeUInt64BE(batch, payloadStart);
            if (controlId < 1) {
              throw new TypeError("Rust Worker control event ID is invalid");
            }
            const controlPayloadStart = payloadStart + 8;
            let payload: unknown;
            try {
              payload = JSON.parse(batch.toString("utf8", controlPayloadStart, payloadEnd));
            } catch (error) {
              throw new TypeError("Rust Worker control event payload is invalid JSON", {
                cause: error,
              });
            }
            if (kind === EVENT_CONNECT) {
              schedule(sessionId, () => {
                const completion = this.#receiver!.acceptNativeTcpConnect(
                  sessionId,
                  createIpcSequence(sequence),
                  payload,
                );
                return this.#acknowledgeControlAfter(
                  completion,
                  kind,
                  sessionId,
                  sequence,
                  controlId,
                );
              });
            } else if (kind === EVENT_CLOSE) {
              schedule(sessionId, () => {
                const completion = this.#receiver!.acceptNativeTcpClose(
                  sessionId,
                  createIpcSequence(sequence),
                  payload,
                );
                return this.#acknowledgeControlAfter(
                  completion,
                  kind,
                  sessionId,
                  sequence,
                  controlId,
                );
              });
            } else {
              schedule(sessionId, () => {
                const completion = this.#receiver!.acceptNativeTcpBuffer(
                  sessionId,
                  createIpcSequence(sequence),
                  payload,
                );
                return this.#acknowledgeControlAfter(
                  completion,
                  kind,
                  sessionId,
                  sequence,
                  controlId,
                );
              });
            }
            offset = payloadEnd;
            continue;
          }
          if (sequence < 1) {
            throw new TypeError("Rust Worker data-plane event identity is invalid");
          }
          schedule(sessionId, () => {
            this.#activeMessages += 1;
            let completion: void | Promise<void>;
            try {
              completion = this.#receiver!.acceptNativeTcpMessage(
                sessionId,
                createIpcSequence(sequence),
                batch.subarray(payloadStart, payloadEnd),
              );
            } catch (error) {
              this.#activeMessages -= 1;
              throw error;
            }
            if (completion === undefined) {
              this.#activeMessages -= 1;
              acknowledgements.set(sessionId, sequence);
              return;
            }
            return completion.then(() => {
              acknowledgements.set(sessionId, sequence);
            }).finally(() => {
              this.#activeMessages -= 1;
            });
          });
          offset = payloadEnd;
        }
        if (offset !== batch.byteLength) {
          throw new TypeError("Rust Worker data-plane batch contains trailing bytes");
        }
        if (sessionTails.size !== 0) {
          await Promise.allSettled(sessionTails.values());
        }
        if (failed) {
          throw firstFailure;
        }
        if (acknowledgements.size !== 0) {
          const payload = Buffer.allocUnsafe(acknowledgements.size * 16);
          let acknowledgementOffset = 0;
          for (const [sessionId, sequence] of acknowledgements) {
            writeSafeUInt64BE(payload, sessionId, acknowledgementOffset);
            writeSafeUInt64BE(payload, sequence, acknowledgementOffset + 8);
            acknowledgementOffset += 16;
          }
          if (!this.#native.acknowledge(payload)) {
            throw new Error("Rust Worker data-plane acknowledgement was rejected");
          }
        }
        if (completedDrainBarrier) {
          this.#settleDrain();
        } else {
          this.#maintainDrainBarrier();
        }
      }
      if (!this.#closing) {
        throw new Error("Rust Worker data-plane thread stopped unexpectedly");
      }
    } catch (error) {
      if (this.#closing) {
        return;
      }
      this.#context.metrics.recordError();
      this.#context.log("error", "runtime.worker.rust_data_plane_failed", {
        workerId: this.#context.worker_id,
        errorName: error instanceof Error ? error.name : "UnknownError",
        errorMessage: error instanceof Error ? error.message : String(error),
      });
      this.#context.requestStop(error);
      this.#rejectPendingDrain(error);
    }
  }

  #acknowledgeControlAfter(
    completion: void | Promise<void>,
    kind: number,
    sessionId: SessionId,
    sequence: number,
    controlId: number,
  ): void | Promise<void> {
    if (completion === undefined) {
      this.#acknowledgeControl(kind, sessionId, sequence, controlId);
      return;
    }
    return completion.then(() => {
      this.#acknowledgeControl(kind, sessionId, sequence, controlId);
    });
  }

  #acknowledgeControl(
    kind: number,
    sessionId: SessionId,
    sequence: number,
    controlId: number,
  ): void {
    if (!this.#native.acknowledgeControl(kind, sessionId, sequence, controlId)) {
      throw new Error("Rust Worker control acknowledgement was rejected");
    }
  }

  #settleDrain(): void {
    const resolve = this.#resolveDrain;
    if (resolve === undefined) {
      return;
    }
    this.#resolveDrain = undefined;
    this.#rejectDrain = undefined;
    this.#drainPromise = undefined;
    this.#drainBarrierId = undefined;
    resolve();
  }

  #maintainDrainBarrier(): void {
    if (this.#drainPromise === undefined || this.#closing) {
      return;
    }
    if (!this.#native.running) {
      if (this.#activeMessages === 0 && this.#native.pendingEvents === 0) {
        this.#settleDrain();
      }
      return;
    }
    if (!this.#native.connected) {
      this.#drainBarrierId = undefined;
      return;
    }
    if (this.#drainBarrierId !== undefined) {
      return;
    }
    const barrierId = this.#native.requestDrain();
    if (Number.isSafeInteger(barrierId) && barrierId >= 1) {
      this.#drainBarrierId = barrierId;
    } else {
      this.#drainBarrierId = undefined;
    }
  }

  #rejectPendingDrain(error: unknown): void {
    const reject = this.#rejectDrain;
    if (reject === undefined) {
      return;
    }
    this.#resolveDrain = undefined;
    this.#rejectDrain = undefined;
    this.#drainPromise = undefined;
    this.#drainBarrierId = undefined;
    reject(error);
  }
}
