import type { SessionId } from "../protocol/session-id.ts";

export const NETWORK_COMMAND_WRITE_REJECTION_REASON = Object.freeze({
  UNKNOWN_SESSION: "UNKNOWN_SESSION",
  SESSION_NOT_OPEN: "SESSION_NOT_OPEN",
  PROTOCOL_MISMATCH: "PROTOCOL_MISMATCH",
  INVALID_PAYLOAD: "INVALID_PAYLOAD",
  MESSAGE_TOO_LARGE: "MESSAGE_TOO_LARGE",
  OUTPUT_BUFFER_OVERFLOW: "OUTPUT_BUFFER_OVERFLOW",
  OUTPUT_SEQUENCE_EXHAUSTED: "OUTPUT_SEQUENCE_EXHAUSTED",
  WRITE_FAILED: "WRITE_FAILED",
} as const);

export type NetworkCommandWriteRejectionReason =
  (typeof NETWORK_COMMAND_WRITE_REJECTION_REASON)[
    keyof typeof NETWORK_COMMAND_WRITE_REJECTION_REASON
  ];

export interface NetworkCommandWriteAccepted {
  readonly accepted: true;
  readonly outputSequence: number | null;
  readonly backpressured: boolean;
  readonly closeStarted: boolean;
}

export interface NetworkCommandWriteRejected {
  readonly accepted: false;
  readonly reason: NetworkCommandWriteRejectionReason;
  readonly error?: unknown;
}

export type NetworkCommandWriteResult =
  | Readonly<NetworkCommandWriteAccepted>
  | Readonly<NetworkCommandWriteRejected>;

export interface MasterNetworkCommandWriter {
  sendSession(sessionId: SessionId, data: Uint8Array): NetworkCommandWriteResult;
  pushSession(
    sessionId: SessionId,
    data: Uint8Array,
    opcode: number,
  ): NetworkCommandWriteResult;
  closeSession(
    sessionId: SessionId,
    code?: number,
    reason?: string,
  ): NetworkCommandWriteResult;
}
