declare const workerIdBrand: unique symbol;
declare const taskWorkerIdBrand: unique symbol;
declare const workerGenerationBrand: unique symbol;
declare const processPidBrand: unique symbol;

export type WorkerId = number & { readonly [workerIdBrand]: "WorkerId" };
export type TaskWorkerId = number & { readonly [taskWorkerIdBrand]: "TaskWorkerId" };
export type WorkerGeneration = number & {
  readonly [workerGenerationBrand]: "WorkerGeneration";
};
export type ProcessPid = number & { readonly [processPidBrand]: "ProcessPid" };
export type WorkerPid = ProcessPid;

function assertIntegerInRange(name: string, value: number, min: number, max: number): void {
  if (!Number.isSafeInteger(value) || value < min || value > max) {
    throw new RangeError(`${name} must be a safe integer in [${min}, ${max}], got ${value}`);
  }
}

export function createWorkerId(value: number): WorkerId {
  assertIntegerInRange("workerId", value, 0, Number.MAX_SAFE_INTEGER);
  return value as WorkerId;
}

export function createTaskWorkerId(value: number): TaskWorkerId {
  assertIntegerInRange("taskWorkerId", value, 0, Number.MAX_SAFE_INTEGER);
  return value as TaskWorkerId;
}

export function createWorkerGeneration(value: number): WorkerGeneration {
  assertIntegerInRange("workerGeneration", value, 0, Number.MAX_SAFE_INTEGER);
  return value as WorkerGeneration;
}

export function createProcessPid(value: number): ProcessPid {
  assertIntegerInRange("processPid", value, 1, Number.MAX_SAFE_INTEGER);
  return value as ProcessPid;
}

export function toGlobalTaskWorkerId(
  workerNum: number,
  taskWorkerId: TaskWorkerId,
  taskWorkerNum?: number,
): WorkerId {
  assertIntegerInRange("workerNum", workerNum, 0, Number.MAX_SAFE_INTEGER);
  if (taskWorkerNum !== undefined) {
    assertIntegerInRange("taskWorkerNum", taskWorkerNum, 0, Number.MAX_SAFE_INTEGER);
    if (taskWorkerId >= taskWorkerNum) {
      throw new RangeError(`taskWorkerId ${taskWorkerId} is outside task pool size ${taskWorkerNum}`);
    }
  }

  const globalId = workerNum + taskWorkerId;
  assertIntegerInRange("globalTaskWorkerId", globalId, 0, Number.MAX_SAFE_INTEGER);
  return globalId as WorkerId;
}

export function toTaskWorkerId(
  workerNum: number,
  globalTaskWorkerId: WorkerId,
  taskWorkerNum?: number,
): TaskWorkerId {
  assertIntegerInRange("workerNum", workerNum, 0, Number.MAX_SAFE_INTEGER);
  if (globalTaskWorkerId < workerNum) {
    throw new RangeError(
      `globalTaskWorkerId ${globalTaskWorkerId} belongs to the event worker range`,
    );
  }

  const taskWorkerId = globalTaskWorkerId - workerNum;
  if (taskWorkerNum !== undefined) {
    assertIntegerInRange("taskWorkerNum", taskWorkerNum, 0, Number.MAX_SAFE_INTEGER);
    if (taskWorkerId >= taskWorkerNum) {
      throw new RangeError(
        `globalTaskWorkerId ${globalTaskWorkerId} is outside task pool size ${taskWorkerNum}`,
      );
    }
  }
  return taskWorkerId as TaskWorkerId;
}

export function isEventWorkerId(workerId: WorkerId, workerNum: number): boolean {
  assertIntegerInRange("workerNum", workerNum, 0, Number.MAX_SAFE_INTEGER);
  return workerId < workerNum;
}

export function isTaskWorkerId(
  workerId: WorkerId,
  workerNum: number,
  taskWorkerNum: number,
): boolean {
  assertIntegerInRange("workerNum", workerNum, 0, Number.MAX_SAFE_INTEGER);
  assertIntegerInRange("taskWorkerNum", taskWorkerNum, 0, Number.MAX_SAFE_INTEGER);
  return workerId >= workerNum && workerId < workerNum + taskWorkerNum;
}

export function toGlobalUserTaskWorkerId(
  workerNum: number,
  taskWorkerNum: number,
  userTaskWorkerId: TaskWorkerId,
  userTaskWorkerNum?: number,
): WorkerId {
  assertIntegerInRange("workerNum", workerNum, 0, Number.MAX_SAFE_INTEGER);
  assertIntegerInRange("taskWorkerNum", taskWorkerNum, 0, Number.MAX_SAFE_INTEGER);
  if (userTaskWorkerNum !== undefined) {
    assertIntegerInRange("userTaskWorkerNum", userTaskWorkerNum, 0, Number.MAX_SAFE_INTEGER);
    if (userTaskWorkerId >= userTaskWorkerNum) {
      throw new RangeError(
        `userTaskWorkerId ${userTaskWorkerId} is outside user task pool size ${userTaskWorkerNum}`,
      );
    }
  }
  return createWorkerId(workerNum + taskWorkerNum + userTaskWorkerId);
}

export function isUserTaskWorkerId(
  workerId: WorkerId,
  workerNum: number,
  taskWorkerNum: number,
  userTaskWorkerNum: number,
): boolean {
  const start = workerNum + taskWorkerNum;
  return workerId >= start && workerId < start + userTaskWorkerNum;
}
