import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export interface NativeTcpFrameCodecHandle {
  readonly bufferedBytes: number;
  push(chunk: Uint8Array): Buffer[];
  encode(body: Uint8Array, header?: Uint8Array): Buffer;
  reset(): void;
}

export interface NativeTcpFrameCodecConstructor {
  new (
    lengthOffset: number,
    lengthFieldBytes: number,
    bodyOffset: number,
    maxFrameBytes: number,
  ): NativeTcpFrameCodecHandle;
}

export interface NativeTcpServerOptions {
  readonly host: string;
  readonly port: number;
  readonly noDelay?: boolean;
  readonly maxConnections?: number;
  readonly maxFrameBytes?: number;
  readonly socketBufferBytes?: number;
  readonly bufferHighWatermarkBytes?: number;
  readonly bufferLowWatermarkBytes?: number;
  readonly runtimeThreads?: number;
  readonly dataPlanePath?: string;
  readonly dataPlaneQueueMessages?: number;
}

export interface NativeTcpListenerInfo {
  readonly host: string;
  readonly port: number;
  readonly family: string;
}

export interface NativeTcpWriteResult {
  readonly accepted: boolean;
  readonly backpressured: boolean;
  readonly bufferedBytes: number;
}

export interface NativeWorkerControlOptions {
  readonly workerId: number;
  readonly workerGeneration: number;
  readonly eventKind: number;
  readonly sessionId: number;
  readonly sequence: number;
  readonly timeoutMs?: number;
}

export interface NativeTcpServerHandle {
  readonly running: boolean;
  start(options: NativeTcpServerOptions): NativeTcpListenerInfo;
  drainEvents(maxEvents: number, maxBytes: number): Buffer;
  waitEvents(maxEvents: number, maxBytes: number, timeoutMs: number): Promise<Buffer>;
  write(connectionId: number, data: Uint8Array): NativeTcpWriteResult;
  registerSession(
    connectionId: number,
    sessionId: number,
    workerId: number,
    workerGeneration: number,
    inputSequence: number,
    outputSequence: number,
  ): boolean;
  deliverWorkerControl(
    options: NativeWorkerControlOptions,
    payload: Uint8Array,
  ): Promise<void>;
  sessionCounters(connectionId: number): NativeTcpSessionCounters | undefined;
  pause(connectionId: number): boolean;
  resume(connectionId: number): boolean;
  closeConnection(connectionId: number): boolean;
  stopAccepting(): boolean;
  close(): boolean;
}

export interface NativeTcpSessionCounters {
  readonly inputSequence: number;
  readonly outputSequence: number;
  readonly acknowledgedInputSequence: number;
  readonly paused: boolean;
}

export interface NativeTcpServerConstructor {
  new (): NativeTcpServerHandle;
}

export interface NativeWorkerDataPlaneOptions {
  readonly path: string;
  readonly workerId: number;
  readonly generation: number;
  readonly queueMessages?: number;
  readonly reconnectDelayMs?: number;
}

export interface NativeWorkerDataPlaneSendResult {
  readonly accepted: boolean;
  readonly backpressured: boolean;
}

export interface NativeWorkerDataPlaneHandle {
  readonly running: boolean;
  readonly connected: boolean;
  readonly pendingEvents: number;
  start(options: NativeWorkerDataPlaneOptions): void;
  waitEvents(maxEvents: number, maxBytes: number, timeoutMs: number): Promise<Buffer>;
  send(sessionId: number, data: Uint8Array): NativeWorkerDataPlaneSendResult;
  closeSession(sessionId: number): NativeWorkerDataPlaneSendResult;
  acknowledge(acknowledgements: Uint8Array): boolean;
  acknowledgeControl(
    eventKind: number,
    sessionId: number,
    sequence: number,
    controlId: number,
  ): boolean;
  requestDrain(): number;
  close(): boolean;
}

export interface NativeWorkerDataPlaneConstructor {
  new (): NativeWorkerDataPlaneHandle;
}

export interface RustDataPlaneBinding {
  readonly NativeTcpFrameCodec: NativeTcpFrameCodecConstructor;
  readonly NativeTcpServer: NativeTcpServerConstructor;
  readonly NativeWorkerDataPlane: NativeWorkerDataPlaneConstructor;
}

const require = createRequire(import.meta.url);
const here = dirname(fileURLToPath(import.meta.url));
const addonPath = resolve(
  here,
  "..",
  "..",
  "build",
  "Release",
  "alloy_core_native.node",
);

let cachedBinding: RustDataPlaneBinding | undefined;

export function loadRustDataPlaneBinding(): RustDataPlaneBinding {
  cachedBinding ??= require(addonPath) as RustDataPlaneBinding;
  return cachedBinding;
}
