export const RUNTIME_LOG_LEVELS = Object.freeze([
  "debug",
  "info",
  "warn",
  "error",
] as const);

export type RuntimeLogLevel = (typeof RUNTIME_LOG_LEVELS)[number];
export type RuntimeLogScalar = null | boolean | number | string;
export type RuntimeLogValue =
  | RuntimeLogScalar
  | readonly RuntimeLogValue[]
  | { readonly [key: string]: RuntimeLogValue };
export type RuntimeLogFields = Readonly<Record<string, RuntimeLogValue>>;

export interface RuntimeLogRecord {
  readonly timestampMs: number;
  readonly monotonicMs: number;
  readonly level: RuntimeLogLevel;
  readonly event: string;
  readonly fields: RuntimeLogFields;
}

export interface StructuredLogger {
  write(record: RuntimeLogRecord): void;
}

export const STRUCTURED_LOG_LEVELS = RUNTIME_LOG_LEVELS;
export type StructuredLogLevel = RuntimeLogLevel;
export type StructuredLogScalar = RuntimeLogScalar;
export type StructuredLogValue = RuntimeLogValue;
export type StructuredLogFields = RuntimeLogFields;
export type StructuredLogRecord = RuntimeLogRecord;

function assertTimestamp(name: string, value: number): void {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative finite number`);
  }
}

function cloneJsonSafeValue(value: unknown, path: string, seen: WeakSet<object>): RuntimeLogValue {
  if (
    value === null ||
    typeof value === "boolean" ||
    typeof value === "string"
  ) {
    return value;
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new TypeError(`${path} must contain only finite numbers`);
    }
    return value;
  }
  if (typeof value !== "object") {
    throw new TypeError(`${path} is not JSON-safe`);
  }
  if (seen.has(value)) {
    throw new TypeError(`${path} must not contain cycles`);
  }

  seen.add(value);
  try {
    if (Array.isArray(value)) {
      const clone = value.map((item, index) =>
        cloneJsonSafeValue(item, `${path}[${index}]`, seen),
      );
      return Object.freeze(clone);
    }

    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new TypeError(`${path} must contain only plain objects`);
    }
    const symbols = Object.getOwnPropertySymbols(value);
    if (symbols.length > 0) {
      throw new TypeError(`${path} must not contain symbol keys`);
    }

    const entries = Object.entries(value).map(([key, item]) => [
      key,
      cloneJsonSafeValue(item, `${path}.${key}`, seen),
    ] as const);
    return Object.freeze(Object.fromEntries(entries));
  } finally {
    seen.delete(value);
  }
}

function isRuntimeLogFields(value: RuntimeLogValue): value is RuntimeLogFields {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

export function createStructuredLogRecord(
  timestampMs: number,
  monotonicMs: number,
  level: RuntimeLogLevel,
  event: string,
  fields: RuntimeLogFields = {},
): RuntimeLogRecord {
  assertTimestamp("timestampMs", timestampMs);
  assertTimestamp("monotonicMs", monotonicMs);
  if (!(RUNTIME_LOG_LEVELS as readonly string[]).includes(level)) {
    throw new TypeError(`unknown structured log level ${String(level)}`);
  }
  if (typeof event !== "string" || event.length === 0) {
    throw new TypeError("event must not be empty");
  }

  const clonedFields = cloneJsonSafeValue(fields, "fields", new WeakSet<object>());
  if (!isRuntimeLogFields(clonedFields)) {
    throw new TypeError("fields must be a plain object");
  }

  return Object.freeze({
    timestampMs,
    monotonicMs,
    level,
    event,
    fields: clonedFields,
  });
}

export const NOOP_STRUCTURED_LOGGER: StructuredLogger = Object.freeze({
  write(_record: RuntimeLogRecord): void {},
});
