import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import type { ConnectionRegistry } from "../connection/connection-registry.ts";
import { CONNECTION_STATE } from "../lifecycle/states.ts";
import type {
  NetworkBufferEvent,
  NetworkClosedEvent,
  NetworkMessageEvent,
  NetworkOpenedEvent,
  NetworkServerEvent,
  NetworkServerEventSink,
} from "../network/network-server.ts";
import {
  IPC_MESSAGE_TYPE,
  createIpcSequence,
  type IpcPayload,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import {
  decodeSessionId,
  type SessionId,
} from "../protocol/session-id.ts";
import {
  createWorkerId,
  type WorkerGeneration,
  type WorkerId,
} from "../protocol/worker-id.ts";
import type {
  ProcessBus,
  ProcessBusSendOptions,
} from "../process/process-bus.ts";
import {
  DEFAULT_DATA_QUEUE_HIGH_BYTES,
  DEFAULT_DATA_QUEUE_HIGH_MESSAGES,
  DEFAULT_DATA_QUEUE_LOW_BYTES,
  DEFAULT_DATA_QUEUE_LOW_MESSAGES,
  DEFAULT_DATA_QUEUE_MAX_BYTES,
  DEFAULT_DATA_QUEUE_MAX_MESSAGES,
} from "../process/process-transport.ts";
import {
  SystemTimerScheduler,
  assertTimerDelay,
  type RuntimeTimer,
  type TimerScheduler,
} from "../runtime/clock.ts";
import type { RuntimeProtocol } from "../runtime/runtime-server.ts";
import type { RuntimeMetrics } from "../metrics/runtime-metrics.ts";
import {
  NETWORK_BUFFER_STATE,
  encodeNetworkBufferStatePayload,
} from "./network-buffer-protocol.ts";
import {
  encodeNetworkClosePayload,
  encodeNetworkConnectPayload,
  encodeNetworkMessagePayload,
  encodeNetworkResumePayload,
} from "./network-event-protocol.ts";

export const DEFAULT_DISPATCH_SESSION_MAX_MESSAGES = 64;
export const DEFAULT_DISPATCH_SESSION_HIGH_MESSAGES = 48;
export const DEFAULT_DISPATCH_SESSION_LOW_MESSAGES = 32;
export const DEFAULT_DISPATCH_SESSION_MAX_BYTES = 2 * 1024 * 1024;
export const DEFAULT_DISPATCH_SESSION_HIGH_BYTES = 1536 * 1024;
export const DEFAULT_DISPATCH_SESSION_LOW_BYTES = 1024 * 1024;
export const DEFAULT_DISPATCH_RECOVERY_TIMEOUT_MS = 5_000;

const DISPATCH_ENVELOPE_OVERHEAD_BYTES = 512;
const textEncoder = new TextEncoder();

interface Deferred {
  readonly promise: Promise<void>;
  readonly resolve: () => void;
  readonly reject: (reason?: unknown) => void;
}

interface DispatchItem {
  readonly options: ProcessBusSendOptions;
  readonly byteLength: number;
  readonly deferred: Deferred;
  readonly closesSession: boolean;
  readonly connectsSession: boolean;
  readonly hydratesSession: boolean;
}

interface DispatchConnectionState {
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly request: NetworkOpenedEvent["request"];
  readonly queue: DispatchItem[];
  lastInputSequence: number;
  connectDelivered: boolean;
  ownerAvailable: boolean;
  closing: boolean;
  paused: boolean;
  backlogPressured: boolean;
  pendingMessages: number;
  pendingBytes: number;
  inFlight: DispatchItem | undefined;
  recoveryTimer: RuntimeTimer | undefined;
}

interface DispatchWorkerState {
  readonly workerId: WorkerId;
  quiescing: boolean;
  restoreExpected: boolean;
  peerAvailable: boolean;
  lifecycleEpoch: number;
  peerPressured: boolean;
  backlogPressured: boolean;
  pendingMessages: number;
  pendingBytes: number;
}

export interface WorkerDispatcherOptions<Handle extends object, ProtocolState> {
  readonly bus: ProcessBus;
  readonly connections: ConnectionRegistry<Handle, ProtocolState>;
  readonly workerNum: number;
  readonly timers?: TimerScheduler;
  readonly metrics?: Pick<
    RuntimeMetrics,
    | "recordNetworkInputPause"
    | "recordNetworkInputResume"
    | "recordNetworkInputTimeout"
  >;
  readonly recoveryTimeoutMs?: number;
  readonly sessionMaxMessages?: number;
  readonly sessionMaxBytes?: number;
  readonly sessionHighMessages?: number;
  readonly sessionHighBytes?: number;
  readonly sessionLowMessages?: number;
  readonly sessionLowBytes?: number;
  readonly workerMaxMessages?: number;
  readonly workerMaxBytes?: number;
  readonly workerHighMessages?: number;
  readonly workerHighBytes?: number;
  readonly workerLowMessages?: number;
  readonly workerLowBytes?: number;
  readonly externalMessageDelivery?: boolean;
  readonly externalControlDelivery?: (
    options: Readonly<ProcessBusSendOptions>,
  ) => Promise<void>;
  readonly resolveWorkerGeneration?: (
    workerId: WorkerId,
  ) => WorkerGeneration | null;
  readonly synchronizeSession?: (sessionId: SessionId) => void;
  readonly waitForSessionPaused?: (sessionId: SessionId) => Promise<void>;
  readonly onSessionReady?: (
    sessionId: SessionId,
    workerId: WorkerId,
    workerGeneration: WorkerGeneration,
  ) => void;
}

export interface WorkerDispatcherQuiesceOptions {
  readonly preserveOwnerAvailability?: boolean;
}

export interface WorkerDispatcherStats {
  readonly closed: boolean;
  readonly activeSessions: number;
  readonly pendingMessages: number;
  readonly pendingBytes: number;
  readonly pausedConnections: number;
  readonly pressuredWorkers: number;
  readonly pauseTransitions: number;
  readonly resumeTransitions: number;
  readonly recoveryTimeouts: number;
  readonly queueRejections: number;
  readonly deliveryErrors: number;
}

function createDeferred(): Deferred {
  let resolve!: () => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<void>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  void promise.catch(() => undefined);
  return { promise, resolve, reject };
}

function assertCapacity(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function assertWatermarks(
  name: string,
  low: number,
  high: number,
  maximum: number,
): void {
  assertCapacity(`${name} low`, low);
  assertCapacity(`${name} high`, high);
  assertCapacity(`${name} max`, maximum);
  if (low > high || high > maximum) {
    throw new RangeError(`${name} watermarks must satisfy low <= high <= max`);
  }
}

function payloadByteLength(payload: IpcPayload): number {
  if (payload instanceof Uint8Array) {
    return payload.byteLength + DISPATCH_ENVELOPE_OVERHEAD_BYTES;
  }
  return textEncoder.encode(JSON.stringify(payload)).byteLength +
    DISPATCH_ENVELOPE_OVERHEAD_BYTES;
}

function isIpcQueueFull(error: unknown): boolean {
  return error instanceof FrameworkError &&
    error.code === FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL;
}

export function dispatchMode2WorkerId(
  sessionId: SessionId,
  workerNum: number,
): WorkerId {
  if (!Number.isSafeInteger(workerNum) || workerNum < 1) {
    throw new RangeError(`workerNum must be a positive safe integer, got ${workerNum}`);
  }
  return createWorkerId(decodeSessionId(sessionId).slotIndex % workerNum);
}

export class WorkerDispatcher<Handle extends object, ProtocolState>
  implements NetworkServerEventSink
{
  readonly #bus: ProcessBus;
  readonly #connections: ConnectionRegistry<Handle, ProtocolState>;
  readonly #workerNum: number;
  readonly #timers: TimerScheduler;
  readonly #metrics: WorkerDispatcherOptions<Handle, ProtocolState>["metrics"];
  readonly #ownsTimers: boolean;
  readonly #recoveryTimeoutMs: number;
  readonly #sessionMaxMessages: number;
  readonly #sessionMaxBytes: number;
  readonly #sessionHighMessages: number;
  readonly #sessionHighBytes: number;
  readonly #sessionLowMessages: number;
  readonly #sessionLowBytes: number;
  readonly #workerMaxMessages: number;
  readonly #workerMaxBytes: number;
  readonly #workerHighMessages: number;
  readonly #workerHighBytes: number;
  readonly #workerLowMessages: number;
  readonly #workerLowBytes: number;
  readonly #externalMessageDelivery: boolean;
  readonly #externalControlDelivery:
    | ((options: Readonly<ProcessBusSendOptions>) => Promise<void>)
    | undefined;
  readonly #resolveWorkerGeneration:
    | ((workerId: WorkerId) => WorkerGeneration | null)
    | undefined;
  readonly #synchronizeSession: ((sessionId: SessionId) => void) | undefined;
  readonly #waitForSessionPaused:
    | ((sessionId: SessionId) => Promise<void>)
    | undefined;
  readonly #onSessionReady:
    | ((
      sessionId: SessionId,
      workerId: WorkerId,
      workerGeneration: WorkerGeneration,
    ) => void)
    | undefined;
  readonly #states = new Map<SessionId, DispatchConnectionState>();
  readonly #workers = new Map<WorkerId, DispatchWorkerState>();
  readonly #disposePeerUnavailable: () => void;
  readonly #disposePeerCapacity: () => void;
  #closed = false;
  #pauseTransitions = 0;
  #resumeTransitions = 0;
  #recoveryTimeouts = 0;
  #queueRejections = 0;
  #deliveryErrors = 0;

  constructor(options: WorkerDispatcherOptions<Handle, ProtocolState>) {
    if (options.bus.localIdentity.role !== PROCESS_ROLE.MASTER) {
      throw new TypeError("WorkerDispatcher requires a MASTER ProcessBus");
    }
    if (!Number.isSafeInteger(options.workerNum) || options.workerNum < 1) {
      throw new RangeError(
        `workerNum must be a positive safe integer, got ${options.workerNum}`,
      );
    }
    this.#bus = options.bus;
    this.#connections = options.connections;
    this.#workerNum = options.workerNum;
    this.#ownsTimers = options.timers === undefined;
    this.#timers = options.timers ?? new SystemTimerScheduler({
      onCallbackError: () => undefined,
    });
    this.#metrics = options.metrics;
    this.#externalMessageDelivery = options.externalMessageDelivery ?? false;
    this.#externalControlDelivery = options.externalControlDelivery;
    this.#resolveWorkerGeneration = options.resolveWorkerGeneration;
    this.#synchronizeSession = options.synchronizeSession;
    this.#waitForSessionPaused = options.waitForSessionPaused;
    this.#onSessionReady = options.onSessionReady;
    this.#recoveryTimeoutMs = options.recoveryTimeoutMs ??
      DEFAULT_DISPATCH_RECOVERY_TIMEOUT_MS;
    assertTimerDelay(this.#recoveryTimeoutMs, "recoveryTimeoutMs");

    this.#sessionMaxMessages = options.sessionMaxMessages ??
      DEFAULT_DISPATCH_SESSION_MAX_MESSAGES;
    this.#sessionMaxBytes = options.sessionMaxBytes ??
      DEFAULT_DISPATCH_SESSION_MAX_BYTES;
    this.#sessionHighMessages = options.sessionHighMessages ??
      Math.min(DEFAULT_DISPATCH_SESSION_HIGH_MESSAGES, this.#sessionMaxMessages);
    this.#sessionHighBytes = options.sessionHighBytes ??
      Math.min(DEFAULT_DISPATCH_SESSION_HIGH_BYTES, this.#sessionMaxBytes);
    this.#sessionLowMessages = options.sessionLowMessages ??
      Math.min(DEFAULT_DISPATCH_SESSION_LOW_MESSAGES, this.#sessionHighMessages);
    this.#sessionLowBytes = options.sessionLowBytes ??
      Math.min(DEFAULT_DISPATCH_SESSION_LOW_BYTES, this.#sessionHighBytes);

    this.#workerMaxMessages = options.workerMaxMessages ??
      DEFAULT_DATA_QUEUE_MAX_MESSAGES;
    this.#workerMaxBytes = options.workerMaxBytes ?? DEFAULT_DATA_QUEUE_MAX_BYTES;
    this.#workerHighMessages = options.workerHighMessages ??
      Math.min(DEFAULT_DATA_QUEUE_HIGH_MESSAGES, this.#workerMaxMessages);
    this.#workerHighBytes = options.workerHighBytes ??
      Math.min(DEFAULT_DATA_QUEUE_HIGH_BYTES, this.#workerMaxBytes);
    this.#workerLowMessages = options.workerLowMessages ??
      Math.min(DEFAULT_DATA_QUEUE_LOW_MESSAGES, this.#workerHighMessages);
    this.#workerLowBytes = options.workerLowBytes ??
      Math.min(DEFAULT_DATA_QUEUE_LOW_BYTES, this.#workerHighBytes);

    assertWatermarks(
      "session message",
      this.#sessionLowMessages,
      this.#sessionHighMessages,
      this.#sessionMaxMessages,
    );
    assertWatermarks(
      "session byte",
      this.#sessionLowBytes,
      this.#sessionHighBytes,
      this.#sessionMaxBytes,
    );
    assertWatermarks(
      "worker message",
      this.#workerLowMessages,
      this.#workerHighMessages,
      this.#workerMaxMessages,
    );
    assertWatermarks(
      "worker byte",
      this.#workerLowBytes,
      this.#workerHighBytes,
      this.#workerMaxBytes,
    );

    for (let index = 0; index < this.#workerNum; index += 1) {
      const workerId = createWorkerId(index);
      this.#workers.set(workerId, {
        workerId,
        quiescing: false,
        restoreExpected: false,
        peerAvailable: true,
        lifecycleEpoch: 0,
        peerPressured: false,
        backlogPressured: false,
        pendingMessages: 0,
        pendingBytes: 0,
      });
    }

    this.#disposePeerUnavailable = options.bus.onPeerUnavailable((identity, error) => {
      if (
        this.#closed ||
        identity.role !== PROCESS_ROLE.WORKER ||
        identity.workerId === null
      ) {
        return;
      }
      const worker = this.#workers.get(identity.workerId);
      if (worker !== undefined) {
        worker.peerAvailable = false;
      }
      const planned = worker?.quiescing === true;
      for (const [sessionId, state] of this.#states) {
        if (state.ownerWorkerId !== identity.workerId) {
          continue;
        }
        state.ownerAvailable = false;
        if (planned) {
          continue;
        }
        this.#skipQueued(state);
        const connection = this.#connections.get(sessionId);
        if (connection !== undefined) {
          this.#connections.beginClose(sessionId, error);
        }
        this.#finalizeIfIdle(sessionId, state);
      }
    });
    this.#disposePeerCapacity = options.bus.onPeerCapacityChange((capacity) => {
      const identity = capacity.identity;
      if (
        this.#closed ||
        identity.role !== PROCESS_ROLE.WORKER ||
        identity.workerId === null
      ) {
        return;
      }
      const worker = this.#workers.get(identity.workerId);
      if (worker === undefined || worker.peerPressured === capacity.pressured) {
        return;
      }
      worker.peerPressured = capacity.pressured;
      this.#reevaluateWorker(worker);
      if (!capacity.pressured) {
        this.#pumpWorker(worker.workerId);
      }
    });
  }

  handle(event: NetworkServerEvent): Promise<void> {
    if (this.#closed) {
      throw new Error("WorkerDispatcher is closed");
    }
    switch (event.type) {
      case "opened":
        return this.#handleOpened(event);
      case "message":
        return this.#handleMessage(event);
      case "buffer":
        return this.#handleBuffer(event);
      case "closed":
        return this.#handleClosed(event);
    }
  }

  async quiesceWorker(
    workerId: WorkerId,
    options: WorkerDispatcherQuiesceOptions = {},
  ): Promise<void> {
    if (this.#closed) {
      throw new Error("WorkerDispatcher is closed");
    }
    const worker = this.#requireWorker(workerId);
    worker.quiescing = true;
    worker.restoreExpected = !options.preserveOwnerAvailability;
    if (options.preserveOwnerAvailability && worker.peerAvailable) {
      this.#enableQuiescedWorkerDelivery(workerId);
    }
    worker.lifecycleEpoch += 1;
    const lifecycleEpoch = worker.lifecycleEpoch;
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId !== workerId) {
        continue;
      }
      if (state.closing) {
        if (state.pendingMessages > 0) {
          this.#startRecoveryTimer(sessionId, state);
        }
      } else {
        this.#setPaused(sessionId, state, true);
      }
    }
    await this.#waitForWorkerIdle(
      workerId,
      lifecycleEpoch,
      !options.preserveOwnerAvailability,
    );
    if (!options.preserveOwnerAvailability && this.#waitForSessionPaused !== undefined) {
      const waitForSessionPaused = this.#waitForSessionPaused;
      const sessions = [...this.#states.entries()]
        .filter(([, state]) =>
          state.ownerWorkerId === workerId && !state.closing
        )
        .map(([sessionId]) => sessionId);
      await Promise.all(sessions.map((sessionId) => waitForSessionPaused(sessionId)));
      for (const sessionId of sessions) {
        const state = this.#states.get(sessionId);
        const record = this.#connections.get(sessionId);
        if (state !== undefined && record !== undefined) {
          state.lastInputSequence = record.inputSequence;
        }
      }
    }
  }

  async restoreWorker(workerId: WorkerId): Promise<void> {
    if (this.#closed) {
      throw new Error("WorkerDispatcher is closed");
    }
    const worker = this.#requireWorker(workerId);
    if (!worker.quiescing) {
      return;
    }
    worker.peerAvailable = true;
    const lifecycleEpoch = worker.lifecycleEpoch;

    const sessions = [...this.#states.entries()]
      .filter(([, state]) => state.ownerWorkerId === workerId)
      .sort(([left], [right]) => left - right);
    try {
      for (const [sessionId, state] of sessions) {
        if (!worker.quiescing || worker.lifecycleEpoch !== lifecycleEpoch) {
          return;
        }
        if (
          this.#states.get(sessionId) !== state ||
          state.closing ||
          !state.connectDelivered
        ) {
          continue;
        }
        const record = this.#connections.get(sessionId);
        if (record === undefined || record.state !== CONNECTION_STATE.OPEN) {
          continue;
        }
        this.#synchronizeSession?.(sessionId);
        const synchronizedRecord = this.#connections.get(sessionId);
        if (
          synchronizedRecord === undefined ||
          synchronizedRecord.state !== CONNECTION_STATE.OPEN
        ) {
          continue;
        }
        state.lastInputSequence = synchronizedRecord.inputSequence;
        const payload = encodeNetworkResumePayload({
          ownerWorkerId: workerId,
          protocol: state.protocol,
          connectedAt: synchronizedRecord.connectedAt,
          lastActiveAt: synchronizedRecord.lastActiveAt,
          peerInfo: synchronizedRecord.peerInfo,
          ...(state.request === undefined ? {} : { request: state.request }),
          inputSequence: synchronizedRecord.inputSequence,
          outputBufferedBytes: synchronizedRecord.outputBufferedBytes,
          outputBufferState: synchronizedRecord.overflow
            ? NETWORK_BUFFER_STATE.OVERFLOW
            : synchronizedRecord.outputBufferFull
              ? NETWORK_BUFFER_STATE.FULL
              : NETWORK_BUFFER_STATE.EMPTY,
        });
        state.ownerAvailable = true;
        await this.#admit(sessionId, state, {
          messageType: IPC_MESSAGE_TYPE.NET_CONNECT,
          targetRole: PROCESS_ROLE.WORKER,
          targetWorkerId: workerId,
          sessionId,
          sequence: createIpcSequence(synchronizedRecord.inputSequence),
          payload,
        }, false, false, true);
      }
    } catch (error) {
      this.#failWorkerRestore(workerId, error);
      throw error;
    }

    if (!worker.quiescing || worker.lifecycleEpoch !== lifecycleEpoch) {
      return;
    }

    const restoreExpected = worker.restoreExpected;
    worker.quiescing = false;
    worker.restoreExpected = false;
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId !== workerId) {
        continue;
      }
      if (state.closing) {
        state.ownerAvailable = restoreExpected && state.pendingMessages > 0;
      } else {
        const record = this.#connections.get(sessionId);
        state.ownerAvailable = record?.state === CONNECTION_STATE.OPEN;
      }
    }
    this.#reevaluateWorker(worker);
    if (!this.#isWorkerPressured(workerId)) {
      this.#pumpWorker(workerId);
    }
  }

  cancelWorkerQuiesce(workerId: WorkerId): void {
    if (this.#closed) {
      return;
    }
    const worker = this.#requireWorker(workerId);
    if (!worker.quiescing) {
      return;
    }
    worker.lifecycleEpoch += 1;
    worker.quiescing = false;
    worker.restoreExpected = false;
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId !== workerId) {
        continue;
      }
      if (state.closing) {
        this.#discardQueuedHydration(state);
        state.ownerAvailable = state.pendingMessages > 0;
      } else {
        const record = this.#connections.get(sessionId);
        state.ownerAvailable = record?.state === CONNECTION_STATE.OPEN;
      }
    }
    this.#reevaluateWorker(worker);
    if (!this.#isWorkerPressured(workerId)) {
      this.#pumpWorker(workerId);
    }
  }

  stats(): Readonly<WorkerDispatcherStats> {
    let pendingMessages = 0;
    let pendingBytes = 0;
    let pausedConnections = 0;
    for (const state of this.#states.values()) {
      pendingMessages += state.pendingMessages;
      pendingBytes += state.pendingBytes;
      if (state.paused) {
        pausedConnections += 1;
      }
    }
    return Object.freeze({
      closed: this.#closed,
      activeSessions: this.#states.size,
      pendingMessages,
      pendingBytes,
      pausedConnections,
      pressuredWorkers: [...this.#workers.values()].filter((worker) =>
        worker.peerPressured || worker.backlogPressured
      ).length,
      pauseTransitions: this.#pauseTransitions,
      resumeTransitions: this.#resumeTransitions,
      recoveryTimeouts: this.#recoveryTimeouts,
      queueRejections: this.#queueRejections,
      deliveryErrors: this.#deliveryErrors,
    });
  }

  close(reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#closed = true;
    this.#disposePeerUnavailable();
    this.#disposePeerCapacity();
    for (const [sessionId, state] of this.#states) {
      state.ownerAvailable = false;
      this.#cancelRecoveryTimer(state, reason);
      this.#skipQueued(state);
      this.#finalizeIfIdle(sessionId, state);
    }
    if (this.#ownsTimers) {
      this.#timers.cancelAll(reason);
      void this.#timers.closeGlobally(reason).catch(() => undefined);
    }
  }

  #handleOpened(event: NetworkOpenedEvent): Promise<void> {
    if (this.#states.has(event.sessionId)) {
      throw new Error(`Connection ${event.sessionId} was already dispatched`);
    }
    const ownerWorkerId = dispatchMode2WorkerId(event.sessionId, this.#workerNum);
    const assigned = this.#connections.assignOwner(event.sessionId, ownerWorkerId);
    if (assigned === undefined) {
      throw new Error(`Connection ${event.sessionId} is unavailable for dispatch`);
    }
    const state: DispatchConnectionState = {
      ownerWorkerId,
      protocol: event.protocol,
      request: event.request,
      queue: [],
      lastInputSequence: 0,
      connectDelivered: false,
      ownerAvailable: !this.#requireWorker(ownerWorkerId).quiescing,
      closing: false,
      paused: false,
      backlogPressured: false,
      pendingMessages: 0,
      pendingBytes: 0,
      inFlight: undefined,
      recoveryTimer: undefined,
    };
    this.#states.set(event.sessionId, state);
    if (!state.ownerAvailable) {
      this.#setPaused(event.sessionId, state, true);
    }
    const payload = encodeNetworkConnectPayload({
      ownerWorkerId,
      protocol: event.protocol,
      connectedAt: event.connectedAt,
      peerInfo: event.peerInfo,
      ...(event.request === undefined ? {} : { request: event.request }),
    });
    return this.#admit(event.sessionId, state, {
      messageType: IPC_MESSAGE_TYPE.NET_CONNECT,
      targetRole: PROCESS_ROLE.WORKER,
      targetWorkerId: ownerWorkerId,
      sessionId: event.sessionId,
      sequence: createIpcSequence(0),
      payload,
    }, false, true);
  }

  #handleMessage(event: NetworkMessageEvent): Promise<void> {
    const state = this.#requireOpenState(event.sessionId, event.protocol);
    const expectedSequence = state.lastInputSequence + 1;
    if (event.inputSequence !== expectedSequence) {
      throw new Error(
        `Connection ${event.sessionId} expected input sequence ${expectedSequence}, got ${event.inputSequence}`,
      );
    }
    const payload = encodeNetworkMessagePayload({
      protocol: event.protocol,
      data: event.data,
      ...(event.opcode === undefined ? {} : { opcode: event.opcode }),
      finish: event.finish,
    });
    state.lastInputSequence = event.inputSequence;
    return this.#admit(event.sessionId, state, {
      messageType: IPC_MESSAGE_TYPE.NET_MESSAGE,
      targetRole: PROCESS_ROLE.WORKER,
      targetWorkerId: state.ownerWorkerId,
      sessionId: event.sessionId,
      sequence: createIpcSequence(event.inputSequence),
      payload,
    }, false);
  }

  #handleBuffer(event: NetworkBufferEvent): Promise<void> {
    const state = this.#states.get(event.sessionId);
    if (state === undefined) {
      return Promise.resolve();
    }
    this.#assertProtocol(event.sessionId, state, event.protocol);
    if (state.closing || !state.ownerAvailable) {
      return Promise.resolve();
    }
    const record = this.#connections.get(event.sessionId);
    const bufferedBytes = record?.outputBufferedBytes ?? 0;
    const payload = encodeNetworkBufferStatePayload({
      ownerWorkerId: state.ownerWorkerId,
      protocol: event.protocol,
      state: event.state,
      bufferedBytes,
    });
    return this.#admit(event.sessionId, state, {
      messageType: IPC_MESSAGE_TYPE.NET_BUFFER_STATE,
      targetRole: PROCESS_ROLE.WORKER,
      targetWorkerId: state.ownerWorkerId,
      sessionId: event.sessionId,
      sequence: createIpcSequence(state.lastInputSequence),
      payload,
    }, false);
  }

  #handleClosed(event: NetworkClosedEvent): Promise<void> {
    if (event.ownerWorkerId === null) {
      if (this.#states.has(event.sessionId)) {
        throw new Error(
          `Connection ${event.sessionId} lost its owner before close dispatch`,
        );
      }
      return Promise.resolve();
    }
    const state = this.#requireState(event.sessionId, event.protocol);
    if (event.ownerWorkerId !== state.ownerWorkerId) {
      throw new Error(
        `Connection ${event.sessionId} close owner ${event.ownerWorkerId} does not match ${state.ownerWorkerId}`,
      );
    }
    if (
      this.#externalMessageDelivery &&
      event.inputSequence >= state.lastInputSequence
    ) {
      state.lastInputSequence = event.inputSequence;
    }
    if (event.inputSequence !== state.lastInputSequence) {
      throw new Error(
        `Connection ${event.sessionId} close input sequence ${event.inputSequence} does not match dispatched sequence ${state.lastInputSequence}`,
      );
    }
    state.closing = true;
    this.#cancelRecoveryTimer(state, event.cause);
    if (event.inputSequence >= Number.MAX_SAFE_INTEGER) {
      throw new RangeError(`Connection ${event.sessionId} event sequence is exhausted`);
    }
    const payload = encodeNetworkClosePayload({
      ownerWorkerId: state.ownerWorkerId,
      protocol: event.protocol,
      inputSequence: event.inputSequence,
      outputSequence: event.outputSequence,
      cause: event.cause,
    });
    const closeOptions: ProcessBusSendOptions = {
      messageType: IPC_MESSAGE_TYPE.NET_CLOSE,
      targetRole: PROCESS_ROLE.WORKER,
      targetWorkerId: state.ownerWorkerId,
      sessionId: event.sessionId,
      sequence: createIpcSequence(event.inputSequence + 1),
      payload,
    };
    const worker = this.#requireWorker(state.ownerWorkerId);
    if (state.ownerAvailable) {
      const delivery = this.#admit(event.sessionId, state, closeOptions, true);
      if (worker.quiescing) {
        this.#startRecoveryTimer(event.sessionId, state);
      }
      return delivery;
    }

    if (!worker.quiescing || !worker.restoreExpected) {
      this.#skipQueued(state);
      this.#finalizeIfIdle(event.sessionId, state);
      return this.#waitForIdle(event.sessionId, state);
    }

    const deliveries: Promise<void>[] = [];
    if (state.connectDelivered) {
      const resumePayload = encodeNetworkResumePayload({
        ownerWorkerId: state.ownerWorkerId,
        protocol: event.protocol,
        connectedAt: event.connectedAt,
        lastActiveAt: event.lastActiveAt,
        peerInfo: event.peerInfo,
        ...(state.request === undefined ? {} : { request: state.request }),
        inputSequence: event.inputSequence,
        outputBufferedBytes: event.outputBufferedBytes,
        outputBufferState: event.outputBufferState,
      });
      deliveries.push(this.#admit(event.sessionId, state, {
        messageType: IPC_MESSAGE_TYPE.NET_CONNECT,
        targetRole: PROCESS_ROLE.WORKER,
        targetWorkerId: state.ownerWorkerId,
        sessionId: event.sessionId,
        sequence: createIpcSequence(event.inputSequence),
        payload: resumePayload,
      }, false, false, true));
    }
    deliveries.push(this.#admit(event.sessionId, state, closeOptions, true));
    this.#startRecoveryTimer(event.sessionId, state);
    return Promise.all(deliveries).then(() => undefined);
  }

  #admit(
    sessionId: SessionId,
    state: DispatchConnectionState,
    options: ProcessBusSendOptions,
    closesSession: boolean,
    connectsSession = false,
    hydratesSession = false,
  ): Promise<void> {
    const worker = this.#requireWorker(state.ownerWorkerId);
    const byteLength = payloadByteLength(options.payload);
    const messageLimit = this.#sessionMaxMessages + (closesSession ? 1 : 0);
    const byteLimit = this.#sessionMaxBytes +
      (closesSession ? DISPATCH_ENVELOPE_OVERHEAD_BYTES * 2 : 0);
    if (
      state.pendingMessages >= messageLimit ||
      byteLength > byteLimit - state.pendingBytes ||
      worker.pendingMessages >= this.#workerMaxMessages + (closesSession ? 1 : 0) ||
      byteLength > this.#workerMaxBytes +
          (closesSession ? DISPATCH_ENVELOPE_OVERHEAD_BYTES * 2 : 0) -
        worker.pendingBytes
    ) {
      this.#queueRejections += 1;
      const error = new FrameworkError(
        FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL,
        `Connection ${sessionId} dispatch backlog is full`,
        {
          sessionId,
          ownerWorkerId: state.ownerWorkerId,
          sessionPendingMessages: state.pendingMessages,
          sessionPendingBytes: state.pendingBytes,
          workerPendingMessages: worker.pendingMessages,
          workerPendingBytes: worker.pendingBytes,
          messageBytes: byteLength,
        },
      );
      this.#connections.beginClose(sessionId, error);
      throw error;
    }

    const deferred = createDeferred();
    const queuedOptions = options.payload instanceof Uint8Array
      ? { ...options, ownsPayload: true }
      : options;
    state.queue.push({
      options: queuedOptions,
      byteLength,
      deferred,
      closesSession,
      connectsSession,
      hydratesSession,
    });
    state.pendingMessages += 1;
    state.pendingBytes += byteLength;
    worker.pendingMessages += 1;
    worker.pendingBytes += byteLength;
    this.#updateBacklogPressure(state, worker);
    this.#pump(sessionId, state);
    return deferred.promise;
  }

  #pump(sessionId: SessionId, state: DispatchConnectionState): void {
    if (
      this.#closed ||
      state.inFlight !== undefined ||
      !state.ownerAvailable ||
      this.#isWorkerPressured(state.ownerWorkerId)
    ) {
      return;
    }
    const item = state.queue.shift();
    if (item === undefined) {
      this.#finalizeIfIdle(sessionId, state);
      return;
    }
    state.inFlight = item;
    let completion: Promise<void>;
    try {
      completion = this.#externalControlDelivery !== undefined &&
          (item.options.messageType === IPC_MESSAGE_TYPE.NET_CONNECT ||
            item.options.messageType === IPC_MESSAGE_TYPE.NET_CLOSE ||
            item.options.messageType === IPC_MESSAGE_TYPE.NET_BUFFER_STATE)
        ? this.#externalControlDelivery(item.options)
        : this.#bus.enqueue(item.options).completion;
    } catch (error) {
      if (isIpcQueueFull(error)) {
        state.inFlight = undefined;
        state.queue.unshift(item);
        this.#setPaused(sessionId, state, true);
        return;
      }
      queueMicrotask(() => this.#finishFailed(sessionId, state, item, error));
      return;
    }
    void completion.then(
      () => this.#finishSuccessful(sessionId, state, item),
      (error: unknown) => this.#finishFailed(sessionId, state, item, error),
    );
  }

  #finishSuccessful(
    sessionId: SessionId,
    state: DispatchConnectionState,
    item: DispatchItem,
  ): void {
    if (state.inFlight !== item) {
      return;
    }
    if ((item.connectsSession || item.hydratesSession) && !state.closing) {
      const generation = this.#resolveWorkerGeneration?.(state.ownerWorkerId);
      if (this.#onSessionReady !== undefined) {
        if (generation === null || generation === undefined) {
          this.#finishFailed(
            sessionId,
            state,
            item,
            new Error(`Worker ${state.ownerWorkerId} has no active generation`),
          );
          return;
        }
        try {
          this.#onSessionReady(
            sessionId,
            state.ownerWorkerId,
            generation,
          );
        } catch (error) {
          this.#finishFailed(sessionId, state, item, error);
          return;
        }
      }
    }
    state.inFlight = undefined;
    this.#releaseCapacity(state, item);
    if (item.connectsSession) {
      state.connectDelivered = true;
    }
    item.deferred.resolve();
    const worker = this.#requireWorker(state.ownerWorkerId);
    this.#updateBacklogPressure(state, worker);
    if (item.closesSession) {
      this.#finalizeIfIdle(sessionId, state);
      return;
    }
    this.#pump(sessionId, state);
  }

  #finishFailed(
    sessionId: SessionId,
    state: DispatchConnectionState,
    item: DispatchItem,
    error: unknown,
  ): void {
    if (state.inFlight !== item) {
      return;
    }
    state.inFlight = undefined;
    this.#releaseCapacity(state, item);
    this.#deliveryErrors += 1;
    item.deferred.reject(error);
    for (const queued of state.queue.splice(0)) {
      this.#releaseCapacity(state, queued);
      queued.deferred.reject(error);
    }
    this.#updateBacklogPressure(state, this.#requireWorker(state.ownerWorkerId));
    this.#finalizeIfIdle(sessionId, state);
  }

  #releaseCapacity(state: DispatchConnectionState, item: DispatchItem): void {
    const worker = this.#requireWorker(state.ownerWorkerId);
    state.pendingMessages -= 1;
    state.pendingBytes -= item.byteLength;
    worker.pendingMessages -= 1;
    worker.pendingBytes -= item.byteLength;
  }

  #skipQueued(state: DispatchConnectionState): void {
    for (const item of state.queue.splice(0)) {
      this.#releaseCapacity(state, item);
      item.deferred.resolve();
    }
    this.#updateBacklogPressure(state, this.#requireWorker(state.ownerWorkerId));
  }

  #discardQueuedHydration(state: DispatchConnectionState): void {
    const index = state.queue.findIndex((item) => item.hydratesSession);
    if (index < 0) {
      return;
    }
    const [item] = state.queue.splice(index, 1);
    if (item === undefined) {
      return;
    }
    this.#releaseCapacity(state, item);
    item.deferred.resolve();
    this.#updateBacklogPressure(state, this.#requireWorker(state.ownerWorkerId));
  }

  #enableQuiescedWorkerDelivery(workerId: WorkerId): void {
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId !== workerId) {
        continue;
      }
      if (state.closing) {
        this.#discardQueuedHydration(state);
        state.ownerAvailable = state.pendingMessages > 0;
        continue;
      }
      const record = this.#connections.get(sessionId);
      state.ownerAvailable = record?.state === CONNECTION_STATE.OPEN;
    }
    this.#pumpWorker(workerId);
  }

  #waitForIdle(
    sessionId: SessionId,
    state: DispatchConnectionState,
  ): Promise<void> {
    if (state.pendingMessages === 0) {
      this.#finalizeIfIdle(sessionId, state);
      return Promise.resolve();
    }
    const waits = [
      ...(state.inFlight === undefined ? [] : [state.inFlight.deferred.promise]),
      ...state.queue.map((item) => item.deferred.promise),
    ];
    return Promise.allSettled(waits).then(() => {
      this.#finalizeIfIdle(sessionId, state);
    });
  }

  async #waitForWorkerIdle(
    workerId: WorkerId,
    lifecycleEpoch: number,
    sealOwnerDelivery: boolean,
  ): Promise<void> {
    const worker = this.#requireWorker(workerId);
    while (worker.quiescing && worker.lifecycleEpoch === lifecycleEpoch) {
      const waits: Promise<void>[] = [];
      for (const state of this.#states.values()) {
        if (state.ownerWorkerId !== workerId || !state.ownerAvailable) {
          continue;
        }
        if (state.inFlight !== undefined) {
          waits.push(state.inFlight.deferred.promise);
        }
        waits.push(...state.queue.map((item) => item.deferred.promise));
      }
      if (waits.length === 0) {
        if (sealOwnerDelivery) {
          for (const state of this.#states.values()) {
            if (state.ownerWorkerId === workerId) {
              state.ownerAvailable = false;
            }
          }
        }
        return;
      }
      await Promise.allSettled(waits);
    }
  }

  #failWorkerRestore(workerId: WorkerId, error: unknown): void {
    this.#requireWorker(workerId).peerAvailable = false;
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId !== workerId) {
        continue;
      }
      state.ownerAvailable = false;
      this.#abortPending(state, error);
      this.#connections.beginClose(sessionId, error);
      this.#finalizeIfIdle(sessionId, state);
    }
  }

  #abortPending(state: DispatchConnectionState, error: unknown): void {
    const inFlight = state.inFlight;
    if (inFlight !== undefined) {
      state.inFlight = undefined;
      this.#releaseCapacity(state, inFlight);
      inFlight.deferred.reject(error);
    }
    for (const item of state.queue.splice(0)) {
      this.#releaseCapacity(state, item);
      item.deferred.reject(error);
    }
    this.#updateBacklogPressure(state, this.#requireWorker(state.ownerWorkerId));
  }

  #finalizeIfIdle(sessionId: SessionId, state: DispatchConnectionState): void {
    if (!state.closing || state.pendingMessages !== 0) {
      return;
    }
    this.#cancelRecoveryTimer(state);
    if (this.#states.get(sessionId) === state) {
      this.#states.delete(sessionId);
    }
  }

  #updateBacklogPressure(
    state: DispatchConnectionState,
    worker: DispatchWorkerState,
  ): void {
    const wasStatePressured = state.backlogPressured;
    const wasWorkerPressured = worker.backlogPressured;
    if (!state.backlogPressured) {
      state.backlogPressured =
        state.pendingMessages >= this.#sessionHighMessages ||
        state.pendingBytes >= this.#sessionHighBytes;
    } else if (
      state.pendingMessages <= this.#sessionLowMessages &&
      state.pendingBytes <= this.#sessionLowBytes
    ) {
      state.backlogPressured = false;
    }

    if (!worker.backlogPressured) {
      worker.backlogPressured =
        worker.pendingMessages >= this.#workerHighMessages ||
        worker.pendingBytes >= this.#workerHighBytes;
    } else if (
      worker.pendingMessages <= this.#workerLowMessages &&
      worker.pendingBytes <= this.#workerLowBytes
    ) {
      worker.backlogPressured = false;
    }
    if (
      state.backlogPressured !== wasStatePressured ||
      worker.backlogPressured !== wasWorkerPressured
    ) {
      this.#reevaluateWorker(worker);
    }
  }

  #reevaluateWorker(worker: DispatchWorkerState): void {
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId !== worker.workerId || state.closing) {
        continue;
      }
      const shouldPause = state.backlogPressured ||
        worker.backlogPressured ||
        worker.peerPressured ||
        worker.quiescing;
      this.#setPaused(sessionId, state, shouldPause);
    }
  }

  #setPaused(
    sessionId: SessionId,
    state: DispatchConnectionState,
    paused: boolean,
  ): void {
    if (state.paused === paused || state.closing) {
      return;
    }
    if (paused) {
      if (!this.#connections.pauseConnection(sessionId)) {
        return;
      }
      state.paused = true;
      this.#pauseTransitions += 1;
      this.#recordMetric(() => this.#metrics?.recordNetworkInputPause());
      this.#startRecoveryTimer(sessionId, state);
      return;
    }
    this.#cancelRecoveryTimer(state);
    if (!this.#connections.resumeConnection(sessionId)) {
      return;
    }
    state.paused = false;
    this.#resumeTransitions += 1;
    this.#recordMetric(() => this.#metrics?.recordNetworkInputResume());
    this.#pump(sessionId, state);
  }

  #startRecoveryTimer(sessionId: SessionId, state: DispatchConnectionState): void {
    if (state.recoveryTimer !== undefined) {
      return;
    }
    state.recoveryTimer = this.#timers.setTimeout(this.#recoveryTimeoutMs, () => {
      state.recoveryTimer = undefined;
      const worker = this.#workers.get(state.ownerWorkerId);
      const awaitingRecovery = state.paused ||
        (worker?.quiescing === true && state.pendingMessages > 0);
      if (!awaitingRecovery || this.#states.get(sessionId) !== state) {
        return;
      }
      this.#recoveryTimeouts += 1;
      this.#recordMetric(() => this.#metrics?.recordNetworkInputTimeout());
      const error = new FrameworkError(
        FRAMEWORK_ERROR_CODE.DRAIN_TIMEOUT,
        `Connection ${sessionId} dispatch backpressure did not recover within ${this.#recoveryTimeoutMs}ms`,
        {
          sessionId,
          ownerWorkerId: state.ownerWorkerId,
          timeoutMs: this.#recoveryTimeoutMs,
          pendingMessages: state.pendingMessages,
          pendingBytes: state.pendingBytes,
        },
      );
      this.#abortPending(state, error);
      this.#connections.beginClose(sessionId, error);
      this.#finalizeIfIdle(sessionId, state);
    });
  }

  #cancelRecoveryTimer(state: DispatchConnectionState, reason?: unknown): void {
    const timer = state.recoveryTimer;
    if (timer === undefined) {
      return;
    }
    state.recoveryTimer = undefined;
    timer.cancel(reason);
  }

  #recordMetric(record: () => void): void {
    try {
      record();
    } catch {
      // Metrics observers cannot change dispatch backpressure behavior.
    }
  }

  #pumpWorker(workerId: WorkerId): void {
    if (this.#isWorkerPressured(workerId)) {
      return;
    }
    for (const [sessionId, state] of this.#states) {
      if (state.ownerWorkerId === workerId) {
        this.#pump(sessionId, state);
      }
    }
  }

  #isWorkerPressured(workerId: WorkerId): boolean {
    const worker = this.#requireWorker(workerId);
    return worker.peerPressured || worker.backlogPressured;
  }

  #requireWorker(workerId: WorkerId): DispatchWorkerState {
    const worker = this.#workers.get(workerId);
    if (worker === undefined) {
      throw new Error(`Worker ${workerId} is outside the dispatch pool`);
    }
    return worker;
  }

  #requireState(
    sessionId: SessionId,
    protocol: RuntimeProtocol,
  ): DispatchConnectionState {
    const state = this.#states.get(sessionId);
    if (state === undefined) {
      throw new Error(`Connection ${sessionId} has not been dispatched`);
    }
    if (state.closing) {
      throw new Error(`Connection ${sessionId} is already closing`);
    }
    this.#assertProtocol(sessionId, state, protocol);
    return state;
  }

  #requireOpenState(
    sessionId: SessionId,
    protocol: RuntimeProtocol,
  ): DispatchConnectionState {
    const state = this.#requireState(sessionId, protocol);
    if (!state.ownerAvailable) {
      throw new Error(`Connection ${sessionId} owner Worker is unavailable`);
    }
    return state;
  }

  #assertProtocol(
    sessionId: SessionId,
    state: DispatchConnectionState,
    protocol: RuntimeProtocol,
  ): void {
    if (state.protocol !== protocol) {
      throw new Error(
        `Connection ${sessionId} protocol changed from ${state.protocol} to ${protocol}`,
      );
    }
  }
}
