import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import type { SharedRuntimeDescriptor } from "./types.ts";

export interface NativeRuntimeStateHandle {
  readonly __nativeRuntimeStateHandle: unique symbol;
}

export interface NativeConnectionRecord {
  readonly sessionId: number;
  readonly slotIndex: number;
  readonly sessionGeneration: number;
  readonly masterGeneration: number;
  readonly gatewayId: number;
  readonly ownerWorkerId: number | null;
  readonly state: number | "ACCEPTED" | "HANDSHAKING" | "OPEN" | "CLOSING" | "CLOSED";
  readonly protocol: number | "tcp" | "websocket";
  readonly protocolState: number;
  readonly remoteAddress: string;
  readonly remotePort: number;
  readonly serverPort: number;
  readonly connectedAtMs: number;
  readonly lastActiveAtMs: number;
  readonly outputBufferBytes: number;
  readonly outputBufferFull: boolean;
  readonly overflow: boolean;
}

export interface NativeWorkerRecord {
  readonly workerId: number;
  readonly taskWorkerId: number | null;
  readonly pid: number | null;
  readonly generation: number;
  readonly role: number | "WORKER" | "TASK_WORKER" | "USER_TASK_WORKER";
  readonly state:
    | number
    | "SPAWNING"
    | "BOOTING"
    | "READY"
    | "RUNNING"
    | "DRAINING"
    | "EXITED"
    | "FAILED";
  readonly restartCount: number;
  readonly startedAt: number;
  readonly readyAt: number | null;
  readonly lastHeartbeatAt: number | null;
}

export interface NativeConnectionProbe {
  readonly status: "open" | "closed" | "stale" | "unknown" | "busy";
  readonly record?: NativeConnectionRecord;
}

export interface NativeMasterClaim {
  readonly handle: NativeRuntimeStateHandle;
  readonly descriptor: SharedRuntimeDescriptor;
  readonly masterGeneration: number;
  readonly recovered: boolean;
  readonly previousCleanShutdown: boolean;
}

export interface NativeRuntimeStateBinding {
  claimMaster(options: {
    readonly key: string;
    readonly ledgerDirectory: string;
    readonly connectionCapacity: number;
    readonly workerCapacity: number;
    readonly masterPid: number;
    readonly generationLimit: number;
  }): NativeMasterClaim;
  attachReader(descriptor: SharedRuntimeDescriptor): NativeRuntimeStateHandle;
  info(handle: NativeRuntimeStateHandle): Readonly<Record<string, unknown>>;
  close(handle: NativeRuntimeStateHandle): boolean;
  destroy(handle: NativeRuntimeStateHandle, cleanShutdown: boolean): boolean;
  purgeLedger(options: { readonly key: string; readonly ledgerDirectory: string }): boolean;
  publishConnection(
    handle: NativeRuntimeStateHandle,
    record: NativeConnectionRecord,
  ): boolean;
  readConnection(
    handle: NativeRuntimeStateHandle,
    sessionId: number,
  ): NativeConnectionProbe;
  probeConnectionAdmission(
    handle: NativeRuntimeStateHandle,
    sessionId: number,
  ): number;
  snapshotOpenSessionIds(handle: NativeRuntimeStateHandle): number[];
  connectionCount(handle: NativeRuntimeStateHandle): number;
  publishWorker(handle: NativeRuntimeStateHandle, record: NativeWorkerRecord): boolean;
  snapshotWorkers(handle: NativeRuntimeStateHandle): NativeWorkerRecord[];
  addStat(
    handle: NativeRuntimeStateHandle,
    metricId: number,
    delta: number,
  ): number;
  atomicGet(handle: NativeRuntimeStateHandle, atomicId: number): number;
  atomicSet(handle: NativeRuntimeStateHandle, atomicId: number, value: number): number;
  atomicCompareSet(
    handle: NativeRuntimeStateHandle,
    atomicId: number,
    expected: number,
    value: number,
  ): boolean;
  lockTry(handle: NativeRuntimeStateHandle, lockId: number, ownerToken: number): boolean;
  lockRelease(handle: NativeRuntimeStateHandle, lockId: number, ownerToken: number): boolean;
  lockClearOwner(handle: NativeRuntimeStateHandle, ownerToken: number): number;
  snapshotStats(handle: NativeRuntimeStateHandle): number[];
  debugSetSchemaVersion(handle: NativeRuntimeStateHandle, version: number): void;
  debugPoisonConnectionSequence(
    handle: NativeRuntimeStateHandle,
    slotIndex: number,
  ): void;
}

const require = createRequire(import.meta.url);
const here = dirname(fileURLToPath(import.meta.url));
const addonPath = resolve(
  here,
  "..",
  "..",
  "build",
  "Release",
  "ts_swoole_runtime_state.node",
);

let cachedBinding: NativeRuntimeStateBinding | undefined;

export function loadNativeRuntimeStateBinding(): NativeRuntimeStateBinding {
  cachedBinding ??= require(addonPath) as NativeRuntimeStateBinding;
  return cachedBinding;
}
