import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import {
  assertWorkerTransition,
  WORKER_STATE,
  type WorkerState,
} from "../lifecycle/states.ts";
import { PROCESS_ROLE, type ProcessRole } from "../protocol/process-role.ts";
import {
  createProcessPid,
  createTaskWorkerId,
  createWorkerGeneration,
  createWorkerId,
  toGlobalTaskWorkerId,
  toGlobalUserTaskWorkerId,
  toTaskWorkerId,
  type TaskWorkerId,
  type WorkerGeneration,
  type WorkerId,
  type WorkerPid,
} from "../protocol/worker-id.ts";
import { SystemClock, type Clock } from "../runtime/clock.ts";

export type WorkerProcessRole = Exclude<ProcessRole, typeof PROCESS_ROLE.MASTER>;

export interface WorkerSlotSnapshot {
  readonly workerId: WorkerId;
  readonly role: WorkerProcessRole;
  readonly taskWorkerId: TaskWorkerId | null;
}

export interface WorkerInstanceRef {
  readonly workerId: WorkerId;
  readonly generation: WorkerGeneration;
}

export interface WorkerInstanceIdentity extends WorkerSlotSnapshot, WorkerInstanceRef {}

export interface WorkerRecordSnapshot extends WorkerInstanceIdentity {
  readonly pid: WorkerPid | null;
  readonly state: WorkerState;
  readonly restartCount: number;
  readonly startedAt: number;
  readonly readyAt: number | null;
  readonly lastHeartbeatAt: number | null;
}

export interface WorkerRegistryOptions {
  readonly workerNum: number;
  readonly taskWorkerNum: number;
  readonly userTaskWorkerNum?: number;
  readonly clock?: Clock;
  readonly onRecordChanged?: (
    record: Readonly<WorkerRecordSnapshot>,
  ) => void;
}

interface MutableWorkerRecord {
  workerId: WorkerId;
  role: WorkerProcessRole;
  taskWorkerId: TaskWorkerId | null;
  pid: WorkerPid | null;
  generation: WorkerGeneration;
  state: WorkerState;
  restartCount: number;
  startedAt: number;
  readyAt: number | null;
  lastHeartbeatAt: number | null;
}

function assertPoolSize(name: string, value: number, minimum: number): void {
  if (!Number.isSafeInteger(value) || value < minimum) {
    throw new RangeError(`${name} must be a safe integer >= ${minimum}, got ${value}`);
  }
}

function freezeSlot(slot: WorkerSlotSnapshot): WorkerSlotSnapshot {
  return Object.freeze({ ...slot });
}

function freezeRecord(record: MutableWorkerRecord): WorkerRecordSnapshot {
  return Object.freeze({ ...record });
}

export class WorkerRegistry {
  readonly workerNum: number;
  readonly taskWorkerNum: number;
  readonly userTaskWorkerNum: number;
  readonly #clock: Clock;
  readonly #onRecordChanged:
    | ((record: Readonly<WorkerRecordSnapshot>) => void)
    | undefined;
  readonly #records = new Map<WorkerId, MutableWorkerRecord>();
  readonly #issuedInstances = new WeakSet<object>();

  constructor(options: WorkerRegistryOptions) {
    assertPoolSize("workerNum", options.workerNum, 1);
    assertPoolSize("taskWorkerNum", options.taskWorkerNum, 0);
    const userTaskWorkerNum = options.userTaskWorkerNum ?? 0;
    assertPoolSize("userTaskWorkerNum", userTaskWorkerNum, 0);
    const size = options.workerNum + options.taskWorkerNum + userTaskWorkerNum;
    if (!Number.isSafeInteger(size)) {
      throw new RangeError(
        `workerNum + taskWorkerNum + userTaskWorkerNum must be a safe integer, got ${size}`,
      );
    }

    this.workerNum = options.workerNum;
    this.taskWorkerNum = options.taskWorkerNum;
    this.userTaskWorkerNum = userTaskWorkerNum;
    this.#clock = options.clock ?? new SystemClock();
    this.#onRecordChanged = options.onRecordChanged;
  }

  get size(): number {
    return this.workerNum + this.taskWorkerNum + this.userTaskWorkerNum;
  }

  get activeSize(): number {
    return this.#records.size;
  }

  *slots(): IterableIterator<WorkerSlotSnapshot> {
    for (let index = 0; index < this.workerNum; index += 1) {
      yield freezeSlot({
        workerId: createWorkerId(index),
        role: PROCESS_ROLE.WORKER,
        taskWorkerId: null,
      });
    }
    for (let index = 0; index < this.taskWorkerNum; index += 1) {
      const taskWorkerId = createTaskWorkerId(index);
      yield freezeSlot({
        workerId: toGlobalTaskWorkerId(this.workerNum, taskWorkerId, this.taskWorkerNum),
        role: PROCESS_ROLE.TASK_WORKER,
        taskWorkerId,
      });
    }
    for (let index = 0; index < this.userTaskWorkerNum; index += 1) {
      yield freezeSlot({
        workerId: toGlobalUserTaskWorkerId(
          this.workerNum,
          this.taskWorkerNum,
          createTaskWorkerId(index),
          this.userTaskWorkerNum,
        ),
        role: PROCESS_ROLE.USER_TASK_WORKER,
        taskWorkerId: null,
      });
    }
  }

  getSlot(workerId: WorkerId): WorkerSlotSnapshot | undefined {
    const slot = this.#findSlot(workerId);
    return slot === undefined ? undefined : freezeSlot(slot);
  }

  get(workerId: WorkerId): WorkerRecordSnapshot | undefined {
    const record = this.#records.get(workerId);
    return record === undefined ? undefined : this.#snapshotRecord(record);
  }

  require(workerId: WorkerId): WorkerRecordSnapshot {
    return this.#snapshotRecord(this.#requireRecord(workerId));
  }

  snapshot(): readonly WorkerRecordSnapshot[] {
    return Object.freeze(
      [...this.#records.values()]
        .sort((left, right) => left.workerId - right.workerId)
        .map((record) => this.#snapshotRecord(record)),
    );
  }

  isCurrent(instance: WorkerInstanceRef): boolean {
    if (!this.#isIssuedInstance(instance)) {
      return false;
    }
    const record = this.#records.get(instance.workerId);
    return record !== undefined && record.generation === instance.generation;
  }

  beginSpawn(workerId: WorkerId): WorkerRecordSnapshot {
    const slot = this.#requireSlot(workerId);
    const previous = this.#records.get(workerId);
    let generation: WorkerGeneration;
    let restartCount: number;

    if (previous === undefined) {
      generation = createWorkerGeneration(1);
      restartCount = 0;
    } else {
      assertWorkerTransition(previous.state, WORKER_STATE.SPAWNING);
      generation = createWorkerGeneration(previous.generation + 1);
      restartCount = previous.restartCount + 1;
    }

    const record: MutableWorkerRecord = {
      ...slot,
      pid: null,
      generation,
      state: WORKER_STATE.SPAWNING,
      restartCount,
      startedAt: this.#clock.wallTimeMs(),
      readyAt: null,
      lastHeartbeatAt: null,
    };
    this.#records.set(workerId, record);
    try {
      return this.#publishRecord(record, true);
    } catch (error) {
      if (previous === undefined) {
        this.#records.delete(workerId);
      } else {
        this.#records.set(workerId, previous);
      }
      throw error;
    }
  }

  attachProcess(
    instance: WorkerInstanceRef,
    pid: number,
  ): WorkerRecordSnapshot | undefined {
    const record = this.#findCurrent(instance);
    if (record === undefined) {
      return undefined;
    }
    const workerPid = createProcessPid(pid);
    if (record.state === WORKER_STATE.BOOTING && record.pid === workerPid) {
      return this.#snapshotRecord(record);
    }

    assertWorkerTransition(record.state, WORKER_STATE.BOOTING);
    const previous = { ...record };
    record.pid = workerPid;
    record.state = WORKER_STATE.BOOTING;
    return this.#publishRecordWithRollback(record, previous);
  }

  markReady(instance: WorkerInstanceRef): WorkerRecordSnapshot | undefined {
    return this.#transition(instance, WORKER_STATE.READY, (record) => {
      record.readyAt = this.#clock.wallTimeMs();
    });
  }

  markRunning(instance: WorkerInstanceRef): WorkerRecordSnapshot | undefined {
    return this.#transition(instance, WORKER_STATE.RUNNING);
  }

  markDraining(instance: WorkerInstanceRef): WorkerRecordSnapshot | undefined {
    return this.#transition(instance, WORKER_STATE.DRAINING);
  }

  markExited(instance: WorkerInstanceRef): WorkerRecordSnapshot | undefined {
    const record = this.#findCurrent(instance);
    if (record === undefined) {
      return undefined;
    }
    if (record.state === WORKER_STATE.EXITED || record.state === WORKER_STATE.FAILED) {
      return this.#snapshotRecord(record);
    }

    assertWorkerTransition(record.state, WORKER_STATE.EXITED);
    const previous = { ...record };
    record.state = WORKER_STATE.EXITED;
    return this.#publishRecordWithRollback(record, previous);
  }

  markFailed(instance: WorkerInstanceRef): WorkerRecordSnapshot | undefined {
    const record = this.#findCurrent(instance);
    if (record === undefined) {
      return undefined;
    }
    if (record.state === WORKER_STATE.FAILED || record.state === WORKER_STATE.EXITED) {
      return this.#snapshotRecord(record);
    }

    assertWorkerTransition(record.state, WORKER_STATE.FAILED);
    const previous = { ...record };
    record.state = WORKER_STATE.FAILED;
    return this.#publishRecordWithRollback(record, previous);
  }

  markHeartbeat(instance: WorkerInstanceRef): WorkerRecordSnapshot | undefined {
    const record = this.#findCurrent(instance);
    if (record === undefined) {
      return undefined;
    }
    if (
      record.pid === null ||
      record.state === WORKER_STATE.SPAWNING ||
      record.state === WORKER_STATE.EXITED ||
      record.state === WORKER_STATE.FAILED
    ) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        `Worker ${record.workerId} cannot record a heartbeat from ${record.state}`,
        {
          workerId: record.workerId,
          generation: record.generation,
          state: record.state,
        },
      );
    }

    const previous = { ...record };
    record.lastHeartbeatAt = this.#clock.wallTimeMs();
    return this.#publishRecordWithRollback(record, previous);
  }

  #transition(
    instance: WorkerInstanceRef,
    state: WorkerState,
    update?: (record: MutableWorkerRecord) => void,
  ): WorkerRecordSnapshot | undefined {
    const record = this.#findCurrent(instance);
    if (record === undefined) {
      return undefined;
    }
    assertWorkerTransition(record.state, state);
    const previous = { ...record };
    update?.(record);
    record.state = state;
    return this.#publishRecordWithRollback(record, previous);
  }

  #findSlot(workerId: WorkerId): WorkerSlotSnapshot | undefined {
    if (!Number.isSafeInteger(workerId) || workerId < 0 || workerId >= this.size) {
      return undefined;
    }
    if (workerId < this.workerNum) {
      return {
        workerId: createWorkerId(workerId),
        role: PROCESS_ROLE.WORKER,
        taskWorkerId: null,
      };
    }

    if (workerId < this.workerNum + this.taskWorkerNum) {
      return {
        workerId: createWorkerId(workerId),
        role: PROCESS_ROLE.TASK_WORKER,
        taskWorkerId: toTaskWorkerId(this.workerNum, workerId, this.taskWorkerNum),
      };
    }
    return {
      workerId: createWorkerId(workerId),
      role: PROCESS_ROLE.USER_TASK_WORKER,
      taskWorkerId: null,
    };
  }

  #requireSlot(workerId: WorkerId): WorkerSlotSnapshot {
    const slot = this.#findSlot(workerId);
    if (slot === undefined) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
        `Worker ${workerId} is outside configured registry slots`,
        {
          workerId,
          workerNum: this.workerNum,
          taskWorkerNum: this.taskWorkerNum,
          userTaskWorkerNum: this.userTaskWorkerNum,
        },
      );
    }
    return slot;
  }

  #requireRecord(workerId: WorkerId): MutableWorkerRecord {
    this.#requireSlot(workerId);
    const record = this.#records.get(workerId);
    if (record === undefined) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
        `Worker ${workerId} has no registered process instance`,
        { workerId },
      );
    }
    return record;
  }

  #findCurrent(instance: WorkerInstanceRef): MutableWorkerRecord | undefined {
    if (!this.#isIssuedInstance(instance)) {
      return undefined;
    }
    const record = this.#requireRecord(instance.workerId);
    return record.generation === instance.generation ? record : undefined;
  }

  #snapshotRecord(
    record: MutableWorkerRecord,
    issueInstance = false,
  ): WorkerRecordSnapshot {
    const snapshot = freezeRecord(record);
    if (issueInstance) {
      this.#issuedInstances.add(snapshot);
    }
    return snapshot;
  }

  #publishRecord(
    record: MutableWorkerRecord,
    issueInstance = false,
  ): WorkerRecordSnapshot {
    const snapshot = this.#snapshotRecord(record, issueInstance);
    this.#onRecordChanged?.(snapshot);
    return snapshot;
  }

  #publishRecordWithRollback(
    record: MutableWorkerRecord,
    previous: MutableWorkerRecord,
  ): WorkerRecordSnapshot {
    try {
      return this.#publishRecord(record);
    } catch (error) {
      Object.assign(record, previous);
      throw error;
    }
  }

  #isIssuedInstance(instance: WorkerInstanceRef): boolean {
    return typeof instance === "object" && instance !== null && this.#issuedInstances.has(instance);
  }
}
