import { loadRuntimeSettings } from "../config/runtime-settings.ts";
import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import { RuntimeMetrics } from "../metrics/runtime-metrics.ts";
import { SESSION_ID_LAYOUT } from "../protocol/session-id.ts";
import { createProcessPid, type ProcessPid } from "../protocol/worker-id.ts";
import type { RuntimeSettings } from "./runtime-server.ts";
import {
  SystemClock,
  SystemTimerScheduler,
  type Clock,
  type TimerScheduler,
} from "./clock.ts";
import { SequentialIdGenerator, type IdGenerator } from "./id-generator.ts";
import { ResourceScope, type RuntimeResource } from "./resource-scope.ts";
import {
  createStructuredLogRecord,
  NOOP_STRUCTURED_LOGGER,
  type StructuredLogLevel,
  type StructuredLogFields,
  type StructuredLogger,
} from "./structured-logger.ts";

export class RuntimeAbortError extends Error {
  readonly reason: unknown;

  constructor(message: string, reason?: unknown) {
    super(message);
    this.name = "RuntimeAbortError";
    this.reason = reason;
  }
}

export interface RuntimeContextOptions {
  readonly settings: unknown;
  readonly parentSignal?: AbortSignal;
  readonly logger?: StructuredLogger;
  readonly clock?: Clock;
  readonly timers?: TimerScheduler;
  readonly idGenerator?: IdGenerator<number>;
  readonly metrics?: RuntimeMetrics;
  readonly masterPid?: ProcessPid;
  readonly masterGeneration?: number;
}

function readErrorString(read: () => unknown, fallback: string): string {
  try {
    return String(read());
  } catch {
    return fallback;
  }
}

function describeTimerCallbackError(
  error: unknown,
): Readonly<Record<string, string>> {
  let errorValue: Error | null = null;
  try {
    if (error instanceof Error) {
      errorValue = error;
    }
  } catch {
    // Some proxy values can throw while their prototype chain is inspected.
  }

  if (errorValue !== null) {
    return {
      errorName: readErrorString(() => errorValue.name, "Error"),
      errorMessage: readErrorString(
        () => errorValue.message,
        "<unreadable error message>",
      ),
    };
  }
  return {
    errorName: "UnknownError",
    errorMessage: readErrorString(() => error, "<unprintable thrown value>"),
  };
}

export class RuntimeContext implements RuntimeResource {
  readonly settings: Readonly<RuntimeSettings>;
  readonly masterPid: ProcessPid;
  readonly masterGeneration: number;
  readonly clock: Clock;
  readonly timers: TimerScheduler;
  readonly idGenerator: IdGenerator<number>;
  readonly logger: StructuredLogger;
  readonly metrics: RuntimeMetrics;

  readonly #controller = new AbortController();
  readonly #resources: ResourceScope;
  #closePromise: Promise<void> | null = null;
  #closed = false;

  constructor(options: RuntimeContextOptions) {
    this.settings = loadRuntimeSettings(options.settings);
    this.masterPid = options.masterPid ?? createProcessPid(process.pid);
    const masterGeneration = options.masterGeneration ?? 1;
    if (
      !Number.isSafeInteger(masterGeneration) ||
      masterGeneration < 0 ||
      masterGeneration > SESSION_ID_LAYOUT.maxMasterGeneration
    ) {
      throw new RangeError(
        `masterGeneration must be a safe integer in [0, ${SESSION_ID_LAYOUT.maxMasterGeneration}]`,
      );
    }
    this.masterGeneration = masterGeneration;
    this.clock = options.clock ?? new SystemClock();
    this.idGenerator = options.idGenerator ?? new SequentialIdGenerator();
    this.logger = options.logger ?? NOOP_STRUCTURED_LOGGER;
    this.metrics = options.metrics ?? new RuntimeMetrics();
    this.metrics.setState("CREATED");
    this.timers = options.timers ?? new SystemTimerScheduler({
      clock: this.clock,
      onCallbackError: (error) => this.#reportTimerCallbackError(error),
    });

    this.#resources = new ResourceScope((size) => {
      this.metrics.setActiveResourceCount(size);
    });
    this.#resources.defer("runtime.timer-scheduler", (reason) =>
      this.timers.closeGlobally(reason),
    );

    const parentSignal = options.parentSignal;
    if (parentSignal !== undefined) {
      const forwardAbort = (): void => {
        this.requestStop(parentSignal.reason);
      };
      if (parentSignal.aborted) {
        forwardAbort();
      } else {
        parentSignal.addEventListener("abort", forwardAbort, { once: true });
        this.#resources.defer("runtime.parent-abort-listener", () => {
          parentSignal.removeEventListener("abort", forwardAbort);
        });
      }
    }
  }

  get signal(): AbortSignal {
    return this.#controller.signal;
  }

  get resourceCount(): number {
    return this.#resources.size;
  }

  get closed(): boolean {
    return this.#closed;
  }

  requestStop(reason?: unknown): boolean {
    if (this.signal.aborted) {
      return false;
    }
    this.#controller.abort(reason);
    return true;
  }

  registerResource<Resource extends RuntimeResource>(
    name: string,
    resource: Resource,
  ): Resource {
    this.#assertAcceptingResources();
    return this.#resources.use(name, resource);
  }

  deferResource(
    name: string,
    cleanup: (reason?: unknown) => void | Promise<void>,
  ): void {
    this.#assertAcceptingResources();
    this.#resources.defer(name, cleanup);
  }

  log(
    level: StructuredLogLevel,
    event: string,
    fields: StructuredLogFields = {},
  ): void {
    try {
      this.logger.write(
        createStructuredLogRecord(
          this.clock.wallTimeMs(),
          this.clock.monotonicTimeMs(),
          level,
          event,
          fields,
        ),
      );
    } catch {
      this.metrics.recordLogWriteError();
    }
  }

  closeFromResourceDisposer(reason?: unknown): Promise<void> | undefined {
    if (this.#closePromise === null) {
      return undefined;
    }
    const scopeClose = this.#resources.close(reason);
    return scopeClose === this.#closePromise ? undefined : scopeClose;
  }

  joinCloseFromCallback(): Promise<void> | undefined {
    return this.timers.joinCloseFromCallback();
  }

  closeGlobally(reason?: unknown): Promise<void> {
    if (this.#closePromise !== null) {
      return this.#closePromise;
    }

    const closePromise = this.#resources.close(reason);
    this.#closePromise = closePromise;
    void closePromise.then(
      () => {
        this.#closed = true;
      },
      () => {
        this.#closed = true;
      },
    );
    this.requestStop(reason ?? new RuntimeAbortError("RuntimeContext is closing"));
    return closePromise;
  }

  close(reason?: unknown): Promise<void> {
    const resourceClose = this.closeFromResourceDisposer(reason);
    if (resourceClose !== undefined) {
      return resourceClose;
    }

    const callbackClose = this.joinCloseFromCallback();
    const globalClose = this.closeGlobally(reason);
    return callbackClose ?? globalClose;
  }

  #reportTimerCallbackError(error: unknown): void {
    this.metrics.recordError();
    this.log("error", "runtime.timer.callback_failed", describeTimerCallbackError(error));
  }

  #assertAcceptingResources(): void {
    if (this.#closed || this.signal.aborted) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        "RuntimeContext cannot accept resources after stop was requested",
        { closed: this.#closed, aborted: this.signal.aborted },
      );
    }
  }
}
