import { PROCESS_ROLE } from "../protocol/process-role.ts";
import {
  createProcessPid,
  type ProcessPid,
  type TaskWorkerId,
  type WorkerGeneration,
  type WorkerId,
} from "../protocol/worker-id.ts";
import type {
  ChildProcessRole,
  ValidatedChildBootstrap,
} from "../process/child-control-protocol.ts";
import {
  RuntimeContext,
  type RuntimeContextOptions,
} from "./runtime-context.ts";
import type { RuntimeSettings } from "./runtime-server.ts";

export type WorkerRuntimeContextDependencies = Omit<
  RuntimeContextOptions,
  "settings" | "masterPid" | "masterGeneration"
>;

export class WorkerRuntimeContext extends RuntimeContext {
  readonly worker_id: WorkerId;
  readonly worker_pid: ProcessPid;
  readonly taskworker: boolean;
  readonly setting: Readonly<RuntimeSettings>;
  readonly master_pid: ProcessPid;
  readonly generation: WorkerGeneration;
  readonly role: ChildProcessRole;
  readonly taskWorkerId: TaskWorkerId | null;
  readonly configVersion: number;

  private constructor(
    bootstrap: ValidatedChildBootstrap,
    workerPid: ProcessPid,
    dependencies: WorkerRuntimeContextDependencies,
  ) {
    super({
      ...dependencies,
      settings: bootstrap.settings,
      masterPid: bootstrap.masterPid,
      masterGeneration: bootstrap.masterGeneration,
    });
    this.worker_id = bootstrap.workerId;
    this.worker_pid = workerPid;
    this.taskworker = bootstrap.role !== PROCESS_ROLE.WORKER;
    this.setting = this.settings;
    this.master_pid = this.masterPid;
    this.generation = bootstrap.workerGeneration;
    this.role = bootstrap.role;
    this.taskWorkerId = bootstrap.taskWorkerId;
    this.configVersion = bootstrap.configVersion;
    Object.freeze(this);
  }

  static fromValidatedBootstrap(
    bootstrap: ValidatedChildBootstrap,
    actualWorkerPid: number,
    dependencies: WorkerRuntimeContextDependencies = {},
  ): WorkerRuntimeContext {
    return new WorkerRuntimeContext(
      bootstrap,
      createProcessPid(actualWorkerPid),
      dependencies,
    );
  }
}

export function createWorkerRuntimeContext(
  bootstrap: ValidatedChildBootstrap,
  actualWorkerPid: number,
  dependencies: WorkerRuntimeContextDependencies = {},
): WorkerRuntimeContext {
  return WorkerRuntimeContext.fromValidatedBootstrap(
    bootstrap,
    actualWorkerPid,
    dependencies,
  );
}
