import { randomUUID } from "node:crypto";

import {
  FRAMEWORK_ERROR_CODE,
  FrameworkError,
  type FrameworkErrorCode,
} from "../errors/framework-error.ts";
import type { WorkerId } from "../protocol/worker-id.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import {
  LIFECYCLE_CONTROL_ACTION,
  createReloadRequest,
  createRestartRequest,
  createShutdownRequest,
  type LifecycleControlAction,
  type ValidatedChildBootstrap,
} from "./child-control-protocol.ts";
import {
  PROCESS_TRANSPORT_LANE,
  type ProcessTransport,
} from "./process-transport.ts";

export type WorkerLifecycleControlTransport = Pick<ProcessTransport, "send">;

export interface WorkerLifecycleControllerOptions {
  readonly bootstrap: ValidatedChildBootstrap;
  readonly transport: WorkerLifecycleControlTransport;
  readonly onDeliveryError?: (error: unknown) => void;
}

export interface WorkerLifecycleControllerStats {
  readonly closed: boolean;
  readonly acceptedRequests: number;
  readonly rejectedRequests: number;
  readonly restartRequests: number;
  readonly reloadRequests: number;
  readonly shutdownRequests: number;
  readonly deliveryErrors: number;
  readonly lastError: FrameworkErrorCode | null;
}

function asLifecycleErrorCode(error: unknown): FrameworkErrorCode {
  try {
    if (error instanceof FrameworkError) {
      return error.code;
    }
  } catch {
    // Hostile thrown values must remain inside the boolean lifecycle facade.
  }
  return FRAMEWORK_ERROR_CODE.INVALID_STATE;
}

export class WorkerLifecycleController implements RuntimeResource {
  readonly #bootstrap: ValidatedChildBootstrap;
  readonly #transport: WorkerLifecycleControlTransport;
  readonly #onDeliveryError: ((error: unknown) => void) | undefined;
  #sequence = 1;
  #closed = false;
  #acceptedRequests = 0;
  #rejectedRequests = 0;
  #restartRequests = 0;
  #reloadRequests = 0;
  #shutdownRequests = 0;
  #deliveryErrors = 0;
  #lastError: FrameworkErrorCode | null = null;

  constructor(options: WorkerLifecycleControllerOptions) {
    if (options.transport === null || typeof options.transport !== "object") {
      throw new TypeError("WorkerLifecycleController requires a ProcessTransport");
    }
    this.#bootstrap = options.bootstrap;
    this.#transport = options.transport;
    this.#onDeliveryError = options.onDeliveryError;
  }

  stop(targetWorkerId: WorkerId = this.#bootstrap.workerId): boolean {
    return this.#admit(LIFECYCLE_CONTROL_ACTION.RESTART_REQUEST, (request) =>
      createRestartRequest(this.#bootstrap, {
        ...request,
        targetWorkerId: this.#requireTargetWorkerId(targetWorkerId),
      })
    );
  }

  reload(onlyTaskWorkers = false): boolean {
    return this.#admit(LIFECYCLE_CONTROL_ACTION.RELOAD_REQUEST, (request) =>
      createReloadRequest(this.#bootstrap, {
        ...request,
        onlyTaskWorkers: this.#requireBoolean(
          "onlyTaskWorkers",
          onlyTaskWorkers,
        ),
      })
    );
  }

  shutdown(): boolean {
    return this.#admit(
      LIFECYCLE_CONTROL_ACTION.SHUTDOWN_REQUEST,
      (request) => createShutdownRequest(this.#bootstrap, request),
    );
  }

  getLastError(): FrameworkErrorCode | null {
    return this.#lastError;
  }

  stats(): Readonly<WorkerLifecycleControllerStats> {
    return Object.freeze({
      closed: this.#closed,
      acceptedRequests: this.#acceptedRequests,
      rejectedRequests: this.#rejectedRequests,
      restartRequests: this.#restartRequests,
      reloadRequests: this.#reloadRequests,
      shutdownRequests: this.#shutdownRequests,
      deliveryErrors: this.#deliveryErrors,
      lastError: this.#lastError,
    });
  }

  close(_reason?: unknown): void {
    this.#closed = true;
  }

  #admit(
    action: Exclude<
      LifecycleControlAction,
      | typeof LIFECYCLE_CONTROL_ACTION.DRAIN_REQUEST
      | typeof LIFECYCLE_CONTROL_ACTION.DRAINED
    >,
    createEnvelope: (request: {
      readonly messageId: string;
      readonly requestId: string;
      readonly sequence: number;
    }) => ReturnType<typeof createShutdownRequest>,
  ): boolean {
    try {
      if (this.#closed) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
          "Worker lifecycle controller is closed",
        );
      }
      const nonce = randomUUID();
      const requestId =
        `lifecycle:${this.#bootstrap.workerId}:${this.#bootstrap.workerGeneration}:${this.#sequence}:${nonce}`;
      const envelope = createEnvelope({
        messageId: `${action.toLowerCase()}:${requestId}`,
        requestId,
        sequence: this.#sequence,
      });
      const completion = this.#transport.send(
        envelope,
        PROCESS_TRANSPORT_LANE.CONTROL,
      );
      this.#sequence += 1;
      this.#acceptedRequests += 1;
      if (action === LIFECYCLE_CONTROL_ACTION.RESTART_REQUEST) {
        this.#restartRequests += 1;
      } else if (action === LIFECYCLE_CONTROL_ACTION.RELOAD_REQUEST) {
        this.#reloadRequests += 1;
      } else {
        this.#shutdownRequests += 1;
      }
      this.#lastError = null;
      void completion.catch((error: unknown) => {
        this.#deliveryErrors += 1;
        try {
          this.#onDeliveryError?.(error);
        } catch {
          // Delivery observers cannot change an already-returned admission result.
        }
      });
      return true;
    } catch (error) {
      this.#rejectedRequests += 1;
      this.#lastError = asLifecycleErrorCode(error);
      return false;
    }
  }

  #requireTargetWorkerId(value: unknown): WorkerId {
    const workerCount =
      this.#bootstrap.settings.worker_num + this.#bootstrap.settings.task_worker_num +
        (this.#bootstrap.settings.user_task_worker_num ?? 0);
    if (
      typeof value !== "number" ||
      !Number.isSafeInteger(value) ||
      value < 0 ||
      value >= workerCount
    ) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
        `Worker ${String(value)} is outside the configured process pool`,
        { workerId: value, workerCount },
      );
    }
    return value as WorkerId;
  }

  #requireBoolean(name: string, value: unknown): boolean {
    if (typeof value !== "boolean") {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        `${name} must be a boolean`,
      );
    }
    return value;
  }
}
