export const FRAMEWORK_ERROR_CODES = Object.freeze([
  "INVALID_STATE",
  "INVALID_SESSION",
  "SESSION_CLOSED",
  "STALE_GENERATION",
  "UNKNOWN_WORKER",
  "WORKER_NOT_READY",
  "IPC_CHANNEL_CLOSED",
  "IPC_QUEUE_FULL",
  "MESSAGE_TOO_LARGE",
  "OUTPUT_BUFFER_OVERFLOW",
  "READY_TIMEOUT",
  "DRAIN_TIMEOUT",
] as const);

export type FrameworkErrorCode = (typeof FRAMEWORK_ERROR_CODES)[number];

export const FRAMEWORK_ERROR_CODE = Object.freeze(
  Object.fromEntries(FRAMEWORK_ERROR_CODES.map((code) => [code, code])) as {
    readonly [Code in FrameworkErrorCode]: Code;
  },
);

export class FrameworkError extends Error {
  readonly code: FrameworkErrorCode;
  readonly details: Readonly<Record<string, unknown>>;

  constructor(
    code: FrameworkErrorCode,
    message: string,
    details: Readonly<Record<string, unknown>> = {},
  ) {
    super(message);
    this.name = "FrameworkError";
    this.code = code;
    this.details = Object.freeze({ ...details });
  }
}
