import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import {
  validateIpcEnvelope,
  type IpcEnvelopeV1,
  type IpcJsonValue,
  type IpcPayload,
} from "../protocol/ipc-envelope.ts";
import { isDecodedNodeIpcWireEnvelope } from "./node-ipc-wire.ts";

/**
 * 一条 IPC 信封能承载的字节上限。
 *
 * **这不是随手填的数字，别直接调大。** 它由「一个 WebSocket 单帧必须能装进一条 IPC
 * 信封」推出：`DEFAULT_WEB_SOCKET_MAX_MESSAGE_BYTES`(960 KiB) + 信封开销预留
 * (`DEFAULT_IPC_ENVELOPE_HEADROOM_BYTES`，64 KiB)。`tests/unit/websocket-protocol.test.ts`
 * 的 `S04-UNIT-WS-008` 断言的就是这个关系。
 *
 * 想承载更大的业务消息时，**不要只调这一个值** —— 单条消息上限必须显著小于 lane 队列
 * 上限（`DEFAULT_DATA_QUEUE_MAX_BYTES` 8 MiB / `DEFAULT_PROCESS_BUS_MAILBOX_MAX_BYTES` 8 MiB），
 * 否则一条满尺寸消息就会把整条 lane 占满，之后所有正常消息都撞 `IPC_QUEUE_FULL`。
 * 这个关系由 `assertMessageFitsLane()` 在构造期强制校验。
 */
export const DEFAULT_MAX_IPC_MESSAGE_BYTES = 1024 * 1024;

/**
 * 信封自身（13 个元数据字段 + 长度前缀）的预留量。
 * `DEFAULT_MAX_IPC_MESSAGE_BYTES` 与 WebSocket 单帧上限之间的差额就是它。
 */
export const DEFAULT_IPC_ENVELOPE_HEADROOM_BYTES = 64 * 1024;

/**
 * 单条消息上限最多只能占 lane 队列上限的 1/4。
 *
 * 取值理由：默认 1 MiB 消息 / 8 MiB lane = 8 条，留 4 条的余量既允许把消息调到 2 MiB，
 * 又保证队列里始终能同时放下多条消息，不会退化成「一条大消息独占整条 lane」。
 */
export const RECOMMENDED_MIN_MESSAGES_PER_LANE = 4;

export const IPC_ENVELOPE_KEYS = Object.freeze([
  "protocolVersion",
  "messageId",
  "messageType",
  "sourceRole",
  "sourceWorkerId",
  "sourceGeneration",
  "targetRole",
  "targetWorkerId",
  "correlationId",
  "sessionId",
  "sequence",
  "flags",
  "payload",
] as const satisfies readonly (keyof IpcEnvelopeV1)[]);

export interface IpcEnvelopeCodecOptions {
  readonly maxMessageBytes?: number;
}

export interface EncodedIpcEnvelope {
  readonly envelope: Readonly<IpcEnvelopeV1>;
  readonly byteLength: number;
}

const envelopeKeySet = new Set<PropertyKey>(IPC_ENVELOPE_KEYS);
const encodedEnvelopeCache = new WeakMap<object, EncodedIpcEnvelope>();
type PayloadCopyMode = "copy" | "owned" | "owned-binary";

function assertNonNegativeSafeInteger(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function hasExactEnvelopeShape(value: unknown): boolean {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const keys = Reflect.ownKeys(value);
  if (keys.length !== IPC_ENVELOPE_KEYS.length) {
    return false;
  }
  let ordered = true;
  for (let index = 0; index < keys.length; index += 1) {
    if (keys[index] !== IPC_ENVELOPE_KEYS[index]) {
      ordered = false;
      break;
    }
  }
  if (!ordered) {
    for (const key of keys) {
      if (!envelopeKeySet.has(key)) {
        return false;
      }
    }
  }
  for (const key of IPC_ENVELOPE_KEYS) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
      return false;
    }
  }
  return true;
}

function cloneJsonValue(value: IpcJsonValue): IpcJsonValue {
  if (value === null || typeof value !== "object") {
    return value;
  }

  if (Array.isArray(value)) {
    return Object.freeze(value.map((item) => cloneJsonValue(item)));
  }

  const objectValue = value as { readonly [key: string]: IpcJsonValue };
  const clone = Object.create(
    Object.getPrototypeOf(value),
  ) as Record<string, IpcJsonValue>;
  for (const key of Object.keys(value)) {
    Object.defineProperty(clone, key, {
      configurable: false,
      enumerable: true,
      value: cloneJsonValue(objectValue[key] as IpcJsonValue),
      writable: false,
    });
  }
  return Object.freeze(clone);
}

function clonePayload(payload: IpcPayload): IpcPayload {
  if (payload instanceof Uint8Array) {
    return Buffer.isBuffer(payload)
      ? Buffer.from(payload)
      : new Uint8Array(payload);
  }
  return cloneJsonValue(payload);
}

function snapshotEnvelope(
  envelope: IpcEnvelopeV1,
  copyPayload: boolean,
): Readonly<IpcEnvelopeV1> {
  return Object.freeze({
    protocolVersion: envelope.protocolVersion,
    messageId: envelope.messageId,
    messageType: envelope.messageType,
    sourceRole: envelope.sourceRole,
    sourceWorkerId: envelope.sourceWorkerId,
    sourceGeneration: envelope.sourceGeneration,
    targetRole: envelope.targetRole,
    targetWorkerId: envelope.targetWorkerId,
    correlationId: envelope.correlationId,
    sessionId: envelope.sessionId,
    sequence: envelope.sequence,
    flags: envelope.flags,
    payload: copyPayload ? clonePayload(envelope.payload) : envelope.payload,
  });
}

function jsonStringByteLength(value: string): number {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 0x20 || code === 0x22 || code === 0x5c || code > 0x7f) {
      return Buffer.byteLength(JSON.stringify(value), "utf8");
    }
  }
  return value.length + 2;
}

function nullableIntegerByteLength(value: number | null): number {
  return value === null ? 4 : String(value).length;
}

// Remove placeholder values once so binary hot paths only count dynamic fields.
const BINARY_ENVELOPE_FIXED_BYTES = (() => {
  const template = {
    protocolVersion: 1,
    messageId: "",
    messageType: "",
    sourceRole: "",
    sourceWorkerId: null,
    sourceGeneration: null,
    targetRole: "",
    targetWorkerId: null,
    correlationId: null,
    sessionId: null,
    sequence: 0,
    flags: 0,
    payload: "",
  };
  const dynamicBytes = jsonStringByteLength("") * 4 + 4 * 5 + 2;
  return Buffer.byteLength(JSON.stringify(template), "utf8") - dynamicBytes;
})();

function measureBinaryEnvelope(envelope: Readonly<IpcEnvelopeV1>): number {
  return BINARY_ENVELOPE_FIXED_BYTES +
    jsonStringByteLength(envelope.messageId) +
    envelope.messageType.length + 2 +
    envelope.sourceRole.length + 2 +
    nullableIntegerByteLength(envelope.sourceWorkerId) +
    nullableIntegerByteLength(envelope.sourceGeneration) +
    envelope.targetRole.length + 2 +
    nullableIntegerByteLength(envelope.targetWorkerId) +
    (envelope.correlationId === null
      ? 4
      : jsonStringByteLength(envelope.correlationId)) +
    nullableIntegerByteLength(envelope.sessionId) +
    String(envelope.sequence).length +
    String(envelope.flags).length +
    (envelope.payload as Uint8Array).byteLength;
}

function measureEnvelope(envelope: Readonly<IpcEnvelopeV1>): number {
  if (envelope.payload instanceof Uint8Array) {
    return measureBinaryEnvelope(envelope);
  }

  return Buffer.byteLength(JSON.stringify(envelope), "utf8");
}

function invalidEnvelope(
  value: unknown,
  requireExactShape: boolean,
): TypeError | undefined {
  if (
    requireExactShape &&
    !isDecodedNodeIpcWireEnvelope(value) &&
    !hasExactEnvelopeShape(value)
  ) {
    return new TypeError(
      `invalid IPC envelope: envelope must contain exactly these enumerable data fields: ${IPC_ENVELOPE_KEYS.join(", ")}`,
    );
  }

  const issues = validateIpcEnvelope(value);
  if (issues.length === 0) {
    return undefined;
  }
  const messages = issues.map((issue) => `${String(issue.field)}: ${issue.message}`);
  return new TypeError(`invalid IPC envelope: ${messages.join("; ")}`);
}

export class IpcEnvelopeCodec {
  readonly maxMessageBytes: number;

  constructor(
    options: IpcEnvelopeCodecOptions | number = {},
  ) {
    const maxMessageBytes = typeof options === "number"
      ? options
      : options.maxMessageBytes ?? DEFAULT_MAX_IPC_MESSAGE_BYTES;
    assertNonNegativeSafeInteger("maxMessageBytes", maxMessageBytes);
    this.maxMessageBytes = maxMessageBytes;
  }

  encode(envelope: IpcEnvelopeV1): EncodedIpcEnvelope {
    return this.#snapshot(envelope, true, "copy");
  }

  encodeLocal(envelope: IpcEnvelopeV1): EncodedIpcEnvelope {
    return this.#snapshot(envelope, false, "copy");
  }

  encodeOwned(envelope: IpcEnvelopeV1): EncodedIpcEnvelope {
    return this.#snapshot(envelope, false, "owned");
  }

  decode(value: unknown): EncodedIpcEnvelope {
    return this.#snapshot(value, true, "copy");
  }

  decodeOwned(value: unknown): EncodedIpcEnvelope {
    return this.#snapshot(value, true, "owned-binary");
  }

  #snapshot(
    value: unknown,
    requireExactShape: boolean,
    copyMode: PayloadCopyMode,
  ): EncodedIpcEnvelope {
    if (typeof value === "object" && value !== null) {
      const cached = encodedEnvelopeCache.get(value);
      if (cached !== undefined) {
        this.#assertMessageSize(cached.byteLength, cached.envelope);
        return cached;
      }
    }

    const error = invalidEnvelope(value, requireExactShape);
    if (error !== undefined) {
      throw error;
    }

    const source = value as IpcEnvelopeV1;
    const copyPayload = copyMode === "copy" ||
      (copyMode === "owned-binary" && !(source.payload instanceof Uint8Array));
    const envelope = snapshotEnvelope(source, copyPayload);
    const byteLength = measureEnvelope(envelope);
    this.#assertMessageSize(byteLength, envelope);
    const encoded = Object.freeze({ envelope, byteLength });
    encodedEnvelopeCache.set(envelope, encoded);
    return encoded;
  }

  /**
   * 超限时把「是哪条消息」一起报出来。
   *
   * 只报字节数的话，线上拿到 `MESSAGE_TOO_LARGE` 根本定位不到发送方，
   * 所以把 messageType / sessionId / correlationId / sequence 一并带上。
   */
  #assertMessageSize(byteLength: number, envelope?: Readonly<IpcEnvelopeV1>): void {
    if (byteLength > this.maxMessageBytes) {
      const locator = envelope === undefined
        ? {}
        : {
            messageType: envelope.messageType,
            sessionId: envelope.sessionId,
            correlationId: envelope.correlationId,
            sequence: envelope.sequence,
            sourceRole: envelope.sourceRole,
            sourceWorkerId: envelope.sourceWorkerId,
          };
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.MESSAGE_TOO_LARGE,
        `IPC message size ${byteLength} exceeds ${this.maxMessageBytes} bytes` +
          ` (messageType=${String(locator["messageType"])}` +
          ` sessionId=${String(locator["sessionId"])}` +
          ` correlationId=${String(locator["correlationId"])}` +
          ` sequence=${String(locator["sequence"])})`,
        { byteLength, maxMessageBytes: this.maxMessageBytes, ...locator },
      );
    }
  }
}
