import type { IpcJsonValue, IpcPayload } from "../protocol/ipc-envelope.ts";
import {
  createTaskWorkerId,
  createWorkerGeneration,
  createWorkerId,
  type TaskWorkerId,
  type WorkerGeneration,
  type WorkerId,
} from "../protocol/worker-id.ts";

export const TASK_PROTOCOL_VERSION = 1 as const;
export const TASK_PROTOCOL_HEADER_BYTES = 64;

export const TASK_PAYLOAD_KIND = Object.freeze({
  WORKER_DISPATCH: 1,
  SCHEDULED_DISPATCH: 2,
  FINISH: 3,
} as const);

export const TASK_PAYLOAD_ENCODING = Object.freeze({
  NONE: 0,
  JSON: 1,
  BINARY: 2,
} as const);

export const TASK_PROTOCOL_HEADER_OFFSETS = Object.freeze({
  VERSION: 0,
  KIND: 1,
  ENCODING: 2,
  FLAGS: 3,
  PAYLOAD_BYTES: 4,
  TASK_ID: 8,
  SOURCE_WORKER_ID: 16,
  SOURCE_GENERATION: 24,
  REQUESTED_TASK_WORKER_ID: 32,
  SELECTED_TASK_WORKER_ID: 40,
  SELECTED_WORKER_ID: 48,
  SELECTED_GENERATION: 56,
} as const);

export type TaskPayloadKind = (typeof TASK_PAYLOAD_KIND)[keyof typeof TASK_PAYLOAD_KIND];
export type TaskPayloadEncoding =
  (typeof TASK_PAYLOAD_ENCODING)[keyof typeof TASK_PAYLOAD_ENCODING];

export interface TaskKey {
  readonly taskId: number;
  readonly sourceWorkerId: WorkerId;
  readonly sourceGeneration: WorkerGeneration;
}

export interface TaskSelection {
  readonly selectedTaskWorkerId: TaskWorkerId;
  readonly selectedWorkerId: WorkerId;
  readonly selectedGeneration: WorkerGeneration;
}

export interface UnselectedTaskSelection {
  readonly selectedTaskWorkerId: null;
  readonly selectedWorkerId: null;
  readonly selectedGeneration: null;
}

export interface WorkerTaskDispatchPayload extends TaskKey {
  readonly protocolVersion: typeof TASK_PROTOCOL_VERSION;
  readonly kind: typeof TASK_PAYLOAD_KIND.WORKER_DISPATCH;
  readonly requestedTaskWorkerId: TaskWorkerId | null;
  readonly data: IpcPayload;
}

export interface ScheduledTaskDispatchPayload extends TaskKey, TaskSelection {
  readonly protocolVersion: typeof TASK_PROTOCOL_VERSION;
  readonly kind: typeof TASK_PAYLOAD_KIND.SCHEDULED_DISPATCH;
  readonly requestedTaskWorkerId: TaskWorkerId | null;
  readonly data: IpcPayload;
}

interface TaskFinishPayloadBase extends TaskKey {
  readonly protocolVersion: typeof TASK_PROTOCOL_VERSION;
  readonly kind: typeof TASK_PAYLOAD_KIND.FINISH;
}

export type TaskFinishWithoutResultPayload = TaskFinishPayloadBase &
  (TaskSelection | UnselectedTaskSelection) & {
    readonly hasResult: false;
  };

export interface TaskFinishWithResultPayload extends TaskFinishPayloadBase, TaskSelection {
  readonly hasResult: true;
  readonly result: IpcPayload;
}

export type TaskFinishPayload =
  | TaskFinishWithoutResultPayload
  | TaskFinishWithResultPayload;

export type TaskProtocolPayload =
  | WorkerTaskDispatchPayload
  | ScheduledTaskDispatchPayload
  | TaskFinishPayload;

export interface EncodeWorkerTaskDispatchPayloadOptions extends TaskKey {
  readonly requestedTaskWorkerId: TaskWorkerId | null;
  readonly data: IpcPayload;
}

export interface EncodeScheduledTaskDispatchPayloadOptions extends TaskKey, TaskSelection {
  readonly requestedTaskWorkerId: TaskWorkerId | null;
  readonly data: IpcPayload;
}

interface EncodeTaskFinishPayloadOptionsBase extends TaskKey {}

export type EncodeTaskFinishWithoutResultPayloadOptions = EncodeTaskFinishPayloadOptionsBase &
  (TaskSelection | UnselectedTaskSelection) & {
    readonly hasResult: false;
  };

export interface EncodeTaskFinishWithResultPayloadOptions
  extends EncodeTaskFinishPayloadOptionsBase, TaskSelection {
  readonly hasResult: true;
  readonly result: IpcPayload;
}

export type EncodeTaskFinishPayloadOptions =
  | EncodeTaskFinishWithoutResultPayloadOptions
  | EncodeTaskFinishWithResultPayloadOptions;

const UINT64_NULL = 0xffff_ffff_ffff_ffffn;
const UINT32_MAX = 0xffff_ffff;
const TASK_FLAG_HAS_RESULT = 1;
const TASK_ALLOWED_FLAGS = TASK_FLAG_HAS_RESULT;
const MAX_JSON_DEPTH = 100;
const strictTextDecoder = new TextDecoder("utf-8", { fatal: true });

interface EncodedApplicationPayload {
  readonly encoding: TaskPayloadEncoding;
  readonly bytes: Buffer;
}

interface DecodedHeader extends TaskKey {
  readonly kind: TaskPayloadKind;
  readonly encoding: TaskPayloadEncoding;
  readonly flags: number;
  readonly payload: Buffer;
  readonly requestedTaskWorkerId: TaskWorkerId | null;
  readonly selectedTaskWorkerId: TaskWorkerId | null;
  readonly selectedWorkerId: WorkerId | null;
  readonly selectedGeneration: WorkerGeneration | null;
}

function isUint8Array(value: unknown): value is Uint8Array {
  try {
    return value instanceof Uint8Array;
  } catch {
    return false;
  }
}

function copyBinary(value: Uint8Array, name: string): Buffer {
  try {
    return Buffer.from(value);
  } catch {
    throw new TypeError(`${name} must be an inspectable Uint8Array`);
  }
}

function inspectObject(value: object, name: string): {
  readonly prototype: object | null;
  readonly ownKeys: readonly PropertyKey[];
} {
  try {
    return {
      prototype: Object.getPrototypeOf(value),
      ownKeys: Reflect.ownKeys(value),
    };
  } catch {
    throw new TypeError(`${name} must be an inspectable JSON value`);
  }
}

function requireDataDescriptor(
  value: object,
  key: PropertyKey,
  name: string,
): PropertyDescriptor {
  let descriptor: PropertyDescriptor | undefined;
  try {
    descriptor = Object.getOwnPropertyDescriptor(value, key);
  } catch {
    throw new TypeError(`${name} must be an inspectable JSON data field`);
  }
  if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
    throw new TypeError(`${name} must be an enumerable JSON data field`);
  }
  return descriptor;
}

function snapshotJsonValue(
  value: unknown,
  name: string,
  seen: WeakSet<object>,
  depth: number,
): IpcJsonValue {
  if (depth > MAX_JSON_DEPTH) {
    throw new TypeError(`${name} exceeds the maximum JSON nesting depth`);
  }
  if (value === null || typeof value === "boolean" || typeof value === "string") {
    return value;
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new TypeError(`${name} numbers must be finite`);
    }
    return value;
  }
  if (typeof value !== "object" || isUint8Array(value)) {
    throw new TypeError(`${name} must be JSON-safe or a top-level Uint8Array`);
  }
  if (seen.has(value)) {
    throw new TypeError(`${name} must not contain cycles`);
  }

  seen.add(value);
  try {
    if (Array.isArray(value)) {
      const { ownKeys } = inspectObject(value, name);
      const expectedKeys = new Set<PropertyKey>(["length"]);
      const snapshot: IpcJsonValue[] = [];
      for (let index = 0; index < value.length; index += 1) {
        const key = String(index);
        expectedKeys.add(key);
        const descriptor = requireDataDescriptor(value, key, `${name}[${index}]`);
        snapshot.push(snapshotJsonValue(
          descriptor.value,
          `${name}[${index}]`,
          seen,
          depth + 1,
        ));
      }
      if (ownKeys.length !== expectedKeys.size || ownKeys.some((key) => !expectedKeys.has(key))) {
        throw new TypeError(`${name} arrays must not contain holes or extra properties`);
      }
      return Object.freeze(snapshot);
    }

    const { prototype, ownKeys } = inspectObject(value, name);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new TypeError(`${name} objects must have Object or null prototype`);
    }
    const snapshot: Record<string, IpcJsonValue> = {};
    for (const key of ownKeys) {
      if (typeof key !== "string") {
        throw new TypeError(`${name} objects must not contain symbol keys`);
      }
      const descriptor = requireDataDescriptor(value, key, `${name}.${key}`);
      Object.defineProperty(snapshot, key, {
        configurable: false,
        enumerable: true,
        writable: false,
        value: snapshotJsonValue(descriptor.value, `${name}.${key}`, seen, depth + 1),
      });
    }
    return Object.freeze(snapshot);
  } finally {
    seen.delete(value);
  }
}

function encodeApplicationPayload(value: IpcPayload, name: string): EncodedApplicationPayload {
  if (isUint8Array(value)) {
    return {
      encoding: TASK_PAYLOAD_ENCODING.BINARY,
      bytes: copyBinary(value, name),
    };
  }

  const snapshot = snapshotJsonValue(value, name, new WeakSet<object>(), 0);
  let serialized: string;
  try {
    serialized = JSON.stringify(snapshot);
  } catch {
    throw new TypeError(`${name} must be serializable JSON`);
  }
  return {
    encoding: TASK_PAYLOAD_ENCODING.JSON,
    bytes: Buffer.from(serialized, "utf8"),
  };
}

function decodeApplicationPayload(
  encoding: TaskPayloadEncoding,
  payload: Buffer,
  name: string,
): IpcPayload {
  if (encoding === TASK_PAYLOAD_ENCODING.BINARY) {
    return Buffer.from(payload);
  }
  if (encoding !== TASK_PAYLOAD_ENCODING.JSON) {
    throw new TypeError(`${name} must use JSON or binary encoding`);
  }

  let text: string;
  try {
    text = strictTextDecoder.decode(payload);
  } catch {
    throw new TypeError(`${name} JSON contains invalid UTF-8`);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    throw new TypeError(`${name} contains invalid JSON`);
  }
  return snapshotJsonValue(parsed, name, new WeakSet<object>(), 0);
}

function requireSafeInteger(value: unknown, name: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 0) {
    throw new TypeError(`${name} must be a non-negative safe integer`);
  }
  return value as number;
}

function requireWorkerId(value: unknown, name: string): WorkerId {
  return createWorkerId(requireSafeInteger(value, name));
}

function requireTaskWorkerId(value: unknown, name: string): TaskWorkerId {
  return createTaskWorkerId(requireSafeInteger(value, name));
}

function requireGeneration(value: unknown, name: string): WorkerGeneration {
  return createWorkerGeneration(requireSafeInteger(value, name));
}

function requireNullableTaskWorkerId(
  value: unknown,
  name: string,
): TaskWorkerId | null {
  return value === null ? null : requireTaskWorkerId(value, name);
}

function assertPayloadSize(byteLength: number): void {
  if (byteLength > UINT32_MAX) {
    throw new RangeError(`Task payload exceeds ${UINT32_MAX} bytes`);
  }
}

function writeSafeInteger(payload: Buffer, offset: number, value: unknown, name: string): void {
  payload.writeBigUInt64BE(BigInt(requireSafeInteger(value, name)), offset);
}

function writeNullableTaskWorkerId(
  payload: Buffer,
  offset: number,
  value: unknown,
  name: string,
): void {
  if (value === null) {
    payload.writeBigUInt64BE(UINT64_NULL, offset);
    return;
  }
  payload.writeBigUInt64BE(BigInt(requireTaskWorkerId(value, name)), offset);
}

function writeNullField(payload: Buffer, offset: number): void {
  payload.writeBigUInt64BE(UINT64_NULL, offset);
}

function createPayload(
  kind: TaskPayloadKind,
  options: TaskKey,
  requestedTaskWorkerId: TaskWorkerId | null,
  selection: TaskSelection | null,
  applicationPayload: EncodedApplicationPayload,
  flags: number,
): Buffer {
  assertPayloadSize(applicationPayload.bytes.byteLength);
  const payload = Buffer.alloc(TASK_PROTOCOL_HEADER_BYTES + applicationPayload.bytes.byteLength);
  payload[TASK_PROTOCOL_HEADER_OFFSETS.VERSION] = TASK_PROTOCOL_VERSION;
  payload[TASK_PROTOCOL_HEADER_OFFSETS.KIND] = kind;
  payload[TASK_PROTOCOL_HEADER_OFFSETS.ENCODING] = applicationPayload.encoding;
  payload[TASK_PROTOCOL_HEADER_OFFSETS.FLAGS] = flags;
  payload.writeUInt32BE(applicationPayload.bytes.byteLength, TASK_PROTOCOL_HEADER_OFFSETS.PAYLOAD_BYTES);
  writeSafeInteger(payload, TASK_PROTOCOL_HEADER_OFFSETS.TASK_ID, options.taskId, "taskId");
  writeSafeInteger(
    payload,
    TASK_PROTOCOL_HEADER_OFFSETS.SOURCE_WORKER_ID,
    options.sourceWorkerId,
    "sourceWorkerId",
  );
  writeSafeInteger(
    payload,
    TASK_PROTOCOL_HEADER_OFFSETS.SOURCE_GENERATION,
    options.sourceGeneration,
    "sourceGeneration",
  );
  writeNullableTaskWorkerId(
    payload,
    TASK_PROTOCOL_HEADER_OFFSETS.REQUESTED_TASK_WORKER_ID,
    requestedTaskWorkerId,
    "requestedTaskWorkerId",
  );

  if (selection === null) {
    writeNullField(payload, TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_TASK_WORKER_ID);
    writeNullField(payload, TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_WORKER_ID);
    writeNullField(payload, TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_GENERATION);
  } else {
    writeSafeInteger(
      payload,
      TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_TASK_WORKER_ID,
      selection.selectedTaskWorkerId,
      "selectedTaskWorkerId",
    );
    writeSafeInteger(
      payload,
      TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_WORKER_ID,
      selection.selectedWorkerId,
      "selectedWorkerId",
    );
    writeSafeInteger(
      payload,
      TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_GENERATION,
      selection.selectedGeneration,
      "selectedGeneration",
    );
  }
  payload.set(applicationPayload.bytes, TASK_PROTOCOL_HEADER_BYTES);
  return payload;
}

export function encodeWorkerTaskDispatchPayload(
  options: EncodeWorkerTaskDispatchPayloadOptions,
): Buffer {
  const requestedTaskWorkerId = requireNullableTaskWorkerId(
    options.requestedTaskWorkerId,
    "requestedTaskWorkerId",
  );
  return createPayload(
    TASK_PAYLOAD_KIND.WORKER_DISPATCH,
    options,
    requestedTaskWorkerId,
    null,
    encodeApplicationPayload(options.data, "Task dispatch data"),
    0,
  );
}

export function encodeScheduledTaskDispatchPayload(
  options: EncodeScheduledTaskDispatchPayloadOptions,
): Buffer {
  const requestedTaskWorkerId = requireNullableTaskWorkerId(
    options.requestedTaskWorkerId,
    "requestedTaskWorkerId",
  );
  return createPayload(
    TASK_PAYLOAD_KIND.SCHEDULED_DISPATCH,
    options,
    requestedTaskWorkerId,
    options,
    encodeApplicationPayload(options.data, "Scheduled task data"),
    0,
  );
}

export function encodeTaskFinishPayload(options: EncodeTaskFinishPayloadOptions): Buffer {
  const applicationPayload: EncodedApplicationPayload = options.hasResult
    ? encodeApplicationPayload(options.result, "Task finish result")
    : { encoding: TASK_PAYLOAD_ENCODING.NONE, bytes: Buffer.alloc(0) };
  const selection = optionalSelection(options);
  if (options.hasResult && selection === null) {
    throw new TypeError("Task finish with a result requires a selected Task Worker identity");
  }
  return createPayload(
    TASK_PAYLOAD_KIND.FINISH,
    options,
    null,
    selection,
    applicationPayload,
    options.hasResult ? TASK_FLAG_HAS_RESULT : 0,
  );
}

function optionalSelection(
  value: TaskSelection | UnselectedTaskSelection,
): TaskSelection | null {
  const fields = [
    value.selectedTaskWorkerId,
    value.selectedWorkerId,
    value.selectedGeneration,
  ];
  if (fields.every((field) => field === null)) {
    return null;
  }
  if (fields.some((field) => field === null)) {
    throw new TypeError("Task selection must be complete or entirely null");
  }
  return {
    selectedTaskWorkerId: requireTaskWorkerId(
      value.selectedTaskWorkerId,
      "selectedTaskWorkerId",
    ),
    selectedWorkerId: requireWorkerId(value.selectedWorkerId, "selectedWorkerId"),
    selectedGeneration: requireGeneration(
      value.selectedGeneration,
      "selectedGeneration",
    ),
  };
}

function requireKind(value: number): TaskPayloadKind {
  if (
    value !== TASK_PAYLOAD_KIND.WORKER_DISPATCH &&
    value !== TASK_PAYLOAD_KIND.SCHEDULED_DISPATCH &&
    value !== TASK_PAYLOAD_KIND.FINISH
  ) {
    throw new TypeError("Task payload contains an unknown kind");
  }
  return value;
}

function requireEncoding(value: number): TaskPayloadEncoding {
  if (
    value !== TASK_PAYLOAD_ENCODING.NONE &&
    value !== TASK_PAYLOAD_ENCODING.JSON &&
    value !== TASK_PAYLOAD_ENCODING.BINARY
  ) {
    throw new TypeError("Task payload contains an unknown encoding");
  }
  return value;
}

function readSafeInteger(payload: Buffer, offset: number, name: string): number {
  const value = payload.readBigUInt64BE(offset);
  if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new TypeError(`${name} must be a non-negative safe integer`);
  }
  return Number(value);
}

function readNullableTaskWorkerId(
  payload: Buffer,
  offset: number,
  name: string,
): TaskWorkerId | null {
  const value = payload.readBigUInt64BE(offset);
  if (value === UINT64_NULL) {
    return null;
  }
  if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new TypeError(`${name} must be null or a non-negative safe integer`);
  }
  return createTaskWorkerId(Number(value));
}

function decodeHeader(value: unknown): DecodedHeader {
  if (!isUint8Array(value) || value.byteLength < TASK_PROTOCOL_HEADER_BYTES) {
    throw new TypeError("Task payload must contain a complete fixed binary header");
  }
  const bytes = copyBinary(value, "Task payload");
  if (bytes[TASK_PROTOCOL_HEADER_OFFSETS.VERSION] !== TASK_PROTOCOL_VERSION) {
    throw new TypeError("Task payload has an unsupported version");
  }
  const kind = requireKind(bytes[TASK_PROTOCOL_HEADER_OFFSETS.KIND]!);
  const encoding = requireEncoding(bytes[TASK_PROTOCOL_HEADER_OFFSETS.ENCODING]!);
  const flags = bytes[TASK_PROTOCOL_HEADER_OFFSETS.FLAGS]!;
  if ((flags & ~TASK_ALLOWED_FLAGS) !== 0) {
    throw new TypeError("Task payload contains unknown flags");
  }
  const payloadBytes = bytes.readUInt32BE(TASK_PROTOCOL_HEADER_OFFSETS.PAYLOAD_BYTES);
  const expectedBytes = TASK_PROTOCOL_HEADER_BYTES + payloadBytes;
  if (bytes.byteLength !== expectedBytes) {
    throw new TypeError(
      bytes.byteLength < expectedBytes
        ? "Task payload body is truncated"
        : "Task payload contains trailing bytes",
    );
  }

  return {
    kind,
    encoding,
    flags,
    payload: Buffer.from(bytes.subarray(TASK_PROTOCOL_HEADER_BYTES)),
    taskId: readSafeInteger(bytes, TASK_PROTOCOL_HEADER_OFFSETS.TASK_ID, "taskId"),
    sourceWorkerId: requireWorkerId(
      readSafeInteger(bytes, TASK_PROTOCOL_HEADER_OFFSETS.SOURCE_WORKER_ID, "sourceWorkerId"),
      "sourceWorkerId",
    ),
    sourceGeneration: requireGeneration(
      readSafeInteger(
        bytes,
        TASK_PROTOCOL_HEADER_OFFSETS.SOURCE_GENERATION,
        "sourceGeneration",
      ),
      "sourceGeneration",
    ),
    requestedTaskWorkerId: readNullableTaskWorkerId(
      bytes,
      TASK_PROTOCOL_HEADER_OFFSETS.REQUESTED_TASK_WORKER_ID,
      "requestedTaskWorkerId",
    ),
    selectedTaskWorkerId: readNullableTaskWorkerId(
      bytes,
      TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_TASK_WORKER_ID,
      "selectedTaskWorkerId",
    ),
    selectedWorkerId: (() => {
      const value = bytes.readBigUInt64BE(TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_WORKER_ID);
      return value === UINT64_NULL
        ? null
        : requireWorkerId(Number(value), "selectedWorkerId");
    })(),
    selectedGeneration: (() => {
      const value = bytes.readBigUInt64BE(TASK_PROTOCOL_HEADER_OFFSETS.SELECTED_GENERATION);
      return value === UINT64_NULL
        ? null
        : requireGeneration(Number(value), "selectedGeneration");
    })(),
  };
}

function requireNoSelection(header: DecodedHeader): void {
  if (
    header.selectedTaskWorkerId !== null ||
    header.selectedWorkerId !== null ||
    header.selectedGeneration !== null
  ) {
    throw new TypeError("Worker task dispatch must not contain a selected Task Worker");
  }
}

function requireSelection(header: DecodedHeader): TaskSelection {
  if (
    header.selectedTaskWorkerId === null ||
    header.selectedWorkerId === null ||
    header.selectedGeneration === null
  ) {
    throw new TypeError("Task payload requires a complete selected Task Worker identity");
  }
  return {
    selectedTaskWorkerId: header.selectedTaskWorkerId,
    selectedWorkerId: header.selectedWorkerId,
    selectedGeneration: header.selectedGeneration,
  };
}

function optionalDecodedSelection(
  header: DecodedHeader,
): TaskSelection | UnselectedTaskSelection {
  const fields = [
    header.selectedTaskWorkerId,
    header.selectedWorkerId,
    header.selectedGeneration,
  ];
  if (fields.every((field) => field === null)) {
    return {
      selectedTaskWorkerId: null,
      selectedWorkerId: null,
      selectedGeneration: null,
    };
  }
  if (fields.some((field) => field === null)) {
    throw new TypeError("Task payload selection must be complete or entirely null");
  }
  return requireSelection(header);
}

function assertDispatchHeader(header: DecodedHeader): void {
  if (header.flags !== 0) {
    throw new TypeError("Task dispatch flags must be zero");
  }
  if (header.encoding === TASK_PAYLOAD_ENCODING.NONE) {
    throw new TypeError("Task dispatch must contain JSON or binary data");
  }
}

export function decodeTaskProtocolPayload(value: unknown): Readonly<TaskProtocolPayload> {
  const header = decodeHeader(value);
  const taskKey = {
    taskId: header.taskId,
    sourceWorkerId: header.sourceWorkerId,
    sourceGeneration: header.sourceGeneration,
  } as const;

  if (header.kind === TASK_PAYLOAD_KIND.WORKER_DISPATCH) {
    assertDispatchHeader(header);
    requireNoSelection(header);
    return Object.freeze({
      protocolVersion: TASK_PROTOCOL_VERSION,
      kind: TASK_PAYLOAD_KIND.WORKER_DISPATCH,
      ...taskKey,
      requestedTaskWorkerId: header.requestedTaskWorkerId,
      data: decodeApplicationPayload(header.encoding, header.payload, "Task dispatch data"),
    });
  }

  if (header.kind === TASK_PAYLOAD_KIND.SCHEDULED_DISPATCH) {
    assertDispatchHeader(header);
    const selection = requireSelection(header);
    return Object.freeze({
      protocolVersion: TASK_PROTOCOL_VERSION,
      kind: TASK_PAYLOAD_KIND.SCHEDULED_DISPATCH,
      ...taskKey,
      requestedTaskWorkerId: header.requestedTaskWorkerId,
      ...selection,
      data: decodeApplicationPayload(header.encoding, header.payload, "Scheduled task data"),
    });
  }

  if (header.requestedTaskWorkerId !== null) {
    throw new TypeError("Task finish must not contain a requested Task Worker ID");
  }
  const hasResult = (header.flags & TASK_FLAG_HAS_RESULT) !== 0;
  if (!hasResult) {
    if (header.encoding !== TASK_PAYLOAD_ENCODING.NONE || header.payload.byteLength !== 0) {
      throw new TypeError("Task finish without a result must use empty NONE encoding");
    }
    return Object.freeze({
      protocolVersion: TASK_PROTOCOL_VERSION,
      kind: TASK_PAYLOAD_KIND.FINISH,
      ...taskKey,
      ...optionalDecodedSelection(header),
      hasResult: false,
    });
  }
  if (header.encoding === TASK_PAYLOAD_ENCODING.NONE) {
    throw new TypeError("Task finish with a result must use JSON or binary encoding");
  }
  const selection = requireSelection(header);
  return Object.freeze({
    protocolVersion: TASK_PROTOCOL_VERSION,
    kind: TASK_PAYLOAD_KIND.FINISH,
    ...taskKey,
    ...selection,
    hasResult: true,
    result: decodeApplicationPayload(header.encoding, header.payload, "Task finish result"),
  });
}

export function decodeWorkerTaskDispatchPayload(
  value: unknown,
): Readonly<WorkerTaskDispatchPayload> {
  const payload = decodeTaskProtocolPayload(value);
  if (payload.kind !== TASK_PAYLOAD_KIND.WORKER_DISPATCH) {
    throw new TypeError("Task payload is not a Worker-to-Master dispatch");
  }
  return payload;
}

export function decodeScheduledTaskDispatchPayload(
  value: unknown,
): Readonly<ScheduledTaskDispatchPayload> {
  const payload = decodeTaskProtocolPayload(value);
  if (payload.kind !== TASK_PAYLOAD_KIND.SCHEDULED_DISPATCH) {
    throw new TypeError("Task payload is not a Master-to-Task dispatch");
  }
  return payload;
}

export function decodeTaskFinishPayload(value: unknown): Readonly<TaskFinishPayload> {
  const payload = decodeTaskProtocolPayload(value);
  if (payload.kind !== TASK_PAYLOAD_KIND.FINISH) {
    throw new TypeError("Task payload is not a Task finish");
  }
  return payload;
}
