const CONTROL_MESSAGE_TYPES: ReadonlySet<IpcMessageType> = new Set([
  IPC_MESSAGE_TYPE.CONTROL_BOOTSTRAP,
  IPC_MESSAGE_TYPE.CONTROL_READY,
  IPC_MESSAGE_TYPE.CONTROL_DRAIN,
  IPC_MESSAGE_TYPE.CONTROL_SHUTDOWN,
  IPC_MESSAGE_TYPE.CONTROL_HEARTBEAT,
  IPC_MESSAGE_TYPE.CONTROL_CAPACITY,
]);

export type WorkerEntryPhase =
  | "bootstrap"
  | "initializing"
  | "running"
  | "draining"
  | "stopping";

export const DEFAULT_WORKER_ENTRY_BUSINESS_MAX_MESSAGES =
  DEFAULT_DATA_QUEUE_MAX_MESSAGES;
export const DEFAULT_WORKER_ENTRY_BUSINESS_MAX_BYTES =
  DEFAULT_DATA_QUEUE_MAX_BYTES;
export const DEFAULT_WORKER_ENTRY_BUSINESS_HIGH_MESSAGES =
  DEFAULT_DATA_QUEUE_HIGH_MESSAGES;
export const DEFAULT_WORKER_ENTRY_BUSINESS_HIGH_BYTES =
  DEFAULT_DATA_QUEUE_HIGH_BYTES;
export const DEFAULT_WORKER_ENTRY_BUSINESS_LOW_MESSAGES =
  DEFAULT_DATA_QUEUE_LOW_MESSAGES;
export const DEFAULT_WORKER_ENTRY_BUSINESS_LOW_BYTES =
  DEFAULT_DATA_QUEUE_LOW_BYTES;

interface Deferred<Value> {
  readonly promise: Promise<Value>;
  readonly resolve: (value: Value) => void;
  readonly reject: (reason?: unknown) => void;
}

export interface WorkerEntryStop {
  readonly reason: unknown;
  readonly failed: boolean;
  readonly invokeWorkerStop: boolean;
}

export interface WorkerEntryMessageMuxOptions {
  readonly codec?: IpcEnvelopeCodec;
  readonly businessMaxMessages?: number;
  readonly businessMaxBytes?: number;
  readonly businessHighMessages?: number;
  readonly businessHighBytes?: number;
  readonly businessLowMessages?: number;
  readonly businessLowBytes?: number;
  readonly onBusinessCapacityChange?: WorkerEntryBusinessCapacityListener;
  /** 父进程断开后清理流程的宽限时间，超过就强制退出。默认 DEFAULT_PARENT_DISCONNECT_EXIT_GRACE_MS */
  readonly parentDisconnectExitGraceMs?: number;
  /** 强制退出动作，可注入以便测试。默认 process.exit(1) */
  readonly forceExit?: (code: number) => void;
}

export interface WorkerEntryBusinessCapacityState {
  readonly pressured: boolean;
  readonly pendingMessages: number;
  readonly pendingBytes: number;
  readonly maxMessages: number;
  readonly maxBytes: number;
  readonly highWaterMessages: number;
  readonly highWaterBytes: number;
  readonly lowWaterMessages: number;
  readonly lowWaterBytes: number;
}

export type WorkerEntryBusinessCapacityListener = (
  state: Readonly<WorkerEntryBusinessCapacityState>,
) => void;

export interface WorkerEntryMessageMuxStats {
  readonly phase: WorkerEntryPhase;
  readonly stopping: boolean;
  readonly maxMessages: number;
  readonly maxBytes: number;
  readonly pressured: boolean;
  readonly highWaterMessages: number;
  readonly highWaterBytes: number;
  readonly lowWaterMessages: number;
  readonly lowWaterBytes: number;
  readonly pendingMessages: number;
  readonly pendingBytes: number;
  readonly queuedMessages: number;
  readonly queuedBytes: number;
  readonly inFlightMessages: 0 | 1;
  readonly inFlightBytes: number;
  readonly acceptedMessages: number;
  readonly rejectedMessages: number;
  readonly completedMessages: number;
  readonly failedMessages: number;
  readonly draining: boolean;
}

export interface WorkerEntryBusinessBus {
  acceptFrom(
    peer: ProcessBusPeerHandle,
    envelope: IpcEnvelopeV1,
  ): Promise<void>;
}

type PendingBusinessMessage = EncodedIpcEnvelope;

export interface WorkerEntryInitializerContext {
  readonly context: WorkerRuntimeContext;
  readonly sharedState: SharedRuntimeStateReader;
  readonly bus: ProcessBus;
  readonly networkEvents: WorkerNetworkEventReceiver | null;
  readonly networkCommands: WorkerNetworkCommandSender;
  readonly tasks: WorkerTaskRuntime;
  readonly processMessages: WorkerProcessMessenger;
  readonly lifecycle: WorkerLifecycleController;
}

export type WorkerEntryInitializer = (
  runtime: Readonly<WorkerEntryInitializerContext>,
) => void | Promise<void>;

export interface RunWorkerEntryOptions {
  readonly sharedStateProvider?: SharedRuntimeStateProvider;
  readonly initialize?: WorkerEntryInitializer;
  readonly onReady?: (
    runtime: Readonly<WorkerEntryInitializerContext>,
  ) => void;
  readonly onWorkerExit?: WorkerEntryInitializer;
  readonly onWorkerStop?: WorkerEntryInitializer;
}

function createDeferred<Value>(): Deferred<Value> {
  let resolve!: (value: Value) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<Value>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function assertCapacity(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function assertWatermarkOrder(
  name: string,
  low: number,
  high: number,
  max: number,
): void {
  if (low > high || high > max) {
    throw new RangeError(
      `${name} watermarks must satisfy low <= high <= max, got ${low} <= ${high} <= ${max}`,
    );
  }
}

function parentDisconnectReason(result: Readonly<NodeParentProcessCloseResult>): Error {
  return result.reason === "not-connected"
    ? new Error("Worker entry requires an active Node IPC channel")
    : new Error(
      "Master IPC disconnected",
      result.error === undefined ? undefined : { cause: result.error },
    );
}

/**
 * 父进程 IPC 断开后，清理流程最多允许跑多久，超过就强制退出。
 *
 * 父进程被 `SIGKILL` 后，子进程靠 `disconnect` 事件进入清理流程（这是设计好的自愈路径）。
 * 但如果清理被某个卡住的 IO 拖住，这个进程就会变成孤儿，一直占着端口和内存，只能靠外部
 * supervisor 收尸。这个兜底 timer 用 `unref()`，清理正常完成时进程会自然退出，
 * 它不会拖住事件循环；只有清理真的卡住时才会生效。
 *
 * 10s 的依据：正常停机（drain + 释放共享内存）远快于它，而外部 supervisor 的探测周期
 * 通常是 10s 量级，早于它退出才有意义。
 */
export const DEFAULT_PARENT_DISCONNECT_EXIT_GRACE_MS = 10_000;

/**
 * 默认的强制退出动作。
 *
 * 走 stderr 而不是业务日志：这条路径只有在父进程已经没了、且清理卡住时才会触发，
 * 此刻业务日志通道很可能已经不可用，stderr 是唯一还能确定落地的出口。
 * alloy-core 其余部分不写 stdout/stderr，这里是刻意的例外，因为它是最后兜底。
 */
function defaultForcedExit(code: number): void {
  process.stderr.write(
    `[alloy-core] worker ${String(process.pid)} forced exit ${String(code)}: ` +
      "master IPC disconnected and cleanup did not finish in time\n",
  );
  process.exit(code);
}

export class WorkerEntryMessageMux {
  readonly #bootstrap = createDeferred<ValidatedChildBootstrap>();
  readonly #stopped = createDeferred<Readonly<WorkerEntryStop>>();
  readonly #codec: IpcEnvelopeCodec;
  readonly #businessMaxMessages: number;
  readonly #businessMaxBytes: number;
  readonly #businessHighMessages: number;
  readonly #businessHighBytes: number;
  readonly #businessLowMessages: number;
  readonly #businessLowBytes: number;
  readonly #onBusinessCapacityChange: WorkerEntryBusinessCapacityListener | undefined;
  readonly #parentDisconnectExitGraceMs: number;
  readonly #forceExit: (code: number) => void;
  readonly #businessQueue: PendingBusinessMessage[] = [];
  #phase: WorkerEntryPhase = "bootstrap";
  #bootstrapValue: ValidatedChildBootstrap | undefined;
  #context: WorkerRuntimeContext | undefined;
  #bus: WorkerEntryBusinessBus | undefined;
  #masterPeer: ProcessBusPeerHandle | undefined;
  #stopOutcome: Readonly<WorkerEntryStop> | undefined;
  #activeDrainRequest: Readonly<ValidatedDrainRequest> | undefined;
  #drainRequestWaiter:
    | Deferred<Readonly<ValidatedDrainRequest> | null>
    | undefined;
  readonly #queuedDrainRequests: Readonly<ValidatedDrainRequest>[] = [];
  #businessInFlight: PendingBusinessMessage | undefined;
  #businessPendingMessages = 0;
  #businessPendingBytes = 0;
  #businessQueuedBytes = 0;
  #businessPressured = false;
  #acceptedBusinessMessages = 0;
  #rejectedBusinessMessages = 0;
  #completedBusinessMessages = 0;
  #failedBusinessMessages = 0;
  #drainDeferred: Deferred<void> | undefined;
  #disposeMessage: ProcessTransportListenerDisposer;
  #disposeProtocolError: ProcessTransportListenerDisposer;
  /** 父进程断开后武装的硬退出兜底，见 #armForcedExit */
  #forcedExitTimer: ReturnType<typeof globalThis.setTimeout> | undefined;

  constructor(
    transport: ProcessTransport,
    endpoint: Pick<NodeParentProcessEndpoint, "closed">,
    options: WorkerEntryMessageMuxOptions = {},
  ) {
    const businessMaxMessages = options.businessMaxMessages ??
      DEFAULT_WORKER_ENTRY_BUSINESS_MAX_MESSAGES;
    const businessMaxBytes = options.businessMaxBytes ??
      DEFAULT_WORKER_ENTRY_BUSINESS_MAX_BYTES;
    const businessHighMessages = options.businessHighMessages ??
      Math.min(DEFAULT_WORKER_ENTRY_BUSINESS_HIGH_MESSAGES, businessMaxMessages);
    const businessHighBytes = options.businessHighBytes ??
      Math.min(DEFAULT_WORKER_ENTRY_BUSINESS_HIGH_BYTES, businessMaxBytes);
    const businessLowMessages = options.businessLowMessages ??
      Math.min(DEFAULT_WORKER_ENTRY_BUSINESS_LOW_MESSAGES, businessHighMessages);
    const businessLowBytes = options.businessLowBytes ??
      Math.min(DEFAULT_WORKER_ENTRY_BUSINESS_LOW_BYTES, businessHighBytes);
    assertCapacity("businessMaxMessages", businessMaxMessages);
    assertCapacity("businessMaxBytes", businessMaxBytes);
    assertCapacity("businessHighMessages", businessHighMessages);
    assertCapacity("businessHighBytes", businessHighBytes);
    assertCapacity("businessLowMessages", businessLowMessages);
    assertCapacity("businessLowBytes", businessLowBytes);
    assertWatermarkOrder(
      "business message",
      businessLowMessages,
      businessHighMessages,
      businessMaxMessages,
    );
    assertWatermarkOrder(
      "business byte",
      businessLowBytes,
      businessHighBytes,
      businessMaxBytes,
    );
    this.#codec = options.codec ?? new IpcEnvelopeCodec();
    this.#businessMaxMessages = businessMaxMessages;
    this.#businessMaxBytes = businessMaxBytes;
    this.#businessHighMessages = businessHighMessages;
    this.#businessHighBytes = businessHighBytes;
    this.#businessLowMessages = businessLowMessages;
    this.#businessLowBytes = businessLowBytes;
    this.#onBusinessCapacityChange = options.onBusinessCapacityChange;
    this.#parentDisconnectExitGraceMs = options.parentDisconnectExitGraceMs ??
      DEFAULT_PARENT_DISCONNECT_EXIT_GRACE_MS;
    assertCapacity("parentDisconnectExitGraceMs", this.#parentDisconnectExitGraceMs);
    this.#forceExit = options.forceExit ?? defaultForcedExit;
    this.#disposeMessage = transport.onMessage(this.#onEnvelope);
    this.#disposeProtocolError = transport.onProtocolError((error) => {
      this.fail(error);
    });
    void endpoint.closed.then((result) => {
      if (this.#phase === "stopping") {
        return;
      }
      const error = parentDisconnectReason(result);
      // 「not-connected」表示从来就没有父进程通道（本地/测试构造），不是父进程掉了，
      // 这种情况不该武装强制退出，否则会把测试进程也杀掉。
      if (result.reason !== "not-connected") {
        this.#armForcedExit();
      }
      this.#beginStop(error, this.#phase === "bootstrap", false);
    }).catch((error: unknown) => {
      this.fail(error);
    });
  }

  /**
   * 武装「清理卡死就强制退出」的兜底。
   *
   * timer 用 `unref()`：清理正常完成时进程会自然退出，它不会把事件循环多留 10 秒。
   * 清理真的卡住时（IO 不返回），这个 timer 是子进程唯一的退出路径。
   *
   * 刻意**不做解除**：兜底一旦武装就有效到进程退出。原因是本类能观察到的最晚时点
   * `dispose()` 位于 `runWorkerEntry` 清理流程的**起点之前**，真正容易卡住的部分
   * （关闭连接、释放共享内存、等 bus drain）全在它之后。若在 `dispose()` 里清掉
   * timer，覆盖窗口只剩几毫秒，兜底等于不存在。而 `unref()` 已经保证它不会拖住
   * 正常退出，所以「不解除」不会带来误杀，只会覆盖住真正需要它的那段路径。
   */
  #armForcedExit(): void {
    if (this.#forcedExitTimer !== undefined) {
      return;
    }
    const timer = globalThis.setTimeout(() => {
      this.#forcedExitTimer = undefined;
      this.#forceExit(1);
    }, this.#parentDisconnectExitGraceMs);
    timer.unref();
    this.#forcedExitTimer = timer;
  }

  get stopping(): boolean {
    return this.#stopOutcome !== undefined;
  }

  receiveBootstrap(): Promise<ValidatedChildBootstrap> {
    return this.#bootstrap.promise;
  }

  bindRuntime(
    context: WorkerRuntimeContext,
    bus: WorkerEntryBusinessBus,
    masterPeer: ProcessBusPeerHandle,
  ): void {
    this.#context = context;
    this.#bus = bus;
    this.#masterPeer = masterPeer;
    if (this.#stopOutcome !== undefined) {
      context.requestStop(this.#stopOutcome.reason);
    }
  }

  startRunning(): void {
    if (this.#stopOutcome !== undefined) {
      return;
    }
    if (this.#phase !== "initializing") {
      throw new Error(`cannot start worker message mux from ${this.#phase}`);
    }
    this.#phase = "running";
  }

  waitForStop(): Promise<Readonly<WorkerEntryStop>> {
    return this.#stopped.promise;
  }

  waitForDrainRequest(): Promise<Readonly<ValidatedDrainRequest> | null> {
    if (this.#stopOutcome !== undefined) {
      return Promise.resolve(null);
    }
    if (this.#activeDrainRequest !== undefined) {
      return Promise.reject(new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        "Worker drain request is already active",
      ));
    }
    const queued = this.#queuedDrainRequests.shift();
    if (queued !== undefined) {
      this.#activeDrainRequest = queued;
      return Promise.resolve(queued);
    }
    this.#drainRequestWaiter ??=
      createDeferred<Readonly<ValidatedDrainRequest> | null>();
    return this.#drainRequestWaiter.promise;
  }

  completeDrain(request: Readonly<ValidatedDrainRequest>): void {
    if (
      this.#phase !== "draining" ||
      this.#activeDrainRequest !== request
    ) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        "Worker drain completion does not match the active request",
      );
    }
    this.#activeDrainRequest = undefined;
    if (this.#queuedDrainRequests.length === 0) {
      this.#phase = "running";
    }
  }

  fail(error: unknown): void {
    this.#beginStop(error, true, false);
  }

  drain(): Promise<void> {
    if (this.#businessPendingMessages === 0) {
      return Promise.resolve();
    }
    this.#drainDeferred ??= createDeferred<void>();
    return this.#drainDeferred.promise;
  }

  stats(): Readonly<WorkerEntryMessageMuxStats> {
    return Object.freeze({
      phase: this.#phase,
      stopping: this.stopping,
      maxMessages: this.#businessMaxMessages,
      maxBytes: this.#businessMaxBytes,
      pressured: this.#businessPressured,
      highWaterMessages: this.#businessHighMessages,
      highWaterBytes: this.#businessHighBytes,
      lowWaterMessages: this.#businessLowMessages,
      lowWaterBytes: this.#businessLowBytes,
      pendingMessages: this.#businessPendingMessages,
      pendingBytes: this.#businessPendingBytes,
      queuedMessages: this.#businessQueue.length,
      queuedBytes: this.#businessQueuedBytes,
      inFlightMessages: this.#businessInFlight === undefined ? 0 : 1,
      inFlightBytes: this.#businessInFlight?.byteLength ?? 0,
      acceptedMessages: this.#acceptedBusinessMessages,
      rejectedMessages: this.#rejectedBusinessMessages,
      completedMessages: this.#completedBusinessMessages,
      failedMessages: this.#failedBusinessMessages,
      draining: this.#drainDeferred !== undefined,
    });
  }

  dispose(): void {
    this.#phase = "stopping";
    this.#disposeMessage();
    this.#disposeProtocolError();
    this.#disposeMessage = () => {};
    this.#disposeProtocolError = () => {};
    this.#queuedDrainRequests.length = 0;
    this.#settleDrainWaiter(null);
    this.#settleDrain();
  }

  readonly #onEnvelope = (envelope: Readonly<IpcEnvelopeV1>): void => {
    if (this.#phase === "stopping") {
      return;
    }
    if (this.#phase === "bootstrap") {
      try {
        const bootstrap = parseBootstrapControlEnvelope(envelope);
        this.#bootstrapValue = bootstrap;
        this.#phase = "initializing";
        this.#bootstrap.resolve(bootstrap);
      } catch (error) {
        this.fail(error);
      }
      return;
    }

    if (envelope.messageType === IPC_MESSAGE_TYPE.CONTROL_DRAIN) {
      try {
        this.#acceptDrainRequest(envelope);
      } catch (error) {
        this.fail(error);
      }
      return;
    }

    if (CONTROL_MESSAGE_TYPES.has(envelope.messageType)) {
      try {
        parseShutdownControlEnvelope(envelope, this.#requireBootstrap());
        this.#beginStop("CONTROL_SHUTDOWN", false, true);
      } catch (error) {
        this.fail(error);
      }
      return;
    }

    if (this.#phase === "initializing") {
      this.fail(new FrameworkError(
        FRAMEWORK_ERROR_CODE.WORKER_NOT_READY,
        "Worker received business IPC before READY",
      ));
      return;
    }
    this.#enqueueBusiness(envelope);
  };

  #acceptDrainRequest(envelope: Readonly<IpcEnvelopeV1>): void {
    if (this.#phase !== "running" && this.#phase !== "draining") {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        `Worker cannot accept a drain request from ${this.#phase}`,
      );
    }
    const request = parseLifecycleControlEnvelope(
      envelope,
      this.#requireBootstrap(),
    );
    if (request.action !== LIFECYCLE_CONTROL_ACTION.DRAIN_REQUEST) {
      throw new TypeError("Worker only accepts Master-authored DRAIN_REQUEST controls");
    }
    const pendingDrainRequests = this.#queuedDrainRequests.length +
      (this.#activeDrainRequest === undefined ? 0 : 1);
    if (pendingDrainRequests >= DEFAULT_CONTROL_QUEUE_MAX_MESSAGES) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL,
        "Worker drain barrier queue is full",
        {
          maxRequests: DEFAULT_CONTROL_QUEUE_MAX_MESSAGES,
          pendingRequests: pendingDrainRequests,
        },
      );
    }
    this.#phase = "draining";
    if (
      this.#activeDrainRequest === undefined &&
      this.#drainRequestWaiter !== undefined
    ) {
      this.#activeDrainRequest = request;
      this.#settleDrainWaiter(request);
      return;
    }
    this.#queuedDrainRequests.push(request);
  }

  #requireBootstrap(): ValidatedChildBootstrap {
    if (this.#bootstrapValue === undefined) {
      throw new Error("worker message mux has no validated bootstrap");
    }
    return this.#bootstrapValue;
  }

  #enqueueBusiness(envelope: Readonly<IpcEnvelopeV1>): void {
    const bus = this.#bus;
    const masterPeer = this.#masterPeer;
    if (bus === undefined || masterPeer === undefined) {
      this.fail(new Error("worker ProcessBus is not bound"));
      return;
    }

    let encoded: EncodedIpcEnvelope;
    try {
      encoded = this.#codec.decode(envelope);
    } catch (error) {
      this.#rejectedBusinessMessages += 1;
      this.fail(error);
      return;
    }
    if (
      this.#businessPendingMessages >= this.#businessMaxMessages ||
      encoded.byteLength > this.#businessMaxBytes - this.#businessPendingBytes
    ) {
      this.#rejectedBusinessMessages += 1;
      this.fail(new FrameworkError(
        FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL,
        "Worker entry business IPC queue is full",
        {
          maxMessages: this.#businessMaxMessages,
          maxBytes: this.#businessMaxBytes,
          pendingMessages: this.#businessPendingMessages,
          pendingBytes: this.#businessPendingBytes,
          messageBytes: encoded.byteLength,
        },
      ));
      return;
    }

    this.#businessQueue.push(encoded);
    this.#businessPendingMessages += 1;
    this.#businessPendingBytes += encoded.byteLength;
    this.#businessQueuedBytes += encoded.byteLength;
    this.#acceptedBusinessMessages += 1;
    this.#updateBusinessPressure();
    this.#pumpBusiness();
  }

  #pumpBusiness(): void {
    if (this.#businessInFlight !== undefined) {
      return;
    }
    const pending = this.#businessQueue.shift();
    if (pending === undefined) {
      this.#settleDrain();
      return;
    }
    const bus = this.#requireBus();
    const masterPeer = this.#requireMasterPeer();
    this.#businessQueuedBytes -= pending.byteLength;
    this.#businessInFlight = pending;
    void Promise.resolve()
      .then(() => bus.acceptFrom(masterPeer, pending.envelope))
      .then(
        () => this.#settleBusiness(pending, false),
        (error: unknown) => this.#settleBusiness(pending, true, error),
      );
  }

  #settleBusiness(
    pending: PendingBusinessMessage,
    failed: boolean,
    error?: unknown,
  ): void {
    if (this.#businessInFlight !== pending) {
      return;
    }
    this.#businessInFlight = undefined;
    this.#businessPendingMessages -= 1;
    this.#businessPendingBytes -= pending.byteLength;
    this.#updateBusinessPressure();
    if (failed) {
      this.#failedBusinessMessages += 1;
      this.fail(error);
    } else {
      this.#completedBusinessMessages += 1;
    }
    this.#settleDrain();
    this.#pumpBusiness();
  }

  #requireBus(): WorkerEntryBusinessBus {
    if (this.#bus === undefined) {
      throw new Error("worker ProcessBus is not bound");
    }
    return this.#bus;
  }

  #requireMasterPeer(): ProcessBusPeerHandle {
    if (this.#masterPeer === undefined) {
      throw new Error("worker master ProcessBus peer is not bound");
    }
    return this.#masterPeer;
  }

  #settleDrain(): void {
    if (this.#businessPendingMessages !== 0 || this.#drainDeferred === undefined) {
      return;
    }
    const deferred = this.#drainDeferred;
    this.#drainDeferred = undefined;
    deferred.resolve();
  }

  #capacityState(): Readonly<WorkerEntryBusinessCapacityState> {
    return Object.freeze({
      pressured: this.#businessPressured,
      pendingMessages: this.#businessPendingMessages,
      pendingBytes: this.#businessPendingBytes,
      maxMessages: this.#businessMaxMessages,
      maxBytes: this.#businessMaxBytes,
      highWaterMessages: this.#businessHighMessages,
      highWaterBytes: this.#businessHighBytes,
      lowWaterMessages: this.#businessLowMessages,
      lowWaterBytes: this.#businessLowBytes,
    });
  }

  #updateBusinessPressure(): void {
    const atHighWater =
      this.#businessPendingMessages >= this.#businessHighMessages ||
      this.#businessPendingBytes >= this.#businessHighBytes;
    const atOrBelowLowWater =
      this.#businessPendingMessages <= this.#businessLowMessages &&
      this.#businessPendingBytes <= this.#businessLowBytes;
    const nextPressured = this.#businessPressured
      ? !atOrBelowLowWater
      : atHighWater;
    if (nextPressured === this.#businessPressured) {
      return;
    }
    this.#businessPressured = nextPressured;
    const listener = this.#onBusinessCapacityChange;
    if (listener === undefined) {
      return;
    }
    try {
      listener(this.#capacityState());
    } catch {
      // Capacity observers cannot throw through the transport message event.
    }
  }

  #beginStop(
    reason: unknown,
    failed: boolean,
    invokeWorkerStop: boolean,
  ): void {
    if (this.#stopOutcome !== undefined) {
      return;
    }
    const previousPhase = this.#phase;
    const outcome = Object.freeze({ reason, failed, invokeWorkerStop });
    this.#stopOutcome = outcome;
    this.#phase = "stopping";
    this.#context?.requestStop(reason);
    if (previousPhase === "bootstrap") {
      this.#bootstrap.reject(reason);
    }
    this.#queuedDrainRequests.length = 0;
    this.#settleDrainWaiter(null);
    this.#stopped.resolve(outcome);
    this.#settleDrain();
  }

  #settleDrainWaiter(
    request: Readonly<ValidatedDrainRequest> | null,
  ): void {
    const waiter = this.#drainRequestWaiter;
    if (waiter === undefined) {
      return;
    }
    this.#drainRequestWaiter = undefined;
    waiter.resolve(request);
  }
}

async function collectCleanupFailure(
  failures: unknown[],
  cleanup: () => void | Promise<void>,
): Promise<void> {
  try {
    await cleanup();
  } catch (error) {
    failures.push(error);
  }
}

export async function runWorkerEntry(
  options: RunWorkerEntryOptions = {},
): Promise<void> {
  const endpoint = new NodeParentProcessEndpoint();
  const transport = new BoundedProcessTransport(endpoint);
  let capacityBootstrap: ValidatedChildBootstrap | undefined;
  let capacityControlEnabled = false;
  let capacitySequence = 1;
  let mux!: WorkerEntryMessageMux;
  mux = new WorkerEntryMessageMux(transport, endpoint, {
    onBusinessCapacityChange: (state) => {
      if (
        !capacityControlEnabled ||
        capacityBootstrap === undefined ||
        mux.stopping
      ) {
        return;
      }
      let completion: Promise<void>;
      try {
        const envelope = createCapacityControlEnvelope(capacityBootstrap, {
          messageId: `capacity:${process.pid}:${capacitySequence}:${randomUUID()}`,
          sequence: capacitySequence,
          pressured: state.pressured,
          pendingMessages: state.pendingMessages,
          pendingBytes: state.pendingBytes,
        });
        capacitySequence += 1;
        completion = transport.send(envelope, PROCESS_TRANSPORT_LANE.CONTROL);
      } catch (error) {
        mux.fail(error);
        return;
      }
      void completion.catch((error: unknown) => {
        mux.fail(error);
      });
    },
  });
  let context: WorkerRuntimeContext | undefined;
  let sharedState: SharedRuntimeStateReader | undefined;
  let sharedStateRegistered = false;
  let bus: ProcessBus | undefined;
  let networkEvents: WorkerNetworkEventReceiver | undefined;
  let networkCommands: WorkerNetworkCommandSender | undefined;
  let rustDataPlane: RustWorkerDataPlane | undefined;
  let tasks: WorkerTaskRuntime | undefined;
  let processMessages: WorkerProcessMessenger | undefined;
  let lifecycle: WorkerLifecycleController | undefined;
  let initializerContext: Readonly<WorkerEntryInitializerContext> | undefined;
  let initializationSucceeded = false;
  let workerExitInvoked = false;
  let maxRequestStopRequested = false;
  let invokeWorkerStop = false;
  let executionFailed = false;
  let executionError: unknown;
  let closeReason: unknown = "Worker entry completed";

  try {
    const bootstrap = await mux.receiveBootstrap();
    capacityBootstrap = bootstrap;
    const sharedStateProvider = options.sharedStateProvider ??
      new NativeSharedRuntimeStateProvider();
    sharedState = sharedStateProvider.attachReader(bootstrap.sharedRuntime);
    context = createWorkerRuntimeContext(bootstrap, process.pid);
    context.registerResource("worker.shared-runtime-state", sharedState);
    sharedStateRegistered = true;
    context.registerResource("worker.process-transport", transport);
    lifecycle = context.registerResource(
      "worker.lifecycle-controller",
      new WorkerLifecycleController({
        bootstrap,
        transport,
        onDeliveryError: (error) => {
          context?.log("error", "runtime.worker.lifecycle_delivery_failed", {
            workerId: context.worker_id,
            errorName: error instanceof Error ? error.name : "UnknownError",
            errorMessage: error instanceof Error ? error.message : String(error),
          });
        },
      }),
    );

    bus = context.registerResource("worker.process-bus", new ProcessBus({
      localIdentity: {
        role: context.role,
        workerId: context.worker_id,
        generation: context.generation,
      },
      timers: context.timers,
      metrics: context.metrics,
    }));
    const masterPeer = bus.attachPeer({
      role: PROCESS_ROLE.MASTER,
      workerId: null,
      generation: null,
      transport,
    });
    bus.activatePeer(masterPeer);
    tasks = context.registerResource("worker.tasks", new WorkerTaskRuntime({
      bus,
      workerNum: context.settings.worker_num,
      taskWorkerNum: context.settings.task_worker_num,
      userTaskWorkerNum: context.settings.user_task_worker_num ?? 0,
      onDeliveryError: (error) => {
        context?.log("error", "runtime.worker.task_delivery_failed", {
          workerId: context.worker_id,
          errorName: error instanceof Error ? error.name : "UnknownError",
          errorMessage: error instanceof Error ? error.message : String(error),
        });
      },
    }));
    processMessages = context.registerResource(
      "worker.process-messages",
      new WorkerProcessMessenger({
        bus,
        workerNum: context.settings.worker_num,
        taskWorkerNum: context.settings.task_worker_num,
        userTaskWorkerNum: context.settings.user_task_worker_num ?? 0,
        onDeliveryError: (error) => {
          context?.log("error", "runtime.worker.process_message_delivery_failed", {
            workerId: context.worker_id,
            errorName: error instanceof Error ? error.name : "UnknownError",
            errorMessage: error instanceof Error ? error.message : String(error),
          });
        },
      }),
    );
    if (context.role === PROCESS_ROLE.WORKER) {
      const maxRequest = context.settings.max_request ?? 0;
      const lifecycleController = lifecycle;
      networkEvents = context.registerResource(
        "worker.network-events",
        new WorkerNetworkEventReceiver({
          bus,
          localWorkerId: context.worker_id,
          ...(maxRequest === 0
            ? {}
            : {
              onMessageComplete: (completedMessages: number) => {
                if (
                  maxRequestStopRequested ||
                  completedMessages < maxRequest
                ) {
                  return;
                }
                maxRequestStopRequested = true;
                if (!lifecycleController.stop()) {
                  context?.log("error", "runtime.worker.max_request_stop_rejected", {
                    workerId: context.worker_id,
                    completedMessages,
                    maxRequest,
                    error: lifecycleController.getLastError(),
                  });
                }
              },
            }),
        }),
      );
    }
    if (
      process.env.ALLOY_CORE_RUST_DATA_PLANE === "1" &&
      context.settings.protocol === "tcp"
    ) {
      rustDataPlane = context.registerResource(
        "worker.rust-data-plane",
        new RustWorkerDataPlane({
          context,
          ...(networkEvents === undefined ? {} : { receiver: networkEvents }),
          path: rustDataPlanePath(context.master_pid, context.masterGeneration),
        }),
      );
    }
    networkCommands = new WorkerNetworkCommandSender({
      bus,
      sharedState,
      ...(rustDataPlane === undefined ? {} : { nativeDataPlane: rustDataPlane }),
      ...(context.settings.buffer_output_size === undefined
        ? {}
        : { maxPayloadBytes: context.settings.buffer_output_size }),
      onDeliveryError: (error) => {
        context?.log("error", "runtime.worker.network_command_delivery_failed", {
          workerId: context.worker_id,
          errorName: error instanceof Error ? error.name : "UnknownError",
          errorMessage: error instanceof Error ? error.message : String(error),
        });
      },
    });
    mux.bindRuntime(context, bus, masterPeer);

    if (!mux.stopping) {
      initializerContext = Object.freeze({
        context,
        sharedState,
        bus,
        networkEvents: networkEvents ?? null,
        networkCommands,
        tasks,
        processMessages,
        lifecycle,
      });
      await options.initialize?.(initializerContext);
      initializationSucceeded = true;
    }

    if (!mux.stopping) {
      if (initializerContext === undefined) {
        throw new Error("Worker initializer context is unavailable before READY");
      }
      const ready = createReadyControlEnvelope(bootstrap, {
        messageId: `ready:${context.worker_pid}:${randomUUID()}`,
        workerPid: createProcessPid(process.pid),
      });
      bus.activateLocal();
      const readySent = transport.send(ready, PROCESS_TRANSPORT_LANE.CONTROL);
      capacityControlEnabled = true;
      mux.startRunning();
      await readySent;
      options.onReady?.(initializerContext);
    }

    while (true) {
      const drainRequest = await mux.waitForDrainRequest();
      if (drainRequest === null) {
        break;
      }
      if (initializerContext === undefined) {
        throw new Error("Worker initializer context is unavailable during drain");
      }
      context.requestStop(drainRequest);
      tasks.sealNewTasks(drainRequest);
      bus.sealLocalRequests(drainRequest);
      await mux.drain();
      await bus.drain();
      await rustDataPlane?.drain();
      await tasks.drainPendingTasks();
      await tasks.drain();
      await bus.drain();
      if (!mux.stopping && initializationSucceeded && !workerExitInvoked) {
        workerExitInvoked = true;
        await options.onWorkerExit?.(initializerContext);
        await tasks.drain();
        await bus.drain();
      }
      if (mux.stopping) {
        break;
      }
      const drainedSequence = context.idGenerator.next();
      const drained = transport.sendControlAfterData(
        createDrained(bootstrap, {
          messageId:
            `drained:${context.worker_id}:${context.generation}:${drainedSequence}:${randomUUID()}`,
          sequence: drainedSequence,
          requestId: drainRequest.requestId,
        }),
      );
      mux.completeDrain(drainRequest);
      await drained;
    }

    const stop = await mux.waitForStop();
    closeReason = stop.reason;
    if (stop.failed) {
      throw stop.reason;
    }
    invokeWorkerStop = stop.invokeWorkerStop && initializationSucceeded;
  } catch (error) {
    executionFailed = true;
    executionError = error;
    closeReason = error;
    mux.fail(error);
  }

  context?.requestStop(closeReason);
  mux.dispose();
  tasks?.sealNewTasks(closeReason);
  const cleanupFailures: unknown[] = [];
  if (bus !== undefined) {
    await collectCleanupFailure(
      cleanupFailures,
      () => bus.sealLocalRequests(closeReason),
    );
  }
  await collectCleanupFailure(cleanupFailures, () => mux.drain());
  if (bus !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => bus.drain());
  }
  if (tasks !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => tasks.drain());
  }
  if (bus !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => bus.drain());
  }
  if (
    invokeWorkerStop &&
    initializerContext !== undefined &&
    options.onWorkerStop !== undefined
  ) {
    await collectCleanupFailure(
      cleanupFailures,
      () => options.onWorkerStop?.(initializerContext),
    );
  }
  networkCommands?.seal(closeReason);
  processMessages?.seal(closeReason);
  tasks?.seal(closeReason);
  lifecycle?.close(closeReason);
  if (bus !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => bus.drain());
  }
  if (rustDataPlane !== undefined) {
    await collectCleanupFailure(
      cleanupFailures,
      () => rustDataPlane.close(closeReason),
    );
  }
  if (networkEvents !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => networkEvents.close(closeReason));
  }
  if (processMessages !== undefined) {
    await collectCleanupFailure(
      cleanupFailures,
      () => processMessages.close(closeReason),
    );
  }
  if (tasks !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => tasks.close(closeReason));
  }
  if (bus !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => bus.close(closeReason));
  }
  if (context !== undefined) {
    await collectCleanupFailure(cleanupFailures, () => context.closeGlobally(closeReason));
  } else {
    await collectCleanupFailure(cleanupFailures, () => transport.close(closeReason));
  }
  if (sharedState !== undefined && !sharedStateRegistered) {
    await collectCleanupFailure(cleanupFailures, () => sharedState?.close(closeReason));
  }
  endpoint.disconnect();
  await endpoint.closed;

  if (executionFailed && cleanupFailures.length > 0) {
    throw new AggregateError(
      [executionError, ...cleanupFailures],
      "Worker entry and cleanup both failed",
    );
  }
  if (executionFailed) {
    throw executionError;
  }
  if (cleanupFailures.length === 1) {
    throw cleanupFailures[0];
  }
  if (cleanupFailures.length > 1) {
    throw new AggregateError(cleanupFailures, "Worker entry cleanup failed");
  }
}
