import {
  loadRustDataPlaneBinding,
  type NativeTcpServerHandle,
} from "../native/rust-data-plane-binding.ts";
import type {
  NetworkAdapter,
  NetworkAdapterEvents,
  NetworkConnectionHandle,
  NetworkDataPlaneCounters,
  NetworkDataPlaneControlEvent,
  NetworkDataPlaneRoute,
  NetworkListenOptions,
  NetworkListenerInfo,
  NetworkPeerInfo,
  NetworkOutputBufferState,
  NetworkWriteResult,
} from "./network-adapter.ts";

const BATCH_HEADER_BYTES = 4;
const EVENT_RECORD_BYTES = 12;
const CONNECTED_PAYLOAD_HEADER_BYTES = 8;
const EVENT_CONNECTED = 1;
const EVENT_DATA = 2;
const EVENT_END = 3;
const EVENT_ERROR = 4;
const EVENT_CLOSE = 5;
const EVENT_LISTENER_ERROR = 6;
const EVENT_BUFFER = 7;
const BUFFER_STATE_EMPTY = 0;
const BUFFER_STATE_FULL = 1;
const BUFFER_STATE_OVERFLOW = 2;
const WORKER_EVENT_CONNECT = 3;
const WORKER_EVENT_CLOSE = 4;
const WORKER_EVENT_BUFFER = 5;
const POLL_MAX_EVENTS = 4_096;
const POLL_MAX_BYTES = 8 * 1024 * 1024;
const textDecoder = new TextDecoder();

interface DecodedNativeEvent {
  readonly kind: number;
  readonly flags: number;
  readonly connectionId: number;
  readonly payload: Buffer;
}

class RustNetworkConnection implements NetworkConnectionHandle {
  readonly adapterConnectionId = Symbol("rust-network-connection");
  readonly nativeId: number;
  readonly peerInfo: Readonly<NetworkPeerInfo>;
  closed = false;
  inputSequence = 0;
  outputSequence = 0;
  bufferEventSequence = 0;

  constructor(nativeId: number, peerInfo: Readonly<NetworkPeerInfo>) {
    this.nativeId = nativeId;
    this.peerInfo = peerInfo;
  }
}

export interface RustNetworkAdapterOptions {
  readonly dataPlanePath?: string;
  readonly dataPlaneQueueMessages?: number;
  readonly runtimeThreads?: number;
  readonly maxConnections?: number;
  readonly maxFrameBytes?: number;
  readonly socketBufferBytes?: number;
  readonly bufferHighWatermarkBytes?: number;
  readonly bufferLowWatermarkBytes?: number;
}

function decodeBufferState(value: number): NetworkOutputBufferState {
  if (value === BUFFER_STATE_EMPTY) {
    return "empty";
  }
  if (value === BUFFER_STATE_FULL) {
    return "full";
  }
  if (value === BUFFER_STATE_OVERFLOW) {
    return "overflow";
  }
  throw new TypeError(`Rust network buffer state ${value} is invalid`);
}

function readSafeUInt64BE(buffer: Buffer, offset: number, name: string): number {
  const value = buffer.readBigUInt64BE(offset);
  if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new TypeError(`Rust network ${name} exceeds JavaScript safe range`);
  }
  return Number(value);
}

function decodeBatch(batch: Buffer): readonly DecodedNativeEvent[] {
  if (batch.byteLength < BATCH_HEADER_BYTES) {
    throw new TypeError("Rust network event batch is truncated");
  }
  const count = batch.readUInt32BE(0);
  const events: DecodedNativeEvent[] = [];
  let offset = BATCH_HEADER_BYTES;
  for (let index = 0; index < count; index += 1) {
    if (batch.byteLength - offset < EVENT_RECORD_BYTES) {
      throw new TypeError("Rust network event record is truncated");
    }
    const kind = batch[offset]!;
    const flags = batch[offset + 1]!;
    const connectionId = batch.readUInt32BE(offset + 4);
    const payloadBytes = batch.readUInt32BE(offset + 8);
    const payloadStart = offset + EVENT_RECORD_BYTES;
    const payloadEnd = payloadStart + payloadBytes;
    if (payloadEnd > batch.byteLength) {
      throw new TypeError("Rust network event payload is truncated");
    }
    events.push({
      kind,
      flags,
      connectionId,
      payload: batch.subarray(payloadStart, payloadEnd),
    });
    offset = payloadEnd;
  }
  if (offset !== batch.byteLength) {
    throw new TypeError("Rust network event batch contains trailing bytes");
  }
  return events;
}

function decodePeerInfo(payload: Buffer): Readonly<NetworkPeerInfo> {
  if (payload.byteLength < CONNECTED_PAYLOAD_HEADER_BYTES) {
    throw new TypeError("Rust network connected event is truncated");
  }
  const remotePort = payload.readUInt16BE(0);
  const localPort = payload.readUInt16BE(2);
  const remoteAddressBytes = payload.readUInt16BE(4);
  const localAddressBytes = payload.readUInt16BE(6);
  const remoteStart = CONNECTED_PAYLOAD_HEADER_BYTES;
  const remoteEnd = remoteStart + remoteAddressBytes;
  const localEnd = remoteEnd + localAddressBytes;
  if (localEnd !== payload.byteLength) {
    throw new TypeError("Rust network connected addresses are invalid");
  }
  return Object.freeze({
    remoteAddress: textDecoder.decode(payload.subarray(remoteStart, remoteEnd)),
    remotePort,
    localAddress: textDecoder.decode(payload.subarray(remoteEnd, localEnd)),
    localPort,
  });
}

export class RustNetworkAdapter
  implements NetworkAdapter<RustNetworkConnection>
{
  readonly deliversTcpFrames = true;
  readonly routesTcpFramesToWorkers: boolean;

  readonly #native: NativeTcpServerHandle;
  readonly #options: Readonly<RustNetworkAdapterOptions>;
  readonly #connections = new Map<number, RustNetworkConnection>();
  #events: NetworkAdapterEvents<RustNetworkConnection> | undefined;
  #listenPromise: Promise<NetworkListenerInfo> | undefined;
  #closePromise: Promise<void> | undefined;
  #pumpPromise: Promise<void> | undefined;
  #closeRequested = false;

  constructor(
    native?: NativeTcpServerHandle,
    options: RustNetworkAdapterOptions = {},
  ) {
    this.#native = native ?? new (loadRustDataPlaneBinding().NativeTcpServer)();
    this.#options = Object.freeze({ ...options });
    this.routesTcpFramesToWorkers = options.dataPlanePath !== undefined;
  }

  get activeConnectionCount(): number {
    return this.#connections.size;
  }

  listen(
    options: NetworkListenOptions,
    events: NetworkAdapterEvents<RustNetworkConnection>,
  ): Promise<NetworkListenerInfo> {
    if (this.#listenPromise !== undefined) {
      return this.#listenPromise;
    }
    if (this.#closeRequested) {
      return Promise.reject(new Error("Rust network adapter is closing"));
    }
    this.#events = events;
    try {
      const info = this.#native.start({
        host: options.host,
        port: options.port,
        noDelay: options.noDelay ?? false,
        maxConnections: this.#options.maxConnections ?? 1_024,
        maxFrameBytes: this.#options.maxFrameBytes ?? 512 * 1024,
        socketBufferBytes: this.#options.socketBufferBytes ?? 1024 * 1024,
        ...(this.#options.bufferHighWatermarkBytes === undefined
          ? {}
          : { bufferHighWatermarkBytes: this.#options.bufferHighWatermarkBytes }),
        ...(this.#options.bufferLowWatermarkBytes === undefined
          ? {}
          : { bufferLowWatermarkBytes: this.#options.bufferLowWatermarkBytes }),
        runtimeThreads: this.#options.runtimeThreads ?? 1,
        ...(this.#options.dataPlanePath === undefined
          ? {}
          : { dataPlanePath: this.#options.dataPlanePath }),
        ...(this.#options.dataPlaneQueueMessages === undefined
          ? {}
          : { dataPlaneQueueMessages: this.#options.dataPlaneQueueMessages }),
      });
      this.#listenPromise = Promise.resolve(Object.freeze(info));
      this.#pumpPromise = this.#pumpEvents();
    } catch (error) {
      this.#listenPromise = Promise.reject(error);
      void this.#listenPromise.catch(() => {});
    }
    return this.#listenPromise;
  }

  closeListener(): Promise<void> {
    this.#native.stopAccepting();
    return Promise.resolve();
  }

  pauseConnection(connection: RustNetworkConnection): void {
    const active = this.#requireConnection(connection);
    if (!this.#native.pause(active.nativeId)) {
      throw new Error("Rust network connection could not be paused");
    }
  }

  resumeConnection(connection: RustNetworkConnection): void {
    const active = this.#requireConnection(connection);
    if (!this.#native.resume(active.nativeId)) {
      throw new Error("Rust network connection could not be resumed");
    }
  }

  write(
    connection: RustNetworkConnection,
    data: Uint8Array,
  ): Readonly<NetworkWriteResult> {
    const active = this.#requireConnection(connection);
    const result = this.#native.write(active.nativeId, data);
    if (!result.accepted) {
      throw new Error("Rust network connection is not writable");
    }
    return Object.freeze({
      backpressured: result.backpressured,
      bufferedBytes: result.bufferedBytes,
    });
  }

  closeConnection(connection: RustNetworkConnection): void {
    const active = this.#requireConnection(connection);
    this.#native.closeConnection(active.nativeId);
  }

  getPeerInfo(connection: RustNetworkConnection): Readonly<NetworkPeerInfo> {
    return this.#requireConnection(connection).peerInfo;
  }

  bindDataPlaneRoute(
    connection: RustNetworkConnection,
    route: Readonly<NetworkDataPlaneRoute>,
  ): void {
    const active = this.#requireConnection(connection);
    if (!this.routesTcpFramesToWorkers) {
      return;
    }
    if (!this.#native.registerSession(
      active.nativeId,
      route.sessionId,
      route.workerId,
      route.workerGeneration,
      route.inputSequence,
      route.outputSequence,
    )) {
      throw new Error("Rust network connection could not bind its Worker route");
    }
  }

  getDataPlaneCounters(
    connection: RustNetworkConnection,
  ): Readonly<NetworkDataPlaneCounters> | undefined {
    if (!this.routesTcpFramesToWorkers) {
      return undefined;
    }
    const counters = connection.closed
      ? {
        inputSequence: connection.inputSequence,
        outputSequence: connection.outputSequence,
      }
      : this.#native.sessionCounters(this.#requireConnection(connection).nativeId);
    return counters === undefined ? undefined : Object.freeze({ ...counters });
  }

  deliverDataPlaneControl(
    event: Readonly<NetworkDataPlaneControlEvent>,
  ): Promise<void> {
    if (!this.routesTcpFramesToWorkers) {
      return Promise.reject(new Error("Rust Worker data plane is not enabled"));
    }
    return this.#native.deliverWorkerControl(
      {
        workerId: event.workerId,
        workerGeneration: event.workerGeneration,
        eventKind: event.type === "connect"
          ? WORKER_EVENT_CONNECT
          : event.type === "close"
            ? WORKER_EVENT_CLOSE
            : WORKER_EVENT_BUFFER,
        sessionId: event.sessionId,
        sequence: event.sequence,
        timeoutMs: 5_000,
      },
      event.payload,
    );
  }

  async close(): Promise<void> {
    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }
    this.#closeRequested = true;
    this.#closePromise = Promise.resolve().then(() => {
      this.#native.close();
      this.#connections.clear();
    });
    return this.#closePromise;
  }

  [Symbol.asyncDispose](): Promise<void> {
    return this.close();
  }

  async #pumpEvents(): Promise<void> {
    try {
      while (
        !this.#closeRequested &&
        (this.#native.running || this.#connections.size !== 0)
      ) {
        const events = decodeBatch(
          await this.#native.waitEvents(POLL_MAX_EVENTS, POLL_MAX_BYTES, 100),
        );
        for (const event of events) {
          this.#dispatch(event);
        }
      }
    } catch (error) {
      this.#reportListenerError(error);
      if (!this.#closeRequested) {
        void this.close();
      }
    }
  }

  #dispatch(event: DecodedNativeEvent): void {
    if (event.kind === EVENT_CONNECTED) {
      const connection = new RustNetworkConnection(
        event.connectionId,
        decodePeerInfo(event.payload),
      );
      this.#connections.set(connection.nativeId, connection);
      this.#invoke(connection, () => this.#events?.onConnection(connection));
      return;
    }
    if (event.kind === EVENT_LISTENER_ERROR) {
      this.#reportListenerError(new Error(textDecoder.decode(event.payload)));
      return;
    }
    const connection = this.#connections.get(event.connectionId);
    if (connection === undefined) {
      return;
    }
    if (event.kind === EVENT_DATA) {
      this.#invoke(connection, () => this.#events?.onData(connection, event.payload));
    } else if (event.kind === EVENT_END) {
      this.#invoke(connection, () => this.#events?.onEnd(connection));
    } else if (event.kind === EVENT_ERROR) {
      this.#invoke(connection, () => {
        this.#events?.onError(connection, new Error(textDecoder.decode(event.payload)));
      });
    } else if (event.kind === EVENT_BUFFER) {
      if (event.payload.byteLength !== 16) {
        this.#invoke(connection, () => {
          throw new TypeError("Rust network buffer event is invalid");
        });
        return;
      }
      const bufferedBytes = readSafeUInt64BE(
        event.payload,
        0,
        "buffered byte count",
      );
      const sequence = readSafeUInt64BE(event.payload, 8, "buffer event sequence");
      if (sequence <= connection.bufferEventSequence) {
        return;
      }
      connection.bufferEventSequence = sequence;
      const state = decodeBufferState(event.flags);
      this.#invoke(connection, () => {
        this.#events?.onBufferChange?.(connection, state, bufferedBytes);
      });
    } else if (event.kind === EVENT_CLOSE) {
      if (event.payload.byteLength === 16) {
        const inputSequence = Number(event.payload.readBigUInt64BE(0));
        const outputSequence = Number(event.payload.readBigUInt64BE(8));
        if (
          Number.isSafeInteger(inputSequence) &&
          Number.isSafeInteger(outputSequence)
        ) {
          connection.inputSequence = inputSequence;
          connection.outputSequence = outputSequence;
        }
      }
      connection.closed = true;
      this.#connections.delete(connection.nativeId);
      try {
        this.#events?.onClose(connection, (event.flags & 1) !== 0);
      } catch {
        // Close observers cannot escape the polling boundary.
      }
    }
  }

  #invoke(connection: RustNetworkConnection, callback: () => void): void {
    try {
      callback();
    } catch (error) {
      try {
        this.#events?.onError(connection, error);
      } catch {
        // Error observers cannot escape the polling boundary.
      }
      this.#native.closeConnection(connection.nativeId);
    }
  }

  #reportListenerError(error: unknown): void {
    try {
      this.#events?.onListenerError(error);
    } catch {
      // Listener error observers cannot escape the polling boundary.
    }
  }

  #requireConnection(connection: RustNetworkConnection): RustNetworkConnection {
    if (
      connection.closed ||
      this.#connections.get(connection.nativeId) !== connection
    ) {
      throw new Error("Rust network connection is closed or belongs to another adapter");
    }
    return connection;
  }
}
