import type { FrameworkErrorCode } from "../errors/framework-error.ts";
import type { SessionId } from "../protocol/session-id.ts";
import type {
  ProcessPid,
  TaskWorkerId,
  WorkerGeneration,
  WorkerId,
} from "../protocol/worker-id.ts";
import type { ProcessRole } from "../protocol/process-role.ts";
import type { WorkerState } from "../lifecycle/states.ts";

export type RuntimeProtocol = "tcp" | "websocket";

export interface RuntimeSettings {
  readonly host: string;
  readonly port: number;
  readonly protocol: RuntimeProtocol;
  readonly work_mode: "process";
  readonly sock_type: "tcp";
  readonly reactor_num?: 1;
  readonly daemonize?: boolean;
  readonly open_tcp_nodelay?: boolean;
  readonly worker_num: number;
  readonly max_request?: number;
  readonly max_conn?: number;
  readonly dispatch_mode: 2;
  readonly task_worker_num: number;
  readonly user_task_worker_num?: number;
  readonly log_file?: string;
  readonly enable_coroutine?: boolean;
  readonly backlog?: number;
  readonly user?: string;
  readonly group?: string;
  readonly send_yield?: boolean;
  readonly buffer_input_size?: number;
  readonly buffer_output_size?: number;
  readonly socket_buffer_size?: number;
  readonly buffer_high_watermark?: number;
  readonly buffer_low_watermark?: number;
  readonly backpressure_timeout_ms?: number;
  readonly idle_timeout_ms?: number;
  readonly read_timeout_ms?: number;
  readonly write_timeout_ms?: number;
}

export interface RuntimeConnectionView extends Iterable<SessionId> {
  readonly size: number;
}

export interface RuntimeConnectionInfo {
  readonly remote_ip: string;
  readonly remote_port: number;
  readonly server_port: number;
  readonly connect_time: number;
  readonly last_time: number;
  readonly websocket_status?: number;
  readonly uid?: number;
  readonly close_errno?: number;
}

export interface RuntimeWorkerInfo {
  readonly workerId: WorkerId;
  readonly role: Exclude<ProcessRole, "MASTER">;
  readonly state: WorkerState;
  readonly pid: ProcessPid | null;
  readonly generation: WorkerGeneration;
}

export interface WebSocketOpenRequest {
  readonly fd: SessionId;
  readonly [key: string]: unknown;
}

export interface RuntimeHttpRequest {
  readonly fd: SessionId;
  readonly get: Readonly<Record<string, unknown>>;
  readonly post: Readonly<Record<string, unknown>>;
  readonly header: Readonly<Record<string, string | undefined>>;
  readonly server: Readonly<Record<string, string | number | undefined>>;
  readonly body: Uint8Array;
}

export interface RuntimeHttpResponse {
  header(name: string, value: string): boolean;
  status(code: number): boolean;
  end(data?: Uint8Array | string): boolean;
}

export interface RuntimeStats {
  readonly connections: number;
  readonly workers: number;
  readonly taskWorkers: number;
  readonly invalidSessions: number;
  readonly staleGenerations: number;
  readonly capacity: Readonly<RuntimeCapacityStats>;
  readonly errors: Readonly<Partial<Record<FrameworkErrorCode, number>>>;
}

export interface RuntimeCapacityStats {
  readonly ipcPendingRequests: number;
  readonly ipcPendingMessages: number;
  readonly ipcPendingBytes: number;
  readonly ipcPressuredPeers: number;
  readonly ipcRejectionCount: number;
  readonly inputPausedConnections: number;
  readonly inputQueuedBytes: number;
  readonly inputPauseCount: number;
  readonly inputResumeCount: number;
  readonly inputTimeoutCount: number;
  readonly inputRejectionCount: number;
  readonly outputFullConnections: number;
  readonly outputOverflowConnections: number;
  readonly outputQueuedBytes: number;
  readonly outputFullCount: number;
  readonly outputEmptyCount: number;
  readonly outputOverflowCount: number;
  readonly outputTimeoutCount: number;
  readonly outputRejectionCount: number;
  readonly taskPending: number;
  readonly taskAssignments: number;
  readonly taskRejectionCount: number;
}

export const EMPTY_RUNTIME_CAPACITY_STATS: Readonly<RuntimeCapacityStats> =
  Object.freeze({
    ipcPendingRequests: 0,
    ipcPendingMessages: 0,
    ipcPendingBytes: 0,
    ipcPressuredPeers: 0,
    ipcRejectionCount: 0,
    inputPausedConnections: 0,
    inputQueuedBytes: 0,
    inputPauseCount: 0,
    inputResumeCount: 0,
    inputTimeoutCount: 0,
    inputRejectionCount: 0,
    outputFullConnections: 0,
    outputOverflowConnections: 0,
    outputQueuedBytes: 0,
    outputFullCount: 0,
    outputEmptyCount: 0,
    outputOverflowCount: 0,
    outputTimeoutCount: 0,
    outputRejectionCount: 0,
    taskPending: 0,
    taskAssignments: 0,
    taskRejectionCount: 0,
  });

export interface WebSocketFrame {
  readonly fd: SessionId;
  readonly data: Uint8Array | string;
  readonly opcode: number;
  readonly finish: boolean;
}

export interface RuntimeServerContract {
  readonly worker_id: WorkerId | null;
  readonly worker_pid: ProcessPid | null;
  readonly taskworker: boolean;
  readonly setting: Readonly<RuntimeSettings>;
  readonly master_pid: ProcessPid;
  readonly generation: WorkerGeneration | null;
  readonly connections: RuntimeConnectionView;

  task(data: unknown, taskWorkerId?: TaskWorkerId): number | false;
  finish(data: unknown): boolean;
  sendMessage(message: unknown, targetWorkerId: WorkerId): boolean;
  requestMessage(message: unknown, targetWorkerId: WorkerId, timeoutMs?: number): Promise<unknown>;
  push(fd: SessionId, data: Uint8Array | string, opcode?: number): boolean;
  send(fd: SessionId, data: Uint8Array | string): boolean;
  close(fd: SessionId, code?: number, reason?: string): boolean;
  exist(fd: SessionId): boolean;
  connection_info(fd: SessionId): Readonly<RuntimeConnectionInfo> | false;
  connection_owner(fd: SessionId): WorkerId | false;
  workers(): readonly Readonly<RuntimeWorkerInfo>[];
  addStat(metricId: number, delta?: number): number | false;
  snapshotStats(): readonly number[];
  atomicGet(atomicId: number): number | false;
  atomicAdd(atomicId: number, delta: number): number | false;
  atomicSet(atomicId: number, value: number): number | false;
  atomicCompareSet(atomicId: number, expected: number, value: number): boolean;
  lockTry(lockId: number, ownerToken?: number): boolean;
  lockAcquire(lockId: number, ownerToken?: number, timeoutMs?: number): Promise<boolean>;
  lockRelease(lockId: number, ownerToken?: number): boolean;
  stop(workerId?: WorkerId): boolean;
  reload(onlyTaskWorker?: boolean): boolean;
  shutdown(): boolean;
  stats(): Readonly<RuntimeStats>;
  getLastError(): FrameworkErrorCode | null;
}

export interface RuntimeCallbacks {
  readonly onStart?: (server: RuntimeServerContract) => void | Promise<void>;
  readonly onShutdown?: (server: RuntimeServerContract) => void | Promise<void>;
  readonly onManagerStart?: (server: RuntimeServerContract) => void | Promise<void>;
  readonly onManagerStop?: (server: RuntimeServerContract) => void | Promise<void>;
  readonly onWorkerStart?: (
    server: RuntimeServerContract,
    workerId: WorkerId,
  ) => void | Promise<void>;
  readonly onWorkerExit?: (
    server: RuntimeServerContract,
    workerId: WorkerId,
  ) => void | Promise<void>;
  readonly onWorkerStop?: (
    server: RuntimeServerContract,
    workerId: WorkerId,
  ) => void | Promise<void>;
  readonly onWorkerError?: (
    server: RuntimeServerContract,
    workerId: WorkerId,
    workerPid: ProcessPid,
    exitCode: number,
    signal: number,
  ) => void | Promise<void>;
  readonly onBeforeReload?: (server: RuntimeServerContract) => void | Promise<void>;
  readonly onConnect?: (
    server: RuntimeServerContract,
    fd: SessionId,
    reactorId: 0,
  ) => void | Promise<void>;
  readonly onOpen?: (
    server: RuntimeServerContract,
    request: WebSocketOpenRequest,
  ) => void | Promise<void>;
  readonly onReceive?: (
    server: RuntimeServerContract,
    fd: SessionId,
    reactorId: 0,
    data: Uint8Array,
  ) => void | Promise<void>;
  readonly onMessage?: (
    server: RuntimeServerContract,
    frame: WebSocketFrame,
  ) => void | Promise<void>;
  readonly onRequest?: (
    request: RuntimeHttpRequest,
    response: RuntimeHttpResponse,
  ) => void | Promise<void>;
  readonly onClose?: (
    server: RuntimeServerContract,
    fd: SessionId,
    reactorId: 0,
  ) => void | Promise<void>;
  readonly onTask?: (
    server: RuntimeServerContract,
    taskId: number,
    sourceWorkerId: WorkerId,
    data: unknown,
  ) => unknown | Promise<unknown>;
  readonly onFinish?: (
    server: RuntimeServerContract,
    taskId: number,
    data: unknown,
  ) => void | Promise<void>;
  readonly onPipeMessage?: (
    server: RuntimeServerContract,
    sourceWorkerId: WorkerId,
    message: unknown,
  ) => void | Promise<void>;
  readonly onPipeRequest?: (
    server: RuntimeServerContract,
    sourceWorkerId: WorkerId,
    message: unknown,
  ) => unknown | Promise<unknown>;
  readonly onBufferFull?: (
    server: RuntimeServerContract,
    fd: SessionId,
  ) => void | Promise<void>;
  readonly onBufferEmpty?: (
    server: RuntimeServerContract,
    fd: SessionId,
  ) => void | Promise<void>;
}
