import type { IpcJsonValue } from "../protocol/ipc-envelope.ts";
import type { RuntimeProtocol } from "../runtime/runtime-server.ts";
import {
  createWorkerId,
  type WorkerId,
} from "../protocol/worker-id.ts";

export const NETWORK_BUFFER_PROTOCOL_VERSION = 1 as const;

export const NETWORK_BUFFER_STATE = Object.freeze({
  FULL: "full",
  OVERFLOW: "overflow",
  EMPTY: "empty",
} as const);

export type NetworkBufferState =
  (typeof NETWORK_BUFFER_STATE)[keyof typeof NETWORK_BUFFER_STATE];

export interface NetworkBufferStatePayload {
  readonly version: typeof NETWORK_BUFFER_PROTOCOL_VERSION;
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly state: NetworkBufferState;
  readonly bufferedBytes: number;
}

export interface EncodeNetworkBufferStatePayloadOptions {
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly state: NetworkBufferState;
  readonly bufferedBytes: number;
}

type IpcJsonObject = Readonly<Record<string, IpcJsonValue>>;

const PAYLOAD_KEYS = Object.freeze([
  "version",
  "ownerWorkerId",
  "protocol",
  "state",
  "bufferedBytes",
] as const);
const PAYLOAD_KEY_SET: ReadonlySet<string> = new Set(PAYLOAD_KEYS);

function requireExactRecord(value: unknown): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError("NET_BUFFER_STATE payload must be a plain object");
  }
  const prototype = Object.getPrototypeOf(value);
  const keys = Reflect.ownKeys(value);
  if (
    (prototype !== Object.prototype && prototype !== null) ||
    keys.length !== PAYLOAD_KEYS.length ||
    keys.some((key) => typeof key !== "string" || !PAYLOAD_KEY_SET.has(key))
  ) {
    throw new TypeError(
      `NET_BUFFER_STATE payload must contain exactly: ${PAYLOAD_KEYS.join(", ")}`,
    );
  }
  for (const key of PAYLOAD_KEYS) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
      throw new TypeError(`NET_BUFFER_STATE payload.${key} must be an enumerable data field`);
    }
  }
  return value as Record<string, unknown>;
}

function requireProtocol(value: unknown): RuntimeProtocol {
  if (value !== "tcp" && value !== "websocket") {
    throw new TypeError("NET_BUFFER_STATE protocol must be tcp or websocket");
  }
  return value;
}

function requireState(value: unknown): NetworkBufferState {
  if (
    value !== NETWORK_BUFFER_STATE.FULL &&
    value !== NETWORK_BUFFER_STATE.OVERFLOW &&
    value !== NETWORK_BUFFER_STATE.EMPTY
  ) {
    throw new TypeError("NET_BUFFER_STATE state is invalid");
  }
  return value;
}

export function decodeNetworkBufferStatePayload(
  value: unknown,
): Readonly<NetworkBufferStatePayload> {
  const record = requireExactRecord(value);
  if (record.version !== NETWORK_BUFFER_PROTOCOL_VERSION) {
    throw new TypeError("NET_BUFFER_STATE payload has an unsupported version");
  }
  if (
    typeof record.bufferedBytes !== "number" ||
    !Number.isSafeInteger(record.bufferedBytes) ||
    record.bufferedBytes < 0
  ) {
    throw new TypeError("NET_BUFFER_STATE bufferedBytes must be a non-negative safe integer");
  }
  return Object.freeze({
    version: NETWORK_BUFFER_PROTOCOL_VERSION,
    ownerWorkerId: createWorkerId(record.ownerWorkerId as number),
    protocol: requireProtocol(record.protocol),
    state: requireState(record.state),
    bufferedBytes: record.bufferedBytes,
  });
}

export function encodeNetworkBufferStatePayload(
  options: EncodeNetworkBufferStatePayloadOptions,
): Readonly<NetworkBufferStatePayload> & IpcJsonObject {
  return decodeNetworkBufferStatePayload({
    version: NETWORK_BUFFER_PROTOCOL_VERSION,
    ownerWorkerId: options.ownerWorkerId,
    protocol: options.protocol,
    state: options.state,
    bufferedBytes: options.bufferedBytes,
  }) as Readonly<NetworkBufferStatePayload> & IpcJsonObject;
}
