import { AsyncLocalStorage } from "node:async_hooks";

import {
  assertConnectionTransition,
  CONNECTION_STATE,
  type ConnectionState,
} from "../lifecycle/states.ts";
import type { SessionId } from "../protocol/session-id.ts";
import type { WorkerId } from "../protocol/worker-id.ts";
import { SystemClock, type Clock } from "../runtime/clock.ts";
import { SessionManager } from "./session-manager.ts";

export interface ConnectionPeerInfo {
  readonly remoteAddress: string;
  readonly remotePort: number;
  readonly localAddress: string;
  readonly localPort: number;
}

export interface ConnectionWriteResult {
  readonly backpressured: boolean;
  readonly bufferedBytes: number;
}

export interface ConnectionOperations<Handle extends object> {
  pauseConnection(handle: Handle): void;
  resumeConnection(handle: Handle): void;
  write(handle: Handle, data: Uint8Array): Readonly<ConnectionWriteResult>;
  closeConnection(handle: Handle, cause?: unknown): void;
  getPeerInfo(handle: Handle): ConnectionPeerInfo;
}

export interface ConnectionRecordSnapshot<ProtocolState> {
  readonly sessionId: SessionId;
  readonly state: ConnectionState;
  readonly protocolState: ProtocolState;
  readonly ownerWorkerId: WorkerId | null;
  readonly inputSequence: number;
  readonly outputSequence: number;
  readonly inputBufferedBytes: number;
  readonly outputBufferedBytes: number;
  readonly outputBufferFull: boolean;
  readonly overflow: boolean;
  readonly connectedAt: number;
  readonly lastActiveAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly closeCause: unknown;
  readonly closed: Promise<void>;
}

export type ConnectionClosedHandler<ProtocolState> = (
  connection: ConnectionRecordSnapshot<ProtocolState>,
) => void | Promise<void>;

export interface ConnectionRegistryOptions<Handle extends object, ProtocolState> {
  readonly sessions: SessionManager;
  readonly operations: ConnectionOperations<Handle>;
  readonly clock?: Clock;
  readonly onClosed?: ConnectionClosedHandler<ProtocolState>;
  readonly onRecordChanged?: (
    connection: ConnectionRecordSnapshot<ProtocolState>,
  ) => void;
  readonly activityPublishIntervalMs?: number;
}

interface MutableConnectionRecord<Handle extends object, ProtocolState> {
  readonly sessionId: SessionId;
  readonly handle: Handle;
  state: ConnectionState;
  protocolState: ProtocolState;
  ownerWorkerId: WorkerId | null;
  inputSequence: number;
  outputSequence: number;
  inputBufferedBytes: number;
  outputBufferedBytes: number;
  outputBufferFull: boolean;
  overflow: boolean;
  readonly connectedAt: number;
  lastActiveAt: number;
  lastPublishedActiveAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  closeCause: unknown;
  closeCauseSet: boolean;
  readonly closed: Promise<void>;
  readonly resolveClosed: () => void;
  readonly rejectClosed: (reason?: unknown) => void;
  readonly onClosedDone: Promise<void>;
  readonly resolveOnClosedDone: () => void;
  readonly rejectOnClosedDone: (reason?: unknown) => void;
}

interface ConnectionClosedHandlerInvocation {
  active: boolean;
  readonly registry: object;
}

const activeConnectionClosedHandler =
  new AsyncLocalStorage<ConnectionClosedHandlerInvocation>();

function freezePeerInfo(peerInfo: ConnectionPeerInfo): Readonly<ConnectionPeerInfo> {
  return Object.freeze({ ...peerInfo });
}

function assertNonNegativeSafeInteger(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

export class ConnectionRegistry<Handle extends object, ProtocolState>
  implements Iterable<SessionId>
{
  readonly #sessions: SessionManager;
  readonly #operations: ConnectionOperations<Handle>;
  readonly #clock: Clock;
  readonly #onClosed: ConnectionClosedHandler<ProtocolState> | undefined;
  readonly #onRecordChanged:
    | ((connection: ConnectionRecordSnapshot<ProtocolState>) => void)
    | undefined;
  readonly #activityPublishIntervalMs: number;
  readonly #bySessionId = new Map<SessionId, MutableConnectionRecord<Handle, ProtocolState>>();
  readonly #byHandle = new Map<Handle, SessionId>();
  readonly #pendingClosed = new Set<Promise<void>>();
  readonly #pendingOnClosed = new Set<Promise<void>>();

  constructor(options: ConnectionRegistryOptions<Handle, ProtocolState>) {
    this.#sessions = options.sessions;
    this.#operations = options.operations;
    this.#clock = options.clock ?? new SystemClock();
    this.#onClosed = options.onClosed;
    this.#onRecordChanged = options.onRecordChanged;
    this.#activityPublishIntervalMs = options.activityPublishIntervalMs ?? 0;
    assertNonNegativeSafeInteger(
      "activityPublishIntervalMs",
      this.#activityPublishIntervalMs,
    );
  }

  get size(): number {
    return this.#bySessionId.size;
  }

  [Symbol.iterator](): IterableIterator<SessionId> {
    return this.#bySessionId.keys();
  }

  add(handle: Handle, protocolState: ProtocolState): ConnectionRecordSnapshot<ProtocolState> {
    if (this.#byHandle.has(handle)) {
      throw new Error("Connection handle is already registered");
    }

    const peerInfo = freezePeerInfo(this.#operations.getPeerInfo(handle));
    const sessionId = this.#sessions.acquire();
    let connectedAt: number;
    try {
      connectedAt = this.#clock.wallTimeMs();
    } catch (error) {
      if (!this.#sessions.release(sessionId)) {
        throw new AggregateError(
          [
            error,
            new Error(`Connection ${sessionId} failed to roll back its Session slot`),
          ],
          "Connection registration failed",
        );
      }
      throw error;
    }
    let resolveClosed!: () => void;
    let rejectClosed!: (reason?: unknown) => void;
    const closed = new Promise<void>((resolve, reject) => {
      resolveClosed = resolve;
      rejectClosed = reject;
    });
    let resolveOnClosedDone!: () => void;
    let rejectOnClosedDone!: (reason?: unknown) => void;
    const onClosedDone = new Promise<void>((resolve, reject) => {
      resolveOnClosedDone = resolve;
      rejectOnClosedDone = reject;
    });
    void closed.catch(() => undefined);
    void onClosedDone.catch(() => undefined);
    this.#pendingClosed.add(closed);
    this.#pendingOnClosed.add(onClosedDone);
    void closed.then(
      () => this.#pendingClosed.delete(closed),
      () => this.#pendingClosed.delete(closed),
    );
    void onClosedDone.then(
      () => this.#pendingOnClosed.delete(onClosedDone),
      () => this.#pendingOnClosed.delete(onClosedDone),
    );

    const record: MutableConnectionRecord<Handle, ProtocolState> = {
      sessionId,
      handle,
      state: CONNECTION_STATE.ACCEPTED,
      protocolState,
      ownerWorkerId: null,
      inputSequence: 0,
      outputSequence: 0,
      inputBufferedBytes: 0,
      outputBufferedBytes: 0,
      outputBufferFull: false,
      overflow: false,
      connectedAt,
      lastActiveAt: connectedAt,
      lastPublishedActiveAt: connectedAt,
      peerInfo,
      closeCause: undefined,
      closeCauseSet: false,
      closed,
      resolveClosed,
      rejectClosed,
      onClosedDone,
      resolveOnClosedDone,
      rejectOnClosedDone,
    };
    this.#bySessionId.set(sessionId, record);
    this.#byHandle.set(handle, sessionId);
    try {
      return this.#publish(record);
    } catch (error) {
      this.#bySessionId.delete(sessionId);
      this.#byHandle.delete(handle);
      this.#pendingClosed.delete(closed);
      this.#pendingOnClosed.delete(onClosedDone);
      const failures: unknown[] = [error];
      try {
        if (!this.#sessions.release(sessionId)) {
          failures.push(
            new Error(`Connection ${sessionId} failed to roll back its Session slot`),
          );
        }
      } catch (releaseError) {
        failures.push(releaseError);
      }
      const rejection = failures.length === 1
        ? failures[0]
        : new AggregateError(failures, "Connection shared publication rollback failed");
      rejectClosed(rejection);
      rejectOnClosedDone(rejection);
      throw rejection;
    }
  }

  has(sessionId: SessionId): boolean {
    return this.#bySessionId.has(sessionId);
  }

  get(sessionId: SessionId): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#bySessionId.get(sessionId);
    return record === undefined ? undefined : this.#snapshot(record);
  }

  getByHandle(handle: Handle): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const sessionId = this.#byHandle.get(handle);
    return sessionId === undefined ? undefined : this.get(sessionId);
  }

  getSessionId(handle: Handle): SessionId | undefined {
    return this.#byHandle.get(handle);
  }

  getHandle(sessionId: SessionId): Handle | undefined {
    return this.#bySessionId.get(sessionId)?.handle;
  }

  setProtocolState(
    sessionId: SessionId,
    protocolState: ProtocolState,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#bySessionId.get(sessionId);
    if (record === undefined || record.state === CONNECTION_STATE.CLOSING) {
      return undefined;
    }
    record.protocolState = protocolState;
    return this.#publish(record);
  }

  markHandshaking(sessionId: SessionId): ConnectionRecordSnapshot<ProtocolState> | undefined {
    return this.#transition(sessionId, CONNECTION_STATE.HANDSHAKING);
  }

  markOpen(sessionId: SessionId): ConnectionRecordSnapshot<ProtocolState> | undefined {
    return this.#transition(sessionId, CONNECTION_STATE.OPEN);
  }

  assignOwner(
    sessionId: SessionId,
    ownerWorkerId: WorkerId | null,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    if (
      ownerWorkerId !== null &&
      (!Number.isSafeInteger(ownerWorkerId) || ownerWorkerId < 0)
    ) {
      throw new RangeError(`ownerWorkerId must be null or a non-negative safe integer`);
    }
    if (record.ownerWorkerId === null) {
      record.ownerWorkerId = ownerWorkerId;
      return this.#publish(record);
    }
    if (record.ownerWorkerId !== ownerWorkerId) {
      throw new Error(
        `Connection ${sessionId} owner cannot be reassigned from ${record.ownerWorkerId} to ${ownerWorkerId}`,
      );
    }
    return this.#publish(record);
  }

  nextInputSequence(sessionId: SessionId): number | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    record.inputSequence = this.#nextSequence("inputSequence", record.inputSequence);
    return record.inputSequence;
  }

  nextOutputSequence(sessionId: SessionId): number | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    record.outputSequence = this.#nextSequence("outputSequence", record.outputSequence);
    return record.outputSequence;
  }

  synchronizeSequences(
    sessionId: SessionId,
    inputSequence: number,
    outputSequence: number,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    assertNonNegativeSafeInteger("inputSequence", inputSequence);
    assertNonNegativeSafeInteger("outputSequence", outputSequence);
    const record = this.#bySessionId.get(sessionId);
    if (record === undefined) {
      return undefined;
    }
    if (
      inputSequence < record.inputSequence ||
      outputSequence < record.outputSequence
    ) {
      throw new RangeError(
        `Connection ${sessionId} data-plane sequences cannot move backwards`,
      );
    }
    if (
      inputSequence === record.inputSequence &&
      outputSequence === record.outputSequence
    ) {
      return this.#snapshot(record);
    }
    record.inputSequence = inputSequence;
    record.outputSequence = outputSequence;
    return this.#publish(record);
  }

  setBufferedBytes(
    sessionId: SessionId,
    inputBufferedBytes: number,
    outputBufferedBytes: number,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    assertNonNegativeSafeInteger("inputBufferedBytes", inputBufferedBytes);
    assertNonNegativeSafeInteger("outputBufferedBytes", outputBufferedBytes);
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    if (
      record.inputBufferedBytes === inputBufferedBytes &&
      record.outputBufferedBytes === outputBufferedBytes
    ) {
      return this.#snapshot(record);
    }
    record.inputBufferedBytes = inputBufferedBytes;
    record.outputBufferedBytes = outputBufferedBytes;
    return this.#publish(record);
  }

  setOverflow(
    sessionId: SessionId,
    overflow: boolean,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    if (record.overflow === overflow) {
      return this.#snapshot(record);
    }
    record.overflow = overflow;
    return this.#publish(record);
  }

  setOutputBufferFull(
    sessionId: SessionId,
    outputBufferFull: boolean,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    if (record.outputBufferFull === outputBufferFull) {
      return this.#snapshot(record);
    }
    record.outputBufferFull = outputBufferFull;
    return this.#publish(record);
  }

  touch(sessionId: SessionId): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    record.lastActiveAt = this.#clock.wallTimeMs();
    return this.#publish(record);
  }

  touchActivity(sessionId: SessionId): boolean {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return false;
    }
    record.lastActiveAt = this.#clock.wallTimeMs();
    if (
      record.lastActiveAt - record.lastPublishedActiveAt >=
        this.#activityPublishIntervalMs
    ) {
      this.#publish(record);
    }
    return true;
  }

  pauseConnection(sessionId: SessionId): boolean {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return false;
    }
    this.#operations.pauseConnection(record.handle);
    return true;
  }

  resumeConnection(sessionId: SessionId): boolean {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return false;
    }
    this.#operations.resumeConnection(record.handle);
    return true;
  }

  write(
    sessionId: SessionId,
    data: Uint8Array,
  ): Readonly<ConnectionWriteResult> | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    const result = this.#operations.write(record.handle, data);
    if (typeof result.backpressured !== "boolean") {
      throw new TypeError("write result backpressured must be a boolean");
    }
    assertNonNegativeSafeInteger("write result bufferedBytes", result.bufferedBytes);
    const bufferedBytesChanged = record.outputBufferedBytes !== result.bufferedBytes;
    record.outputBufferedBytes = result.bufferedBytes;
    if (bufferedBytesChanged) {
      this.#publish(record);
    }
    return Object.freeze({
      backpressured: result.backpressured,
      bufferedBytes: result.bufferedBytes,
    });
  }

  beginClose(sessionId: SessionId, cause?: unknown): boolean {
    const record = this.#bySessionId.get(sessionId);
    if (record === undefined || record.state === CONNECTION_STATE.CLOSING) {
      return false;
    }

    this.#markClosing(record, cause);
    let publicationError: unknown;
    try {
      this.#publish(record);
    } catch (error) {
      publicationError = error;
    }
    try {
      this.#operations.closeConnection(record.handle, cause);
    } catch (error) {
      this.finalizeClose(record.handle, error);
    }
    if (publicationError !== undefined) {
      throw publicationError;
    }
    return true;
  }

  finalizeClose(handle: Handle, cause?: unknown): boolean {
    const sessionId = this.#byHandle.get(handle);
    if (sessionId === undefined) {
      return false;
    }
    const record = this.#bySessionId.get(sessionId);
    if (record === undefined) {
      this.#byHandle.delete(handle);
      return false;
    }

    const closeFailures: unknown[] = [];
    if (record.state !== CONNECTION_STATE.CLOSING) {
      this.#markClosing(record, cause);
      try {
        this.#publish(record);
      } catch (error) {
        closeFailures.push(error);
      }
    }
    assertConnectionTransition(record.state, CONNECTION_STATE.CLOSED);
    record.state = CONNECTION_STATE.CLOSED;
    try {
      record.lastActiveAt = this.#clock.wallTimeMs();
    } catch (error) {
      closeFailures.push(error);
    }
    try {
      this.#publish(record);
    } catch (error) {
      closeFailures.push(error);
    }
    this.#bySessionId.delete(record.sessionId);
    this.#byHandle.delete(record.handle);

    let released = false;
    try {
      released = this.#sessions.release(record.sessionId);
    } catch (error) {
      closeFailures.push(error);
    }
    const snapshot = this.#snapshot(record);
    if (!released) {
      closeFailures.push(
        new Error(`Connection ${record.sessionId} finalized with a stale Session slot`),
      );
    }
    this.#completeClosed(record, snapshot, closeFailures);
    return true;
  }

  async close(sessionId: SessionId, cause?: unknown): Promise<boolean> {
    const record = this.#bySessionId.get(sessionId);
    if (record === undefined) {
      return false;
    }
    const failures: unknown[] = [];
    try {
      this.beginClose(sessionId, cause);
    } catch (error) {
      failures.push(error);
    }
    const results = await Promise.allSettled([
      record.closed,
      ...(this.#shouldJoinOnClosed() ? [record.onClosedDone] : []),
    ]);
    for (const result of results) {
      if (result.status === "rejected") {
        failures.push(result.reason);
      }
    }
    this.#throwCloseFailures(failures, `Connection ${sessionId} close failed`);
    return true;
  }

  async closeAll(cause?: unknown): Promise<void> {
    const records = [...this.#bySessionId.values()];
    const pendingClosed = [...this.#pendingClosed];
    const pendingOnClosed = this.#shouldJoinOnClosed() ? [...this.#pendingOnClosed] : [];
    const failures: unknown[] = [];
    for (const record of records) {
      try {
        this.beginClose(record.sessionId, cause);
      } catch (error) {
        failures.push(error);
      }
    }
    const results = await Promise.allSettled([
      ...pendingClosed,
      ...pendingOnClosed,
    ]);
    for (const result of results) {
      if (result.status === "rejected") {
        failures.push(result.reason);
      }
    }
    this.#throwCloseFailures(failures, "ConnectionRegistry close failed");
  }

  #transition(
    sessionId: SessionId,
    state: typeof CONNECTION_STATE.HANDSHAKING | typeof CONNECTION_STATE.OPEN,
  ): ConnectionRecordSnapshot<ProtocolState> | undefined {
    const record = this.#findUsable(sessionId);
    if (record === undefined) {
      return undefined;
    }
    assertConnectionTransition(record.state, state);
    record.state = state;
    record.lastActiveAt = this.#clock.wallTimeMs();
    return this.#publish(record);
  }

  #findUsable(
    sessionId: SessionId,
  ): MutableConnectionRecord<Handle, ProtocolState> | undefined {
    const record = this.#bySessionId.get(sessionId);
    return record === undefined || record.state === CONNECTION_STATE.CLOSING
      ? undefined
      : record;
  }

  #nextSequence(name: string, current: number): number {
    if (current >= Number.MAX_SAFE_INTEGER) {
      throw new RangeError(`${name} exhausted the safe integer range`);
    }
    return current + 1;
  }

  #markClosing(
    record: MutableConnectionRecord<Handle, ProtocolState>,
    cause: unknown,
  ): void {
    assertConnectionTransition(record.state, CONNECTION_STATE.CLOSING);
    record.state = CONNECTION_STATE.CLOSING;
    if (!record.closeCauseSet) {
      record.closeCause = cause;
      record.closeCauseSet = true;
    }
  }

  #shouldJoinOnClosed(): boolean {
    const invocation = activeConnectionClosedHandler.getStore();
    return invocation?.active !== true || invocation.registry !== this;
  }

  #throwCloseFailures(failures: readonly unknown[], message: string): void {
    if (failures.length === 0) {
      return;
    }
    if (failures.length === 1) {
      throw failures[0];
    }
    throw new AggregateError(failures, message);
  }

  #completeClosed(
    record: MutableConnectionRecord<Handle, ProtocolState>,
    snapshot: ConnectionRecordSnapshot<ProtocolState>,
    closeFailures: readonly unknown[],
  ): void {
    if (closeFailures.length === 0) {
      record.resolveClosed();
    } else if (closeFailures.length === 1) {
      record.rejectClosed(closeFailures[0]);
    } else {
      record.rejectClosed(
        new AggregateError(closeFailures, `Connection ${record.sessionId} close failed`),
      );
    }

    if (this.#onClosed === undefined) {
      record.resolveOnClosedDone();
      return;
    }

    const invocation: ConnectionClosedHandlerInvocation = {
      active: true,
      registry: this,
    };
    let result: void | Promise<void>;
    try {
      result = activeConnectionClosedHandler.run(
        invocation,
        () => this.#onClosed?.(snapshot),
      );
    } catch (error) {
      invocation.active = false;
      record.rejectOnClosedDone(error);
      return;
    }
    void Promise.resolve(result).then(
      () => {
        invocation.active = false;
        record.resolveOnClosedDone();
      },
      (error: unknown) => {
        invocation.active = false;
        record.rejectOnClosedDone(error);
      },
    );
  }

  #snapshot(
    record: MutableConnectionRecord<Handle, ProtocolState>,
  ): ConnectionRecordSnapshot<ProtocolState> {
    return Object.freeze({
      sessionId: record.sessionId,
      state: record.state,
      protocolState: record.protocolState,
      ownerWorkerId: record.ownerWorkerId,
      inputSequence: record.inputSequence,
      outputSequence: record.outputSequence,
      inputBufferedBytes: record.inputBufferedBytes,
      outputBufferedBytes: record.outputBufferedBytes,
      outputBufferFull: record.outputBufferFull,
      overflow: record.overflow,
      connectedAt: record.connectedAt,
      lastActiveAt: record.lastActiveAt,
      peerInfo: record.peerInfo,
      closeCause: record.closeCause,
      closed: record.closed,
    });
  }

  #publish(
    record: MutableConnectionRecord<Handle, ProtocolState>,
  ): ConnectionRecordSnapshot<ProtocolState> {
    const snapshot = this.#snapshot(record);
    this.#onRecordChanged?.(snapshot);
    record.lastPublishedActiveAt = record.lastActiveAt;
    return snapshot;
  }
}
