export const DEFAULT_TCP_MAX_FRAME_BYTES = 512 * 1024;
export const DEFAULT_TCP_LENGTH_OFFSET = 0;
export const DEFAULT_TCP_LENGTH_FIELD_BYTES = 4;
export const DEFAULT_TCP_BODY_OFFSET = 5;

export type TcpLengthFieldBytes = 1 | 2 | 4;

export interface TcpFrameCodecOptions {
  readonly lengthOffset?: number;
  readonly lengthFieldBytes?: TcpLengthFieldBytes;
  readonly bodyOffset?: number;
  readonly maxFrameBytes?: number;
}

export interface TcpFrameCodecLike {
  readonly lengthOffset: number;
  readonly lengthFieldBytes: TcpLengthFieldBytes;
  readonly bodyOffset: number;
  readonly maxFrameBytes: number;
  readonly bufferedBytes: number;
  push(chunk: Uint8Array): readonly Buffer[];
  encode(body: Uint8Array, header?: Uint8Array): Buffer;
  reset(): void;
}

export type TcpFrameProtocolErrorCode =
  | "FRAME_TOO_LARGE"
  | "LENGTH_OUT_OF_RANGE";

export class TcpFrameProtocolError extends Error {
  readonly code: TcpFrameProtocolErrorCode;
  readonly details: Readonly<Record<string, unknown>>;

  constructor(
    code: TcpFrameProtocolErrorCode,
    message: string,
    details: Readonly<Record<string, unknown>> = {},
  ) {
    super(message);
    this.name = "TcpFrameProtocolError";
    this.code = code;
    this.details = Object.freeze({ ...details });
  }
}

const EMPTY_BUFFER: Buffer = Buffer.alloc(0);

function assertNonNegativeSafeInteger(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function maximumUnsignedValue(byteLength: TcpLengthFieldBytes): number {
  return byteLength === 4 ? 0xffff_ffff : (2 ** (byteLength * 8)) - 1;
}

/**
 * Incrementally decodes the Swoole-style length protocol. The length field
 * contains the body size; emitted buffers include the complete header and body.
 */
export class TcpFrameCodec implements TcpFrameCodecLike {
  readonly lengthOffset: number;
  readonly lengthFieldBytes: TcpLengthFieldBytes;
  readonly bodyOffset: number;
  readonly maxFrameBytes: number;
  readonly #headerBytes: number;
  #buffer = EMPTY_BUFFER;

  constructor(options: TcpFrameCodecOptions = {}) {
    this.lengthOffset = options.lengthOffset ?? DEFAULT_TCP_LENGTH_OFFSET;
    this.lengthFieldBytes = options.lengthFieldBytes ??
      DEFAULT_TCP_LENGTH_FIELD_BYTES;
    this.bodyOffset = options.bodyOffset ?? DEFAULT_TCP_BODY_OFFSET;
    this.maxFrameBytes = options.maxFrameBytes ?? DEFAULT_TCP_MAX_FRAME_BYTES;

    assertNonNegativeSafeInteger("lengthOffset", this.lengthOffset);
    assertNonNegativeSafeInteger("bodyOffset", this.bodyOffset);
    assertNonNegativeSafeInteger("maxFrameBytes", this.maxFrameBytes);

    const lengthFieldEnd = this.lengthOffset + this.lengthFieldBytes;
    if (this.bodyOffset < lengthFieldEnd) {
      throw new RangeError(
        `bodyOffset ${this.bodyOffset} must not overlap the length field ending at ${lengthFieldEnd}`,
      );
    }
    if (this.maxFrameBytes < this.bodyOffset) {
      throw new RangeError(
        `maxFrameBytes ${this.maxFrameBytes} must be at least bodyOffset ${this.bodyOffset}`,
      );
    }
    this.#headerBytes = Math.max(this.bodyOffset, lengthFieldEnd);
  }

  get bufferedBytes(): number {
    return this.#buffer.byteLength;
  }

  push(chunk: Uint8Array): readonly Buffer[] {
    if (!(chunk instanceof Uint8Array)) {
      throw new TypeError("TCP chunk must be a Uint8Array");
    }
    if (chunk.byteLength === 0) {
      return Object.freeze([]);
    }

    const incoming = Buffer.isBuffer(chunk)
      ? chunk
      : Buffer.from(chunk.buffer, chunk.byteOffset, chunk.byteLength);
    this.#buffer = this.#buffer.byteLength === 0
      ? incoming
      : Buffer.concat([this.#buffer, incoming]);

    const frames: Buffer[] = [];
    let offset = 0;
    while (this.#buffer.byteLength - offset >= this.#headerBytes) {
      const bodyLength = this.#buffer.readUIntBE(
        offset + this.lengthOffset,
        this.lengthFieldBytes,
      );
      const frameLength = this.bodyOffset + bodyLength;
      if (!Number.isSafeInteger(frameLength)) {
        this.#buffer = EMPTY_BUFFER;
        throw new TcpFrameProtocolError(
          "LENGTH_OUT_OF_RANGE",
          "TCP frame length is outside the safe integer range",
          { bodyLength, bodyOffset: this.bodyOffset },
        );
      }
      if (frameLength > this.maxFrameBytes) {
        this.#buffer = EMPTY_BUFFER;
        throw new TcpFrameProtocolError(
          "FRAME_TOO_LARGE",
          `TCP frame size ${frameLength} exceeds ${this.maxFrameBytes} bytes`,
          { bodyLength, frameLength, maxFrameBytes: this.maxFrameBytes },
        );
      }
      if (this.#buffer.byteLength - offset < frameLength) {
        break;
      }

      frames.push(
        offset === 0 && frameLength === this.#buffer.byteLength
          ? this.#buffer
          : this.#buffer.subarray(offset, offset + frameLength),
      );
      offset += frameLength;
    }

    if (offset !== 0) {
      this.#buffer = offset === this.#buffer.byteLength
        ? EMPTY_BUFFER
        : Buffer.from(this.#buffer.subarray(offset));
    }
    return Object.freeze(frames);
  }

  encode(body: Uint8Array, header?: Uint8Array): Buffer {
    if (!(body instanceof Uint8Array)) {
      throw new TypeError("TCP frame body must be a Uint8Array");
    }
    if (header !== undefined && header.byteLength !== this.bodyOffset) {
      throw new RangeError(
        `TCP frame header must contain exactly ${this.bodyOffset} bytes`,
      );
    }

    const frameLength = this.bodyOffset + body.byteLength;
    if (frameLength > this.maxFrameBytes) {
      throw new TcpFrameProtocolError(
        "FRAME_TOO_LARGE",
        `TCP frame size ${frameLength} exceeds ${this.maxFrameBytes} bytes`,
        { bodyLength: body.byteLength, frameLength, maxFrameBytes: this.maxFrameBytes },
      );
    }
    if (body.byteLength > maximumUnsignedValue(this.lengthFieldBytes)) {
      throw new TcpFrameProtocolError(
        "LENGTH_OUT_OF_RANGE",
        `TCP body size ${body.byteLength} does not fit a ${this.lengthFieldBytes}-byte length field`,
        { bodyLength: body.byteLength, lengthFieldBytes: this.lengthFieldBytes },
      );
    }

    const frame = Buffer.allocUnsafe(frameLength);
    if (header === undefined) {
      frame.fill(0, 0, this.bodyOffset);
    } else {
      frame.set(header, 0);
    }
    frame.writeUIntBE(body.byteLength, this.lengthOffset, this.lengthFieldBytes);
    frame.set(body, this.bodyOffset);
    return frame;
  }

  reset(): void {
    this.#buffer = EMPTY_BUFFER;
  }
}
