import {
  IPC_PROTOCOL_VERSION,
  IPC_MESSAGE_TYPE,
  createIpcEnvelope,
  createMessageId,
  type IpcEnvelopeV1,
  type IpcMessageType,
  type IpcSequence,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import type { SessionId } from "../protocol/session-id.ts";
import { createWorkerId, type WorkerId } from "../protocol/worker-id.ts";
import type { ProcessBus } from "../process/process-bus.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import type { RuntimeProtocol } from "../runtime/runtime-server.ts";
import {
  NETWORK_BUFFER_STATE,
  decodeNetworkBufferStatePayload,
  type NetworkBufferState,
  type NetworkBufferStatePayload,
} from "./network-buffer-protocol.ts";
import {
  decodeNetworkClosePayload,
  decodeNetworkConnectPayload,
  decodeNetworkMessagePayload,
  isNetworkResumePayload,
  type NetworkClosePayload,
  type NetworkConnectEventPayload,
  type NetworkMessagePayload,
} from "./network-event-protocol.ts";

const NETWORK_EVENT_MESSAGE_TYPES: ReadonlySet<IpcMessageType> = new Set([
  IPC_MESSAGE_TYPE.NET_CONNECT,
  IPC_MESSAGE_TYPE.NET_MESSAGE,
  IPC_MESSAGE_TYPE.NET_CLOSE,
  IPC_MESSAGE_TYPE.NET_BUFFER_STATE,
]);

export const WORKER_NETWORK_EVENT_REJECTION_REASON = Object.freeze({
  INVALID_SOURCE: "INVALID_SOURCE",
  INVALID_TARGET: "INVALID_TARGET",
  INVALID_METADATA: "INVALID_METADATA",
  MISSING_SESSION: "MISSING_SESSION",
  INVALID_PAYLOAD: "INVALID_PAYLOAD",
  OWNER_MISMATCH: "OWNER_MISMATCH",
  DUPLICATE_SESSION: "DUPLICATE_SESSION",
  UNKNOWN_SESSION: "UNKNOWN_SESSION",
  DUPLICATE_SEQUENCE: "DUPLICATE_SEQUENCE",
  OUT_OF_ORDER_SEQUENCE: "OUT_OF_ORDER_SEQUENCE",
  PROTOCOL_MISMATCH: "PROTOCOL_MISMATCH",
  CLOSE_SEQUENCE_MISMATCH: "CLOSE_SEQUENCE_MISMATCH",
  INVALID_BUFFER_TRANSITION: "INVALID_BUFFER_TRANSITION",
} as const);

export type WorkerNetworkEventRejectionReason =
  (typeof WORKER_NETWORK_EVENT_REJECTION_REASON)[
    keyof typeof WORKER_NETWORK_EVENT_REJECTION_REASON
  ];

export interface WorkerNetworkConnectEvent {
  readonly type: "connect";
  readonly sessionId: SessionId;
  readonly sequence: IpcSequence;
  readonly payload: Readonly<NetworkConnectEventPayload>;
}

export interface WorkerNetworkMessageEvent {
  readonly type: "message";
  readonly sessionId: SessionId;
  readonly sequence: IpcSequence;
  readonly payload: Readonly<NetworkMessagePayload>;
}

export interface WorkerNetworkCloseEvent {
  readonly type: "close";
  readonly sessionId: SessionId;
  readonly sequence: IpcSequence;
  readonly payload: Readonly<NetworkClosePayload>;
}

export type WorkerNetworkEventListener<Event> = (
  event: Readonly<Event>,
) => void | Promise<void>;

export type WorkerNetworkEventListenerDisposer = () => void;

export interface WorkerNetworkBufferEvent {
  readonly type: "buffer";
  readonly sessionId: SessionId;
  readonly sequence: IpcSequence;
  readonly payload: Readonly<NetworkBufferStatePayload>;
}

export type WorkerNetworkEventBus = Pick<ProcessBus, "localIdentity" | "onMessage">;

export interface WorkerNetworkEventReceiverOptions {
  readonly bus: WorkerNetworkEventBus;
  readonly localWorkerId: WorkerId;
  readonly onMessageComplete?: (completedMessages: number) => void;
}

export interface WorkerNetworkEventReceiverStats {
  readonly closed: boolean;
  readonly activeSessions: number;
  readonly acceptedEvents: number;
  readonly acceptedConnects: number;
  readonly acceptedMessages: number;
  readonly completedMessages: number;
  readonly acceptedCloses: number;
  readonly acceptedBufferEvents: number;
  readonly bufferFullEvents: number;
  readonly bufferOverflowEvents: number;
  readonly bufferEmptyEvents: number;
  readonly ignoredEvents: number;
  readonly rejectedEvents: number;
  readonly callbackErrors: number;
  readonly rejectionCounts: Readonly<
    Partial<Record<WorkerNetworkEventRejectionReason, number>>
  >;
}

interface WorkerNetworkSessionState {
  readonly protocol: RuntimeProtocol;
  nextSequence: number;
  bufferState: "empty" | NetworkBufferState;
}

export class WorkerNetworkEventRejectedError extends Error {
  readonly reason: WorkerNetworkEventRejectionReason;
  readonly messageType: IpcMessageType;
  readonly sessionId: SessionId | null;

  constructor(
    reason: WorkerNetworkEventRejectionReason,
    envelope: Readonly<IpcEnvelopeV1>,
    message: string,
    cause?: unknown,
  ) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = "WorkerNetworkEventRejectedError";
    this.reason = reason;
    this.messageType = envelope.messageType;
    this.sessionId = envelope.sessionId;
  }
}

export class WorkerNetworkEventReceiver implements RuntimeResource {
  readonly localWorkerId: WorkerId;

  readonly #sessions = new Map<SessionId, WorkerNetworkSessionState>();
  readonly #connectListeners = new Set<
    WorkerNetworkEventListener<WorkerNetworkConnectEvent>
  >();
  readonly #messageListeners = new Set<
    WorkerNetworkEventListener<WorkerNetworkMessageEvent>
  >();
  readonly #closeListeners = new Set<
    WorkerNetworkEventListener<WorkerNetworkCloseEvent>
  >();
  readonly #bufferListeners = new Set<
    WorkerNetworkEventListener<WorkerNetworkBufferEvent>
  >();
  readonly #rejectionCounts = new Map<WorkerNetworkEventRejectionReason, number>();
  readonly #onMessageComplete: ((completedMessages: number) => void) | undefined;
  #disposeBusMessage: WorkerNetworkEventListenerDisposer;
  #closed = false;
  #acceptedConnects = 0;
  #acceptedMessages = 0;
  #completedMessages = 0;
  #acceptedCloses = 0;
  #acceptedBufferEvents = 0;
  #bufferFullEvents = 0;
  #bufferOverflowEvents = 0;
  #bufferEmptyEvents = 0;
  #ignoredEvents = 0;
  #rejectedEvents = 0;
  #callbackErrors = 0;

  constructor(options: WorkerNetworkEventReceiverOptions) {
    this.localWorkerId = createWorkerId(options.localWorkerId);
    const identity = options.bus.localIdentity;
    if (
      identity.role !== PROCESS_ROLE.WORKER ||
      identity.workerId !== this.localWorkerId ||
      identity.generation === null
    ) {
      throw new TypeError(
        "WorkerNetworkEventReceiver requires the matching event Worker ProcessBus identity",
      );
    }
    this.#onMessageComplete = options.onMessageComplete;
    this.#disposeBusMessage = options.bus.onMessage(this.#handleEnvelope);
  }

  onConnect(
    listener: WorkerNetworkEventListener<WorkerNetworkConnectEvent>,
  ): WorkerNetworkEventListenerDisposer {
    return this.#addListener(this.#connectListeners, listener);
  }

  onMessage(
    listener: WorkerNetworkEventListener<WorkerNetworkMessageEvent>,
  ): WorkerNetworkEventListenerDisposer {
    return this.#addListener(this.#messageListeners, listener);
  }

  acceptNativeTcpMessage(
    sessionId: SessionId,
    sequence: IpcSequence,
    data: Uint8Array,
  ): void | Promise<void> {
    if (this.#closed) {
      return;
    }
    const state = this.#sessions.get(sessionId);
    if (state === undefined) {
      throw new Error(
        `native NET_MESSAGE references unknown Session ${sessionId}`,
      );
    }
    if (state.protocol !== "tcp") {
      throw new Error(
        `native NET_MESSAGE for Session ${sessionId} requires TCP`,
      );
    }
    if (sequence < state.nextSequence) {
      this.#ignoredEvents += 1;
      return;
    }
    if (sequence !== state.nextSequence) {
      throw new Error(
        `native NET_MESSAGE for Session ${sessionId} expected sequence ${state.nextSequence}, got ${sequence}`,
      );
    }

    state.nextSequence += 1;
    this.#acceptedMessages += 1;
    let completion: void | Promise<void>;
    try {
      completion = this.#invokeListeners(this.#messageListeners, Object.freeze({
        type: "message",
        sessionId,
        sequence,
        payload: Object.freeze({
          protocol: "tcp",
          data: Buffer.from(data.buffer, data.byteOffset, data.byteLength),
          finish: true,
        }),
      }));
    } catch (error) {
      this.#completeMessage();
      throw error;
    }
    if (completion === undefined) {
      this.#completeMessage();
      return;
    }
    return completion.finally(() => this.#completeMessage());
  }

  acceptNativeTcpConnect(
    sessionId: SessionId,
    sequence: IpcSequence,
    payload: unknown,
  ): void | Promise<void> {
    return this.#acceptConnect(
      this.#createNativeEnvelope(
        IPC_MESSAGE_TYPE.NET_CONNECT,
        sessionId,
        sequence,
        payload,
      ),
      sessionId,
    );
  }

  acceptNativeTcpClose(
    sessionId: SessionId,
    sequence: IpcSequence,
    payload: unknown,
  ): void | Promise<void> {
    return this.#acceptClose(
      this.#createNativeEnvelope(
        IPC_MESSAGE_TYPE.NET_CLOSE,
        sessionId,
        sequence,
        payload,
      ),
      sessionId,
    );
  }

  acceptNativeTcpBuffer(
    sessionId: SessionId,
    sequence: IpcSequence,
    payload: unknown,
  ): void | Promise<void> {
    return this.#acceptBufferState(
      this.#createNativeEnvelope(
        IPC_MESSAGE_TYPE.NET_BUFFER_STATE,
        sessionId,
        sequence,
        payload,
      ),
      sessionId,
    );
  }

  onClose(
    listener: WorkerNetworkEventListener<WorkerNetworkCloseEvent>,
  ): WorkerNetworkEventListenerDisposer {
    return this.#addListener(this.#closeListeners, listener);
  }

  onBuffer(
    listener: WorkerNetworkEventListener<WorkerNetworkBufferEvent>,
  ): WorkerNetworkEventListenerDisposer {
    return this.#addListener(this.#bufferListeners, listener);
  }

  stats(): Readonly<WorkerNetworkEventReceiverStats> {
    return Object.freeze({
      closed: this.#closed,
      activeSessions: this.#sessions.size,
      acceptedEvents:
        this.#acceptedConnects + this.#acceptedMessages + this.#acceptedCloses +
        this.#acceptedBufferEvents,
      acceptedConnects: this.#acceptedConnects,
      acceptedMessages: this.#acceptedMessages,
      completedMessages: this.#completedMessages,
      acceptedCloses: this.#acceptedCloses,
      acceptedBufferEvents: this.#acceptedBufferEvents,
      bufferFullEvents: this.#bufferFullEvents,
      bufferOverflowEvents: this.#bufferOverflowEvents,
      bufferEmptyEvents: this.#bufferEmptyEvents,
      ignoredEvents: this.#ignoredEvents,
      rejectedEvents: this.#rejectedEvents,
      callbackErrors: this.#callbackErrors,
      rejectionCounts: Object.freeze(
        Object.fromEntries(this.#rejectionCounts) as Partial<
          Record<WorkerNetworkEventRejectionReason, number>
        >,
      ),
    });
  }

  close(_reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#closed = true;
    this.#disposeBusMessage();
    this.#disposeBusMessage = () => {};
    this.#sessions.clear();
    this.#connectListeners.clear();
    this.#messageListeners.clear();
    this.#closeListeners.clear();
    this.#bufferListeners.clear();
  }

  readonly #handleEnvelope = async (
    envelope: Readonly<IpcEnvelopeV1>,
  ): Promise<void> => {
    if (this.#closed) {
      return;
    }
    if (!NETWORK_EVENT_MESSAGE_TYPES.has(envelope.messageType)) {
      this.#ignoredEvents += 1;
      return;
    }

    this.#assertEnvelopeAddress(envelope);
    const sessionId = envelope.sessionId;
    if (sessionId === null) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.MISSING_SESSION,
        envelope,
        `${envelope.messageType} requires a Session ID`,
      );
    }

    switch (envelope.messageType) {
      case IPC_MESSAGE_TYPE.NET_CONNECT:
        await this.#acceptConnect(envelope, sessionId);
        return;
      case IPC_MESSAGE_TYPE.NET_MESSAGE:
        await this.#acceptMessage(envelope, sessionId);
        return;
      case IPC_MESSAGE_TYPE.NET_CLOSE:
        await this.#acceptClose(envelope, sessionId);
        return;
      case IPC_MESSAGE_TYPE.NET_BUFFER_STATE:
        await this.#acceptBufferState(envelope, sessionId);
        return;
      default:
        return;
    }
  };

  #createNativeEnvelope(
    messageType:
      | typeof IPC_MESSAGE_TYPE.NET_CONNECT
      | typeof IPC_MESSAGE_TYPE.NET_CLOSE
      | typeof IPC_MESSAGE_TYPE.NET_BUFFER_STATE,
    sessionId: SessionId,
    sequence: IpcSequence,
    payload: unknown,
  ): Readonly<IpcEnvelopeV1> {
    return createIpcEnvelope({
      protocolVersion: IPC_PROTOCOL_VERSION,
      messageId: createMessageId(`native-${messageType}-${sessionId}-${sequence}`),
      messageType,
      sourceRole: PROCESS_ROLE.MASTER,
      sourceWorkerId: null,
      sourceGeneration: null,
      targetRole: PROCESS_ROLE.WORKER,
      targetWorkerId: this.localWorkerId,
      correlationId: null,
      sessionId,
      sequence,
      flags: 0,
      payload: payload as IpcEnvelopeV1["payload"],
    });
  }

  #assertEnvelopeAddress(envelope: Readonly<IpcEnvelopeV1>): void {
    if (
      envelope.sourceRole !== PROCESS_ROLE.MASTER ||
      envelope.sourceWorkerId !== null ||
      envelope.sourceGeneration !== null
    ) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_SOURCE,
        envelope,
        `${envelope.messageType} must originate from Master`,
      );
    }
    if (
      envelope.targetRole !== PROCESS_ROLE.WORKER ||
      envelope.targetWorkerId !== this.localWorkerId
    ) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_TARGET,
        envelope,
        `${envelope.messageType} must target Worker ${this.localWorkerId}`,
      );
    }
    if (envelope.correlationId !== null || envelope.flags !== 0) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_METADATA,
        envelope,
        `${envelope.messageType} cannot carry correlation or response flags`,
      );
    }
  }

  #acceptConnect(
    envelope: Readonly<IpcEnvelopeV1>,
    sessionId: SessionId,
  ): void | Promise<void> {
    if (this.#sessions.has(sessionId)) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.DUPLICATE_SESSION,
        envelope,
        `Session ${sessionId} already has an active NET_CONNECT`,
      );
    }
    const payload = this.#decodeConnect(envelope);
    const resumed = isNetworkResumePayload(payload);
    if (!resumed && envelope.sequence !== 0) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.OUT_OF_ORDER_SEQUENCE,
        envelope,
        `NET_CONNECT for Session ${sessionId} requires sequence 0`,
      );
    }
    if (resumed && envelope.sequence !== payload.inputSequence) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.OUT_OF_ORDER_SEQUENCE,
        envelope,
        `NET_CONNECT resume for Session ${sessionId} sequence ${envelope.sequence} does not match restored inputSequence ${payload.inputSequence}`,
      );
    }
    this.#assertOwner(envelope, payload.ownerWorkerId);

    this.#sessions.set(sessionId, {
      protocol: payload.protocol,
      nextSequence: resumed ? payload.inputSequence + 1 : 1,
      bufferState: resumed ? payload.outputBufferState : "empty",
    });
    this.#acceptedConnects += 1;
    return this.#invokeListeners(this.#connectListeners, Object.freeze({
      type: "connect",
      sessionId,
      sequence: envelope.sequence,
      payload,
    }));
  }

  #acceptMessage(
    envelope: Readonly<IpcEnvelopeV1>,
    sessionId: SessionId,
  ): void | Promise<void> {
    const state = this.#requireSession(envelope, sessionId);
    this.#assertSequence(envelope, state.nextSequence);
    const payload = this.#decodeMessage(envelope);
    this.#assertProtocol(envelope, state.protocol, payload.protocol);

    state.nextSequence += 1;
    this.#acceptedMessages += 1;
    let completion: void | Promise<void>;
    try {
      completion = this.#invokeListeners(this.#messageListeners, Object.freeze({
        type: "message",
        sessionId,
        sequence: envelope.sequence,
        payload,
      }));
    } catch (error) {
      this.#completeMessage();
      throw error;
    }
    if (completion === undefined) {
      this.#completeMessage();
      return;
    }
    return completion.finally(() => this.#completeMessage());
  }

  #acceptClose(
    envelope: Readonly<IpcEnvelopeV1>,
    sessionId: SessionId,
  ): void | Promise<void> {
    const state = this.#requireSession(envelope, sessionId);
    this.#assertSequence(envelope, state.nextSequence);
    const payload = this.#decodeClose(envelope);
    this.#assertOwner(envelope, payload.ownerWorkerId);
    this.#assertProtocol(envelope, state.protocol, payload.protocol);
    if (payload.inputSequence !== envelope.sequence - 1) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.CLOSE_SEQUENCE_MISMATCH,
        envelope,
        `NET_CLOSE for Session ${sessionId} has inconsistent final inputSequence`,
      );
    }

    this.#sessions.delete(sessionId);
    this.#acceptedCloses += 1;
    return this.#invokeListeners(this.#closeListeners, Object.freeze({
      type: "close",
      sessionId,
      sequence: envelope.sequence,
      payload,
    }));
  }

  #acceptBufferState(
    envelope: Readonly<IpcEnvelopeV1>,
    sessionId: SessionId,
  ): void | Promise<void> {
    const session = this.#requireSession(envelope, sessionId);
    let payload: Readonly<NetworkBufferStatePayload>;
    try {
      payload = decodeNetworkBufferStatePayload(envelope.payload);
    } catch (error) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_PAYLOAD,
        envelope,
        "NET_BUFFER_STATE payload is invalid",
        error,
      );
    }
    this.#assertOwner(envelope, payload.ownerWorkerId);
    this.#assertProtocol(envelope, session.protocol, payload.protocol);
    this.#assertBufferTransition(envelope, session.bufferState, payload.state);

    session.bufferState = payload.state === NETWORK_BUFFER_STATE.EMPTY
      ? "empty"
      : payload.state;
    this.#acceptedBufferEvents += 1;
    if (payload.state === NETWORK_BUFFER_STATE.FULL) {
      this.#bufferFullEvents += 1;
    } else if (payload.state === NETWORK_BUFFER_STATE.OVERFLOW) {
      this.#bufferOverflowEvents += 1;
    } else {
      this.#bufferEmptyEvents += 1;
    }
    return this.#invokeListeners(this.#bufferListeners, Object.freeze({
      type: "buffer",
      sessionId,
      sequence: envelope.sequence,
      payload,
    }));
  }

  #assertBufferTransition(
    envelope: Readonly<IpcEnvelopeV1>,
    previous: "empty" | NetworkBufferState,
    next: NetworkBufferState,
  ): void {
    const valid =
      (previous === "empty" && next === NETWORK_BUFFER_STATE.FULL) ||
      (previous === NETWORK_BUFFER_STATE.FULL &&
        next === NETWORK_BUFFER_STATE.OVERFLOW) ||
      ((previous === NETWORK_BUFFER_STATE.FULL ||
        previous === NETWORK_BUFFER_STATE.OVERFLOW) &&
        next === NETWORK_BUFFER_STATE.EMPTY);
    if (!valid) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_BUFFER_TRANSITION,
        envelope,
        `NET_BUFFER_STATE cannot transition from ${previous} to ${next}`,
      );
    }
  }

  #decodeConnect(
    envelope: Readonly<IpcEnvelopeV1>,
  ): Readonly<NetworkConnectEventPayload> {
    try {
      return decodeNetworkConnectPayload(envelope.payload);
    } catch (error) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_PAYLOAD,
        envelope,
        "NET_CONNECT payload is invalid",
        error,
      );
    }
  }

  #decodeMessage(envelope: Readonly<IpcEnvelopeV1>): Readonly<NetworkMessagePayload> {
    try {
      return decodeNetworkMessagePayload(envelope.payload);
    } catch (error) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_PAYLOAD,
        envelope,
        "NET_MESSAGE payload is invalid",
        error,
      );
    }
  }

  #decodeClose(envelope: Readonly<IpcEnvelopeV1>): Readonly<NetworkClosePayload> {
    try {
      return decodeNetworkClosePayload(envelope.payload);
    } catch (error) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.INVALID_PAYLOAD,
        envelope,
        "NET_CLOSE payload is invalid",
        error,
      );
    }
  }

  #assertOwner(envelope: Readonly<IpcEnvelopeV1>, ownerWorkerId: WorkerId): void {
    if (ownerWorkerId !== this.localWorkerId) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.OWNER_MISMATCH,
        envelope,
        `${envelope.messageType} owner does not match Worker ${this.localWorkerId}`,
      );
    }
  }

  #assertProtocol(
    envelope: Readonly<IpcEnvelopeV1>,
    expected: RuntimeProtocol,
    actual: RuntimeProtocol,
  ): void {
    if (actual !== expected) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.PROTOCOL_MISMATCH,
        envelope,
        `${envelope.messageType} protocol ${actual} does not match ${expected}`,
      );
    }
  }

  #requireSession(
    envelope: Readonly<IpcEnvelopeV1>,
    sessionId: SessionId,
  ): WorkerNetworkSessionState {
    const state = this.#sessions.get(sessionId);
    if (state === undefined) {
      this.#reject(
        WORKER_NETWORK_EVENT_REJECTION_REASON.UNKNOWN_SESSION,
        envelope,
        `${envelope.messageType} references unknown Session ${sessionId}`,
      );
    }
    return state;
  }

  #assertSequence(envelope: Readonly<IpcEnvelopeV1>, expected: number): void {
    if (envelope.sequence === expected) {
      return;
    }
    const reason = envelope.sequence < expected
      ? WORKER_NETWORK_EVENT_REJECTION_REASON.DUPLICATE_SEQUENCE
      : WORKER_NETWORK_EVENT_REJECTION_REASON.OUT_OF_ORDER_SEQUENCE;
    this.#reject(
      reason,
      envelope,
      `${envelope.messageType} sequence ${envelope.sequence} does not match ${expected}`,
    );
  }

  #reject(
    reason: WorkerNetworkEventRejectionReason,
    envelope: Readonly<IpcEnvelopeV1>,
    message: string,
    cause?: unknown,
  ): never {
    this.#rejectedEvents += 1;
    this.#rejectionCounts.set(reason, (this.#rejectionCounts.get(reason) ?? 0) + 1);
    throw new WorkerNetworkEventRejectedError(reason, envelope, message, cause);
  }

  #addListener<Event>(
    listeners: Set<WorkerNetworkEventListener<Event>>,
    listener: WorkerNetworkEventListener<Event>,
  ): WorkerNetworkEventListenerDisposer {
    if (this.#closed) {
      return () => {};
    }
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  }

  #completeMessage(): void {
    this.#completedMessages += 1;
    try {
      this.#onMessageComplete?.(this.#completedMessages);
    } catch {
      // Internal completion observation cannot change callback completion semantics.
    }
  }

  #invokeListeners<Event>(
    listeners: ReadonlySet<WorkerNetworkEventListener<Event>>,
    event: Readonly<Event>,
  ): void | Promise<void> {
    const snapshot = [...listeners];
    const failures: unknown[] = [];
    for (let index = 0; index < snapshot.length; index += 1) {
      try {
        const completion = snapshot[index]!(event);
        if (completion !== undefined) {
          return this.#continueInvokingListeners(
            snapshot,
            event,
            index + 1,
            completion,
            failures,
          );
        }
      } catch (error) {
        failures.push(error);
      }
    }
    this.#finishListenerFailures(failures);
  }

  async #continueInvokingListeners<Event>(
    listeners: readonly WorkerNetworkEventListener<Event>[],
    event: Readonly<Event>,
    index: number,
    pending: Promise<void>,
    failures: unknown[],
  ): Promise<void> {
    let completion: Promise<void> | undefined = pending;
    for (;;) {
      try {
        await completion;
      } catch (error) {
        failures.push(error);
      }
      completion = undefined;
      while (index < listeners.length) {
        try {
          const result = listeners[index++]!(event);
          if (result !== undefined) {
            completion = result;
            break;
          }
        } catch (error) {
          failures.push(error);
        }
      }
      if (completion === undefined) {
        this.#finishListenerFailures(failures);
        return;
      }
    }
  }

  #finishListenerFailures(failures: readonly unknown[]): void {
    this.#callbackErrors += failures.length;
    if (failures.length === 1) {
      throw failures[0];
    }
    if (failures.length > 1) {
      throw new AggregateError(failures, "Worker network event callbacks failed");
    }
  }
}
