import {
  decodeSessionId,
  encodeSessionId,
  isSessionId,
  SESSION_ID_LAYOUT,
  type SessionId,
} from "../protocol/session-id.ts";

const MAX_SESSION_SLOTS = SESSION_ID_LAYOUT.maxSlotIndex + 1;

interface MutableSessionSlot {
  readonly slotIndex: number;
  generation: number;
  sessionId: SessionId | null;
  retired: boolean;
}

export interface SessionManagerOptions {
  readonly masterGeneration: number;
  readonly maxConnections?: number;
}

export class SessionCapacityExhaustedError extends Error {
  constructor(capacity: number, retiredSlots: number) {
    super(
      `Session capacity exhausted: capacity=${capacity}, retiredSlots=${retiredSlots}`,
    );
    this.name = "SessionCapacityExhaustedError";
  }
}

function assertIntegerInRange(name: string, value: number, min: number, max: number): void {
  if (!Number.isSafeInteger(value) || value < min || value > max) {
    throw new RangeError(`${name} must be a safe integer in [${min}, ${max}], got ${value}`);
  }
}

export class SessionManager {
  readonly gatewayId = 0;
  readonly masterGeneration: number;
  readonly capacity: number;

  readonly #slots = new Map<number, MutableSessionSlot>();
  readonly #freeSlotIndexes: number[] = [];
  #nextSlotIndex = 0;
  #activeCount = 0;
  #retiredSlotCount = 0;

  constructor(options: SessionManagerOptions) {
    assertIntegerInRange(
      "masterGeneration",
      options.masterGeneration,
      0,
      SESSION_ID_LAYOUT.maxMasterGeneration,
    );
    const capacity = options.maxConnections ?? MAX_SESSION_SLOTS;
    assertIntegerInRange("maxConnections", capacity, 1, MAX_SESSION_SLOTS);

    this.masterGeneration = options.masterGeneration;
    this.capacity = capacity;
  }

  get activeCount(): number {
    return this.#activeCount;
  }

  get allocatedSlotCount(): number {
    return this.#slots.size;
  }

  get freeSlotCount(): number {
    return this.#freeSlotIndexes.length;
  }

  get retiredSlotCount(): number {
    return this.#retiredSlotCount;
  }

  get availableCount(): number {
    return this.capacity - this.#activeCount - this.#retiredSlotCount;
  }

  acquire(): SessionId {
    const reusableSlotIndex = this.#freeSlotIndexes.pop();
    let slot: MutableSessionSlot;

    if (reusableSlotIndex === undefined) {
      if (this.#nextSlotIndex >= this.capacity) {
        throw new SessionCapacityExhaustedError(this.capacity, this.#retiredSlotCount);
      }

      slot = {
        slotIndex: this.#nextSlotIndex,
        generation: 1,
        sessionId: null,
        retired: false,
      };
      this.#nextSlotIndex += 1;
      this.#slots.set(slot.slotIndex, slot);
    } else {
      const reusableSlot = this.#slots.get(reusableSlotIndex);
      if (
        reusableSlot === undefined ||
        reusableSlot.retired ||
        reusableSlot.sessionId !== null ||
        reusableSlot.generation >= SESSION_ID_LAYOUT.maxSessionGeneration
      ) {
        throw new Error(`Session slot ${reusableSlotIndex} violates reuse invariants`);
      }
      reusableSlot.generation += 1;
      slot = reusableSlot;
    }

    const sessionId = encodeSessionId({
      gatewayId: this.gatewayId,
      masterGeneration: this.masterGeneration,
      slotIndex: slot.slotIndex,
      sessionGeneration: slot.generation,
    });
    slot.sessionId = sessionId;
    this.#activeCount += 1;
    return sessionId;
  }

  release(sessionId: SessionId): boolean {
    if (!isSessionId(sessionId)) {
      return false;
    }

    const parts = decodeSessionId(sessionId);
    if (
      parts.gatewayId !== this.gatewayId ||
      parts.masterGeneration !== this.masterGeneration ||
      parts.slotIndex >= this.capacity
    ) {
      return false;
    }

    const slot = this.#slots.get(parts.slotIndex);
    if (slot === undefined || slot.sessionId !== sessionId || slot.retired) {
      return false;
    }

    slot.sessionId = null;
    this.#activeCount -= 1;
    if (slot.generation === SESSION_ID_LAYOUT.maxSessionGeneration) {
      slot.retired = true;
      this.#retiredSlotCount += 1;
    } else {
      this.#freeSlotIndexes.push(slot.slotIndex);
    }
    return true;
  }

  isCurrent(sessionId: SessionId): boolean {
    if (!isSessionId(sessionId)) {
      return false;
    }
    const parts = decodeSessionId(sessionId);
    if (
      parts.gatewayId !== this.gatewayId ||
      parts.masterGeneration !== this.masterGeneration
    ) {
      return false;
    }
    return this.#slots.get(parts.slotIndex)?.sessionId === sessionId;
  }
}
