import { AsyncLocalStorage } from "node:async_hooks";

import { loadRuntimeSettings } from "../config/runtime-settings.ts";
import { WorkerDispatcher } from "../dispatch/worker-dispatcher.ts";
import { MasterNetworkCommandReceiver } from "../dispatch/master-network-command-receiver.ts";
import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import { NetworkServer } from "../network/network-server.ts";
import { rustTcpDataPlaneEnabled } from "../network/rust-data-plane-path.ts";
import type { ProcessBus } from "../process/process-bus.ts";
import type { WorkerGeneration, WorkerId } from "../protocol/worker-id.ts";
import {
  ProcessSupervisor,
  type ProcessSupervisorOperationReceipt,
  type ProcessSupervisorStopHooks,
  type ProcessSupervisorWorkerLifecycleCoordinator,
} from "../process/process-supervisor.ts";
import {
  assertMasterTransition,
  MASTER_STATE,
  type MasterState,
} from "./states.ts";
import {
  RuntimeAbortError,
  RuntimeContext,
  type RuntimeContextOptions,
} from "../runtime/runtime-context.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import { createProcessPid } from "../protocol/worker-id.ts";
import {
  NativeSharedRuntimeStateProvider,
  SHARED_RUNTIME_STAT_METRIC,
  type MasterSharedRuntimeState,
  type SharedRuntimeStatMetric,
  type SharedRuntimeStateProvider,
} from "../shared-state/shared-runtime-state.ts";

export type MasterRuntimeInitializer = (
  context: RuntimeContext,
) => void | Promise<void>;

export type MasterRuntimeLifecycleHook = (
  context: RuntimeContext,
) => void | Promise<void>;

export interface MasterRuntimeLifecycleHooks {
  readonly onManagerStart?: MasterRuntimeLifecycleHook;
  readonly onStart?: MasterRuntimeLifecycleHook;
  readonly onManagerStop?: MasterRuntimeLifecycleHook;
  readonly onShutdown?: MasterRuntimeLifecycleHook;
}

export interface MasterProcessSupervisor extends RuntimeResource {
  spawnAll(): Promise<void>;
  waitUntilReady(): Promise<void>;
  readonly bus?: ProcessBus;
  stop?(reason?: unknown, hooks?: ProcessSupervisorStopHooks): Promise<void>;
  requestReload?(
    onlyTaskWorkers?: boolean,
    reason?: unknown,
  ): Readonly<ProcessSupervisorOperationReceipt>;
  setWorkerLifecycleCoordinator?(
    coordinator: ProcessSupervisorWorkerLifecycleCoordinator,
  ): void;
  getWorkerGeneration?(workerId: WorkerId): WorkerGeneration | null;
}

export type MasterProcessSupervisorFactory = (
  context: RuntimeContext,
  sharedState: MasterSharedRuntimeState,
) => MasterProcessSupervisor;

export interface MasterNetworkServer extends RuntimeResource {
  listen(): Promise<void>;
  stopAccepting?(reason?: unknown): Promise<void>;
  closeConnections?(reason?: unknown): Promise<void>;
}

export type MasterNetworkServerFactory = (
  context: RuntimeContext,
  processSupervisor: MasterProcessSupervisor,
  sharedState: MasterSharedRuntimeState,
) => MasterNetworkServer;

export interface MasterRuntimeOptions extends RuntimeContextOptions {
  readonly initialize?: MasterRuntimeInitializer;
  readonly hooks?: Readonly<MasterRuntimeLifecycleHooks>;
  readonly processSupervisorFactory?: MasterProcessSupervisorFactory;
  readonly networkServerFactory?: MasterNetworkServerFactory;
  readonly sharedStateProvider?: SharedRuntimeStateProvider;
  readonly runtimeKey?: string;
  readonly sharedStateLedgerDirectory?: string;
}

interface InitializerInvocation {
  active: boolean;
  readonly token: object;
  readonly stoppingHook: boolean;
}

const activeInitializer = new AsyncLocalStorage<InitializerInvocation>();

interface Deferred {
  readonly promise: Promise<void>;
  readonly resolve: () => void;
  readonly reject: (error: unknown) => void;
}

function createDeferred(): Deferred {
  let resolve!: () => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<void>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function readString(read: () => unknown, fallback: string): string {
  try {
    return String(read());
  } catch {
    return fallback;
  }
}

function describeError(error: unknown): Readonly<Record<string, string>> {
  let errorValue: Error | null = null;
  try {
    if (error instanceof Error) {
      errorValue = error;
    }
  } catch {
    // Some proxy values can throw while their prototype chain is inspected.
  }

  if (errorValue !== null) {
    return {
      errorName: readString(() => errorValue.name, "Error"),
      errorMessage: readString(
        () => errorValue.message,
        "<unreadable error message>",
      ),
    };
  }
  return {
    errorName: "UnknownError",
    errorMessage: readString(() => error, "<unprintable thrown value>"),
  };
}

function createDefaultProcessSupervisor(
  context: RuntimeContext,
  sharedState: MasterSharedRuntimeState,
): MasterProcessSupervisor {
  const rustDataPlane = rustTcpDataPlaneEnabled(context.settings.protocol);
  return new ProcessSupervisor({
    context,
    compactIpcEnvelopes: true,
    sharedRuntime: sharedState.descriptor,
    sharedWorkers: sharedState,
    ...(rustDataPlane
      ? { childEnvironment: { ALLOY_CORE_RUST_DATA_PLANE: "1" } }
      : {}),
  });
}

export class DefaultMasterNetworkServer implements MasterNetworkServer {
  readonly network: NetworkServer;
  readonly commands: MasterNetworkCommandReceiver;
  readonly #bus: ProcessBus;
  #closePromise: Promise<void> | undefined;

  constructor(
    network: NetworkServer,
    commands: MasterNetworkCommandReceiver,
    bus: ProcessBus,
  ) {
    this.network = network;
    this.commands = commands;
    this.#bus = bus;
  }

  listen(): Promise<void> {
    return this.network.listen();
  }

  stopAccepting(reason?: unknown): Promise<void> {
    return this.network.stopAccepting(reason);
  }

  closeConnections(reason?: unknown): Promise<void> {
    return this.network.closeConnections(reason);
  }

  close(reason?: unknown): Promise<void> {
    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }
    this.#closePromise = (async () => {
      const failures: unknown[] = [];
      try {
        await this.network.close(reason);
      } catch (error) {
        failures.push(error);
      }
      try {
        await this.#bus.drain();
      } catch (error) {
        failures.push(error);
      }
      // The receiver remains attached until the subsequent Supervisor/Bus close.
      // Worker shutdown drains can still deliver commands after this local drain.
      if (failures.length === 1) {
        throw failures[0];
      }
      if (failures.length > 1) {
        throw new AggregateError(
          failures,
          "Default network server and ProcessBus drain cleanup failed",
        );
      }
    })();
    return this.#closePromise;
  }
}

export function createDefaultNetworkServer(
  context: RuntimeContext,
  processSupervisor: MasterProcessSupervisor,
  sharedState?: MasterSharedRuntimeState,
): DefaultMasterNetworkServer {
  const bus = processSupervisor.bus;
  if (bus === undefined) {
    throw new TypeError(
      "The default NetworkServer requires a MasterProcessSupervisor with a ProcessBus",
    );
  }
  const inputMaxBytes = context.settings.buffer_input_size;
  const recoveryTimeoutMs = context.settings.backpressure_timeout_ms;
  const recordSharedStat = (metricId: SharedRuntimeStatMetric): void => {
    if (sharedState === undefined) {
      return;
    }
    try {
      sharedState.addStat(metricId);
    } catch (error) {
      context.metrics.recordError();
      context.log("error", "runtime.shared.stat_publish_failed", {
        metricId,
        error: error instanceof Error ? error.message : String(error),
      });
      context.requestStop(error);
    }
  };
  const dispatcherMetrics = {
    recordNetworkInputPause(): void {
      context.metrics.recordNetworkInputPause();
      recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_INPUT_PAUSE);
    },
    recordNetworkInputResume(): void {
      context.metrics.recordNetworkInputResume();
      recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_INPUT_RESUME);
    },
    recordNetworkInputTimeout(): void {
      context.metrics.recordNetworkInputTimeout();
      recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_INPUT_TIMEOUT);
    },
  };
  let lifecycle: ProcessSupervisorWorkerLifecycleCoordinator | undefined;
  const externalMessageDelivery = rustTcpDataPlaneEnabled(
    context.settings.protocol,
  );
  let network!: NetworkServer;
  network = new NetworkServer({
    context,
    rustDataPlane: externalMessageDelivery,
    ...(sharedState === undefined ? {} : { sharedConnections: sharedState }),
    eventSinkFactory: (connections) => {
      const dispatcher = new WorkerDispatcher({
        bus,
        connections,
        workerNum: context.settings.worker_num,
        externalMessageDelivery,
        ...(externalMessageDelivery
          ? {
            externalControlDelivery: async (options) => {
              if (
                options.targetWorkerId == null ||
                options.sessionId == null ||
                options.sequence == null ||
                (options.messageType !== "NET_CONNECT" &&
                  options.messageType !== "NET_CLOSE" &&
                  options.messageType !== "NET_BUFFER_STATE")
              ) {
                throw new TypeError("Native control delivery requires a Worker Session event");
              }
              const generation = processSupervisor.getWorkerGeneration?.(
                options.targetWorkerId,
              ) ?? null;
              if (generation === null) {
                throw new Error(
                  `Worker ${options.targetWorkerId} has no active generation`,
                );
              }
              await network.deliverDataPlaneControl(
                options.messageType === "NET_CONNECT"
                  ? "connect"
                  : options.messageType === "NET_CLOSE"
                    ? "close"
                    : "buffer",
                options.sessionId,
                options.targetWorkerId,
                generation,
                options.sequence,
                options.payload,
              );
            },
          }
          : {}),
        resolveWorkerGeneration: (workerId) =>
          processSupervisor.getWorkerGeneration?.(workerId) ?? null,
        ...(externalMessageDelivery
          ? {
            synchronizeSession: (sessionId) => {
              network.synchronizeDataPlaneSession(sessionId);
            },
            waitForSessionPaused: (sessionId) =>
              network.waitForDataPlaneSessionPaused(
                sessionId,
                Math.min(recoveryTimeoutMs ?? 5_000, 1_000),
              ),
            onSessionReady: (sessionId, workerId, workerGeneration) => {
              network.routeSessionToWorker(
                sessionId,
                workerId,
                workerGeneration,
              );
            },
          }
          : {}),
        timers: context.timers,
        metrics: dispatcherMetrics,
        ...(recoveryTimeoutMs === undefined ? {} : { recoveryTimeoutMs }),
        ...(inputMaxBytes === undefined
          ? {}
          : {
            sessionMaxBytes: inputMaxBytes,
            sessionHighBytes: Math.max(1, Math.floor(inputMaxBytes * 0.75)),
            sessionLowBytes: Math.floor(inputMaxBytes * 0.5),
          }),
      });
      lifecycle = dispatcher;
      return dispatcher;
    },
  });
  if (lifecycle === undefined) {
    throw new Error("The default NetworkServer did not create its WorkerDispatcher");
  }
  processSupervisor.setWorkerLifecycleCoordinator?.(lifecycle);
  const commands = new MasterNetworkCommandReceiver({
    context,
    bus,
    writer: network,
  });
  return new DefaultMasterNetworkServer(network, commands, bus);
}

export class MasterRuntime implements RuntimeResource {
  readonly context: RuntimeContext;
  readonly sharedState: MasterSharedRuntimeState;
  readonly stopped: Promise<void>;

  readonly #initialize: MasterRuntimeInitializer;
  readonly #hooks: Readonly<MasterRuntimeLifecycleHooks>;
  readonly #processSupervisorFactory: MasterProcessSupervisorFactory;
  readonly #networkServerFactory: MasterNetworkServerFactory;
  readonly #initializerToken = {};
  readonly #stoppedDeferred = createDeferred();
  readonly #initializerCloseJoin = createDeferred();
  readonly #contextCloseStarted = createDeferred();
  #state: MasterState = MASTER_STATE.CREATED;
  #startPromise: Promise<RuntimeContext> | null = null;
  #initializationDone: Promise<void> | null = null;
  #stopPromise: Promise<void> | null = null;
  #abortListenerAttached = false;
  #managerStarted = false;
  #managerStopped = false;
  #listenerStarted = false;
  #signalListenersAttached = false;
  #processSupervisor: MasterProcessSupervisor | null = null;
  #networkServer: MasterNetworkServer | null = null;

  readonly #onAbort = (): void => {
    const stopPromise = this.stop(this.context.signal.reason);
    void stopPromise.catch((error: unknown) => {
      this.context.log("error", "runtime.master.abort_stop_failed", describeError(error));
    });
  };

  readonly #onSigterm = (): void => {
    void this.stop(new Error("Master Runtime received SIGTERM")).catch(
      (error: unknown) => {
        this.context.log("error", "runtime.master.signal_stop_failed", describeError(error));
      },
    );
  };

  readonly #onSigusr1 = (): void => {
    this.#requestSignalReload(false, "SIGUSR1");
  };

  readonly #onSigusr2 = (): void => {
    this.#requestSignalReload(true, "SIGUSR2");
  };

  constructor(options: MasterRuntimeOptions) {
    const {
      initialize,
      hooks,
      processSupervisorFactory = createDefaultProcessSupervisor,
      networkServerFactory = createDefaultNetworkServer,
      sharedStateProvider = new NativeSharedRuntimeStateProvider(),
      runtimeKey,
      sharedStateLedgerDirectory,
      ...contextOptions
    } = options;
    const settings = loadRuntimeSettings(contextOptions.settings);
    const masterPid = contextOptions.masterPid ?? createProcessPid(process.pid);
    const sharedState = sharedStateProvider.claimMaster({
      settings,
      masterPid,
      ...(runtimeKey === undefined ? {} : { runtimeKey }),
      ...(sharedStateLedgerDirectory === undefined
        ? {}
        : { ledgerDirectory: sharedStateLedgerDirectory }),
    });
    try {
      if (
        contextOptions.masterGeneration !== undefined &&
        contextOptions.masterGeneration !== sharedState.masterGeneration
      ) {
        throw new RangeError(
          `explicit masterGeneration ${contextOptions.masterGeneration} does not match allocated shared generation ${sharedState.masterGeneration}`,
        );
      }
      this.context = new RuntimeContext({
        ...contextOptions,
        settings,
        masterPid,
        masterGeneration: sharedState.masterGeneration,
      });
    } catch (error) {
      try {
        sharedState.release(false);
      } catch (cleanupError) {
        throw new AggregateError(
          [error, cleanupError],
          "Master Runtime context creation and shared-state cleanup both failed",
        );
      }
      throw error;
    }
    this.sharedState = sharedState;
    this.#initialize = initialize ?? (() => {});
    this.#hooks = Object.freeze({ ...hooks });
    this.#processSupervisorFactory = processSupervisorFactory;
    this.#networkServerFactory = networkServerFactory;
    this.stopped = this.#stoppedDeferred.promise;
    void this.stopped.catch(() => {});
    void this.#initializerCloseJoin.promise.catch(() => {});
    void this.#contextCloseStarted.promise.catch(() => {});
  }

  get state(): MasterState {
    return this.#state;
  }

  start(): Promise<RuntimeContext> {
    if (this.#stopPromise !== null) {
      return Promise.reject(
        new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          `Master Runtime cannot start while stopping from ${this.#state}`,
          { state: this.#state },
        ),
      );
    }
    if (
      this.#startPromise !== null &&
      (
        this.#state === MASTER_STATE.INITIALIZING ||
        this.#state === MASTER_STATE.SPAWNING_CHILDREN ||
        this.#state === MASTER_STATE.WAITING_READY ||
        this.#state === MASTER_STATE.LISTENING ||
        this.#state === MASTER_STATE.RUNNING
      )
    ) {
      return this.#startPromise;
    }
    if (this.#state !== MASTER_STATE.CREATED) {
      return Promise.reject(
        new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          `Master Runtime cannot start from ${this.#state}`,
          { state: this.#state },
        ),
      );
    }

    if (this.context.signal.aborted) {
      const error = this.#abortError("Master Runtime was aborted before initialization");
      this.#startPromise = this.#rejectStartAndStop(error);
      return this.#startPromise;
    }

    const startedAt = this.context.clock.monotonicTimeMs();
    this.#transition(MASTER_STATE.INITIALIZING);
    this.#attachAbortListener();
    if (this.context.signal.aborted) {
      const error = this.#abortError("Master Runtime was aborted during initialization");
      this.#startPromise = this.#rejectStartAndStop(error);
      return this.#startPromise;
    }

    const initialization = Promise.resolve().then(async () => {
      if (this.#stopPromise !== null || this.context.signal.aborted) {
        return;
      }

      const invocation: InitializerInvocation = {
        active: true,
        token: this.#initializerToken,
        stoppingHook: false,
      };
      try {
        await activeInitializer.run(invocation, () => this.#initialize(this.context));
      } finally {
        invocation.active = false;
      }

      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted during initialization");
      }

      const processSupervisor = this.#processSupervisorFactory(
        this.context,
        this.sharedState,
      );
      this.#processSupervisor = processSupervisor;
      if (this.context.signal.aborted) {
        const abortError = this.#abortError(
          "Master Runtime was aborted before spawning children",
        );
        try {
          await processSupervisor.close(this.context.signal.reason);
        } catch (cleanupError) {
          throw new AggregateError(
            [abortError, cleanupError],
            "Master Runtime abort and ProcessSupervisor cleanup both failed",
          );
        }
        throw abortError;
      }

      try {
        this.context.registerResource(
          "runtime.process-supervisor",
          processSupervisor,
        );
      } catch (error) {
        try {
          await processSupervisor.close(error);
        } catch (cleanupError) {
          throw new AggregateError(
            [error, cleanupError],
            "Master ProcessSupervisor registration and cleanup both failed",
          );
        }
        throw error;
      }

      this.#transition(MASTER_STATE.SPAWNING_CHILDREN);
      try {
        await processSupervisor.spawnAll();
      } catch (error) {
        if (this.context.signal.aborted) {
          throw this.#abortError("Master Runtime was aborted while spawning children");
        }
        throw error;
      }
      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted while spawning children");
      }

      this.#transition(MASTER_STATE.WAITING_READY);
      try {
        await processSupervisor.waitUntilReady();
      } catch (error) {
        if (this.context.signal.aborted) {
          throw this.#abortError("Master Runtime was aborted while waiting for children");
        }
        throw error;
      }
      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted while waiting for children");
      }
      this.#managerStarted = true;
      await this.#invokeLifecycleHook(this.#hooks.onManagerStart);
      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted during onManagerStart");
      }

      const networkServer = this.#networkServerFactory(
        this.context,
        processSupervisor,
        this.sharedState,
      );
      this.#networkServer = networkServer;
      if (this.context.signal.aborted) {
        const abortError = this.#abortError(
          "Master Runtime was aborted before starting the network listener",
        );
        try {
          await networkServer.close(this.context.signal.reason);
        } catch (cleanupError) {
          throw new AggregateError(
            [abortError, cleanupError],
            "Master Runtime abort and NetworkServer cleanup both failed",
          );
        }
        throw abortError;
      }

      try {
        this.context.registerResource("runtime.network-server", networkServer);
      } catch (error) {
        try {
          await networkServer.close(error);
        } catch (cleanupError) {
          throw new AggregateError(
            [error, cleanupError],
            "Master NetworkServer registration and cleanup both failed",
          );
        }
        throw error;
      }
      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted before listening");
      }

      this.#transition(MASTER_STATE.LISTENING);
      try {
        await networkServer.listen();
      } catch (error) {
        if (this.context.signal.aborted) {
          throw this.#abortError("Master Runtime was aborted while listening");
        }
        throw error;
      }
      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted while listening");
      }
      this.#listenerStarted = true;
      await this.#invokeLifecycleHook(this.#hooks.onStart);
      if (this.context.signal.aborted) {
        throw this.#abortError("Master Runtime was aborted during onStart");
      }
      this.#transition(MASTER_STATE.RUNNING);
      this.#attachSignalListeners();
    });
    this.#initializationDone = initialization.then(
      () => {},
      () => {},
    );

    this.#startPromise = (async () => {
      try {
        await initialization;
        if (this.context.signal.aborted) {
          throw this.#abortError("Master Runtime was aborted during initialization");
        }

        const duration = this.#elapsedSince(startedAt);
        this.context.metrics.recordStart(duration);
        this.context.log("info", "runtime.master.initialized", {
          state: this.#state,
          durationMs: duration,
        });
        return this.context;
      } catch (error) {
        this.context.metrics.recordError();
        this.context.log("error", "runtime.master.initialization_failed", describeError(error));
        try {
          await this.stop(error);
        } catch (cleanupError) {
          throw new AggregateError(
            [error, cleanupError],
            "Master Runtime initialization and cleanup both failed",
          );
        }
        throw error;
      }
    })();

    return this.#startPromise;
  }

  stop(reason?: unknown): Promise<void> {
    const resourceJoin = this.context.closeFromResourceDisposer(reason);
    const callbackJoin = resourceJoin === undefined
      ? this.context.joinCloseFromCallback()
      : undefined;
    const invocation = activeInitializer.getStore();
    const calledFromInitializer =
      invocation?.active === true &&
      invocation.token === this.#initializerToken &&
      !invocation.stoppingHook;
    const calledFromStoppingHook =
      invocation?.active === true &&
      invocation.token === this.#initializerToken &&
      invocation.stoppingHook;

    if (this.#stopPromise !== null) {
      if (calledFromStoppingHook) {
        return Promise.resolve();
      }
      if (callbackJoin !== undefined) {
        return Promise.all([
          callbackJoin,
          this.#contextCloseStarted.promise,
        ]).then(() => undefined);
      }
      if (resourceJoin !== undefined) {
        return resourceJoin;
      }
      if (calledFromInitializer && this.#state === MASTER_STATE.STOPPING) {
        return Promise.resolve();
      }
      return calledFromInitializer
        ? this.#initializerCloseJoin.promise
        : this.#stopPromise;
    }

    const stopReason = reason ?? new RuntimeAbortError("Master Runtime is stopping");
    this.#stopPromise = activeInitializer.exit(() =>
      Promise.resolve().then(() => this.#performStop(stopReason)),
    );
    const stopPromise = this.#stopPromise;
    void stopPromise.then(
      () => this.#stoppedDeferred.resolve(),
      (error: unknown) => this.#stoppedDeferred.reject(error),
    );
    this.context.requestStop(stopReason);
    if (callbackJoin !== undefined) {
      return Promise.all([
        callbackJoin,
        this.#contextCloseStarted.promise,
      ]).then(() => undefined);
    }
    if (resourceJoin !== undefined) {
      return resourceJoin;
    }
    return calledFromInitializer ? this.#initializerCloseJoin.promise : stopPromise;
  }

  close(reason?: unknown): Promise<void> {
    return this.stop(reason);
  }

  async #performStop(stopReason: unknown): Promise<void> {
    const stoppedAt = this.context.clock.monotonicTimeMs();
    const gracefulRuntimeStop = this.#state === MASTER_STATE.RUNNING;
    if (this.#state !== MASTER_STATE.STOPPING) {
      this.#transition(MASTER_STATE.STOPPING);
    }
    this.#detachAbortListener();
    this.#detachSignalListeners();

    const failures: unknown[] = [];
    let contextClose: Promise<void> | null = null;
    const beginContextClose = (): Promise<void> => {
      if (contextClose !== null) {
        return contextClose;
      }
      contextClose = this.context.closeGlobally(stopReason);
      this.#contextCloseStarted.resolve();
      void contextClose.catch(() => {});
      void contextClose.then(
        () => this.#initializerCloseJoin.resolve(),
        (error: unknown) => this.#initializerCloseJoin.reject(error),
      );
      return contextClose;
    };

    // During startup, resource cleanup is what releases pending spawn/READY/listen
    // operations. A fully running Runtime instead uses the staged shutdown below.
    if (!gracefulRuntimeStop) {
      beginContextClose();
    }

    if (this.#initializationDone !== null) {
      await this.#initializationDone;
    }

    let beforeEventWorkerShutdownInvoked = false;
    const beforeEventWorkerShutdown = async (): Promise<void> => {
      if (beforeEventWorkerShutdownInvoked) {
        return;
      }
      beforeEventWorkerShutdownInvoked = true;
      if (this.#managerStarted && !this.#managerStopped) {
        this.#managerStopped = true;
        await this.#collectLifecycleHookFailure(
          failures,
          "onManagerStop",
          this.#hooks.onManagerStop,
        );
      }
      const closeConnections = this.#networkServer?.closeConnections;
      if (closeConnections !== undefined) {
        try {
          await closeConnections.call(this.#networkServer, stopReason);
        } catch (error) {
          failures.push(error);
        }
      }
    };

    if (gracefulRuntimeStop) {
      const stopAccepting = this.#networkServer?.stopAccepting;
      if (stopAccepting !== undefined) {
        try {
          await stopAccepting.call(this.#networkServer, stopReason);
        } catch (error) {
          failures.push(error);
        }
      }

      const processSupervisor = this.#processSupervisor;
      if (processSupervisor?.stop !== undefined) {
        try {
          await processSupervisor.stop(stopReason, { beforeEventWorkerShutdown });
        } catch (error) {
          failures.push(error);
        }
      }
      await beforeEventWorkerShutdown();
      beginContextClose();
    }

    try {
      await beginContextClose();
    } catch (error) {
      failures.push(error);
      try {
        this.context.metrics.recordError();
      } catch {
        // Lifecycle hooks still run after a failed resource cleanup observation.
      }
    }
    if (!gracefulRuntimeStop) {
      await beforeEventWorkerShutdown();
    }
    if (this.#listenerStarted) {
      await this.#collectLifecycleHookFailure(
        failures,
        "onShutdown",
        this.#hooks.onShutdown,
      );
    }
    try {
      this.sharedState.release(gracefulRuntimeStop && failures.length === 0);
    } catch (error) {
      failures.push(error);
    }
    this.#transition(MASTER_STATE.STOPPED);
    this.context.metrics.recordStop(this.#elapsedSince(stoppedAt));

    if (failures.length === 1) {
      this.context.log("error", "runtime.master.cleanup_failed", describeError(failures[0]));
      throw failures[0];
    }
    if (failures.length > 1) {
      const error = new AggregateError(
        failures,
        "Master Runtime cleanup and lifecycle hooks failed",
      );
      this.context.log("error", "runtime.master.cleanup_failed", describeError(error));
      throw error;
    }
  }

  async #invokeLifecycleHook(
    hook: MasterRuntimeLifecycleHook | undefined,
    stoppingHook = false,
  ): Promise<void> {
    if (hook === undefined) {
      return;
    }
    const invocation: InitializerInvocation = {
      active: true,
      token: this.#initializerToken,
      stoppingHook,
    };
    try {
      await activeInitializer.run(invocation, () => hook(this.context));
    } finally {
      invocation.active = false;
    }
  }

  async #collectLifecycleHookFailure(
    failures: unknown[],
    hookName: "onManagerStop" | "onShutdown",
    hook: MasterRuntimeLifecycleHook | undefined,
  ): Promise<void> {
    try {
      await this.#invokeLifecycleHook(hook, true);
    } catch (error) {
      failures.push(error);
      try {
        this.context.metrics.recordError();
      } catch {
        // Hook cleanup must continue even if an injected metrics sink fails.
      }
      this.context.log("error", "runtime.master.lifecycle_hook_failed", {
        hook: hookName,
        ...describeError(error),
      });
    }
  }

  async #rejectStartAndStop(error: RuntimeAbortError): Promise<RuntimeContext> {
    this.context.metrics.recordError();
    this.context.log("warn", "runtime.master.initialization_aborted", describeError(error));
    try {
      await this.stop(error.reason);
    } catch (cleanupError) {
      throw new AggregateError(
        [error, cleanupError],
        "Master Runtime abort and cleanup both failed",
      );
    }
    throw error;
  }

  #transition(next: MasterState): void {
    const previous = this.#state;
    assertMasterTransition(previous, next);
    this.#state = next;
    this.context.metrics.setState(next);
    this.context.log("debug", "runtime.master.state_changed", {
      from: previous,
      to: next,
    });
  }

  #attachAbortListener(): void {
    if (this.#abortListenerAttached) {
      return;
    }
    this.context.signal.addEventListener("abort", this.#onAbort, { once: true });
    this.#abortListenerAttached = true;
  }

  #detachAbortListener(): void {
    if (!this.#abortListenerAttached) {
      return;
    }
    this.context.signal.removeEventListener("abort", this.#onAbort);
    this.#abortListenerAttached = false;
  }

  #attachSignalListeners(): void {
    if (this.#signalListenersAttached) {
      return;
    }
    process.on("SIGTERM", this.#onSigterm);
    process.on("SIGUSR1", this.#onSigusr1);
    process.on("SIGUSR2", this.#onSigusr2);
    this.#signalListenersAttached = true;
  }

  #detachSignalListeners(): void {
    if (!this.#signalListenersAttached) {
      return;
    }
    process.off("SIGTERM", this.#onSigterm);
    process.off("SIGUSR1", this.#onSigusr1);
    process.off("SIGUSR2", this.#onSigusr2);
    this.#signalListenersAttached = false;
  }

  #requestSignalReload(onlyTaskWorkers: boolean, signal: string): void {
    try {
      const receipt = this.#processSupervisor?.requestReload?.(
        onlyTaskWorkers,
        `Master Runtime received ${signal}`,
      );
      if (receipt === undefined) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          `Master Runtime cannot handle ${signal} before the process pool is ready`,
        );
      }
      void receipt.completion.catch((error: unknown) => {
        this.context.log("error", "runtime.master.signal_reload_failed", {
          signal,
          ...describeError(error),
        });
      });
    } catch (error) {
      this.context.metrics.recordError();
      this.context.log("error", "runtime.master.signal_reload_rejected", {
        signal,
        ...describeError(error),
      });
    }
  }

  #abortError(message: string): RuntimeAbortError {
    return new RuntimeAbortError(message, this.context.signal.reason);
  }

  #elapsedSince(startedAt: number): number {
    return Math.max(0, this.context.clock.monotonicTimeMs() - startedAt);
  }
}
