import { createHash, randomUUID } from "node:crypto";
import { mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  CONNECTION_STATES,
  WORKER_STATES,
  type ConnectionState,
  type WorkerState,
} from "../lifecycle/states.ts";
import { PROCESS_ROLE, type ProcessRole } from "../protocol/process-role.ts";
import {
  decodeSessionId,
  SESSION_ID_LAYOUT,
  type SessionId,
} from "../protocol/session-id.ts";
import type {
  ProcessPid,
  TaskWorkerId,
  WorkerGeneration,
  WorkerId,
} from "../protocol/worker-id.ts";
import type { RuntimeSettings } from "../runtime/runtime-server.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import {
  loadNativeRuntimeStateBinding,
  type NativeConnectionRecord,
  type NativeRuntimeStateBinding,
  type NativeRuntimeStateHandle,
  type NativeWorkerRecord,
} from "./native-binding.ts";
import {
  validateSharedRuntimeDescriptor,
  type SharedRuntimeDescriptor,
} from "./types.ts";

const SHARED_CONNECTION_STATE_CODES = new Map<ConnectionState, number>(
  CONNECTION_STATES.map((state, index) => [state, index + 1]),
);
const SHARED_WORKER_STATE_CODES = new Map<WorkerState, number>(
  WORKER_STATES.map((state, index) => [state, index + 1]),
);
const SHARED_PROCESS_ROLE_CODES = Object.freeze({
  [PROCESS_ROLE.WORKER]: 1,
  [PROCESS_ROLE.TASK_WORKER]: 2,
  [PROCESS_ROLE.USER_TASK_WORKER]: 3,
} as const satisfies Readonly<
  Record<Exclude<ProcessRole, typeof PROCESS_ROLE.MASTER>, number>
>);
const SHARED_PROTOCOL_CODES = Object.freeze({ tcp: 1, websocket: 2 } as const);
const SHARED_PROTOCOL_STATES = Object.freeze({
  TCP: 1,
  WEBSOCKET_HANDSHAKING: 2,
  WEBSOCKET_OPEN: 3,
} as const);

export const SHARED_STAT_METRIC_COUNT = 96;
export const SHARED_ATOMIC_CAPACITY = 16;
export const SHARED_LOCK_CAPACITY = 16;
const SHARED_ATOMIC_STAT_BASE = 64;

export const SHARED_RUNTIME_STAT_METRIC = Object.freeze({
  NETWORK_INPUT_PAUSE: 0,
  NETWORK_INPUT_RESUME: 1,
  NETWORK_INPUT_TIMEOUT: 2,
  NETWORK_OUTPUT_FULL: 3,
  NETWORK_OUTPUT_EMPTY: 4,
  NETWORK_OUTPUT_OVERFLOW: 5,
  NETWORK_OUTPUT_TIMEOUT: 6,
  NETWORK_OUTPUT_REJECTION: 7,
} as const satisfies Readonly<Record<string, number>>);

export type SharedRuntimeStatMetric =
  (typeof SHARED_RUNTIME_STAT_METRIC)[keyof typeof SHARED_RUNTIME_STAT_METRIC];

export type SharedConnectionProbeStatus =
  | "open"
  | "closed"
  | "stale"
  | "unknown"
  | "busy";

export interface SharedConnectionSnapshot {
  readonly sessionId: SessionId;
  readonly slotIndex: number;
  readonly sessionGeneration: number;
  readonly masterGeneration: number;
  readonly gatewayId: number;
  readonly ownerWorkerId: WorkerId | null;
  readonly state: ConnectionState;
  readonly protocol: "tcp" | "websocket";
  readonly protocolState: number;
  readonly remoteAddress: string;
  readonly remotePort: number;
  readonly serverPort: number;
  readonly connectedAtMs: number;
  readonly lastActiveAtMs: number;
  readonly outputBufferBytes: number;
  readonly outputBufferFull: boolean;
  readonly overflow: boolean;
}

export interface SharedConnectionProbe {
  readonly status: SharedConnectionProbeStatus;
  readonly record?: Readonly<SharedConnectionSnapshot>;
}

export interface SharedConnectionAdmissionProbe {
  readonly status: SharedConnectionProbeStatus;
  readonly overflow: boolean;
}

export interface SharedWorkerSnapshot {
  readonly workerId: WorkerId;
  readonly taskWorkerId: TaskWorkerId | null;
  readonly pid: ProcessPid | null;
  readonly generation: WorkerGeneration;
  readonly role: Exclude<ProcessRole, typeof PROCESS_ROLE.MASTER>;
  readonly state: WorkerState;
  readonly restartCount: number;
  readonly startedAt: number;
  readonly readyAt: number | null;
  readonly lastHeartbeatAt: number | null;
}

export interface SharedRuntimeStateReader extends RuntimeResource {
  readonly descriptor: SharedRuntimeDescriptor;
  readonly masterGeneration: number;
  probeConnection(sessionId: SessionId): Readonly<SharedConnectionProbe>;
  probeConnectionAdmission?(
    sessionId: SessionId,
  ): Readonly<SharedConnectionAdmissionProbe>;
  snapshotOpenSessionIds(): readonly SessionId[];
  connectionCount(): number;
  snapshotWorkers(): readonly Readonly<SharedWorkerSnapshot>[];
  addStat(metricId: number, delta?: number): number;
  snapshotStats(): readonly number[];
  atomicGet?(atomicId: number): number;
  atomicAdd?(atomicId: number, delta: number): number;
  atomicSet?(atomicId: number, value: number): number;
  atomicCompareSet?(atomicId: number, expected: number, value: number): boolean;
  lockTry?(lockId: number, ownerToken: number): boolean;
  lockRelease?(lockId: number, ownerToken: number): boolean;
  clearLocks?(ownerToken: number): number;
}

export interface SharedConnectionTableWriter {
  publishConnection(record: Readonly<SharedConnectionSnapshot>): void;
}

export interface SharedWorkerTableWriter {
  publishWorker(record: Readonly<SharedWorkerSnapshot>): void;
}

export interface SharedRuntimeStatsWriter {
  addStat(metricId: SharedRuntimeStatMetric, delta?: number): number;
}

export interface MasterSharedRuntimeState
  extends SharedRuntimeStateReader,
    SharedConnectionTableWriter,
    SharedWorkerTableWriter
{
  readonly recovered: boolean;
  readonly previousCleanShutdown: boolean;
  release(cleanShutdown: boolean): void;
}

export interface MasterSharedRuntimeClaimOptions {
  readonly settings: Readonly<RuntimeSettings>;
  readonly masterPid: ProcessPid;
  readonly runtimeKey?: string;
  readonly ledgerDirectory?: string;
}

export interface SharedRuntimeStateProvider {
  claimMaster(options: MasterSharedRuntimeClaimOptions): MasterSharedRuntimeState;
  attachReader(descriptor: SharedRuntimeDescriptor): SharedRuntimeStateReader;
}

function codeFor<State extends string>(
  values: ReadonlyMap<State, number>,
  value: State,
  name: string,
): number {
  const code = values.get(value);
  if (code === undefined) {
    throw new TypeError(`${name} is not supported by the shared runtime ABI: ${value}`);
  }
  return code;
}

function stateFromCode<State extends string>(
  values: readonly State[],
  code: number,
  name: string,
): State {
  const value = values[code - 1];
  if (value === undefined) {
    throw new TypeError(`shared ${name} code is invalid: ${code}`);
  }
  return value;
}

function processRoleFromCode(
  code: number,
): Exclude<ProcessRole, typeof PROCESS_ROLE.MASTER> {
  if (code === SHARED_PROCESS_ROLE_CODES.WORKER) {
    return PROCESS_ROLE.WORKER;
  }
  if (code === SHARED_PROCESS_ROLE_CODES.TASK_WORKER) {
    return PROCESS_ROLE.TASK_WORKER;
  }
  if (code === SHARED_PROCESS_ROLE_CODES.USER_TASK_WORKER) {
    return PROCESS_ROLE.USER_TASK_WORKER;
  }
  throw new TypeError(`shared Worker role code is invalid: ${code}`);
}

function toNativeConnection(
  record: Readonly<SharedConnectionSnapshot>,
): NativeConnectionRecord {
  return {
    ...record,
    state: codeFor(SHARED_CONNECTION_STATE_CODES, record.state, "Connection state"),
    protocol: SHARED_PROTOCOL_CODES[record.protocol],
  };
}

function fromNativeConnection(record: NativeConnectionRecord): SharedConnectionSnapshot {
  const state = typeof record.state === "string"
    ? record.state
    : stateFromCode(CONNECTION_STATES, record.state, "Connection state");
  if (!CONNECTION_STATES.includes(state as ConnectionState)) {
    throw new TypeError(`shared Connection state is invalid: ${state}`);
  }
  const protocol = record.protocol === SHARED_PROTOCOL_CODES.tcp || record.protocol === "tcp"
    ? "tcp"
    : record.protocol === SHARED_PROTOCOL_CODES.websocket || record.protocol === "websocket"
    ? "websocket"
    : null;
  if (protocol === null) {
    throw new TypeError(`shared protocol code is invalid: ${record.protocol}`);
  }
  return Object.freeze({
    ...record,
    sessionId: record.sessionId as SessionId,
    ownerWorkerId: record.ownerWorkerId as WorkerId | null,
    state: state as ConnectionState,
    protocol,
  });
}

function toNativeWorker(record: Readonly<SharedWorkerSnapshot>): NativeWorkerRecord {
  return {
    ...record,
    role: SHARED_PROCESS_ROLE_CODES[record.role],
    state: codeFor(SHARED_WORKER_STATE_CODES, record.state, "Worker state"),
  };
}

function fromNativeWorker(record: NativeWorkerRecord): SharedWorkerSnapshot {
  const state = typeof record.state === "string"
    ? record.state
    : stateFromCode(WORKER_STATES, record.state, "Worker state");
  if (!WORKER_STATES.includes(state as WorkerState)) {
    throw new TypeError(`shared Worker state is invalid: ${state}`);
  }
  const role = typeof record.role === "string"
    ? record.role === PROCESS_ROLE.WORKER ||
        record.role === PROCESS_ROLE.TASK_WORKER ||
        record.role === PROCESS_ROLE.USER_TASK_WORKER
      ? record.role
      : (() => {
        throw new TypeError(`shared Worker role is invalid: ${record.role}`);
      })()
    : processRoleFromCode(record.role);
  return Object.freeze({
    ...record,
    workerId: record.workerId as WorkerId,
    taskWorkerId: record.taskWorkerId as TaskWorkerId | null,
    pid: record.pid as ProcessPid | null,
    generation: record.generation as WorkerGeneration,
    role,
    state: state as WorkerState,
  });
}

function assertMetric(metricId: number, delta: number): void {
  if (!Number.isSafeInteger(metricId) || metricId < 0 || metricId >= SHARED_STAT_METRIC_COUNT) {
    throw new RangeError(
      `metricId must be an integer in [0, ${SHARED_STAT_METRIC_COUNT - 1}]`,
    );
  }
  if (!Number.isSafeInteger(delta)) {
    throw new RangeError("shared stat delta must be a safe integer");
  }
}

function assertSharedPrimitiveId(name: string, value: number, capacity: number): void {
  if (!Number.isSafeInteger(value) || value < 0 || value >= capacity) {
    throw new RangeError(`${name} must be an integer in [0, ${capacity - 1}]`);
  }
}

class NativeSharedRuntimeStateReader implements SharedRuntimeStateReader {
  readonly descriptor: SharedRuntimeDescriptor;
  readonly masterGeneration: number;
  protected readonly binding: NativeRuntimeStateBinding;
  protected readonly handle: NativeRuntimeStateHandle;
  #closed = false;

  constructor(
    binding: NativeRuntimeStateBinding,
    handle: NativeRuntimeStateHandle,
    descriptor: SharedRuntimeDescriptor,
  ) {
    this.binding = binding;
    this.handle = handle;
    this.descriptor = descriptor;
    this.masterGeneration = descriptor.masterGeneration;
  }

  probeConnection(sessionId: SessionId): Readonly<SharedConnectionProbe> {
    if (this.#closed) {
      return Object.freeze({ status: "closed" });
    }
    const probe = this.binding.readConnection(this.handle, sessionId);
    return probe.record === undefined
      ? Object.freeze({ status: probe.status })
      : Object.freeze({
        status: probe.status,
        record: fromNativeConnection(probe.record),
      });
  }

  probeConnectionAdmission(
    sessionId: SessionId,
  ): Readonly<SharedConnectionAdmissionProbe> {
    if (this.#closed) {
      return Object.freeze({ status: "closed", overflow: false });
    }
    const value = this.binding.probeConnectionAdmission(this.handle, sessionId);
    const statusCode = value & 0xff;
    const status: SharedConnectionProbeStatus = statusCode === 1
      ? "open"
      : statusCode === 2
      ? "closed"
      : statusCode === 3
      ? "stale"
      : statusCode === 4
      ? "busy"
      : "unknown";
    return Object.freeze({
      status,
      overflow: status === "open" && (value & 0x100) !== 0,
    });
  }

  snapshotOpenSessionIds(): readonly SessionId[] {
    if (this.#closed) {
      return Object.freeze([]);
    }
    return Object.freeze(
      this.binding.snapshotOpenSessionIds(this.handle).map((value) => value as SessionId),
    );
  }

  connectionCount(): number {
    if (this.#closed) {
      return 0;
    }
    return this.binding.connectionCount(this.handle);
  }

  snapshotWorkers(): readonly Readonly<SharedWorkerSnapshot>[] {
    if (this.#closed) {
      return Object.freeze([]);
    }
    return Object.freeze(
      this.binding.snapshotWorkers(this.handle).map(fromNativeWorker),
    );
  }

  addStat(metricId: number, delta = 1): number {
    assertMetric(metricId, delta);
    if (this.#closed) {
      throw new Error("shared runtime state reader is closed");
    }
    return this.binding.addStat(this.handle, metricId, delta);
  }

  snapshotStats(): readonly number[] {
    if (this.#closed) {
      return Object.freeze(Array.from({ length: SHARED_STAT_METRIC_COUNT }, () => 0));
    }
    return Object.freeze([...this.binding.snapshotStats(this.handle)]);
  }

  atomicGet(atomicId: number): number {
    assertSharedPrimitiveId("atomicId", atomicId, SHARED_ATOMIC_CAPACITY);
    if (this.#closed) throw new Error("shared runtime state reader is closed");
    return this.binding.atomicGet(this.handle, atomicId);
  }

  atomicAdd(atomicId: number, delta: number): number {
    assertSharedPrimitiveId("atomicId", atomicId, SHARED_ATOMIC_CAPACITY);
    return this.addStat(SHARED_ATOMIC_STAT_BASE + atomicId, delta);
  }

  atomicSet(atomicId: number, value: number): number {
    assertSharedPrimitiveId("atomicId", atomicId, SHARED_ATOMIC_CAPACITY);
    if (this.#closed) throw new Error("shared runtime state reader is closed");
    return this.binding.atomicSet(this.handle, atomicId, value);
  }

  atomicCompareSet(atomicId: number, expected: number, value: number): boolean {
    assertSharedPrimitiveId("atomicId", atomicId, SHARED_ATOMIC_CAPACITY);
    if (this.#closed) throw new Error("shared runtime state reader is closed");
    return this.binding.atomicCompareSet(this.handle, atomicId, expected, value);
  }

  lockTry(lockId: number, ownerToken: number): boolean {
    assertSharedPrimitiveId("lockId", lockId, SHARED_LOCK_CAPACITY);
    if (this.#closed) throw new Error("shared runtime state reader is closed");
    return this.binding.lockTry(this.handle, lockId, ownerToken);
  }

  lockRelease(lockId: number, ownerToken: number): boolean {
    assertSharedPrimitiveId("lockId", lockId, SHARED_LOCK_CAPACITY);
    if (this.#closed) throw new Error("shared runtime state reader is closed");
    return this.binding.lockRelease(this.handle, lockId, ownerToken);
  }

  clearLocks(ownerToken: number): number {
    if (this.#closed) throw new Error("shared runtime state reader is closed");
    return this.binding.lockClearOwner(this.handle, ownerToken);
  }

  close(_reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#closed = true;
    if (!this.binding.close(this.handle)) {
      throw new Error("shared runtime reader close was rejected");
    }
  }

  protected markClosed(): void {
    this.#closed = true;
  }
}

class NativeMasterSharedRuntimeState
  extends NativeSharedRuntimeStateReader
  implements MasterSharedRuntimeState
{
  readonly recovered: boolean;
  readonly previousCleanShutdown: boolean;
  readonly #key: string;
  readonly #ledgerDirectory: string;
  readonly #purgeLedgerOnRelease: boolean;
  #released = false;

  constructor(
    binding: NativeRuntimeStateBinding,
    handle: NativeRuntimeStateHandle,
    descriptor: SharedRuntimeDescriptor,
    recovered: boolean,
    previousCleanShutdown: boolean,
    key: string,
    ledgerDirectory: string,
    purgeLedgerOnRelease: boolean,
  ) {
    super(binding, handle, descriptor);
    this.recovered = recovered;
    this.previousCleanShutdown = previousCleanShutdown;
    this.#key = key;
    this.#ledgerDirectory = ledgerDirectory;
    this.#purgeLedgerOnRelease = purgeLedgerOnRelease;
  }

  publishConnection(record: Readonly<SharedConnectionSnapshot>): void {
    const parts = decodeSessionId(record.sessionId);
    if (
      parts.slotIndex !== record.slotIndex ||
      parts.sessionGeneration !== record.sessionGeneration ||
      parts.masterGeneration !== record.masterGeneration ||
      parts.gatewayId !== record.gatewayId ||
      record.masterGeneration !== this.masterGeneration
    ) {
      throw new TypeError("shared Connection record does not match its Session ID");
    }
    if (!this.binding.publishConnection(this.handle, toNativeConnection(record))) {
      throw new Error(`shared Connection ${record.sessionId} publication was rejected`);
    }
  }

  publishWorker(record: Readonly<SharedWorkerSnapshot>): void {
    if (!this.binding.publishWorker(this.handle, toNativeWorker(record))) {
      throw new Error(`shared Worker ${record.workerId} publication was rejected`);
    }
  }

  release(cleanShutdown: boolean): void {
    if (this.#released) {
      return;
    }
    try {
      if (!this.binding.destroy(this.handle, cleanShutdown)) {
        throw new Error("shared runtime Master release was rejected");
      }
    } catch (error) {
      this.markClosed();
      this.#released = true;
      throw error;
    }
    this.markClosed();
    this.#released = true;
    if (this.#purgeLedgerOnRelease) {
      this.binding.purgeLedger({
        key: this.#key,
        ledgerDirectory: this.#ledgerDirectory,
      });
    }
  }

  override close(_reason?: unknown): void {
    this.release(false);
  }
}

function effectiveConnectionCapacity(settings: Readonly<RuntimeSettings>): number {
  return Math.min(
    settings.max_conn ?? SESSION_ID_LAYOUT.maxSlotIndex + 1,
    SESSION_ID_LAYOUT.maxSlotIndex + 1,
  );
}

export function createRuntimeStateKey(
  settings: Readonly<RuntimeSettings>,
  identity: string,
): string {
  const uid = typeof process.getuid === "function" ? process.getuid() : 0;
  return createHash("sha256")
    .update(`${uid}\0${identity}\0${settings.protocol}\0${settings.host}\0${settings.port}`)
    .digest("hex");
}

export class NativeSharedRuntimeStateProvider implements SharedRuntimeStateProvider {
  readonly #binding: NativeRuntimeStateBinding;

  constructor(binding: NativeRuntimeStateBinding = loadNativeRuntimeStateBinding()) {
    this.#binding = binding;
  }

  claimMaster(options: MasterSharedRuntimeClaimOptions): MasterSharedRuntimeState {
    const ledgerDirectory = options.ledgerDirectory ?? join(
      tmpdir(),
      `ts-swoole-runtime-state-${typeof process.getuid === "function" ? process.getuid() : 0}`,
    );
    mkdirSync(ledgerDirectory, { recursive: true, mode: 0o700 });
    const purgeLedgerOnRelease = options.runtimeKey === undefined;
    const key = options.runtimeKey ?? createRuntimeStateKey(
      options.settings,
      `${process.cwd()}\0ephemeral:${process.pid}:${randomUUID()}`,
    );
    const workerCapacity =
      options.settings.worker_num + options.settings.task_worker_num +
        (options.settings.user_task_worker_num ?? 0);
    if (workerCapacity > 0xffff_ffff) {
      throw new RangeError(
        "worker_num + task_worker_num + user_task_worker_num must fit the shared uint32 ABI",
      );
    }
    const claim = this.#binding.claimMaster({
      key,
      ledgerDirectory,
      connectionCapacity: effectiveConnectionCapacity(options.settings),
      workerCapacity,
      masterPid: options.masterPid,
      generationLimit: SESSION_ID_LAYOUT.maxMasterGeneration,
    });
    let descriptor: Readonly<SharedRuntimeDescriptor>;
    try {
      descriptor = validateSharedRuntimeDescriptor(claim.descriptor, {
        masterPid: options.masterPid,
        masterGeneration: claim.masterGeneration,
        connectionCapacity: effectiveConnectionCapacity(options.settings),
        workerCapacity,
      });
    } catch (error) {
      const cleanupFailures: unknown[] = [];
      let destroyed = false;
      try {
        if (!this.#binding.destroy(claim.handle, false)) {
          throw new Error("shared runtime claim rollback was rejected");
        }
        destroyed = true;
      } catch (cleanupError) {
        cleanupFailures.push(cleanupError);
      }
      if (purgeLedgerOnRelease && destroyed) {
        try {
          if (!this.#binding.purgeLedger({ key, ledgerDirectory })) {
            throw new Error("shared runtime claim ledger purge was rejected");
          }
        } catch (cleanupError) {
          cleanupFailures.push(cleanupError);
        }
      }
      if (cleanupFailures.length > 0) {
        throw new AggregateError(
          [error, ...cleanupFailures],
          "shared runtime descriptor validation and claim rollback both failed",
        );
      }
      throw error;
    }
    return new NativeMasterSharedRuntimeState(
      this.#binding,
      claim.handle,
      descriptor,
      claim.recovered,
      claim.previousCleanShutdown,
      key,
      ledgerDirectory,
      purgeLedgerOnRelease,
    );
  }

  attachReader(descriptor: SharedRuntimeDescriptor): SharedRuntimeStateReader {
    const validated = validateSharedRuntimeDescriptor(descriptor);
    return new NativeSharedRuntimeStateReader(
      this.#binding,
      this.#binding.attachReader(validated),
      validated,
    );
  }
}

export function sharedProtocolState(
  protocol: "tcp" | "websocket",
  websocketOpen: boolean,
): number {
  if (protocol === "tcp") {
    return SHARED_PROTOCOL_STATES.TCP;
  }
  return websocketOpen
    ? SHARED_PROTOCOL_STATES.WEBSOCKET_OPEN
    : SHARED_PROTOCOL_STATES.WEBSOCKET_HANDSHAKING;
}
