import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import type { IpcEnvelopeV1 } from "../protocol/ipc-envelope.ts";
import {
  IpcEnvelopeCodec,
  type EncodedIpcEnvelope,
} from "./ipc-message-codec.ts";

export const PROCESS_TRANSPORT_LANE = Object.freeze({
  CONTROL: "control",
  DATA: "data",
} as const);

export type ProcessTransportLane =
  (typeof PROCESS_TRANSPORT_LANE)[keyof typeof PROCESS_TRANSPORT_LANE];

export const DEFAULT_DATA_QUEUE_MAX_MESSAGES = 1024;
export const DEFAULT_DATA_QUEUE_MAX_BYTES = 8 * 1024 * 1024;
export const DEFAULT_DATA_QUEUE_HIGH_MESSAGES = 768;
export const DEFAULT_DATA_QUEUE_HIGH_BYTES = 6 * 1024 * 1024;
export const DEFAULT_DATA_QUEUE_LOW_MESSAGES = 512;
export const DEFAULT_DATA_QUEUE_LOW_BYTES = 4 * 1024 * 1024;
export const DEFAULT_CONTROL_QUEUE_MAX_MESSAGES = 32;
export const DEFAULT_CONTROL_QUEUE_MAX_BYTES = 256 * 1024;

export interface RawIpcSendOperation {
  readonly backpressured: boolean;
  readonly completed: Promise<void>;
}

export type RawIpcMessageListener = (message: unknown) => void;
export type ProcessTransportListenerDisposer = () => void;

export interface RawIpcEndpoint {
  readonly connected: boolean;
  readonly closed: Promise<unknown>;
  /** The endpoint transfers its sole reference to each received raw message. */
  readonly ownsReceivedMessages?: boolean;

  startSend(message: unknown): RawIpcSendOperation;
  onMessage(listener: RawIpcMessageListener): ProcessTransportListenerDisposer;
}

export interface ProcessTransportLaneLimits {
  readonly maxMessages?: number;
  readonly maxBytes?: number;
}

export interface ProcessTransportDataLaneLimits extends ProcessTransportLaneLimits {
  readonly highMessages?: number;
  readonly highBytes?: number;
  readonly lowMessages?: number;
  readonly lowBytes?: number;
}

export interface BoundedProcessTransportOptions {
  readonly codec?: IpcEnvelopeCodec;
  readonly maxMessageBytes?: number;
  readonly data?: ProcessTransportDataLaneLimits;
  readonly control?: ProcessTransportLaneLimits;
  readonly dataMaxMessages?: number;
  readonly dataMaxBytes?: number;
  readonly dataHighMessages?: number;
  readonly dataHighBytes?: number;
  readonly dataLowMessages?: number;
  readonly dataLowBytes?: number;
  readonly controlMaxMessages?: number;
  readonly controlMaxBytes?: number;
}

export interface ProcessTransportCapacityState {
  readonly pressured: boolean;
  readonly nativeBackpressured: boolean;
  readonly dataPendingMessages: number;
  readonly dataPendingBytes: number;
  readonly dataMaxMessages: number;
  readonly dataMaxBytes: number;
  readonly dataHighWaterMessages: number;
  readonly dataHighWaterBytes: number;
  readonly dataLowWaterMessages: number;
  readonly dataLowWaterBytes: number;
}

export interface ProcessTransportStats {
  readonly closed: boolean;
  readonly dataSealed: boolean;
  readonly pendingMessages: number;
  readonly pendingBytes: number;
  readonly queuedMessages: number;
  readonly queuedBytes: number;
  readonly inFlightMessages: 0 | 1;
  readonly inFlightBytes: number;
  readonly inFlightLane: ProcessTransportLane | null;
  readonly backpressured: boolean;
  readonly controlPendingMessages: number;
  readonly controlPendingBytes: number;
  readonly dataPendingMessages: number;
  readonly dataPendingBytes: number;
  readonly dataPressured: boolean;
  readonly dataMaxMessages: number;
  readonly dataMaxBytes: number;
  readonly dataHighWaterMessages: number;
  readonly dataHighWaterBytes: number;
  readonly dataLowWaterMessages: number;
  readonly dataLowWaterBytes: number;
  readonly acceptedMessages: number;
  readonly rejectedMessages: number;
  readonly sentMessages: number;
  readonly sentBytes: number;
  readonly failedMessages: number;
  readonly receivedMessages: number;
  readonly receivedBytes: number;
  readonly protocolErrorCount: number;
  readonly handlerErrorCount: number;
  readonly backpressureCount: number;
}

export type ProcessTransportMessageHandler = (
  envelope: Readonly<IpcEnvelopeV1>,
) => void | PromiseLike<void>;

export type ProcessTransportProtocolErrorHandler = (
  error: unknown,
  rawMessage: unknown,
) => void;

export type ProcessTransportCapacityListener = (
  state: Readonly<ProcessTransportCapacityState>,
) => void;

export interface ProcessTransport {
  readonly closed: Promise<void>;

  send(
    envelope: IpcEnvelopeV1,
    lane?: ProcessTransportLane,
  ): Promise<void>;
  sendControlAfterData(envelope: IpcEnvelopeV1): Promise<void>;
  onMessage(
    handler: ProcessTransportMessageHandler,
  ): ProcessTransportListenerDisposer;
  onProtocolError(
    handler: ProcessTransportProtocolErrorHandler,
  ): ProcessTransportListenerDisposer;
  onCapacityChange(
    listener: ProcessTransportCapacityListener,
  ): ProcessTransportListenerDisposer;
  drain(): Promise<void>;
  sealData(reason?: unknown): void;
  close(reason?: unknown): Promise<void>;
  stats(): Readonly<ProcessTransportStats>;
}

interface Deferred<Value> {
  readonly promise: Promise<Value>;
  readonly resolve: (value: Value) => void;
  readonly reject: (reason?: unknown) => void;
}

interface PendingSend extends EncodedIpcEnvelope {
  readonly lane: ProcessTransportLane;
  readonly deferred: Deferred<void>;
  readonly dataSequence?: bigint;
  readonly dataFence?: bigint;
  backpressured: boolean;
}

interface LaneState {
  readonly maxMessages: number;
  readonly maxBytes: number;
  readonly queue: PendingSend[];
  pendingMessages: number;
  pendingBytes: number;
}

interface DataWatermarks {
  readonly highMessages: number;
  readonly highBytes: number;
  readonly lowMessages: number;
  readonly lowBytes: number;
}

function createDeferred<Value>(): Deferred<Value> {
  let resolve!: (value: Value) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<Value>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function createHandledDeferred<Value>(): Deferred<Value> {
  const deferred = createDeferred<Value>();
  void deferred.promise.catch(() => undefined);
  return deferred;
}

function assertCapacity(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer, got ${value}`);
  }
}

function assertWatermarkOrder(
  name: string,
  low: number,
  high: number,
  max: number,
): void {
  if (low > high || high > max) {
    throw new RangeError(
      `${name} watermarks must satisfy low <= high <= max, got ${low} <= ${high} <= ${max}`,
    );
  }
}

function assertLane(lane: string): asserts lane is ProcessTransportLane {
  if (
    lane !== PROCESS_TRANSPORT_LANE.CONTROL &&
    lane !== PROCESS_TRANSPORT_LANE.DATA
  ) {
    throw new TypeError(`unknown process transport lane: ${lane}`);
  }
}

function reasonText(reason: unknown): string | undefined {
  if (reason === undefined) {
    return undefined;
  }
  if (reason instanceof Error) {
    return reason.message;
  }
  try {
    return String(reason);
  } catch {
    return "<unprintable reason>";
  }
}

function channelClosedError(
  message: string,
  reason?: unknown,
  details: Readonly<Record<string, unknown>> = {},
): FrameworkError {
  if (
    reason instanceof FrameworkError &&
    reason.code === FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED
  ) {
    return reason;
  }

  const renderedReason = reasonText(reason);
  return new FrameworkError(
    FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
    message,
    renderedReason === undefined
      ? details
      : { ...details, reason: renderedReason },
  );
}

function createLaneState(maxMessages: number, maxBytes: number): LaneState {
  return {
    maxMessages,
    maxBytes,
    queue: [],
    pendingMessages: 0,
    pendingBytes: 0,
  };
}

export class BoundedProcessTransport implements ProcessTransport {
  readonly closed: Promise<void>;

  readonly #endpoint: RawIpcEndpoint;
  readonly #codec: IpcEnvelopeCodec;
  readonly #control: LaneState;
  readonly #data: LaneState;
  readonly #dataWatermarks: DataWatermarks;
  readonly #closedDeferred = createDeferred<void>();
  readonly #drainWaiters = new Set<Deferred<void>>();
  readonly #messageHandlers = new Set<ProcessTransportMessageHandler>();
  readonly #protocolErrorHandlers = new Set<ProcessTransportProtocolErrorHandler>();
  readonly #capacityListeners = new Set<ProcessTransportCapacityListener>();
  #disposeRawMessage: ProcessTransportListenerDisposer = () => {};
  #inFlight: PendingSend | undefined;
  #dataSequence = 0n;
  #isClosed = false;
  #dataSealed = false;
  #closeError: FrameworkError | undefined;
  #dataSealError: FrameworkError | undefined;
  #acceptedMessages = 0;
  #rejectedMessages = 0;
  #sentMessages = 0;
  #sentBytes = 0;
  #failedMessages = 0;
  #receivedMessages = 0;
  #receivedBytes = 0;
  #protocolErrorCount = 0;
  #handlerErrorCount = 0;
  #backpressureCount = 0;
  #dataPressured = false;

  constructor(
    endpoint: RawIpcEndpoint,
    options: BoundedProcessTransportOptions = {},
  ) {
    const dataMaxMessages = options.dataMaxMessages ??
      options.data?.maxMessages ??
      DEFAULT_DATA_QUEUE_MAX_MESSAGES;
    const dataMaxBytes = options.dataMaxBytes ??
      options.data?.maxBytes ??
      DEFAULT_DATA_QUEUE_MAX_BYTES;
    const dataHighMessages = options.dataHighMessages ??
      options.data?.highMessages ??
      Math.min(DEFAULT_DATA_QUEUE_HIGH_MESSAGES, dataMaxMessages);
    const dataHighBytes = options.dataHighBytes ??
      options.data?.highBytes ??
      Math.min(DEFAULT_DATA_QUEUE_HIGH_BYTES, dataMaxBytes);
    const dataLowMessages = options.dataLowMessages ??
      options.data?.lowMessages ??
      Math.min(DEFAULT_DATA_QUEUE_LOW_MESSAGES, dataHighMessages);
    const dataLowBytes = options.dataLowBytes ??
      options.data?.lowBytes ??
      Math.min(DEFAULT_DATA_QUEUE_LOW_BYTES, dataHighBytes);
    const controlMaxMessages = options.controlMaxMessages ??
      options.control?.maxMessages ??
      DEFAULT_CONTROL_QUEUE_MAX_MESSAGES;
    const controlMaxBytes = options.controlMaxBytes ??
      options.control?.maxBytes ??
      DEFAULT_CONTROL_QUEUE_MAX_BYTES;
    assertCapacity("data maxMessages", dataMaxMessages);
    assertCapacity("data maxBytes", dataMaxBytes);
    assertCapacity("data highMessages", dataHighMessages);
    assertCapacity("data highBytes", dataHighBytes);
    assertCapacity("data lowMessages", dataLowMessages);
    assertCapacity("data lowBytes", dataLowBytes);
    assertCapacity("control maxMessages", controlMaxMessages);
    assertCapacity("control maxBytes", controlMaxBytes);
    assertWatermarkOrder(
      "data message",
      dataLowMessages,
      dataHighMessages,
      dataMaxMessages,
    );
    assertWatermarkOrder(
      "data byte",
      dataLowBytes,
      dataHighBytes,
      dataMaxBytes,
    );

    this.#endpoint = endpoint;
    this.#codec = options.codec ??
      new IpcEnvelopeCodec(
        options.maxMessageBytes === undefined
          ? {}
          : { maxMessageBytes: options.maxMessageBytes },
      );
    this.#control = createLaneState(controlMaxMessages, controlMaxBytes);
    this.#data = createLaneState(dataMaxMessages, dataMaxBytes);
    this.#dataWatermarks = Object.freeze({
      highMessages: dataHighMessages,
      highBytes: dataHighBytes,
      lowMessages: dataLowMessages,
      lowBytes: dataLowBytes,
    });
    this.closed = this.#closedDeferred.promise;

    this.#disposeRawMessage = endpoint.onMessage(this.#handleRawMessage);
    void endpoint.closed.then(
      (result) => {
        this.#beginClose(
          channelClosedError("raw IPC endpoint closed", result),
        );
      },
      (error) => {
        this.#beginClose(
          channelClosedError("raw IPC endpoint failed", error),
        );
      },
    ).catch(() => undefined);

    if (!endpoint.connected) {
      this.#beginClose(
        channelClosedError("raw IPC endpoint is not connected"),
      );
    }
  }

  send(
    envelope: IpcEnvelopeV1,
    lane: ProcessTransportLane = PROCESS_TRANSPORT_LANE.DATA,
  ): Promise<void> {
    assertLane(lane);
    return this.#enqueueSend(envelope, lane);
  }

  sendControlAfterData(envelope: IpcEnvelopeV1): Promise<void> {
    return this.#enqueueSend(
      envelope,
      PROCESS_TRANSPORT_LANE.CONTROL,
      this.#dataSequence,
    );
  }

  #enqueueSend(
    envelope: IpcEnvelopeV1,
    lane: ProcessTransportLane,
    dataFence?: bigint,
  ): Promise<void> {
    if (this.#isClosed) {
      this.#rejectedMessages += 1;
      throw this.#closeError ??
        channelClosedError("process transport is closed");
    }
    if (lane === PROCESS_TRANSPORT_LANE.DATA && this.#dataSealed) {
      this.#rejectedMessages += 1;
      throw this.#dataSealError ??
        channelClosedError("process transport data lane is sealed");
    }
    if (!this.#endpoint.connected) {
      const error = channelClosedError("raw IPC endpoint is not connected");
      this.#beginClose(error);
      this.#rejectedMessages += 1;
      throw error;
    }

    const encoded = this.#codec.encode(envelope);
    const state = this.#stateFor(lane);
    if (encoded.byteLength > state.maxBytes) {
      // 这条消息比整条 lane 的容量还大，永远排不进去。报 IPC_QUEUE_FULL 会把人往
      // 「并发太高」的方向引，所以单独报，并把定位信息一并带上。
      this.#rejectedMessages += 1;
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.MESSAGE_TOO_LARGE,
        `process transport ${lane} message size ${encoded.byteLength} can never fit in the ` +
          `${lane} lane (${state.maxBytes} bytes)` +
          ` (messageType=${String(envelope.messageType)} sessionId=${String(envelope.sessionId)}` +
          ` correlationId=${String(envelope.correlationId)})`,
        {
          lane,
          byteLength: encoded.byteLength,
          laneMaxBytes: state.maxBytes,
          maxMessageBytes: this.#codec.maxMessageBytes,
          messageType: envelope.messageType,
          sessionId: envelope.sessionId,
          correlationId: envelope.correlationId,
        },
      );
    }
    if (
      state.pendingMessages >= state.maxMessages ||
      encoded.byteLength > state.maxBytes - state.pendingBytes
    ) {
      this.#rejectedMessages += 1;
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL,
        `process transport ${lane} queue is full`,
        {
          lane,
          maxMessages: state.maxMessages,
          maxBytes: state.maxBytes,
          pendingMessages: state.pendingMessages,
          pendingBytes: state.pendingBytes,
          messageBytes: encoded.byteLength,
        },
      );
    }

    const deferred = createHandledDeferred<void>();
    const dataSequence = lane === PROCESS_TRANSPORT_LANE.DATA
      ? this.#dataSequence + 1n
      : undefined;
    const pending: PendingSend = {
      ...encoded,
      lane,
      deferred,
      ...(dataSequence === undefined ? {} : { dataSequence }),
      ...(dataFence === undefined ? {} : { dataFence }),
      backpressured: false,
    };
    state.queue.push(pending);
    if (dataSequence !== undefined) {
      this.#dataSequence = dataSequence;
    }
    state.pendingMessages += 1;
    state.pendingBytes += encoded.byteLength;
    this.#acceptedMessages += 1;
    this.#updateDataPressure();
    this.#pump();
    return deferred.promise;
  }

  onMessage(
    handler: ProcessTransportMessageHandler,
  ): ProcessTransportListenerDisposer {
    if (this.#isClosed) {
      return () => {};
    }
    this.#messageHandlers.add(handler);
    return () => {
      this.#messageHandlers.delete(handler);
    };
  }

  onProtocolError(
    handler: ProcessTransportProtocolErrorHandler,
  ): ProcessTransportListenerDisposer {
    if (this.#isClosed) {
      return () => {};
    }
    this.#protocolErrorHandlers.add(handler);
    return () => {
      this.#protocolErrorHandlers.delete(handler);
    };
  }

  onCapacityChange(
    listener: ProcessTransportCapacityListener,
  ): ProcessTransportListenerDisposer {
    if (this.#isClosed) {
      this.#notifyCapacityListener(listener, this.#capacityState());
      return () => {};
    }
    this.#capacityListeners.add(listener);
    this.#notifyCapacityListener(listener, this.#capacityState());
    return () => {
      this.#capacityListeners.delete(listener);
    };
  }

  drain(): Promise<void> {
    if (this.#pendingMessages() === 0) {
      return Promise.resolve();
    }
    const deferred = createDeferred<void>();
    this.#drainWaiters.add(deferred);
    return deferred.promise;
  }

  sealData(reason?: unknown): void {
    if (this.#dataSealed) {
      return;
    }
    this.#dataSealed = true;
    this.#dataSealError = channelClosedError(
      "process transport data lane is sealed",
      reason,
      { lane: PROCESS_TRANSPORT_LANE.DATA },
    );
    this.#rejectQueued(this.#data, this.#dataSealError);
    this.#pump();
    this.#settleLifecycleWaiters();
  }

  close(reason?: unknown): Promise<void> {
    this.#beginClose(
      channelClosedError("process transport is closed", reason),
    );
    return this.closed;
  }

  stats(): Readonly<ProcessTransportStats> {
    const queuedMessages = this.#control.queue.length + this.#data.queue.length;
    const queuedBytes = this.#control.queue.reduce(
      (total, pending) => total + pending.byteLength,
      0,
    ) + this.#data.queue.reduce(
      (total, pending) => total + pending.byteLength,
      0,
    );
    return Object.freeze({
      closed: this.#isClosed,
      dataSealed: this.#dataSealed,
      pendingMessages: this.#pendingMessages(),
      pendingBytes: this.#control.pendingBytes + this.#data.pendingBytes,
      queuedMessages,
      queuedBytes,
      inFlightMessages: this.#inFlight === undefined ? 0 : 1,
      inFlightBytes: this.#inFlight?.byteLength ?? 0,
      inFlightLane: this.#inFlight?.lane ?? null,
      backpressured: this.#inFlight?.backpressured ?? false,
      controlPendingMessages: this.#control.pendingMessages,
      controlPendingBytes: this.#control.pendingBytes,
      dataPendingMessages: this.#data.pendingMessages,
      dataPendingBytes: this.#data.pendingBytes,
      dataPressured: this.#dataPressured,
      dataMaxMessages: this.#data.maxMessages,
      dataMaxBytes: this.#data.maxBytes,
      dataHighWaterMessages: this.#dataWatermarks.highMessages,
      dataHighWaterBytes: this.#dataWatermarks.highBytes,
      dataLowWaterMessages: this.#dataWatermarks.lowMessages,
      dataLowWaterBytes: this.#dataWatermarks.lowBytes,
      acceptedMessages: this.#acceptedMessages,
      rejectedMessages: this.#rejectedMessages,
      sentMessages: this.#sentMessages,
      sentBytes: this.#sentBytes,
      failedMessages: this.#failedMessages,
      receivedMessages: this.#receivedMessages,
      receivedBytes: this.#receivedBytes,
      protocolErrorCount: this.#protocolErrorCount,
      handlerErrorCount: this.#handlerErrorCount,
      backpressureCount: this.#backpressureCount,
    });
  }

  readonly #handleRawMessage = (rawMessage: unknown): void => {
    if (this.#isClosed) {
      return;
    }

    let decoded: EncodedIpcEnvelope;
    try {
      decoded = this.#endpoint.ownsReceivedMessages === true
        ? this.#codec.decodeOwned(rawMessage)
        : this.#codec.decode(rawMessage);
    } catch (error) {
      this.#protocolErrorCount += 1;
      for (const handler of [...this.#protocolErrorHandlers]) {
        try {
          handler(error, rawMessage);
        } catch {
          // Protocol error observers cannot throw through the raw EventEmitter.
        }
      }
      return;
    }

    this.#receivedMessages += 1;
    this.#receivedBytes += decoded.byteLength;
    for (const handler of [...this.#messageHandlers]) {
      try {
        const result = handler(decoded.envelope);
        if (result !== undefined) {
          void Promise.resolve(result).catch(() => {
            this.#handlerErrorCount += 1;
          });
        }
      } catch {
        this.#handlerErrorCount += 1;
      }
    }
  };

  #stateFor(lane: ProcessTransportLane): LaneState {
    return lane === PROCESS_TRANSPORT_LANE.CONTROL
      ? this.#control
      : this.#data;
  }

  #pump(): void {
    if (this.#isClosed || this.#inFlight !== undefined) {
      return;
    }
    if (!this.#endpoint.connected) {
      this.#beginClose(
        channelClosedError("raw IPC endpoint disconnected before send"),
      );
      return;
    }

    const pending = this.#takeNextPending();
    if (pending === undefined) {
      this.#settleLifecycleWaiters();
      return;
    }
    this.#inFlight = pending;

    let operation: RawIpcSendOperation;
    try {
      operation = this.#endpoint.startSend(pending.envelope);
    } catch (error) {
      this.#finishFailedSend(pending, error);
      return;
    }

    pending.backpressured = operation.backpressured;
    if (operation.backpressured) {
      this.#backpressureCount += 1;
    }
    this.#updateDataPressure();
    void Promise.resolve(operation.completed).then(
      () => this.#finishSuccessfulSend(pending),
      (error) => this.#finishFailedSend(pending, error),
    );
  }

  #takeNextPending(): PendingSend | undefined {
    const ordinaryControlIndex = this.#control.queue.findIndex(
      (pending) => pending.dataFence === undefined,
    );
    if (ordinaryControlIndex >= 0) {
      return this.#control.queue.splice(ordinaryControlIndex, 1)[0];
    }

    const fencedControlIndex = this.#control.queue.findIndex(
      (pending) =>
        pending.dataFence !== undefined &&
        !this.#hasPendingDataAtOrBefore(pending.dataFence),
    );
    if (fencedControlIndex >= 0) {
      return this.#control.queue.splice(fencedControlIndex, 1)[0];
    }
    return this.#data.queue.shift();
  }

  #hasPendingDataAtOrBefore(fence: bigint): boolean {
    if (
      this.#inFlight?.lane === PROCESS_TRANSPORT_LANE.DATA &&
      this.#inFlight.dataSequence !== undefined &&
      this.#inFlight.dataSequence <= fence
    ) {
      return true;
    }
    const queued = this.#data.queue[0];
    return queued?.dataSequence !== undefined && queued.dataSequence <= fence;
  }

  #finishSuccessfulSend(pending: PendingSend): void {
    if (this.#inFlight !== pending) {
      return;
    }
    this.#inFlight = undefined;
    this.#releaseCapacity(pending);
    this.#sentMessages += 1;
    this.#sentBytes += pending.byteLength;
    pending.deferred.resolve();
    this.#updateDataPressure();
    this.#pump();
    this.#settleLifecycleWaiters();
  }

  #finishFailedSend(pending: PendingSend, cause: unknown): void {
    if (this.#inFlight !== pending) {
      return;
    }
    this.#inFlight = undefined;
    this.#releaseCapacity(pending);
    this.#failedMessages += 1;
    const error = channelClosedError(
      "raw IPC send failed",
      cause,
      { lane: pending.lane },
    );
    pending.deferred.reject(error);
    this.#updateDataPressure();
    this.#beginClose(error);
    this.#settleLifecycleWaiters();
  }

  #releaseCapacity(pending: PendingSend): void {
    const state = this.#stateFor(pending.lane);
    state.pendingMessages -= 1;
    state.pendingBytes -= pending.byteLength;
  }

  #rejectQueued(state: LaneState, error: FrameworkError): void {
    for (const pending of state.queue.splice(0)) {
      state.pendingMessages -= 1;
      state.pendingBytes -= pending.byteLength;
      this.#rejectedMessages += 1;
      pending.deferred.reject(error);
    }
    this.#updateDataPressure();
  }

  #beginClose(error: FrameworkError): void {
    if (this.#isClosed) {
      return;
    }
    this.#isClosed = true;
    this.#dataSealed = true;
    this.#closeError = error;
    this.#dataSealError ??= error;
    try {
      this.#disposeRawMessage();
    } catch {
      // Raw endpoint cleanup cannot block transport settlement.
    }
    this.#disposeRawMessage = () => {};
    const inFlight = this.#inFlight;
    if (inFlight !== undefined) {
      this.#inFlight = undefined;
      this.#releaseCapacity(inFlight);
      this.#rejectedMessages += 1;
      inFlight.deferred.reject(error);
    }
    this.#messageHandlers.clear();
    this.#protocolErrorHandlers.clear();
    this.#rejectQueued(this.#control, error);
    this.#rejectQueued(this.#data, error);
    this.#capacityListeners.clear();
    this.#dataPressured = false;
    this.#settleLifecycleWaiters();
  }

  #capacityState(): Readonly<ProcessTransportCapacityState> {
    return Object.freeze({
      pressured: this.#dataPressured,
      nativeBackpressured: this.#inFlight?.backpressured ?? false,
      dataPendingMessages: this.#data.pendingMessages,
      dataPendingBytes: this.#data.pendingBytes,
      dataMaxMessages: this.#data.maxMessages,
      dataMaxBytes: this.#data.maxBytes,
      dataHighWaterMessages: this.#dataWatermarks.highMessages,
      dataHighWaterBytes: this.#dataWatermarks.highBytes,
      dataLowWaterMessages: this.#dataWatermarks.lowMessages,
      dataLowWaterBytes: this.#dataWatermarks.lowBytes,
    });
  }

  #updateDataPressure(): void {
    const nativeBackpressured = this.#inFlight?.backpressured ?? false;
    const atHighWater =
      this.#data.pendingMessages >= this.#dataWatermarks.highMessages ||
      this.#data.pendingBytes >= this.#dataWatermarks.highBytes;
    const atOrBelowLowWater =
      this.#data.pendingMessages <= this.#dataWatermarks.lowMessages &&
      this.#data.pendingBytes <= this.#dataWatermarks.lowBytes;
    const nextPressured = this.#dataPressured
      ? nativeBackpressured || atHighWater || !atOrBelowLowWater
      : nativeBackpressured || atHighWater;
    if (nextPressured === this.#dataPressured) {
      return;
    }
    this.#dataPressured = nextPressured;
    const state = this.#capacityState();
    for (const listener of [...this.#capacityListeners]) {
      this.#notifyCapacityListener(listener, state);
    }
  }

  #notifyCapacityListener(
    listener: ProcessTransportCapacityListener,
    state: Readonly<ProcessTransportCapacityState>,
  ): void {
    try {
      listener(state);
    } catch {
      this.#handlerErrorCount += 1;
    }
  }

  #pendingMessages(): number {
    return this.#control.pendingMessages + this.#data.pendingMessages;
  }

  #settleLifecycleWaiters(): void {
    if (this.#pendingMessages() !== 0) {
      return;
    }
    for (const waiter of this.#drainWaiters) {
      waiter.resolve();
    }
    this.#drainWaiters.clear();
    if (this.#isClosed) {
      this.#closedDeferred.resolve();
    }
  }
}
