interface TcpConnectionProtocolState {
  readonly kind: "tcp";
  readonly frames: TcpFrameCodecLike;
}

interface WebSocketConnectionProtocolState {
  readonly kind: "websocket";
  phase: "handshaking" | "open";
  readonly handshake: WebSocketHandshakeParser;
  readonly frames: WebSocketFrameParser;
}

export type NetworkConnectionProtocolState =
  | TcpConnectionProtocolState
  | WebSocketConnectionProtocolState;

export interface NetworkOpenedEvent {
  readonly type: "opened";
  readonly protocol: RuntimeProtocol;
  readonly sessionId: SessionId;
  readonly connectedAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly request?: WebSocketHandshakeRequest;
}

export interface NetworkMessageEvent {
  readonly type: "message";
  readonly protocol: RuntimeProtocol;
  readonly sessionId: SessionId;
  readonly inputSequence: number;
  readonly data: Uint8Array | string;
  readonly opcode?: number;
  readonly finish: true;
}

export interface NetworkClosedEvent {
  readonly type: "closed";
  readonly protocol: RuntimeProtocol;
  readonly sessionId: SessionId;
  readonly ownerWorkerId: WorkerId | null;
  readonly inputSequence: number;
  readonly outputSequence: number;
  readonly connectedAt: number;
  readonly lastActiveAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly outputBufferedBytes: number;
  readonly outputBufferState: "full" | "overflow" | "empty";
  readonly cause: unknown;
}

export interface NetworkBufferEvent {
  readonly type: "buffer";
  readonly state: "full" | "overflow" | "empty";
  readonly protocol: RuntimeProtocol;
  readonly sessionId: SessionId;
}

export type NetworkServerEvent =
  | NetworkOpenedEvent
  | NetworkMessageEvent
  | NetworkBufferEvent
  | NetworkClosedEvent;

export interface NetworkServerStats {
  readonly inputQueuedBytes: number;
  readonly inputPausedConnections: number;
  readonly inputPauseEvents: number;
  readonly inputResumeEvents: number;
  readonly inputTimeouts: number;
  readonly inputRejections: number;
  readonly bufferFullEvents: number;
  readonly bufferEmptyEvents: number;
  readonly bufferOverflowEvents: number;
  readonly drainTimeouts: number;
  readonly writeRejections: number;
  readonly outputBufferedBytes: number;
  readonly outputBufferFullConnections: number;
  readonly outputBufferOverflowConnections: number;
}

export interface NetworkServerEventSinkStats {
  readonly pendingBytes: number;
  readonly pausedConnections: number;
  readonly pauseTransitions: number;
  readonly resumeTransitions: number;
  readonly recoveryTimeouts: number;
  readonly queueRejections: number;
}

export interface NetworkServerEventSink {
  handle(event: NetworkServerEvent): void | Promise<void>;
  stats?(): Readonly<NetworkServerEventSinkStats>;
  close?(reason?: unknown): void | Promise<void>;
}

export type NetworkServerEventSinkFactory<
  Handle extends NetworkConnectionHandle,
> = (
  connections: ConnectionRegistry<Handle, NetworkConnectionProtocolState>,
) => NetworkServerEventSink;

export interface NetworkServerOptions<Handle extends NetworkConnectionHandle> {
  readonly context: RuntimeContext;
  readonly sharedConnections?: SharedConnectionTableWriter &
    Partial<SharedRuntimeStatsWriter>;
  readonly adapter?: NetworkAdapter<Handle>;
  readonly eventSink?: NetworkServerEventSink;
  readonly eventSinkFactory?: NetworkServerEventSinkFactory<Handle>;
  readonly eventSinkCloseTimeoutMs?: number;
  readonly tcpFrameCodecFactory?: () => TcpFrameCodecLike;
  readonly webSocketHandshakeParserFactory?: () => WebSocketHandshakeParser;
  readonly webSocketFrameParserFactory?: () => WebSocketFrameParser;
  readonly rustDataPlane?: boolean;
}

const HTTP_BAD_REQUEST = Buffer.from(
  "HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n",
  "ascii",
);
const HTTP_UPGRADE_REQUIRED = Buffer.from(
  "HTTP/1.1 426 Upgrade Required\r\nConnection: close\r\nSec-WebSocket-Version: 13\r\nContent-Length: 0\r\n\r\n",
  "ascii",
);
const SHARED_ACTIVITY_PUBLISH_INTERVAL_MS = 1_000;
const NETWORK_GRACEFUL_CLOSE_TIMEOUT_MS = 250;
export const DEFAULT_NETWORK_EVENT_SINK_CLOSE_TIMEOUT_MS = 1_000;
export const DEFAULT_BUFFER_OUTPUT_SIZE = 2 * 1_024 * 1_024;
export const DEFAULT_SOCKET_BUFFER_SIZE = 1 * 1_024 * 1_024;
export const DEFAULT_BACKPRESSURE_TIMEOUT_MS = 5_000;

function readString(read: () => unknown, fallback: string): string {
  try {
    return String(read());
  } catch {
    return fallback;
  }
}

function describeError(error: unknown): Readonly<Record<string, string>> {
  let errorValue: Error | null = null;
  try {
    if (error instanceof Error) {
      errorValue = error;
    }
  } catch {
    // Some proxy values throw while their prototype chain is inspected.
  }

  if (errorValue !== null) {
    return {
      errorName: readString(() => errorValue.name, "Error"),
      errorMessage: readString(
        () => errorValue.message,
        "<unreadable error message>",
      ),
    };
  }
  return {
    errorName: "UnknownError",
    errorMessage: readString(() => error, "<unprintable thrown value>"),
  };
}

function closedCause(kind: string, details: Readonly<Record<string, unknown>> = {}): object {
  return Object.freeze({ kind, ...details });
}

export class NetworkServer<
  Handle extends NetworkConnectionHandle = NodeNetworkConnectionHandle,
> implements RuntimeResource, MasterNetworkCommandWriter {
  readonly sessions: SessionManager;
  readonly connections: ConnectionRegistry<Handle, NetworkConnectionProtocolState>;

  readonly #context: RuntimeContext;
  readonly #adapter: NetworkAdapter<Handle>;
  readonly #sharedStats: Partial<SharedRuntimeStatsWriter> | undefined;
  readonly #eventSink: NetworkServerEventSink | undefined;
  readonly #eventSinkCloseTimeoutMs: number;
  readonly #protocol: RuntimeProtocol;
  readonly #tcpFrameCodecFactory: () => TcpFrameCodecLike;
  readonly #webSocketHandshakeParserFactory: () => WebSocketHandshakeParser;
  readonly #webSocketFrameParserFactory: () => WebSocketFrameParser;
  readonly #bufferOutputSize: number;
  readonly #socketBufferSize: number;
  readonly #bufferHighWatermark: number;
  readonly #bufferLowWatermark: number;
  readonly #backpressureTimeoutMs: number;
  readonly #idleTimeoutMs: number | undefined;
  readonly #readTimeoutMs: number | undefined;
  readonly #writeTimeoutMs: number | undefined;
  readonly #outputDrainTimers = new Map<SessionId, RuntimeTimer>();
  readonly #lastReadAt = new Map<SessionId, number>();
  readonly #lastWriteAt = new Map<SessionId, number>();
  #activityTimeoutTimer: RuntimeTimer | undefined;
  #bufferFullEvents = 0;
  #bufferEmptyEvents = 0;
  #bufferOverflowEvents = 0;
  #drainTimeouts = 0;
  #writeRejections = 0;
  #address: NetworkListenerInfo | undefined;
  #listenPromise: Promise<void> | undefined;
  #stopAcceptingPromise: Promise<void> | undefined;
  #listenerCloseCompletion: Promise<void> | undefined;
  #closeConnectionsPromise: Promise<void> | undefined;
  #closePromise: Promise<void> | undefined;
  #accepting = true;
  #closing = false;

  constructor(options: NetworkServerOptions<Handle>) {
    if (options.eventSink !== undefined && options.eventSinkFactory !== undefined) {
      throw new TypeError("NetworkServer accepts either eventSink or eventSinkFactory, not both");
    }
    this.#context = options.context;
    this.#adapter = options.adapter ??
      ((options.rustDataPlane === true ||
          process.env.ALLOY_CORE_RUST_NETWORK === "1") &&
          options.context.settings.protocol === "tcp"
        ? new RustNetworkAdapter(undefined, {
          ...(options.context.settings.max_conn === undefined
            ? {}
            : { maxConnections: options.context.settings.max_conn }),
          ...(options.context.settings.socket_buffer_size === undefined
            ? {}
            : { socketBufferBytes: options.context.settings.socket_buffer_size }),
          ...(options.context.settings.buffer_high_watermark === undefined
            ? {}
            : {
              bufferHighWatermarkBytes:
                options.context.settings.buffer_high_watermark,
            }),
          ...(options.context.settings.buffer_low_watermark === undefined
            ? {}
            : {
              bufferLowWatermarkBytes:
                options.context.settings.buffer_low_watermark,
            }),
          ...(options.rustDataPlane === true
            ? {
              dataPlanePath: rustDataPlanePath(
                options.context.masterPid,
                options.context.masterGeneration,
              ),
              dataPlaneQueueMessages: 4_096,
              runtimeThreads: 1,
            }
            : {}),
        }) as unknown as NetworkAdapter<Handle>
        : new NodeNetworkAdapter() as unknown as NetworkAdapter<Handle>);
    this.#sharedStats = options.sharedConnections;
    this.#eventSinkCloseTimeoutMs = options.eventSinkCloseTimeoutMs ??
      DEFAULT_NETWORK_EVENT_SINK_CLOSE_TIMEOUT_MS;
    assertTimerDelay(
      this.#eventSinkCloseTimeoutMs,
      "eventSinkCloseTimeoutMs",
    );
    this.#protocol = options.context.settings.protocol;
    const outputSettings = options.context.settings;
    this.#bufferOutputSize = outputSettings.buffer_output_size ??
      DEFAULT_BUFFER_OUTPUT_SIZE;
    this.#socketBufferSize = outputSettings.socket_buffer_size ??
      DEFAULT_SOCKET_BUFFER_SIZE;
    this.#bufferHighWatermark = outputSettings.buffer_high_watermark ??
      Math.floor(this.#socketBufferSize * 0.8);
    this.#bufferLowWatermark = outputSettings.buffer_low_watermark ?? 0;
    this.#backpressureTimeoutMs = outputSettings.backpressure_timeout_ms ??
      DEFAULT_BACKPRESSURE_TIMEOUT_MS;
    this.#idleTimeoutMs = outputSettings.idle_timeout_ms;
    this.#readTimeoutMs = outputSettings.read_timeout_ms;
    this.#writeTimeoutMs = outputSettings.write_timeout_ms;
    assertTimerDelay(this.#backpressureTimeoutMs, "backpressure_timeout_ms");
    this.#tcpFrameCodecFactory = options.tcpFrameCodecFactory ??
      (process.env.ALLOY_CORE_RUST_TCP_CODEC === "1"
        ? () => new RustTcpFrameCodec()
        : () => new TcpFrameCodec());
    this.#webSocketHandshakeParserFactory =
      options.webSocketHandshakeParserFactory ?? (() => new WebSocketHandshakeParser());
    this.#webSocketFrameParserFactory =
      options.webSocketFrameParserFactory ?? (() => new WebSocketFrameParser());

    const layoutCapacity = SESSION_ID_LAYOUT.maxSlotIndex + 1;
    const configuredCapacity = options.context.settings.max_conn ?? layoutCapacity;
    const capacity = Math.min(configuredCapacity, layoutCapacity);
    if (configuredCapacity > layoutCapacity) {
      options.context.log("warn", "runtime.network.max_conn_clamped", {
        configuredMaxConnections: configuredCapacity,
        effectiveMaxConnections: capacity,
      });
    }
    this.sessions = new SessionManager({
      masterGeneration: options.context.masterGeneration,
      maxConnections: capacity,
    });
    this.connections = new ConnectionRegistry({
      sessions: this.sessions,
      operations: this.#adapter,
      clock: options.context.clock,
      activityPublishIntervalMs: SHARED_ACTIVITY_PUBLISH_INTERVAL_MS,
      onClosed: (connection) => this.#handleClosed(connection),
      ...(options.sharedConnections === undefined
        ? {}
        : {
          onRecordChanged: (record) => {
            try {
              const parts = decodeSessionId(record.sessionId);
              const protocol = record.protocolState.kind;
              options.sharedConnections?.publishConnection({
                sessionId: record.sessionId,
                slotIndex: parts.slotIndex,
                sessionGeneration: parts.sessionGeneration,
                masterGeneration: parts.masterGeneration,
                gatewayId: parts.gatewayId,
                ownerWorkerId: record.ownerWorkerId,
                state: record.state,
                protocol,
                protocolState: sharedProtocolState(
                  protocol,
                  protocol === "tcp" || record.protocolState.phase === "open",
                ),
                remoteAddress: record.peerInfo.remoteAddress,
                remotePort: record.peerInfo.remotePort,
                serverPort: record.peerInfo.localPort,
                connectedAtMs: record.connectedAt,
                lastActiveAtMs: record.lastActiveAt,
                outputBufferBytes: record.outputBufferedBytes,
                outputBufferFull: record.outputBufferFull,
                overflow: record.overflow,
              });
            } catch (error) {
              options.context.metrics.recordError();
              options.context.log("error", "runtime.shared.connection_publish_failed", {
                sessionId: record.sessionId,
                error: error instanceof Error ? error.message : String(error),
              });
              options.context.requestStop(error);
              throw error;
            }
          },
        }),
    });
    this.#eventSink = options.eventSink ?? options.eventSinkFactory?.(this.connections);
  }

  get address(): Readonly<NetworkListenerInfo> | undefined {
    return this.#address;
  }

  get routesTcpFramesToWorkers(): boolean {
    return this.#adapter.routesTcpFramesToWorkers === true;
  }

  routeSessionToWorker(
    sessionId: SessionId,
    workerId: WorkerId,
    workerGeneration: number,
  ): void {
    const bind = this.#adapter.bindDataPlaneRoute;
    if (typeof bind !== "function") {
      return;
    }
    const record = this.connections.get(sessionId);
    if (record === undefined || record.state !== "OPEN") {
      throw new Error(`Connection ${sessionId} is unavailable for native routing`);
    }
    const handle = this.connections.getHandle(sessionId);
    if (handle === undefined) {
      throw new Error(`Connection ${sessionId} has no native handle`);
    }
    bind.call(this.#adapter, handle, {
      sessionId,
      workerId,
      workerGeneration,
      inputSequence: record.inputSequence,
      outputSequence: record.outputSequence,
    });
  }

  deliverDataPlaneControl(
    type: "connect" | "close" | "buffer",
    sessionId: SessionId,
    workerId: WorkerId,
    workerGeneration: number,
    sequence: number,
    payload: unknown,
  ): Promise<void> {
    const deliver = this.#adapter.deliverDataPlaneControl;
    if (typeof deliver !== "function") {
      return Promise.reject(new Error("Network adapter has no native control lane"));
    }
    const serialized = JSON.stringify(payload);
    if (typeof serialized !== "string") {
      return Promise.reject(new TypeError("Native control payload is not JSON serializable"));
    }
    return deliver.call(this.#adapter, {
      type,
      sessionId,
      workerId,
      workerGeneration,
      sequence,
      payload: Buffer.from(serialized, "utf8"),
    });
  }

  synchronizeDataPlaneSession(sessionId: SessionId): void {
    const readCounters = this.#adapter.getDataPlaneCounters;
    if (typeof readCounters !== "function") {
      return;
    }
    const handle = this.connections.getHandle(sessionId);
    if (handle === undefined) {
      return;
    }
    const counters = readCounters.call(this.#adapter, handle);
    if (counters !== undefined) {
      this.connections.synchronizeSequences(
        sessionId,
        counters.inputSequence,
        counters.outputSequence,
      );
    }
  }

  async waitForDataPlaneSessionPaused(
    sessionId: SessionId,
    timeoutMs = 5_000,
  ): Promise<void> {
    const readCounters = this.#adapter.getDataPlaneCounters;
    if (typeof readCounters !== "function") {
      return;
    }
    const startedAt = this.#context.clock.monotonicTimeMs();
    while (true) {
      const handle = this.connections.getHandle(sessionId);
      if (handle === undefined) {
        return;
      }
      const counters = readCounters.call(this.#adapter, handle);
      if (
        counters === undefined ||
        counters.paused === true
      ) {
        this.synchronizeDataPlaneSession(sessionId);
        return;
      }
      if (this.#context.clock.monotonicTimeMs() - startedAt >= timeoutMs) {
        throw new Error(
          `Connection ${sessionId} native data plane did not pause within ${timeoutMs}ms`,
        );
      }
      await new Promise<void>((resolve) => setTimeout(resolve, 1));
    }
  }

  get closing(): boolean {
    return this.#closing;
  }

  stats(): Readonly<NetworkServerStats> {
    let inputQueuedBytes = 0;
    let outputBufferedBytes = 0;
    let outputBufferFullConnections = 0;
    let outputBufferOverflowConnections = 0;
    for (const sessionId of this.connections) {
      const record = this.connections.get(sessionId);
      if (record === undefined) {
        continue;
      }
      inputQueuedBytes = this.#boundedAdd(
        inputQueuedBytes,
        record.inputBufferedBytes,
      );
      outputBufferedBytes = Math.min(
        Number.MAX_SAFE_INTEGER,
        outputBufferedBytes + record.outputBufferedBytes,
      );
      if (record.outputBufferFull) {
        outputBufferFullConnections += 1;
      }
      if (record.overflow) {
        outputBufferOverflowConnections += 1;
      }
    }
    const sinkStats = this.#eventSink?.stats?.();
    inputQueuedBytes = this.#boundedAdd(
      inputQueuedBytes,
      sinkStats?.pendingBytes ?? 0,
    );
    return Object.freeze({
      inputQueuedBytes,
      inputPausedConnections: sinkStats?.pausedConnections ?? 0,
      inputPauseEvents: sinkStats?.pauseTransitions ?? 0,
      inputResumeEvents: sinkStats?.resumeTransitions ?? 0,
      inputTimeouts: sinkStats?.recoveryTimeouts ?? 0,
      inputRejections: sinkStats?.queueRejections ?? 0,
      bufferFullEvents: this.#bufferFullEvents,
      bufferEmptyEvents: this.#bufferEmptyEvents,
      bufferOverflowEvents: this.#bufferOverflowEvents,
      drainTimeouts: this.#drainTimeouts,
      writeRejections: this.#writeRejections,
      outputBufferedBytes,
      outputBufferFullConnections,
      outputBufferOverflowConnections,
    });
  }

  sendSession(sessionId: SessionId, data: Uint8Array): NetworkCommandWriteResult {
    const record = this.#commandRecord(sessionId, "tcp");
    if ("accepted" in record) {
      return this.#recordWriteRejection(record);
    }
    if (data.byteLength === 0) {
      return this.#recordWriteRejection(Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.INVALID_PAYLOAD,
        error: new TypeError("TCP send data must not be empty"),
      }));
    }
    const sizeRejection = this.#messageSizeRejection(sessionId, data.byteLength);
    if (sizeRejection !== undefined) {
      return this.#recordWriteRejection(sizeRejection);
    }
    return this.#writeCommand(sessionId, data, false);
  }

  pushSession(
    sessionId: SessionId,
    data: Uint8Array,
    opcode: number,
  ): NetworkCommandWriteResult {
    const record = this.#commandRecord(sessionId, "websocket");
    if ("accepted" in record) {
      return this.#recordWriteRejection(record);
    }
    const sizeRejection = this.#messageSizeRejection(sessionId, data.byteLength);
    if (sizeRejection !== undefined) {
      return this.#recordWriteRejection(sizeRejection);
    }

    let frame: Buffer;
    let closeAfterWrite = false;
    try {
      if (opcode === WEB_SOCKET_OPCODE.CLOSE) {
        const reason = new TextDecoder("utf-8", { fatal: true }).decode(data);
        frame = encodeWebSocketCloseFrame(1000, reason);
        closeAfterWrite = true;
      } else {
        frame = encodeWebSocketFrame({
          opcode: opcode as Parameters<typeof encodeWebSocketFrame>[0]["opcode"],
          data,
        });
      }
    } catch (error) {
      return this.#recordWriteRejection(Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.INVALID_PAYLOAD,
        error,
      }));
    }
    return this.#writeCommand(sessionId, frame, closeAfterWrite);
  }

  closeSession(
    sessionId: SessionId,
    code = 1000,
    reason = "",
  ): NetworkCommandWriteResult {
    const record = this.connections.get(sessionId);
    if (record === undefined) {
      return Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.UNKNOWN_SESSION,
      });
    }
    if (record.state === "CLOSING") {
      return Object.freeze({
        accepted: true,
        outputSequence: null,
        backpressured: false,
        closeStarted: false,
      });
    }
    if (record.state !== "OPEN") {
      return Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.SESSION_NOT_OPEN,
      });
    }
    if (record.protocolState.kind === "websocket") {
      try {
        this.#writeInternal(sessionId, encodeWebSocketCloseFrame(code, reason));
      } catch (error) {
        return this.#recordWriteRejection(Object.freeze({
          accepted: false,
          reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.INVALID_PAYLOAD,
          error,
        }));
      }
    }
    const closeStarted = this.connections.beginClose(
      sessionId,
      closedCause("worker-close-command"),
    );
    return Object.freeze({
      accepted: true,
      outputSequence: null,
      backpressured: false,
      closeStarted,
    });
  }

  listen(): Promise<void> {
    if (this.#listenPromise !== undefined) {
      return this.#listenPromise;
    }
    if (!this.#accepting || this.#closing || this.#context.signal.aborted) {
      return Promise.reject(new Error("NetworkServer cannot listen while closing"));
    }

    const settings = this.#context.settings;
    const listenOptions = settings.backlog === undefined
      ? {
          host: settings.host,
          port: settings.port,
          noDelay: settings.open_tcp_nodelay ?? false,
        }
      : {
          host: settings.host,
          port: settings.port,
          backlog: settings.backlog,
          noDelay: settings.open_tcp_nodelay ?? false,
        };

    const events: NetworkAdapterEvents<Handle> = {
      onConnection: (connection) => this.#handleConnection(connection),
      onData: (connection, data) => this.#handleData(connection, data),
      onDrain: (connection) => this.#handleDrain(connection),
      onBufferChange: (connection, state, bufferedBytes) =>
        this.#handleBufferChange(connection, state, bufferedBytes),
      onEnd: (connection) => this.#handleEnd(connection),
      onError: (connection, error) => this.#handleConnectionError(connection, error),
      onClose: (connection, hadError) => this.#handleNativeClose(connection, hadError),
      onListenerError: (error) => this.#handleListenerError(error),
    };

    this.#listenPromise = (async () => {
      const address = await this.#adapter.listen(listenOptions, events);
      if (!this.#accepting || this.#closing || this.#context.signal.aborted) {
        throw new Error("NetworkServer closed while the listener was starting");
      }
      this.#address = Object.freeze({ ...address });
      this.#context.log("info", "runtime.network.listening", {
        host: address.host,
        port: address.port,
        family: address.family,
        protocol: this.#protocol,
      });
      this.#scheduleActivityTimeoutSweep();
    })();
    void this.#listenPromise.catch(() => {});
    return this.#listenPromise;
  }

  close(reason?: unknown): Promise<void> {
    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }
    this.#closing = true;
    this.#activityTimeoutTimer?.cancel(reason);
    this.#activityTimeoutTimer = undefined;
    let resolveClose!: () => void;
    let rejectClose!: (reason?: unknown) => void;
    const closePromise = new Promise<void>((resolve, reject) => {
      resolveClose = resolve;
      rejectClose = reject;
    });
    this.#closePromise = closePromise;
    void this.#performClose(reason).then(resolveClose, rejectClose);
    void closePromise.catch(() => undefined);
    return closePromise;
  }

  stopAccepting(_reason?: unknown): Promise<void> {
    if (this.#stopAcceptingPromise !== undefined) {
      return this.#stopAcceptingPromise;
    }
    this.#accepting = false;
    this.#listenerCloseCompletion = this.#captureCleanup(() =>
      this.#adapter.closeListener()
    );
    void this.#listenerCloseCompletion.catch(() => undefined);
    this.#address = undefined;
    this.#stopAcceptingPromise = Promise.resolve();
    void this.#stopAcceptingPromise.catch(() => undefined);
    return this.#stopAcceptingPromise;
  }

  closeConnections(reason?: unknown): Promise<void> {
    if (this.#closeConnectionsPromise !== undefined) {
      return this.#closeConnectionsPromise;
    }
    this.#closing = true;
    this.#activityTimeoutTimer?.cancel(reason);
    this.#activityTimeoutTimer = undefined;
    this.#closeConnectionsPromise = this.#performConnectionsClose(reason);
    void this.#closeConnectionsPromise.catch(() => undefined);
    return this.#closeConnectionsPromise;
  }

  async #performClose(reason: unknown): Promise<void> {
    const stopAccepting = this.stopAccepting(reason);
    const listenerClose = this.#listenerCloseCompletion ?? stopAccepting;
    const closeConnections = this.closeConnections(reason);
    const adapterClose = this.#adapter.routesTcpFramesToWorkers === true
      ? closeConnections.then(
        () => this.#captureCleanup(() => this.#adapter.close(reason)),
        () => this.#captureCleanup(() => this.#adapter.close(reason)),
      )
      : undefined;
    const closeEventSink = (): Promise<void> =>
      this.#captureCleanup(() => this.#eventSink?.close?.(reason));
    const eventSinkClose = adapterClose === undefined
      ? closeConnections.then(closeEventSink, closeEventSink)
      : Promise.allSettled([closeConnections, adapterClose]).then(closeEventSink);
    const results = await Promise.allSettled([
      stopAccepting,
      listenerClose,
      closeConnections,
      ...(adapterClose === undefined ? [] : [adapterClose]),
      eventSinkClose,
    ]);
    const failures = results.flatMap((result) =>
      result.status === "rejected" ? [result.reason] : []
    );
    if (failures.length === 1) {
      throw failures[0];
    }
    if (failures.length > 1) {
      throw new AggregateError(failures, "NetworkServer cleanup failed");
    }
  }

  async #performConnectionsClose(reason: unknown): Promise<void> {
    for (const timer of this.#outputDrainTimers.values()) {
      timer.cancel(reason);
    }
    this.#outputDrainTimers.clear();
    for (const sessionId of this.connections) {
      const record = this.connections.get(sessionId);
      if (
        record?.state === "OPEN" &&
        record.protocolState.kind === "websocket"
      ) {
        this.#writeInternal(sessionId, encodeWebSocketCloseFrame(1001));
      }
    }

    const registryClose = this.#captureCleanup(() => this.connections.closeAll(reason));
    if (this.#adapter.routesTcpFramesToWorkers === true) {
      await registryClose;
      return;
    }
    let startAdapterClose!: () => void;
    const adapterClose = new Promise<void>((resolve, reject) => {
      let started = false;
      startAdapterClose = () => {
        if (started) {
          return;
        }
        started = true;
        void this.#captureCleanup(() => this.#adapter.close(reason)).then(resolve, reject);
      };
    });
    void adapterClose.catch(() => undefined);

    let gracefulCloseTimer: RuntimeTimer | undefined;
    let timerClose: Promise<void>;
    try {
      gracefulCloseTimer = this.#context.timers.setTimeout(
        NETWORK_GRACEFUL_CLOSE_TIMEOUT_MS,
        startAdapterClose,
      );
      timerClose = gracefulCloseTimer.done;
      void timerClose.then(startAdapterClose, startAdapterClose);
    } catch (error) {
      timerClose = Promise.reject(error);
      startAdapterClose();
    }

    const finishGracePeriod = (): void => {
      gracefulCloseTimer?.cancel(reason);
      startAdapterClose();
    };
    void registryClose.then(finishGracePeriod, finishGracePeriod);

    const results = await Promise.allSettled([
      registryClose,
      timerClose,
      adapterClose,
    ]);
    const failures = results.flatMap((result) =>
      result.status === "rejected" ? [result.reason] : []
    );
    if (failures.length === 1) {
      throw failures[0];
    }
    if (failures.length > 1) {
      throw new AggregateError(failures, "NetworkServer connection cleanup failed");
    }
  }

  #captureCleanup(cleanup: () => void | Promise<void>): Promise<void> {
    try {
      return Promise.resolve(cleanup());
    } catch (error) {
      return Promise.reject(error);
    }
  }

  #handleConnection(connection: Handle): void {
    if (!this.#accepting || this.#closing) {
      this.#closeUnregistered(connection, closedCause("server-closing"));
      return;
    }

    const protocolState: NetworkConnectionProtocolState = this.#protocol === "tcp"
      ? { kind: "tcp", frames: this.#tcpFrameCodecFactory() }
      : {
          kind: "websocket",
          phase: "handshaking",
          handshake: this.#webSocketHandshakeParserFactory(),
          frames: this.#webSocketFrameParserFactory(),
        };

    let record: ConnectionRecordSnapshot<NetworkConnectionProtocolState>;
    try {
      record = this.connections.add(connection, protocolState);
      const now = this.#context.clock.wallTimeMs();
      this.#lastReadAt.set(record.sessionId, now);
      this.#lastWriteAt.set(record.sessionId, now);
    } catch (error) {
      if (error instanceof SessionCapacityExhaustedError) {
        this.#context.log("warn", "runtime.network.connection_rejected", {
          reason: "max_conn",
          activeConnections: this.connections.size,
          capacity: this.sessions.capacity,
        });
      } else {
        this.#context.log("error", "runtime.network.connection_registration_failed", {
          ...describeError(error),
        });
      }
      this.#closeUnregistered(connection, error);
      return;
    }

    try {
      if (protocolState.kind === "tcp") {
        const opened = this.connections.markOpen(record.sessionId);
        if (opened !== undefined) {
          void this.#emit({
            type: "opened",
            protocol: "tcp",
            sessionId: opened.sessionId,
            connectedAt: opened.connectedAt,
            peerInfo: opened.peerInfo,
          }).catch(() => undefined);
        }
      } else {
        this.connections.markHandshaking(record.sessionId);
      }
    } catch (error) {
      this.#context.log("error", "runtime.network.connection_open_failed", {
        sessionId: record.sessionId,
        ...describeError(error),
      });
      this.connections.beginClose(record.sessionId, error);
    }
  }

  #handleData(connection: Handle, data: Uint8Array): void {
    const sessionId = this.connections.getSessionId(connection);
    if (sessionId === undefined) {
      this.#closeUnregistered(connection, closedCause("unknown-connection-data"));
      return;
    }
    const record = this.connections.get(sessionId);
    if (record === undefined || record.state === "CLOSING") {
      return;
    }
    this.connections.touchActivity(sessionId);
    this.#lastReadAt.set(sessionId, this.#context.clock.wallTimeMs());

    try {
      if (record.protocolState.kind === "tcp") {
        this.#handleTcpData(sessionId, record.protocolState, data);
      } else {
        this.#handleWebSocketData(sessionId, record.protocolState, data);
      }
    } catch (error) {
      this.#handleProtocolError(sessionId, record.protocolState, error);
    }
  }

  #handleTcpData(
    sessionId: SessionId,
    protocolState: TcpConnectionProtocolState,
    data: Uint8Array,
  ): void {
    const frames = this.#adapter.deliversTcpFrames === true
      ? [Buffer.from(data.buffer, data.byteOffset, data.byteLength)]
      : protocolState.frames.push(data);
    this.#setInputBufferedBytes(
      sessionId,
      this.#adapter.deliversTcpFrames === true ? 0 : protocolState.frames.bufferedBytes,
    );
    for (const frame of frames) {
      const inputSequence = this.connections.nextInputSequence(sessionId);
      if (inputSequence === undefined) {
        return;
      }
      void this.#emit({
        type: "message",
        protocol: "tcp",
        sessionId,
        inputSequence,
        data: frame,
        finish: true,
      }).catch(() => undefined);
      if (this.connections.get(sessionId)?.state === "CLOSING") {
        return;
      }
    }
  }

  #handleWebSocketData(
    sessionId: SessionId,
    protocolState: WebSocketConnectionProtocolState,
    data: Uint8Array,
  ): void {
    let frameData = data;
    if (protocolState.phase === "handshaking") {
      const result = protocolState.handshake.push(data);
      this.#setInputBufferedBytes(sessionId, protocolState.handshake.bufferedBytes);
      if (result === null) {
        return;
      }

      this.#writeInternal(
        sessionId,
        createWebSocketHandshakeResponse(result.request),
      );
      protocolState.phase = "open";
      const opened = this.connections.markOpen(sessionId);
      if (opened === undefined) {
        return;
      }
      void this.#emit({
        type: "opened",
        protocol: "websocket",
        sessionId,
        connectedAt: opened.connectedAt,
        peerInfo: opened.peerInfo,
        request: result.request,
      }).catch(() => undefined);
      frameData = result.remainingData;
    }

    if (frameData.byteLength === 0 || this.connections.get(sessionId)?.state === "CLOSING") {
      return;
    }
    const events = protocolState.frames.push(frameData);
    this.#setInputBufferedBytes(sessionId, protocolState.frames.bufferedBytes);
    this.#handleWebSocketEvents(sessionId, events);
  }

  #handleWebSocketEvents(
    sessionId: SessionId,
    events: readonly WebSocketProtocolEvent[],
  ): void {
    for (const event of events) {
      if (event.type === "message") {
        const inputSequence = this.connections.nextInputSequence(sessionId);
        if (inputSequence === undefined) {
          return;
        }
        void this.#emit({
          type: "message",
          protocol: "websocket",
          sessionId,
          inputSequence,
          data: event.data,
          opcode: event.opcode,
          finish: true,
        }).catch(() => undefined);
      } else if (event.type === "ping") {
        this.#writeInternal(
          sessionId,
          encodeWebSocketFrame({
            opcode: WEB_SOCKET_OPCODE.PONG,
            data: event.data,
          }),
        );
      } else if (event.type === "close") {
        const closeFrame = event.code === null
          ? encodeWebSocketFrame({ opcode: WEB_SOCKET_OPCODE.CLOSE })
          : encodeWebSocketCloseFrame(event.code, event.reason);
        this.#writeInternal(sessionId, closeFrame);
        this.connections.beginClose(
          sessionId,
          closedCause("websocket-close", {
            code: event.code,
            reason: event.reason,
          }),
        );
      }

      if (this.connections.get(sessionId)?.state === "CLOSING") {
        return;
      }
    }
  }

  #handleProtocolError(
    sessionId: SessionId,
    protocolState: NetworkConnectionProtocolState,
    error: unknown,
  ): void {
    this.#context.log("warn", "runtime.network.protocol_error", {
      sessionId,
      protocol: protocolState.kind,
      ...describeError(error),
    });

    if (protocolState.kind === "websocket") {
      if (protocolState.phase === "handshaking") {
        const response = error instanceof WebSocketProtocolError &&
            error.details.httpStatus === 426
          ? HTTP_UPGRADE_REQUIRED
          : HTTP_BAD_REQUEST;
        this.#writeInternal(sessionId, response);
      } else {
        const closeCode = error instanceof WebSocketProtocolError
          ? error.closeCode ?? 1002
          : 1002;
        try {
          this.#writeInternal(sessionId, encodeWebSocketCloseFrame(closeCode));
        } catch {
          // The transport close below remains the authoritative cleanup path.
        }
      }
    }
    this.connections.beginClose(sessionId, error);
  }

  #handleEnd(connection: Handle): void {
    const sessionId = this.connections.getSessionId(connection);
    if (sessionId !== undefined) {
      this.connections.beginClose(sessionId, closedCause("remote-end"));
    }
  }

  #handleDrain(connection: Handle): void {
    const sessionId = this.connections.getSessionId(connection);
    if (sessionId === undefined) {
      return;
    }
    const record = this.connections.get(sessionId);
    if (record === undefined || record.state === "CLOSING") {
      return;
    }
    const outputBufferedBytes = 0;
    this.connections.setBufferedBytes(
      sessionId,
      record.inputBufferedBytes,
      outputBufferedBytes,
    );
    this.connections.setOverflow(sessionId, false);
    if (
      record.outputBufferFull &&
      outputBufferedBytes <= this.#bufferLowWatermark
    ) {
      this.connections.setOutputBufferFull(sessionId, false);
      this.#cancelDrainTimeout(sessionId);
      this.#bufferEmptyEvents = this.#incrementCounter(this.#bufferEmptyEvents);
      this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_EMPTY);
      this.#recordMetric(() => this.#context.metrics.recordNetworkOutputBufferEmpty());
      this.#emitBufferEvent(sessionId, record.protocolState.kind, "empty");
    }
    this.connections.touchActivity(sessionId);
  }

  #handleBufferChange(
    connection: Handle,
    state: NetworkOutputBufferState,
    bufferedBytes: number,
  ): void {
    const sessionId = this.connections.getSessionId(connection);
    if (sessionId === undefined) {
      return;
    }
    const record = this.connections.get(sessionId);
    if (record === undefined || record.state === "CLOSING") {
      return;
    }
    if (!Number.isSafeInteger(bufferedBytes) || bufferedBytes < 0) {
      this.#handleConnectionError(
        connection,
        new TypeError("native output buffered bytes must be a non-negative safe integer"),
      );
      return;
    }
    if (state === "empty") {
      if (bufferedBytes > this.#bufferLowWatermark) {
        this.#handleConnectionError(
          connection,
          new TypeError(
            `native empty transition exceeds low watermark: ${bufferedBytes}`,
          ),
        );
        return;
      }
      this.connections.setBufferedBytes(
        sessionId,
        record.inputBufferedBytes,
        bufferedBytes,
      );
      this.connections.setOverflow(sessionId, false);
      if (record.outputBufferFull) {
        this.connections.setOutputBufferFull(sessionId, false);
        this.#cancelDrainTimeout(sessionId);
        this.#bufferEmptyEvents = this.#incrementCounter(this.#bufferEmptyEvents);
        this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_EMPTY);
        this.#recordMetric(() => this.#context.metrics.recordNetworkOutputBufferEmpty());
        this.#emitBufferEvent(sessionId, record.protocolState.kind, "empty");
      }
      this.connections.touchActivity(sessionId);
      return;
    }

    const threshold = state === "overflow"
      ? this.#socketBufferSize
      : this.#bufferHighWatermark;
    const observedBytes = Math.max(
      record.outputBufferedBytes,
      bufferedBytes,
      threshold,
    );
    this.connections.setBufferedBytes(
      sessionId,
      record.inputBufferedBytes,
      observedBytes,
    );
    this.#updateOutputBufferState(
      sessionId,
      record.protocolState.kind,
      observedBytes,
    );
    this.connections.touchActivity(sessionId);
  }

  #handleConnectionError(connection: Handle, error: unknown): void {
    const sessionId = this.connections.getSessionId(connection);
    if (sessionId !== undefined) {
      this.#context.log("warn", "runtime.network.connection_error", {
        sessionId,
        ...describeError(error),
      });
      this.connections.beginClose(sessionId, error);
    }
  }

  #handleNativeClose(connection: Handle, hadError: boolean): void {
    const sessionId = this.connections.getSessionId(connection);
    if (sessionId !== undefined) {
      const counters = this.#adapter.getDataPlaneCounters?.(connection);
      if (counters !== undefined) {
        this.connections.synchronizeSequences(
          sessionId,
          counters.inputSequence,
          counters.outputSequence,
        );
      }
    }
    this.connections.finalizeClose(
      connection,
      closedCause("native-close", { hadError }),
    );
  }

  #handleClosed(
    record: ConnectionRecordSnapshot<NetworkConnectionProtocolState>,
  ): Promise<void> {
    this.#lastReadAt.delete(record.sessionId);
    this.#lastWriteAt.delete(record.sessionId);
    this.#cancelDrainTimeout(record.sessionId, record.closeCause);
    const event: NetworkClosedEvent = {
      type: "closed",
      protocol: record.protocolState.kind,
      sessionId: record.sessionId,
      ownerWorkerId: record.ownerWorkerId,
      inputSequence: record.inputSequence,
      outputSequence: record.outputSequence,
      connectedAt: record.connectedAt,
      lastActiveAt: record.lastActiveAt,
      peerInfo: record.peerInfo,
      outputBufferedBytes: record.outputBufferedBytes,
      outputBufferState: record.overflow
        ? "overflow"
        : record.outputBufferFull
          ? "full"
          : "empty",
      cause: record.closeCause,
    };
    if (this.#eventSink === undefined) {
      return Promise.resolve();
    }

    const delivery = this.#emit(event, false);
    void delivery.catch(() => undefined);
    let rejectTimeout!: (reason?: unknown) => void;
    const timeout = new Promise<void>((_resolve, reject) => {
      rejectTimeout = reject;
    });
    const timeoutError = new Error(
      "Network event sink close delivery for Session " + record.sessionId +
        " timed out after " + this.#eventSinkCloseTimeoutMs + "ms",
    );
    const timer = this.#context.timers.setTimeout(
      this.#eventSinkCloseTimeoutMs,
      () => {
        this.#handleEventSinkFailure(event, timeoutError, false);
        rejectTimeout(timeoutError);
      },
    );
    return Promise.race([delivery, timeout]).finally(() => {
      timer.cancel();
    });
  }

  #handleListenerError(error: unknown): void {
    this.#context.metrics.recordError();
    this.#context.log("error", "runtime.network.listener_error", describeError(error));
    this.#context.requestStop(error);
    void this.close(error).catch((cleanupError: unknown) => {
      this.#context.log(
        "error",
        "runtime.network.listener_cleanup_failed",
        describeError(cleanupError),
      );
    });
  }

  #writeInternal(sessionId: SessionId, data: Uint8Array): boolean {
    const record = this.connections.get(sessionId);
    if (
      record === undefined ||
      record.state === "CLOSING" ||
      record.outputSequence >= Number.MAX_SAFE_INTEGER
    ) {
      return false;
    }
    if (this.#outputOverflowRejection(record) !== undefined) {
      this.#writeRejections = this.#incrementCounter(this.#writeRejections);
      this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_REJECTION);
      return false;
    }
    try {
      const result = this.connections.write(sessionId, data);
      if (result === undefined) {
        return false;
      }
      const outputSequence = this.connections.nextOutputSequence(sessionId);
      if (outputSequence === undefined) {
        return false;
      }
      this.connections.touchActivity(sessionId);
      this.#lastWriteAt.set(sessionId, this.#context.clock.wallTimeMs());
      this.#updateOutputBufferState(
        sessionId,
        record.protocolState.kind,
        result.bufferedBytes,
      );
      return true;
    } catch (error) {
      this.connections.beginClose(sessionId, error);
      return false;
    }
  }

  #commandRecord(
    sessionId: SessionId,
    protocol: RuntimeProtocol,
  ): ConnectionRecordSnapshot<NetworkConnectionProtocolState> |
    Extract<NetworkCommandWriteResult, { readonly accepted: false }> {
    if (this.#closing) {
      return Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.SESSION_NOT_OPEN,
      });
    }
    const record = this.connections.get(sessionId);
    if (record === undefined) {
      return Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.UNKNOWN_SESSION,
      });
    }
    if (record.state !== "OPEN") {
      return Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.SESSION_NOT_OPEN,
      });
    }
    if (record.protocolState.kind !== protocol) {
      return Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.PROTOCOL_MISMATCH,
      });
    }
    return record;
  }

  #writeCommand(
    sessionId: SessionId,
    data: Uint8Array,
    closeAfterWrite: boolean,
  ): NetworkCommandWriteResult {
    const record = this.connections.get(sessionId);
    if (record === undefined) {
      return this.#recordWriteRejection(Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.UNKNOWN_SESSION,
      }));
    }
    if (record.state !== "OPEN") {
      return this.#recordWriteRejection(Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.SESSION_NOT_OPEN,
      }));
    }
    if (record.outputSequence >= Number.MAX_SAFE_INTEGER) {
      const error = new RangeError(
        `Connection ${sessionId} outputSequence exhausted the safe integer range`,
      );
      this.connections.beginClose(sessionId, error);
      return this.#recordWriteRejection(Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.OUTPUT_SEQUENCE_EXHAUSTED,
        error,
      }));
    }
    const overflowRejection = this.#outputOverflowRejection(record);
    if (overflowRejection !== undefined) {
      return this.#recordWriteRejection(overflowRejection);
    }

    try {
      const write = this.connections.write(sessionId, data);
      if (write === undefined) {
        return this.#recordWriteRejection(Object.freeze({
          accepted: false,
          reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.SESSION_NOT_OPEN,
        }));
      }
      const outputSequence = this.connections.nextOutputSequence(sessionId);
      if (outputSequence === undefined) {
        throw new Error(
          `Connection ${sessionId} disappeared after an accepted write`,
        );
      }
      this.connections.touchActivity(sessionId);
      this.#lastWriteAt.set(sessionId, this.#context.clock.wallTimeMs());
      this.#updateOutputBufferState(
        sessionId,
        record.protocolState.kind,
        write.bufferedBytes,
      );
      if (closeAfterWrite) {
        this.connections.beginClose(
          sessionId,
          closedCause("websocket-close-command", { code: 1000 }),
        );
        this.#cancelDrainTimeout(sessionId);
      }
      return Object.freeze({
        accepted: true,
        outputSequence,
        backpressured: write.backpressured,
        closeStarted: closeAfterWrite,
      });
    } catch (error) {
      this.#context.metrics.recordError();
      this.#context.log("error", "runtime.network.command_write_failed", {
        sessionId,
        ...describeError(error),
      });
      this.connections.beginClose(sessionId, error);
      return this.#recordWriteRejection(Object.freeze({
        accepted: false,
        reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.WRITE_FAILED,
        error,
      }));
    }
  }

  #setInputBufferedBytes(sessionId: SessionId, inputBufferedBytes: number): void {
    const record = this.connections.get(sessionId);
    if (record !== undefined) {
      this.connections.setBufferedBytes(
        sessionId,
        inputBufferedBytes,
        record.outputBufferedBytes,
      );
    }
  }

  #messageSizeRejection(
    sessionId: SessionId,
    messageBytes: number,
  ): Extract<NetworkCommandWriteResult, { readonly accepted: false }> | undefined {
    if (messageBytes <= this.#bufferOutputSize) {
      return undefined;
    }
    const error = new FrameworkError(
      "MESSAGE_TOO_LARGE",
      `Network message for Session ${sessionId} is ${messageBytes} bytes; limit is ${this.#bufferOutputSize}`,
      {
        sessionId,
        messageBytes,
        bufferOutputSize: this.#bufferOutputSize,
      },
    );
    return Object.freeze({
      accepted: false,
      reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.MESSAGE_TOO_LARGE,
      error,
    });
  }

  #outputOverflowRejection(
    record: ConnectionRecordSnapshot<NetworkConnectionProtocolState>,
  ): Extract<NetworkCommandWriteResult, { readonly accepted: false }> | undefined {
    if (!record.overflow && record.outputBufferedBytes < this.#socketBufferSize) {
      return undefined;
    }
    this.#updateOutputBufferState(
      record.sessionId,
      record.protocolState.kind,
      record.outputBufferedBytes,
    );
    const error = new FrameworkError(
      "OUTPUT_BUFFER_OVERFLOW",
      `Connection ${record.sessionId} output buffer is full at ${record.outputBufferedBytes} bytes`,
      {
        sessionId: record.sessionId,
        outputBufferedBytes: record.outputBufferedBytes,
        socketBufferSize: this.#socketBufferSize,
      },
    );
    return Object.freeze({
      accepted: false,
      reason: NETWORK_COMMAND_WRITE_REJECTION_REASON.OUTPUT_BUFFER_OVERFLOW,
      error,
    });
  }

  #updateOutputBufferState(
    sessionId: SessionId,
    protocol: RuntimeProtocol,
    outputBufferedBytes: number,
  ): void {
    const record = this.connections.get(sessionId);
    if (record === undefined || record.state === "CLOSING") {
      return;
    }
    const becameFull = outputBufferedBytes > 0 &&
      !record.outputBufferFull &&
      (outputBufferedBytes >= this.#bufferHighWatermark ||
        outputBufferedBytes >= this.#socketBufferSize);
    const becameOverflow = !record.overflow &&
      outputBufferedBytes >= this.#socketBufferSize;
    if (becameFull) {
      this.connections.setOutputBufferFull(sessionId, true);
    }
    if (becameOverflow) {
      this.connections.setOverflow(sessionId, true);
    }
    if (becameFull) {
      this.#bufferFullEvents = this.#incrementCounter(this.#bufferFullEvents);
      this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_FULL);
      this.#recordMetric(() => this.#context.metrics.recordNetworkOutputBufferFull());
      this.#startDrainTimeout(sessionId);
      this.#emitBufferEvent(sessionId, protocol, "full");
    }
    if (becameOverflow) {
      this.#bufferOverflowEvents = this.#incrementCounter(
        this.#bufferOverflowEvents,
      );
      this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_OVERFLOW);
      this.#recordMetric(() => this.#context.metrics.recordNetworkOutputBufferOverflow());
      this.#emitBufferEvent(sessionId, protocol, "overflow");
    }
  }

  #emitBufferEvent(
    sessionId: SessionId,
    protocol: RuntimeProtocol,
    state: NetworkBufferEvent["state"],
  ): void {
    void this.#emit({ type: "buffer", state, protocol, sessionId }).catch(
      () => undefined,
    );
  }

  #startDrainTimeout(sessionId: SessionId): void {
    if (this.#outputDrainTimers.has(sessionId)) {
      return;
    }
    try {
      const timer = this.#context.timers.setTimeout(
        this.#backpressureTimeoutMs,
        () => this.#handleDrainTimeout(sessionId),
      );
      this.#outputDrainTimers.set(sessionId, timer);
    } catch (error) {
      this.connections.beginClose(sessionId, error);
    }
  }

  #cancelDrainTimeout(sessionId: SessionId, reason?: unknown): void {
    const timer = this.#outputDrainTimers.get(sessionId);
    if (timer === undefined) {
      return;
    }
    this.#outputDrainTimers.delete(sessionId);
    timer.cancel(reason);
  }

  #handleDrainTimeout(sessionId: SessionId): void {
    this.#outputDrainTimers.delete(sessionId);
    const record = this.connections.get(sessionId);
    if (
      record === undefined ||
      record.state === "CLOSING" ||
      !record.outputBufferFull
    ) {
      return;
    }
    const error = new FrameworkError(
      "DRAIN_TIMEOUT",
      `Connection ${sessionId} output buffer did not drain within ${this.#backpressureTimeoutMs}ms`,
      {
        sessionId,
        timeoutMs: this.#backpressureTimeoutMs,
        outputBufferedBytes: record.outputBufferedBytes,
      },
    );
    this.#drainTimeouts = this.#incrementCounter(this.#drainTimeouts);
    this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_TIMEOUT);
    this.#context.metrics.recordError();
    this.#context.log("warn", "runtime.network.output_drain_timeout", {
      sessionId,
      outputBufferedBytes: record.outputBufferedBytes,
      timeoutMs: this.#backpressureTimeoutMs,
    });
    this.connections.beginClose(sessionId, error);
  }

  #recordWriteRejection(
    rejection: Extract<NetworkCommandWriteResult, { readonly accepted: false }>,
  ): Extract<NetworkCommandWriteResult, { readonly accepted: false }> {
    this.#writeRejections = this.#incrementCounter(this.#writeRejections);
    this.#recordSharedStat(SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_REJECTION);
    return rejection;
  }

  #recordSharedStat(metricId: SharedRuntimeStatMetric): void {
    const addStat = this.#sharedStats?.addStat;
    if (typeof addStat !== "function") {
      return;
    }
    try {
      addStat.call(this.#sharedStats, metricId);
    } catch (error) {
      this.#context.metrics.recordError();
      this.#context.log("error", "runtime.shared.stat_publish_failed", {
        metricId,
        error: error instanceof Error ? error.message : String(error),
      });
      this.#context.requestStop(error);
    }
  }

  #incrementCounter(current: number): number {
    return current >= Number.MAX_SAFE_INTEGER ? current : current + 1;
  }

  #scheduleActivityTimeoutSweep(): void {
    if (
      this.#closing ||
      (this.#idleTimeoutMs === undefined &&
        this.#readTimeoutMs === undefined &&
        this.#writeTimeoutMs === undefined)
    ) {
      return;
    }
    const configured = [this.#idleTimeoutMs, this.#readTimeoutMs, this.#writeTimeoutMs]
      .filter((value): value is number => value !== undefined);
    const delayMs = Math.max(100, Math.min(...configured, 1_000));
    this.#activityTimeoutTimer = this.#context.timers.setTimeout(delayMs, () => {
      this.#activityTimeoutTimer = undefined;
      this.#sweepActivityTimeouts();
      this.#scheduleActivityTimeoutSweep();
    });
  }

  #sweepActivityTimeouts(): void {
    const now = this.#context.clock.wallTimeMs();
    for (const sessionId of this.connections) {
      const record = this.connections.get(sessionId);
      if (record === undefined || record.state === "CLOSING") continue;
      const lastReadAt = this.#lastReadAt.get(sessionId) ?? record.connectedAt;
      const lastWriteAt = this.#lastWriteAt.get(sessionId) ?? record.connectedAt;
      const idleAt = Math.max(lastReadAt, lastWriteAt);
      const timeout = this.#idleTimeoutMs !== undefined && now - idleAt >= this.#idleTimeoutMs
        ? { kind: "idle", limit: this.#idleTimeoutMs, elapsed: now - idleAt }
        : this.#readTimeoutMs !== undefined && now - lastReadAt >= this.#readTimeoutMs
        ? { kind: "read", limit: this.#readTimeoutMs, elapsed: now - lastReadAt }
        : this.#writeTimeoutMs !== undefined && now - lastWriteAt >= this.#writeTimeoutMs
        ? { kind: "write", limit: this.#writeTimeoutMs, elapsed: now - lastWriteAt }
        : undefined;
      if (timeout === undefined) continue;
      const error = new FrameworkError(
        "DRAIN_TIMEOUT",
        `Connection ${sessionId} ${timeout.kind} timeout after ${timeout.elapsed}ms`,
        { sessionId, timeoutKind: timeout.kind, timeoutMs: timeout.limit },
      );
      this.#context.log("warn", "runtime.network.activity_timeout", {
        sessionId,
        timeoutKind: timeout.kind,
        timeoutMs: timeout.limit,
        elapsedMs: timeout.elapsed,
      });
      this.connections.beginClose(sessionId, error);
    }
  }

  #boundedAdd(left: number, right: number): number {
    return Math.min(Number.MAX_SAFE_INTEGER, left + right);
  }

  #recordMetric(record: () => void): void {
    try {
      record();
    } catch {
      // Capacity metrics must not alter network flow-control decisions.
    }
  }

  async #emit(event: NetworkServerEvent, closeOnFailure = true): Promise<void> {
    const frozenEvent = Object.freeze(event);
    try {
      await this.#eventSink?.handle(frozenEvent);
    } catch (error) {
      this.#handleEventSinkFailure(frozenEvent, error, closeOnFailure);
      throw error;
    }
  }

  #handleEventSinkFailure(
    event: NetworkServerEvent,
    error: unknown,
    closeOnFailure: boolean,
  ): void {
    this.#context.log("error", "runtime.network.event_sink_failed", {
      eventType: event.type,
      sessionId: event.sessionId,
      ...describeError(error),
    });
    if (closeOnFailure) {
      this.connections.beginClose(event.sessionId, error);
    }
  }

  #closeUnregistered(connection: Handle, reason: unknown): void {
    try {
      this.#adapter.closeConnection(connection, reason);
    } catch {
      // The Node adapter owns final native cleanup for unregistered handles.
    }
  }
}
