import {
  FRAMEWORK_ERROR_CODE,
  FrameworkError,
  type FrameworkErrorCode,
} from "../errors/framework-error.ts";
import {
  IPC_MESSAGE_TYPE,
  type IpcEnvelopeV1,
  type IpcPayload,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE, type ProcessRole } from "../protocol/process-role.ts";
import type { WorkerId } from "../protocol/worker-id.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import {
  PROCESS_BUS_FLAG_EXPECT_RESPONSE,
  PROCESS_BUS_FLAG_RESPONSE,
  type ProcessBus,
} from "./process-bus.ts";
import type { ProcessTransportListenerDisposer } from "./process-transport.ts";

export type WorkerProcessMessageBus = Pick<
  ProcessBus,
  "localIdentity" | "enqueue" | "onMessage"
> & Partial<Pick<ProcessBus, "request" | "reply">>;

export type WorkerProcessMessageListener = (
  sourceWorkerId: WorkerId,
  message: IpcPayload,
) => void | Promise<void>;

export type WorkerProcessRequestListener = (
  sourceWorkerId: WorkerId,
  message: IpcPayload,
) => IpcPayload | Promise<IpcPayload>;

export interface WorkerProcessMessengerOptions {
  readonly bus: WorkerProcessMessageBus;
  readonly workerNum: number;
  readonly taskWorkerNum: number;
  readonly userTaskWorkerNum?: number;
  readonly onDeliveryError?: (error: unknown) => void;
}

export const WORKER_PROCESS_MESSAGE_REJECTION_REASON = Object.freeze({
  INVALID_SOURCE: "INVALID_SOURCE",
  INVALID_TARGET: "INVALID_TARGET",
  INVALID_METADATA: "INVALID_METADATA",
} as const);

export type WorkerProcessMessageRejectionReason =
  (typeof WORKER_PROCESS_MESSAGE_REJECTION_REASON)[
    keyof typeof WORKER_PROCESS_MESSAGE_REJECTION_REASON
  ];

export interface WorkerProcessMessengerStats {
  readonly sealed: boolean;
  readonly closed: boolean;
  readonly acceptedSends: number;
  readonly rejectedSends: number;
  readonly deliveryErrors: number;
  readonly receivedMessages: number;
  readonly ignoredMessages: number;
  readonly rejectedMessages: number;
  readonly callbackErrors: number;
  readonly rejectionCounts: Readonly<
    Partial<Record<WorkerProcessMessageRejectionReason, number>>
  >;
  readonly lastError: FrameworkErrorCode | null;
}

export class WorkerProcessMessageRejectedError extends Error {
  readonly reason: WorkerProcessMessageRejectionReason;
  readonly envelope: Readonly<IpcEnvelopeV1>;

  constructor(
    reason: WorkerProcessMessageRejectionReason,
    envelope: Readonly<IpcEnvelopeV1>,
    message: string,
  ) {
    super(message);
    this.name = "WorkerProcessMessageRejectedError";
    this.reason = reason;
    this.envelope = envelope;
  }
}

function assertPoolSize(name: string, value: number, minimum: number): void {
  if (!Number.isSafeInteger(value) || value < minimum) {
    throw new RangeError(
      `${name} must be a safe integer >= ${minimum}, got ${value}`,
    );
  }
}

function isWorkerRole(role: ProcessRole): role is
  | typeof PROCESS_ROLE.WORKER
  | typeof PROCESS_ROLE.TASK_WORKER
  | typeof PROCESS_ROLE.USER_TASK_WORKER {
  return role === PROCESS_ROLE.WORKER ||
    role === PROCESS_ROLE.TASK_WORKER ||
    role === PROCESS_ROLE.USER_TASK_WORKER;
}

function asMessengerErrorCode(error: unknown): FrameworkErrorCode {
  try {
    if (error instanceof FrameworkError) {
      return error.code;
    }
  } catch {
    // Hostile thrown values must remain inside the boolean facade.
  }
  return FRAMEWORK_ERROR_CODE.INVALID_STATE;
}

export class WorkerProcessMessenger implements RuntimeResource {
  readonly workerNum: number;
  readonly taskWorkerNum: number;
  readonly userTaskWorkerNum: number;

  readonly #bus: WorkerProcessMessageBus;
  readonly #onDeliveryError: ((error: unknown) => void) | undefined;
  readonly #listeners = new Set<WorkerProcessMessageListener>();
  readonly #requestListeners = new Set<WorkerProcessRequestListener>();
  readonly #rejectionCounts = new Map<
    WorkerProcessMessageRejectionReason,
    number
  >();
  #disposeBusMessage: ProcessTransportListenerDisposer;
  #sealed = false;
  #closed = false;
  #acceptedSends = 0;
  #rejectedSends = 0;
  #deliveryErrors = 0;
  #receivedMessages = 0;
  #ignoredMessages = 0;
  #rejectedMessages = 0;
  #callbackErrors = 0;
  #lastError: FrameworkErrorCode | null = null;

  constructor(options: WorkerProcessMessengerOptions) {
    assertPoolSize("workerNum", options.workerNum, 1);
    assertPoolSize("taskWorkerNum", options.taskWorkerNum, 0);
    const userTaskWorkerNum = options.userTaskWorkerNum ?? 0;
    assertPoolSize("userTaskWorkerNum", userTaskWorkerNum, 0);
    if (!Number.isSafeInteger(options.workerNum + options.taskWorkerNum + userTaskWorkerNum)) {
      throw new RangeError("configured process pool must be a safe integer");
    }

    const identity = options.bus.localIdentity;
    if (
      !isWorkerRole(identity.role) ||
      identity.workerId === null ||
      identity.generation === null ||
      !Number.isSafeInteger(identity.generation) ||
      identity.generation < 0 ||
      !this.#matchesRole(
        identity.role,
        identity.workerId,
        options.workerNum,
        options.taskWorkerNum,
        userTaskWorkerNum,
      )
    ) {
      throw new TypeError(
        "WorkerProcessMessenger requires a matching Worker or Task Worker ProcessBus identity",
      );
    }

    this.workerNum = options.workerNum;
    this.taskWorkerNum = options.taskWorkerNum;
    this.userTaskWorkerNum = userTaskWorkerNum;
    this.#bus = options.bus;
    this.#onDeliveryError = options.onDeliveryError;
    this.#disposeBusMessage = options.bus.onMessage(this.#handleEnvelope);
  }

  sendMessage(message: IpcPayload, targetWorkerId: WorkerId): boolean {
    try {
      if (this.#sealed || this.#closed) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
          "Worker process messenger is sealed",
        );
      }
      const targetRole = this.#targetRole(targetWorkerId);
      const receipt = this.#bus.enqueue({
        messageType: IPC_MESSAGE_TYPE.PROCESS_MESSAGE,
        targetRole,
        targetWorkerId,
        payload: message,
      });
      void receipt.completion.catch((error: unknown) => {
        this.#deliveryErrors += 1;
        try {
          this.#onDeliveryError?.(error);
        } catch {
          // Delivery observers cannot change an already-returned admission result.
        }
      });
      this.#acceptedSends += 1;
      this.#lastError = null;
      return true;
    } catch (error) {
      this.#rejectedSends += 1;
      this.#lastError = asMessengerErrorCode(error);
      return false;
    }
  }

  async requestMessage(
    message: IpcPayload,
    targetWorkerId: WorkerId,
    timeoutMs?: number,
  ): Promise<IpcPayload> {
    if (this.#sealed || this.#closed) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
        "Worker process messenger is sealed",
      );
    }
    if (this.#bus.request === undefined) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        "Worker process messenger bus does not support requests",
      );
    }
    const response = await this.#bus.request({
      messageType: IPC_MESSAGE_TYPE.PROCESS_MESSAGE,
      targetRole: this.#targetRole(targetWorkerId),
      targetWorkerId,
      payload: message,
      ...(timeoutMs === undefined ? {} : { timeoutMs }),
    });
    return response.payload;
  }

  onPipeMessage(
    listener: WorkerProcessMessageListener,
  ): ProcessTransportListenerDisposer {
    if (this.#closed) {
      return () => {};
    }
    this.#listeners.add(listener);
    return () => {
      this.#listeners.delete(listener);
    };
  }

  onPipeRequest(
    listener: WorkerProcessRequestListener,
  ): ProcessTransportListenerDisposer {
    if (this.#closed) {
      return () => {};
    }
    this.#requestListeners.add(listener);
    return () => {
      this.#requestListeners.delete(listener);
    };
  }

  getLastError(): FrameworkErrorCode | null {
    return this.#lastError;
  }

  stats(): Readonly<WorkerProcessMessengerStats> {
    return Object.freeze({
      sealed: this.#sealed,
      closed: this.#closed,
      acceptedSends: this.#acceptedSends,
      rejectedSends: this.#rejectedSends,
      deliveryErrors: this.#deliveryErrors,
      receivedMessages: this.#receivedMessages,
      ignoredMessages: this.#ignoredMessages,
      rejectedMessages: this.#rejectedMessages,
      callbackErrors: this.#callbackErrors,
      rejectionCounts: Object.freeze(
        Object.fromEntries(this.#rejectionCounts) as Partial<
          Record<WorkerProcessMessageRejectionReason, number>
        >,
      ),
      lastError: this.#lastError,
    });
  }

  seal(_reason?: unknown): void {
    this.#sealed = true;
  }

  close(_reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#sealed = true;
    this.#closed = true;
    this.#disposeBusMessage();
    this.#disposeBusMessage = () => {};
    this.#listeners.clear();
    this.#requestListeners.clear();
  }

  readonly #handleEnvelope = async (
    envelope: Readonly<IpcEnvelopeV1>,
  ): Promise<void> => {
    if (this.#closed) {
      return;
    }
    if (envelope.messageType !== IPC_MESSAGE_TYPE.PROCESS_MESSAGE) {
      this.#ignoredMessages += 1;
      return;
    }

    const sourceWorkerId = this.#requireTrustedSource(envelope);
    this.#assertLocalTarget(envelope);
    this.#receivedMessages += 1;
    if ((envelope.flags & PROCESS_BUS_FLAG_EXPECT_RESPONSE) !== 0) {
      this.#assertRequestMetadata(envelope);
      const payload = await this.#invokeRequestListener(sourceWorkerId, envelope.payload);
      if (this.#bus.reply === undefined) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          "Worker process messenger bus does not support replies",
        );
      }
      await this.#bus.reply(envelope, { payload });
      return;
    }
    this.#assertNeutralMetadata(envelope);
    await this.#invokeListeners(sourceWorkerId, envelope.payload);
  };

  #targetRole(targetWorkerId: WorkerId):
    | typeof PROCESS_ROLE.WORKER
    | typeof PROCESS_ROLE.TASK_WORKER
    | typeof PROCESS_ROLE.USER_TASK_WORKER {
    if (
      !Number.isSafeInteger(targetWorkerId) ||
      targetWorkerId < 0 ||
      targetWorkerId >= this.workerNum + this.taskWorkerNum + this.userTaskWorkerNum
    ) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
        `target Worker ID ${String(targetWorkerId)} is outside the configured process pool`,
        {
          targetWorkerId,
          workerNum: this.workerNum,
          taskWorkerNum: this.taskWorkerNum,
          userTaskWorkerNum: this.userTaskWorkerNum,
        },
      );
    }
    return targetWorkerId < this.workerNum
      ? PROCESS_ROLE.WORKER
      : targetWorkerId < this.workerNum + this.taskWorkerNum
      ? PROCESS_ROLE.TASK_WORKER
      : PROCESS_ROLE.USER_TASK_WORKER;
  }

  #requireTrustedSource(envelope: Readonly<IpcEnvelopeV1>): WorkerId {
    const sourceWorkerId = envelope.sourceWorkerId;
    if (
      !isWorkerRole(envelope.sourceRole) ||
      sourceWorkerId === null ||
      envelope.sourceGeneration === null ||
      !Number.isSafeInteger(envelope.sourceGeneration) ||
      envelope.sourceGeneration < 0 ||
      !this.#matchesRole(
        envelope.sourceRole,
        sourceWorkerId,
        this.workerNum,
        this.taskWorkerNum,
        this.userTaskWorkerNum,
      )
    ) {
      this.#reject(
        WORKER_PROCESS_MESSAGE_REJECTION_REASON.INVALID_SOURCE,
        envelope,
        "PROCESS_MESSAGE has an invalid or untrusted source identity",
      );
    }
    return sourceWorkerId;
  }

  #assertLocalTarget(envelope: Readonly<IpcEnvelopeV1>): void {
    const identity = this.#bus.localIdentity;
    if (
      envelope.targetRole !== identity.role ||
      envelope.targetWorkerId !== identity.workerId
    ) {
      this.#reject(
        WORKER_PROCESS_MESSAGE_REJECTION_REASON.INVALID_TARGET,
        envelope,
        "PROCESS_MESSAGE does not target the local process identity",
      );
    }
  }

  #assertNeutralMetadata(envelope: Readonly<IpcEnvelopeV1>): void {
    if (
      envelope.correlationId !== null ||
      envelope.sessionId !== null ||
      envelope.flags !== 0
    ) {
      this.#reject(
        WORKER_PROCESS_MESSAGE_REJECTION_REASON.INVALID_METADATA,
        envelope,
        "PROCESS_MESSAGE cannot carry correlation, Session, or reserved flags",
      );
    }
  }

  #assertRequestMetadata(envelope: Readonly<IpcEnvelopeV1>): void {
    if (
      envelope.correlationId !== null ||
      envelope.sessionId !== null ||
      envelope.flags !== PROCESS_BUS_FLAG_EXPECT_RESPONSE ||
      (envelope.flags & PROCESS_BUS_FLAG_RESPONSE) !== 0
    ) {
      this.#reject(
        WORKER_PROCESS_MESSAGE_REJECTION_REASON.INVALID_METADATA,
        envelope,
        "PROCESS_MESSAGE request has invalid correlation, Session, or flags",
      );
    }
  }

  #matchesRole(
    role:
      | typeof PROCESS_ROLE.WORKER
      | typeof PROCESS_ROLE.TASK_WORKER
      | typeof PROCESS_ROLE.USER_TASK_WORKER,
    workerId: number,
    workerNum: number,
    taskWorkerNum: number,
    userTaskWorkerNum: number,
  ): boolean {
    if (!Number.isSafeInteger(workerId) || workerId < 0) {
      return false;
    }
    if (role === PROCESS_ROLE.WORKER) {
      return workerId < workerNum;
    }
    if (role === PROCESS_ROLE.TASK_WORKER) {
      return workerId >= workerNum && workerId < workerNum + taskWorkerNum;
    }
    return workerId >= workerNum + taskWorkerNum &&
      workerId < workerNum + taskWorkerNum + userTaskWorkerNum;
  }

  #reject(
    reason: WorkerProcessMessageRejectionReason,
    envelope: Readonly<IpcEnvelopeV1>,
    message: string,
  ): never {
    this.#rejectedMessages += 1;
    this.#rejectionCounts.set(reason, (this.#rejectionCounts.get(reason) ?? 0) + 1);
    throw new WorkerProcessMessageRejectedError(reason, envelope, message);
  }

  async #invokeListeners(
    sourceWorkerId: WorkerId,
    message: IpcPayload,
  ): Promise<void> {
    const failures: unknown[] = [];
    for (const listener of [...this.#listeners]) {
      try {
        await listener(sourceWorkerId, message);
      } catch (error) {
        failures.push(error);
      }
    }
    this.#callbackErrors += failures.length;
    if (failures.length === 1) {
      throw failures[0];
    }
    if (failures.length > 1) {
      throw new AggregateError(failures, "Worker process message callbacks failed");
    }
  }

  async #invokeRequestListener(
    sourceWorkerId: WorkerId,
    message: IpcPayload,
  ): Promise<IpcPayload> {
    const listeners = [...this.#requestListeners];
    if (listeners.length !== 1) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        `PROCESS_MESSAGE request requires exactly one listener, received ${listeners.length}`,
      );
    }
    try {
      return await listeners[0]!(sourceWorkerId, message);
    } catch (error) {
      this.#callbackErrors += 1;
      throw error;
    }
  }
}
