import { AsyncLocalStorage } from "node:async_hooks";
import { randomUUID } from "node:crypto";

import {
  FRAMEWORK_ERROR_CODE,
  FrameworkError,
  type FrameworkErrorCode,
} from "../errors/framework-error.ts";
import {
  IPC_MESSAGE_TYPE,
  createCorrelationId,
  createMessageId,
  type IpcEnvelopeV1,
  type IpcPayload,
  type MessageId,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import {
  createTaskWorkerId,
  isEventWorkerId,
  toTaskWorkerId,
  type TaskWorkerId,
  type WorkerGeneration,
  type WorkerId,
} from "../protocol/worker-id.ts";
import type { ProcessBus } from "../process/process-bus.ts";
import type { RuntimeResource } from "../runtime/resource-scope.ts";
import {
  decodeScheduledTaskDispatchPayload,
  decodeTaskFinishPayload,
  encodeTaskFinishPayload,
  encodeWorkerTaskDispatchPayload,
  type ScheduledTaskDispatchPayload,
} from "./task-protocol.ts";

export const DEFAULT_WORKER_TASK_RUNTIME_MAX_PENDING_TASKS = 1024;

export type WorkerTaskBus = Pick<
  ProcessBus,
  "localIdentity" | "enqueue" | "onMessage" | "drain"
>;

export type WorkerTaskHandler = (
  taskId: number,
  sourceWorkerId: WorkerId,
  data: IpcPayload,
) => unknown | Promise<unknown>;

export type WorkerTaskFinishHandler = (
  taskId: number,
  data: IpcPayload,
) => void | Promise<void>;

export type WorkerTaskListenerDisposer = () => void;

export interface WorkerTaskRuntimeOptions {
  readonly bus: WorkerTaskBus;
  readonly workerNum: number;
  readonly taskWorkerNum: number;
  readonly userTaskWorkerNum?: number;
  readonly maxPendingTasks?: number;
  readonly onDeliveryError?: (error: unknown) => void;
}

export interface WorkerTaskRuntimeStats {
  readonly closed: boolean;
  readonly sealed: boolean;
  readonly newTasksSealed: boolean;
  readonly pendingTasks: number;
  readonly maxPendingTasks: number;
  readonly pendingTaskRejections: number;
  readonly acceptedTasks: number;
  readonly rejectedTasks: number;
  readonly receivedTasks: number;
  readonly admittedFinishes: number;
  readonly receivedFinishes: number;
  readonly completionAcks: number;
  readonly abandonedTasks: number;
  readonly callbackErrors: number;
  readonly rejectedMessages: number;
  readonly deliveryErrors: number;
  readonly completionRetries: number;
  readonly failedCompletions: number;
  readonly lastError: FrameworkErrorCode | null;
}

interface PendingTask {
  readonly dispatchMessageId: MessageId;
}

interface Deferred {
  readonly promise: Promise<void>;
  readonly resolve: () => void;
}

interface ActiveTaskExecution {
  readonly payload: Readonly<ScheduledTaskDispatchPayload>;
  readonly assignmentMessageId: MessageId;
  finished: boolean;
  cleanupRetryScheduled: boolean;
}

function assertPoolSize(name: string, value: number, minimum: number): void {
  if (!Number.isSafeInteger(value) || value < minimum) {
    throw new RangeError(`${name} must be a safe integer >= ${minimum}`);
  }
}

function asFrameworkErrorCode(error: unknown): FrameworkErrorCode {
  try {
    if (error instanceof FrameworkError) {
      return error.code;
    }
  } catch {
    // Hostile thrown values must remain inside the boolean facade.
  }
  return FRAMEWORK_ERROR_CODE.INVALID_STATE;
}

function closedError(message: string): FrameworkError {
  return new FrameworkError(FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED, message);
}

function createDeferred(): Deferred {
  let resolve!: () => void;
  const promise = new Promise<void>((resolvePromise) => {
    resolve = resolvePromise;
  });
  return { promise, resolve };
}

export class WorkerTaskRuntime implements RuntimeResource {
  readonly #bus: WorkerTaskBus;
  readonly #workerNum: number;
  readonly #taskWorkerNum: number;
  readonly #maxPendingTasks: number;
  readonly #localWorkerId: WorkerId;
  readonly #localGeneration: WorkerGeneration;
  readonly #localTaskWorkerId: TaskWorkerId | null;
  readonly #onDeliveryError: ((error: unknown) => void) | undefined;
  readonly #taskHandlers = new Set<WorkerTaskHandler>();
  readonly #finishHandlers = new Set<WorkerTaskFinishHandler>();
  readonly #pendingTasks = new Map<number, PendingTask>();
  readonly #activeTask = new AsyncLocalStorage<ActiveTaskExecution>();
  #completionRetryTail: Promise<void> = Promise.resolve();
  #pendingTasksDrain: Deferred | undefined;
  #disposeBusMessage: WorkerTaskListenerDisposer;
  #nextTaskId = 0;
  #closed = false;
  #sealed = false;
  #newTasksSealed = false;
  #acceptedTasks = 0;
  #rejectedTasks = 0;
  #pendingTaskRejections = 0;
  #receivedTasks = 0;
  #admittedFinishes = 0;
  #receivedFinishes = 0;
  #completionAcks = 0;
  #abandonedTasks = 0;
  #callbackErrors = 0;
  #rejectedMessages = 0;
  #deliveryErrors = 0;
  #completionRetries = 0;
  #failedCompletions = 0;
  #lastError: FrameworkErrorCode | null = null;

  constructor(options: WorkerTaskRuntimeOptions) {
    assertPoolSize("workerNum", options.workerNum, 1);
    assertPoolSize("taskWorkerNum", options.taskWorkerNum, 0);
    const userTaskWorkerNum = options.userTaskWorkerNum ?? 0;
    assertPoolSize("userTaskWorkerNum", userTaskWorkerNum, 0);
    const maxPendingTasks = options.maxPendingTasks ??
      DEFAULT_WORKER_TASK_RUNTIME_MAX_PENDING_TASKS;
    assertPoolSize("maxPendingTasks", maxPendingTasks, 0);
    const identity = options.bus.localIdentity;
    if (
      (identity.role !== PROCESS_ROLE.WORKER &&
        identity.role !== PROCESS_ROLE.TASK_WORKER &&
        identity.role !== PROCESS_ROLE.USER_TASK_WORKER) ||
      identity.workerId === null ||
      identity.generation === null
    ) {
      throw new TypeError(
        "WorkerTaskRuntime requires a supervised Worker ProcessBus identity",
      );
    }
    const configuredSize = options.workerNum + options.taskWorkerNum + userTaskWorkerNum;
    if (!Number.isSafeInteger(configuredSize) || identity.workerId >= configuredSize) {
      throw new TypeError("WorkerTaskRuntime identity is outside the configured process pool");
    }
    if (
      identity.role === PROCESS_ROLE.WORKER &&
      !isEventWorkerId(identity.workerId, options.workerNum)
    ) {
      throw new TypeError("WorkerTaskRuntime Worker identity is outside the Event Worker pool");
    }
    if (
      identity.role === PROCESS_ROLE.TASK_WORKER &&
      identity.workerId < options.workerNum
    ) {
      throw new TypeError("WorkerTaskRuntime Task Worker identity is outside the Task pool");
    }

    this.#bus = options.bus;
    this.#workerNum = options.workerNum;
    this.#taskWorkerNum = options.taskWorkerNum;
    this.#maxPendingTasks = maxPendingTasks;
    this.#localWorkerId = identity.workerId;
    this.#localGeneration = identity.generation;
    this.#localTaskWorkerId = identity.role === PROCESS_ROLE.TASK_WORKER
      ? toTaskWorkerId(options.workerNum, identity.workerId, options.taskWorkerNum)
      : null;
    this.#onDeliveryError = options.onDeliveryError;
    this.#disposeBusMessage = options.bus.onMessage(this.#handleEnvelope);
  }

  task(data: IpcPayload, taskWorkerId?: TaskWorkerId): number | false {
    try {
      if (this.#sealed || this.#newTasksSealed) {
        throw closedError("Worker task sender is sealed");
      }
      if (this.#bus.localIdentity.role !== PROCESS_ROLE.WORKER) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          "Task Workers cannot dispatch another task",
        );
      }
      if (this.#taskWorkerNum === 0) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
          "No Task Workers are configured",
        );
      }
      const requestedTaskWorkerId = taskWorkerId === undefined
        ? null
        : this.#requireTaskWorkerId(taskWorkerId);
      if (this.#pendingTasks.size >= this.#maxPendingTasks) {
        this.#pendingTaskRejections += 1;
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL,
          "Worker task pending capacity is full",
          {
            maxPendingTasks: this.#maxPendingTasks,
            pendingTasks: this.#pendingTasks.size,
          },
        );
      }
      if (this.#nextTaskId >= Number.MAX_SAFE_INTEGER) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          "Worker task ID sequence is exhausted",
        );
      }

      const taskId = this.#nextTaskId;
      const dispatchMessageId = createMessageId(
        `task:${this.#localWorkerId}:${this.#localGeneration}:${taskId}:${randomUUID()}`,
      );
      const receipt = this.#bus.enqueue({
        messageType: IPC_MESSAGE_TYPE.TASK_DISPATCH,
        targetRole: PROCESS_ROLE.MASTER,
        targetWorkerId: null,
        messageId: dispatchMessageId,
        payload: encodeWorkerTaskDispatchPayload({
          taskId,
          sourceWorkerId: this.#localWorkerId,
          sourceGeneration: this.#localGeneration,
          requestedTaskWorkerId,
          data,
        }),
      });
      this.#pendingTasks.set(taskId, { dispatchMessageId });
      this.#nextTaskId += 1;
      this.#acceptedTasks += 1;
      this.#lastError = null;
      this.#observeDelivery(receipt.completion, () => {
        if (this.#pendingTasks.get(taskId)?.dispatchMessageId === dispatchMessageId) {
          this.#pendingTasks.delete(taskId);
          this.#abandonedTasks += 1;
          this.#settlePendingTasksDrain();
        }
      });
      return taskId;
    } catch (error) {
      this.#rejectedTasks += 1;
      this.#lastError = asFrameworkErrorCode(error);
      return false;
    }
  }

  finish(result: IpcPayload): boolean {
    try {
      if (this.#sealed) {
        throw closedError("Worker task runtime is sealed");
      }
      if (this.#bus.localIdentity.role !== PROCESS_ROLE.TASK_WORKER) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          "finish() is only available inside a Task Worker callback",
        );
      }
      const execution = this.#activeTask.getStore();
      if (execution === undefined || execution.finished) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          execution === undefined
            ? "finish() requires an active Task callback"
            : "Task callback has already finished",
        );
      }
      this.#enqueueFinish(execution, true, result);
      this.#lastError = null;
      return true;
    } catch (error) {
      this.#lastError = asFrameworkErrorCode(error);
      return false;
    }
  }

  onTask(handler: WorkerTaskHandler): WorkerTaskListenerDisposer {
    return this.#addListener(this.#taskHandlers, handler);
  }

  onFinish(handler: WorkerTaskFinishHandler): WorkerTaskListenerDisposer {
    return this.#addListener(this.#finishHandlers, handler);
  }

  getLastError(): FrameworkErrorCode | null {
    return this.#lastError;
  }

  sealNewTasks(_reason?: unknown): void {
    this.#newTasksSealed = true;
  }

  seal(_reason?: unknown): void {
    this.#newTasksSealed = true;
    this.#sealed = true;
  }

  stats(): Readonly<WorkerTaskRuntimeStats> {
    return Object.freeze({
      closed: this.#closed,
      sealed: this.#sealed,
      newTasksSealed: this.#newTasksSealed,
      pendingTasks: this.#pendingTasks.size,
      maxPendingTasks: this.#maxPendingTasks,
      pendingTaskRejections: this.#pendingTaskRejections,
      acceptedTasks: this.#acceptedTasks,
      rejectedTasks: this.#rejectedTasks,
      receivedTasks: this.#receivedTasks,
      admittedFinishes: this.#admittedFinishes,
      receivedFinishes: this.#receivedFinishes,
      completionAcks: this.#completionAcks,
      abandonedTasks: this.#abandonedTasks,
      callbackErrors: this.#callbackErrors,
      rejectedMessages: this.#rejectedMessages,
      deliveryErrors: this.#deliveryErrors,
      completionRetries: this.#completionRetries,
      failedCompletions: this.#failedCompletions,
      lastError: this.#lastError,
    });
  }

  async drain(): Promise<void> {
    while (true) {
      const retry = this.#completionRetryTail;
      await retry;
      if (retry === this.#completionRetryTail) {
        return;
      }
    }
  }

  drainPendingTasks(): Promise<void> {
    if (this.#pendingTasks.size === 0) {
      return Promise.resolve();
    }
    this.#pendingTasksDrain ??= createDeferred();
    return this.#pendingTasksDrain.promise;
  }

  close(_reason?: unknown): void {
    if (this.#closed) {
      return;
    }
    this.#closed = true;
    this.seal();
    this.#disposeBusMessage();
    this.#disposeBusMessage = () => {};
    this.#abandonedTasks += this.#pendingTasks.size;
    this.#pendingTasks.clear();
    this.#settlePendingTasksDrain();
    this.#taskHandlers.clear();
    this.#finishHandlers.clear();
  }

  readonly #handleEnvelope = async (
    envelope: Readonly<IpcEnvelopeV1>,
  ): Promise<void> => {
    if (this.#closed) {
      return;
    }
    if (envelope.messageType === IPC_MESSAGE_TYPE.TASK_DISPATCH) {
      await this.#acceptTaskDispatch(envelope);
      return;
    }
    if (envelope.messageType === IPC_MESSAGE_TYPE.TASK_FINISH) {
      await this.#acceptTaskFinish(envelope);
    }
  };

  async #acceptTaskDispatch(envelope: Readonly<IpcEnvelopeV1>): Promise<void> {
    try {
      if (this.#bus.localIdentity.role !== PROCESS_ROLE.TASK_WORKER) {
        throw new TypeError("TASK_DISPATCH can only be delivered to a Task Worker");
      }
      this.#assertMasterEnvelope(envelope, PROCESS_ROLE.TASK_WORKER);
      if (envelope.correlationId === null) {
        throw new TypeError("TASK_DISPATCH requires the source dispatch correlation ID");
      }
      const payload = decodeScheduledTaskDispatchPayload(envelope.payload);
      if (
        payload.selectedWorkerId !== this.#localWorkerId ||
        payload.selectedGeneration !== this.#localGeneration ||
        payload.selectedTaskWorkerId !== this.#localTaskWorkerId
      ) {
        throw new TypeError("TASK_DISPATCH selected identity does not match this Task Worker");
      }
      if (!isEventWorkerId(payload.sourceWorkerId, this.#workerNum)) {
        throw new TypeError("TASK_DISPATCH sourceWorkerId is not an Event Worker");
      }

      this.#receivedTasks += 1;
      const execution: ActiveTaskExecution = {
        payload,
        assignmentMessageId: envelope.messageId,
        finished: false,
        cleanupRetryScheduled: false,
      };
      await this.#activeTask.run(execution, async () => {
        for (const handler of [...this.#taskHandlers]) {
          let result: unknown;
          try {
            result = await handler(payload.taskId, payload.sourceWorkerId, payload.data);
          } catch (error) {
            this.#callbackErrors += 1;
            this.#reportDeliveryError(error);
            break;
          }
          if (!execution.finished && result !== undefined && result !== null) {
            try {
              this.#enqueueFinish(execution, true, result as IpcPayload);
            } catch (error) {
              this.#deliveryErrors += 1;
              this.#lastError = asFrameworkErrorCode(error);
              this.#reportDeliveryError(error);
            }
          }
          if (execution.finished) {
            break;
          }
        }
        if (!execution.finished) {
          try {
            this.#enqueueFinish(execution, false);
          } catch (error) {
            this.#deliveryErrors += 1;
            this.#lastError = asFrameworkErrorCode(error);
            this.#reportDeliveryError(error);
            this.#scheduleCompletionAckRetry(execution);
          }
        }
      });
    } catch (error) {
      this.#rejectedMessages += 1;
      throw error;
    }
  }

  async #acceptTaskFinish(envelope: Readonly<IpcEnvelopeV1>): Promise<void> {
    try {
      if (this.#bus.localIdentity.role !== PROCESS_ROLE.WORKER) {
        throw new TypeError("TASK_FINISH can only be delivered to an Event Worker");
      }
      this.#assertMasterEnvelope(envelope, PROCESS_ROLE.WORKER);
      const payload = decodeTaskFinishPayload(envelope.payload);
      if (
        payload.sourceWorkerId !== this.#localWorkerId ||
        payload.sourceGeneration !== this.#localGeneration
      ) {
        throw new TypeError("TASK_FINISH source identity does not match this Worker generation");
      }
      const pending = this.#pendingTasks.get(payload.taskId);
      if (
        pending === undefined ||
        envelope.correlationId !== createCorrelationId(pending.dispatchMessageId)
      ) {
        throw new TypeError("TASK_FINISH does not match a pending Worker task");
      }

      this.#pendingTasks.delete(payload.taskId);
      this.#settlePendingTasksDrain();
      this.#receivedFinishes += 1;
      if (!payload.hasResult) {
        this.#completionAcks += 1;
        return;
      }
      for (const handler of [...this.#finishHandlers]) {
        try {
          await handler(payload.taskId, payload.result);
        } catch (error) {
          this.#callbackErrors += 1;
          this.#reportDeliveryError(error);
        }
      }
    } catch (error) {
      this.#rejectedMessages += 1;
      throw error;
    }
  }

  #assertMasterEnvelope(
    envelope: Readonly<IpcEnvelopeV1>,
    targetRole: typeof PROCESS_ROLE.WORKER | typeof PROCESS_ROLE.TASK_WORKER,
  ): void {
    if (
      envelope.sourceRole !== PROCESS_ROLE.MASTER ||
      envelope.sourceWorkerId !== null ||
      envelope.sourceGeneration !== null
    ) {
      throw new TypeError(`${envelope.messageType} must originate from Master`);
    }
    if (
      envelope.targetRole !== targetRole ||
      envelope.targetWorkerId !== this.#localWorkerId
    ) {
      throw new TypeError(`${envelope.messageType} targets a different Worker`);
    }
    if (envelope.sessionId !== null || envelope.flags !== 0) {
      throw new TypeError(`${envelope.messageType} contains invalid envelope metadata`);
    }
  }

  #enqueueFinish(
    execution: ActiveTaskExecution,
    hasResult: boolean,
    result?: IpcPayload,
  ): void {
    const payload = execution.payload;
    const finishPayload = hasResult
      ? encodeTaskFinishPayload({
        taskId: payload.taskId,
        sourceWorkerId: payload.sourceWorkerId,
        sourceGeneration: payload.sourceGeneration,
        selectedTaskWorkerId: payload.selectedTaskWorkerId,
        selectedWorkerId: payload.selectedWorkerId,
        selectedGeneration: payload.selectedGeneration,
        hasResult: true,
        result: result as IpcPayload,
      })
      : encodeTaskFinishPayload({
        taskId: payload.taskId,
        sourceWorkerId: payload.sourceWorkerId,
        sourceGeneration: payload.sourceGeneration,
        selectedTaskWorkerId: payload.selectedTaskWorkerId,
        selectedWorkerId: payload.selectedWorkerId,
        selectedGeneration: payload.selectedGeneration,
        hasResult: false,
      });
    const receipt = this.#bus.enqueue({
      messageType: IPC_MESSAGE_TYPE.TASK_FINISH,
      targetRole: PROCESS_ROLE.MASTER,
      targetWorkerId: null,
      correlationId: createCorrelationId(execution.assignmentMessageId),
      payload: finishPayload,
    });
    execution.finished = true;
    this.#admittedFinishes += 1;
    this.#observeDelivery(
      receipt.completion,
      () => this.#scheduleCompletionAckRetry(execution),
    );
  }

  #scheduleCompletionAckRetry(execution: ActiveTaskExecution): void {
    if (execution.cleanupRetryScheduled) {
      return;
    }
    execution.cleanupRetryScheduled = true;
    execution.finished = true;
    this.#completionRetries += 1;
    this.#completionRetryTail = this.#completionRetryTail.then(async () => {
      try {
        await this.#bus.drain();
      } catch (error) {
        this.#deliveryErrors += 1;
        this.#reportDeliveryError(error);
      }
      if (this.#closed) {
        this.#failedCompletions += 1;
        return;
      }

      const payload = execution.payload;
      try {
        const retry = this.#bus.enqueue({
          messageType: IPC_MESSAGE_TYPE.TASK_FINISH,
          targetRole: PROCESS_ROLE.MASTER,
          targetWorkerId: null,
          correlationId: createCorrelationId(execution.assignmentMessageId),
          payload: encodeTaskFinishPayload({
            taskId: payload.taskId,
            sourceWorkerId: payload.sourceWorkerId,
            sourceGeneration: payload.sourceGeneration,
            selectedTaskWorkerId: payload.selectedTaskWorkerId,
            selectedWorkerId: payload.selectedWorkerId,
            selectedGeneration: payload.selectedGeneration,
            hasResult: false,
          }),
        });
        await retry.completion;
      } catch (error) {
        this.#deliveryErrors += 1;
        this.#failedCompletions += 1;
        this.#reportDeliveryError(error);
      }
    });
    void this.#completionRetryTail.catch(() => undefined);
  }

  #requireTaskWorkerId(value: unknown): TaskWorkerId {
    if (
      typeof value !== "number" ||
      !Number.isSafeInteger(value) ||
      value < 0 ||
      value >= this.#taskWorkerNum
    ) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
        `taskWorkerId must be in [0, ${this.#taskWorkerNum})`,
      );
    }
    return createTaskWorkerId(value);
  }

  #observeDelivery(completion: Promise<void>, onFailure?: () => void): void {
    void completion.catch((error: unknown) => {
      this.#deliveryErrors += 1;
      onFailure?.();
      this.#reportDeliveryError(error);
    });
  }

  #reportDeliveryError(error: unknown): void {
    try {
      this.#onDeliveryError?.(error);
    } catch {
      // Delivery and callback observers cannot alter an admitted operation.
    }
  }

  #settlePendingTasksDrain(): void {
    if (this.#pendingTasks.size !== 0 || this.#pendingTasksDrain === undefined) {
      return;
    }
    const drain = this.#pendingTasksDrain;
    this.#pendingTasksDrain = undefined;
    drain.resolve();
  }

  #addListener<Listener>(set: Set<Listener>, listener: Listener): WorkerTaskListenerDisposer {
    if (typeof listener !== "function") {
      throw new TypeError("Worker task listener must be a function");
    }
    if (this.#sealed) {
      return () => {};
    }
    set.add(listener);
    return () => set.delete(listener);
  }
}
