import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import { WORKER_STATE } from "../lifecycle/states.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import {
  createTaskWorkerId,
  toGlobalTaskWorkerId,
  type TaskWorkerId,
  type WorkerId,
} from "../protocol/worker-id.ts";
import {
  WorkerRegistry,
  type WorkerRecordSnapshot,
} from "../process/worker-registry.ts";

export interface TaskSchedulerOptions {
  readonly registry: WorkerRegistry;
  readonly reservedTaskWorkerIds?: Iterable<TaskWorkerId>;
}

export interface TaskSchedulerStats {
  readonly sealed: boolean;
  readonly suspendedWorkerIds: readonly WorkerId[];
  readonly selected: number;
  readonly rejected: number;
  readonly automatic: number;
  readonly explicit: number;
}

function isReady(record: WorkerRecordSnapshot): boolean {
  return record.state === WORKER_STATE.READY || record.state === WORKER_STATE.RUNNING;
}

function unknownTaskWorkerError(
  message: string,
  taskWorkerId: unknown,
  taskWorkerNum: number,
): FrameworkError {
  return new FrameworkError(
    FRAMEWORK_ERROR_CODE.UNKNOWN_WORKER,
    message,
    { taskWorkerId, taskWorkerNum },
  );
}

function parseConfiguredTaskWorkerId(
  value: unknown,
  taskWorkerNum: number,
  name: string,
): TaskWorkerId {
  if (
    typeof value !== "number" ||
    !Number.isSafeInteger(value) ||
    value < 0 ||
    value >= taskWorkerNum
  ) {
    throw unknownTaskWorkerError(
      `${name} must be a pool-local Task Worker ID in [0, ${taskWorkerNum})`,
      value,
      taskWorkerNum,
    );
  }
  return createTaskWorkerId(value);
}

function normalizeRequestedTaskWorkerId(
  value: unknown,
  taskWorkerNum: number,
): TaskWorkerId {
  if (taskWorkerNum === 0) {
    throw unknownTaskWorkerError(
      "TaskScheduler has no configured Task Worker pool",
      value,
      taskWorkerNum,
    );
  }
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) {
    throw unknownTaskWorkerError(
      "requestedTaskWorkerId must be a non-negative safe integer",
      value,
      taskWorkerNum,
    );
  }
  return createTaskWorkerId(value % taskWorkerNum);
}

export class TaskScheduler {
  readonly #registry: WorkerRegistry;
  readonly #reservedTaskWorkerIds: ReadonlySet<TaskWorkerId>;
  readonly #suspendedWorkerIds = new Set<WorkerId>();
  #nextAutomaticTaskWorkerId = 0;
  #sealed = false;
  #selected = 0;
  #rejected = 0;
  #automatic = 0;
  #explicit = 0;

  constructor(options: TaskSchedulerOptions) {
    if (!(options.registry instanceof WorkerRegistry)) {
      throw new TypeError("TaskScheduler requires a WorkerRegistry");
    }
    this.#registry = options.registry;

    const reserved = new Set<TaskWorkerId>();
    for (const value of options.reservedTaskWorkerIds ?? []) {
      reserved.add(
        parseConfiguredTaskWorkerId(
          value,
          this.#registry.taskWorkerNum,
          "reservedTaskWorkerId",
        ),
      );
    }
    this.#reservedTaskWorkerIds = reserved;
  }

  select(requestedTaskWorkerId?: TaskWorkerId): Readonly<WorkerRecordSnapshot> {
    try {
      if (this.#sealed) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.INVALID_STATE,
          "TaskScheduler is sealed",
        );
      }

      const selected = requestedTaskWorkerId === undefined
        ? this.#selectAutomatic()
        : this.#selectExplicit(requestedTaskWorkerId);
      this.#selected += 1;
      if (requestedTaskWorkerId === undefined) {
        this.#automatic += 1;
      } else {
        this.#explicit += 1;
      }
      return selected;
    } catch (error) {
      this.#rejected += 1;
      throw error;
    }
  }

  seal(_reason?: unknown): void {
    this.#sealed = true;
  }

  suspend(workerId: WorkerId): void {
    this.#requireTaskWorkerSlot(workerId);
    this.#suspendedWorkerIds.add(workerId);
  }

  resume(workerId: WorkerId): void {
    this.#requireTaskWorkerSlot(workerId);
    this.#suspendedWorkerIds.delete(workerId);
  }

  stats(): Readonly<TaskSchedulerStats> {
    return Object.freeze({
      sealed: this.#sealed,
      suspendedWorkerIds: Object.freeze(
        [...this.#suspendedWorkerIds].sort((left, right) => left - right),
      ),
      selected: this.#selected,
      rejected: this.#rejected,
      automatic: this.#automatic,
      explicit: this.#explicit,
    });
  }

  #selectAutomatic(): Readonly<WorkerRecordSnapshot> {
    const taskWorkerNum = this.#registry.taskWorkerNum;
    if (taskWorkerNum === 0) {
      throw unknownTaskWorkerError(
        "TaskScheduler has no configured Task Worker pool",
        null,
        taskWorkerNum,
      );
    }
    if (this.#reservedTaskWorkerIds.size >= taskWorkerNum) {
      throw unknownTaskWorkerError(
        "TaskScheduler has no non-reserved Task Worker slots",
        null,
        taskWorkerNum,
      );
    }

    const candidates = this.#registry.snapshot()
      .filter((record) =>
        record.role === PROCESS_ROLE.TASK_WORKER &&
        record.taskWorkerId !== null &&
        !this.#reservedTaskWorkerIds.has(record.taskWorkerId) &&
        !this.#suspendedWorkerIds.has(record.workerId) &&
        isReady(record)
      )
      .sort((left, right) => left.taskWorkerId! - right.taskWorkerId!);
    if (candidates.length === 0) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.WORKER_NOT_READY,
        "TaskScheduler has no READY automatic Task Worker candidates",
        {
          taskWorkerNum,
          reservedTaskWorkerIds: [...this.#reservedTaskWorkerIds].sort((left, right) =>
            left - right
          ),
          suspendedWorkerIds: [...this.#suspendedWorkerIds].sort((left, right) =>
            left - right
          ),
        },
      );
    }

    const selected = candidates.find((record) =>
      record.taskWorkerId! >= this.#nextAutomaticTaskWorkerId
    ) ?? candidates[0]!;
    this.#nextAutomaticTaskWorkerId = (selected.taskWorkerId! + 1) % taskWorkerNum;
    return selected;
  }

  #selectExplicit(requestedTaskWorkerId: TaskWorkerId): Readonly<WorkerRecordSnapshot> {
    const taskWorkerId = normalizeRequestedTaskWorkerId(
      requestedTaskWorkerId,
      this.#registry.taskWorkerNum,
    );
    const workerId = toGlobalTaskWorkerId(
      this.#registry.workerNum,
      taskWorkerId,
      this.#registry.taskWorkerNum,
    );
    const slot = this.#requireTaskWorkerSlot(workerId);
    if (slot.taskWorkerId !== taskWorkerId) {
      throw unknownTaskWorkerError(
        `Task Worker ${taskWorkerId} does not map to a Task Worker slot`,
        taskWorkerId,
        this.#registry.taskWorkerNum,
      );
    }

    if (this.#suspendedWorkerIds.has(workerId)) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.WORKER_NOT_READY,
        `Task Worker ${taskWorkerId} is suspended`,
        {
          taskWorkerId,
          workerId,
          suspended: true,
        },
      );
    }

    const record = this.#registry.get(workerId);
    if (record === undefined || !isReady(record)) {
      throw new FrameworkError(
        FRAMEWORK_ERROR_CODE.WORKER_NOT_READY,
        `Task Worker ${taskWorkerId} is not READY`,
        {
          taskWorkerId,
          workerId,
          state: record?.state ?? null,
        },
      );
    }
    if (
      record.role !== PROCESS_ROLE.TASK_WORKER ||
      record.taskWorkerId !== taskWorkerId
    ) {
      throw unknownTaskWorkerError(
        `Worker ${workerId} is not Task Worker ${taskWorkerId}`,
        taskWorkerId,
        this.#registry.taskWorkerNum,
      );
    }
    return record;
  }

  #requireTaskWorkerSlot(workerId: WorkerId) {
    const slot = this.#registry.getSlot(workerId);
    if (slot === undefined || slot.role !== PROCESS_ROLE.TASK_WORKER) {
      throw unknownTaskWorkerError(
        `Worker ${workerId} is not a configured global Task Worker ID`,
        workerId,
        this.#registry.taskWorkerNum,
      );
    }
    return slot;
  }
}
