export interface IdGenerator<Id> {
  next(): Id;
}

export class SequentialIdGenerator implements IdGenerator<number> {
  #current: number;

  constructor(start = 0) {
    if (!Number.isSafeInteger(start) || start < 0) {
      throw new RangeError(
        `start must be a non-negative safe integer, got ${start}`,
      );
    }
    this.#current = start;
  }

  next(): number {
    if (this.#current === Number.MAX_SAFE_INTEGER) {
      throw new RangeError("sequential ID generator exhausted the safe integer range");
    }
    this.#current += 1;
    return this.#current;
  }
}
