import {
  IPC_MESSAGE_TYPES,
  IPC_PROTOCOL_VERSION,
  type IpcEnvelopeV1,
  type IpcMessageType,
} from "../protocol/ipc-envelope.ts";
import {
  PROCESS_ROLES,
  type ProcessRole,
} from "../protocol/process-role.ts";

const NODE_IPC_WIRE_TAG = 0x414c_4c31;
const NODE_IPC_WIRE_FIELDS = 13;
const decodedWireEnvelopes = new WeakSet<object>();

const messageTypeCodes = new Map<IpcMessageType, number>(
  IPC_MESSAGE_TYPES.map((messageType, index) => [messageType, index]),
);
const processRoleCodes = new Map<ProcessRole, number>(
  PROCESS_ROLES.map((role, index) => [role, index]),
);

function isEnvelopeCandidate(value: unknown): value is IpcEnvelopeV1 {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const envelope = value as Partial<IpcEnvelopeV1>;
  return envelope.protocolVersion === IPC_PROTOCOL_VERSION &&
    messageTypeCodes.has(envelope.messageType as IpcMessageType) &&
    processRoleCodes.has(envelope.sourceRole as ProcessRole) &&
    processRoleCodes.has(envelope.targetRole as ProcessRole);
}

export function encodeNodeIpcWireMessage(message: unknown): unknown {
  if (!isEnvelopeCandidate(message)) {
    return message;
  }
  return [
    NODE_IPC_WIRE_TAG,
    message.messageId,
    messageTypeCodes.get(message.messageType),
    processRoleCodes.get(message.sourceRole),
    message.sourceWorkerId,
    message.sourceGeneration,
    processRoleCodes.get(message.targetRole),
    message.targetWorkerId,
    message.correlationId,
    message.sessionId,
    message.sequence,
    message.flags,
    message.payload,
  ];
}

export function decodeNodeIpcWireMessage(message: unknown): unknown {
  if (
    !Array.isArray(message) ||
    message.length !== NODE_IPC_WIRE_FIELDS ||
    message[0] !== NODE_IPC_WIRE_TAG
  ) {
    return message;
  }
  const messageType = IPC_MESSAGE_TYPES[message[2] as number];
  const sourceRole = PROCESS_ROLES[message[3] as number];
  const targetRole = PROCESS_ROLES[message[6] as number];
  const envelope = {
    protocolVersion: IPC_PROTOCOL_VERSION,
    messageId: message[1],
    messageType,
    sourceRole,
    sourceWorkerId: message[4],
    sourceGeneration: message[5],
    targetRole,
    targetWorkerId: message[7],
    correlationId: message[8],
    sessionId: message[9],
    sequence: message[10],
    flags: message[11],
    payload: message[12],
  };
  decodedWireEnvelopes.add(envelope);
  return envelope;
}

export function isDecodedNodeIpcWireEnvelope(value: unknown): boolean {
  return typeof value === "object" &&
    value !== null &&
    decodedWireEnvelopes.has(value);
}
