import { FrameworkError, FRAMEWORK_ERROR_CODE } from "../errors/framework-error.ts";
import { isProcessRole, PROCESS_ROLE, type ProcessRole } from "./process-role.ts";
import { isSessionId, type SessionId } from "./session-id.ts";
import {
  createWorkerGeneration,
  createWorkerId,
  type WorkerGeneration,
  type WorkerId,
} from "./worker-id.ts";

declare const messageIdBrand: unique symbol;
declare const correlationIdBrand: unique symbol;
declare const ipcSequenceBrand: unique symbol;

export type MessageId = string & { readonly [messageIdBrand]: "MessageId" };
export type CorrelationId = string & { readonly [correlationIdBrand]: "CorrelationId" };
export type IpcSequence = number & { readonly [ipcSequenceBrand]: "IpcSequence" };

export const IPC_PROTOCOL_VERSION = 1 as const;

export const IPC_MESSAGE_TYPES = Object.freeze([
  "CONTROL_BOOTSTRAP",
  "CONTROL_READY",
  "CONTROL_DRAIN",
  "CONTROL_SHUTDOWN",
  "CONTROL_HEARTBEAT",
  "CONTROL_CAPACITY",
  "NET_CONNECT",
  "NET_MESSAGE",
  "NET_CLOSE",
  "NET_SEND",
  "NET_CLOSE_COMMAND",
  "NET_BUFFER_STATE",
  "PROCESS_MESSAGE",
  "TASK_DISPATCH",
  "TASK_FINISH",
] as const);

export type IpcMessageType = (typeof IPC_MESSAGE_TYPES)[number];

export const IPC_MESSAGE_TYPE = Object.freeze(
  Object.fromEntries(IPC_MESSAGE_TYPES.map((type) => [type, type])) as {
    readonly [Type in IpcMessageType]: Type;
  },
);

export type IpcScalar = null | boolean | number | string;
export type IpcJsonValue =
  | IpcScalar
  | readonly IpcJsonValue[]
  | { readonly [key: string]: IpcJsonValue };
export type IpcPayload = IpcJsonValue | Uint8Array;

export interface IpcEnvelopeV1 {
  readonly protocolVersion: typeof IPC_PROTOCOL_VERSION;
  readonly messageId: MessageId;
  readonly messageType: IpcMessageType;
  readonly sourceRole: ProcessRole;
  readonly sourceWorkerId: WorkerId | null;
  readonly sourceGeneration: WorkerGeneration | null;
  readonly targetRole: ProcessRole;
  readonly targetWorkerId: WorkerId | null;
  readonly correlationId: CorrelationId | null;
  readonly sessionId: SessionId | null;
  readonly sequence: IpcSequence;
  readonly flags: number;
  readonly payload: IpcPayload;
}

export interface IpcEnvelopeValidationOptions {
  readonly maxPayloadBytes?: number;
}

export interface IpcEnvelopeValidationIssue {
  readonly field: keyof IpcEnvelopeV1 | "envelope";
  readonly message: string;
}

export function createMessageId(value: string): MessageId {
  if (value.length === 0 || value.length > 128) {
    throw new RangeError("messageId must contain 1 to 128 characters");
  }
  return value as MessageId;
}

export function createCorrelationId(value: string): CorrelationId {
  if (value.length === 0 || value.length > 128) {
    throw new RangeError("correlationId must contain 1 to 128 characters");
  }
  return value as CorrelationId;
}

export function createIpcSequence(value: number): IpcSequence {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`sequence must be a non-negative safe integer, got ${value}`);
  }
  return value as IpcSequence;
}

function isPlainObject(value: object): value is Record<string, unknown> {
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function isJsonSafe(value: unknown, seen: WeakSet<object>): boolean {
  if (value === null || typeof value === "boolean" || typeof value === "string") {
    return true;
  }
  if (typeof value === "number") {
    return Number.isFinite(value);
  }
  if (typeof value !== "object" || value instanceof Uint8Array) {
    return false;
  }
  if (seen.has(value)) {
    return false;
  }
  seen.add(value);

  let valid: boolean;
  if (Array.isArray(value)) {
    valid = value.every((item) => isJsonSafe(item, seen));
  } else if (isPlainObject(value)) {
    valid = Object.values(value).every((item) => isJsonSafe(item, seen));
  } else {
    valid = false;
  }

  seen.delete(value);
  return valid;
}

function validatePayload(value: unknown): { readonly valid: boolean; readonly bytes: number } {
  if (value instanceof Uint8Array) {
    return { valid: true, bytes: value.byteLength };
  }
  if (!isJsonSafe(value, new WeakSet<object>())) {
    return { valid: false, bytes: 0 };
  }

  const serialized = JSON.stringify(value);
  return {
    valid: typeof serialized === "string",
    bytes: typeof serialized === "string" ? new TextEncoder().encode(serialized).byteLength : 0,
  };
}
function isSourceAddress(role: ProcessRole, workerId: unknown, generation: unknown): boolean {
  if (role === PROCESS_ROLE.MASTER) {
    return workerId === null && generation === null;
  }
  return (
    typeof workerId === "number" &&
    Number.isSafeInteger(workerId) &&
    workerId >= 0 &&
    typeof generation === "number" &&
    Number.isSafeInteger(generation) &&
    generation >= 0
  );
}

function isTargetAddress(role: ProcessRole, workerId: unknown): boolean {
  if (role === PROCESS_ROLE.MASTER) {
    return workerId === null;
  }
  return typeof workerId === "number" && Number.isSafeInteger(workerId) && workerId >= 0;
}

export function isValidBinaryIpcEnvelope(
  value: unknown,
  options: IpcEnvelopeValidationOptions = {},
): value is IpcEnvelopeV1 & { readonly payload: Uint8Array } {
  if (typeof value !== "object" || value === null || !isPlainObject(value)) {
    return false;
  }
  const envelope = value as Record<string, unknown>;
  const payload = envelope.payload;
  return envelope.protocolVersion === IPC_PROTOCOL_VERSION &&
    typeof envelope.messageId === "string" &&
    envelope.messageId.length > 0 &&
    envelope.messageId.length <= 128 &&
    IPC_MESSAGE_TYPES.includes(envelope.messageType as IpcMessageType) &&
    isProcessRole(envelope.sourceRole) &&
    isSourceAddress(
      envelope.sourceRole,
      envelope.sourceWorkerId,
      envelope.sourceGeneration,
    ) &&
    isProcessRole(envelope.targetRole) &&
    isTargetAddress(envelope.targetRole, envelope.targetWorkerId) &&
    (envelope.correlationId === null ||
      (typeof envelope.correlationId === "string" &&
        envelope.correlationId.length > 0 &&
        envelope.correlationId.length <= 128)) &&
    (envelope.sessionId === null || isSessionId(envelope.sessionId)) &&
    Number.isSafeInteger(envelope.sequence) &&
    (envelope.sequence as number) >= 0 &&
    Number.isInteger(envelope.flags) &&
    (envelope.flags as number) >= 0 &&
    (envelope.flags as number) <= 0xffff_ffff &&
    payload instanceof Uint8Array &&
    (options.maxPayloadBytes === undefined ||
      payload.byteLength <= options.maxPayloadBytes);
}

export function validateIpcEnvelope(
  value: unknown,
  options: IpcEnvelopeValidationOptions = {},
): readonly IpcEnvelopeValidationIssue[] {
  if (isValidBinaryIpcEnvelope(value, options)) {
    return [];
  }
  const issues: IpcEnvelopeValidationIssue[] = [];
  if (typeof value !== "object" || value === null || !isPlainObject(value)) {
    return [{ field: "envelope", message: "envelope must be a plain object" }];
  }

  const envelope = value as Record<string, unknown>;
  if (envelope.protocolVersion !== IPC_PROTOCOL_VERSION) {
    issues.push({ field: "protocolVersion", message: "unsupported protocol version" });
  }
  if (
    typeof envelope.messageId !== "string" ||
    envelope.messageId.length === 0 ||
    envelope.messageId.length > 128
  ) {
    issues.push({ field: "messageId", message: "messageId must contain 1 to 128 characters" });
  }
  if (!IPC_MESSAGE_TYPES.includes(envelope.messageType as IpcMessageType)) {
    issues.push({ field: "messageType", message: "unknown messageType" });
  }
  if (!isProcessRole(envelope.sourceRole)) {
    issues.push({ field: "sourceRole", message: "unknown sourceRole" });
  } else if (
    !isSourceAddress(envelope.sourceRole, envelope.sourceWorkerId, envelope.sourceGeneration)
  ) {
    issues.push({ field: "sourceWorkerId", message: "source address does not match sourceRole" });
  }
  if (!isProcessRole(envelope.targetRole)) {
    issues.push({ field: "targetRole", message: "unknown targetRole" });
  } else if (!isTargetAddress(envelope.targetRole, envelope.targetWorkerId)) {
    issues.push({ field: "targetWorkerId", message: "target address does not match targetRole" });
  }
  if (
    envelope.correlationId !== null &&
    (typeof envelope.correlationId !== "string" ||
      envelope.correlationId.length === 0 ||
      envelope.correlationId.length > 128)
  ) {
    issues.push({
      field: "correlationId",
      message: "correlationId must be null or contain 1 to 128 characters",
    });
  }
  if (envelope.sessionId !== null && !isSessionId(envelope.sessionId)) {
    issues.push({ field: "sessionId", message: "sessionId must be a valid SessionId or null" });
  }
  if (!Number.isSafeInteger(envelope.sequence) || (envelope.sequence as number) < 0) {
    issues.push({ field: "sequence", message: "sequence must be a non-negative safe integer" });
  }
  if (
    !Number.isInteger(envelope.flags) ||
    (envelope.flags as number) < 0 ||
    (envelope.flags as number) > 0xffff_ffff
  ) {
    issues.push({ field: "flags", message: "flags must be an unsigned 32-bit integer" });
  }

  const payload = validatePayload(envelope.payload);
  if (!payload.valid) {
    issues.push({ field: "payload", message: "payload must be binary or JSON-safe plain data" });
  } else if (
    options.maxPayloadBytes !== undefined &&
    payload.bytes > options.maxPayloadBytes
  ) {
    issues.push({
      field: "payload",
      message: `payload size ${payload.bytes} exceeds ${options.maxPayloadBytes} bytes`,
    });
  }

  return issues;
}

export function createIpcEnvelope(envelope: IpcEnvelopeV1): Readonly<IpcEnvelopeV1> {
  const issues = validateIpcEnvelope(envelope);
  if (issues.length > 0) {
    throw new TypeError(`invalid IPC envelope: ${issues.map((issue) => issue.message).join("; ")}`);
  }
  return Object.freeze({ ...envelope });
}

export function assertEnvelopeSourceGeneration(
  envelope: IpcEnvelopeV1,
  currentGeneration: WorkerGeneration,
): void {
  if (envelope.sourceRole === PROCESS_ROLE.MASTER) {
    return;
  }
  if (
    envelope.sourceGeneration === null ||
    envelope.sourceGeneration !== currentGeneration
  ) {
    throw new FrameworkError(
      FRAMEWORK_ERROR_CODE.STALE_GENERATION,
      "IPC envelope was produced by a stale process generation",
      {
        sourceWorkerId: envelope.sourceWorkerId,
        sourceGeneration: envelope.sourceGeneration,
        currentGeneration,
      },
    );
  }
}

export function coerceWorkerAddressForTest(workerId: number, generation: number): {
  readonly workerId: WorkerId;
  readonly generation: WorkerGeneration;
} {
  return {
    workerId: createWorkerId(workerId),
    generation: createWorkerGeneration(generation),
  };
}
