import type { IpcJsonValue } from "../protocol/ipc-envelope.ts";
import type { RuntimeProtocol } from "../runtime/runtime-server.ts";
import { FRAMEWORK_ERROR_CODE, FrameworkError } from "../errors/framework-error.ts";
import {
  DEFAULT_WEB_SOCKET_MAX_MESSAGE_BYTES,
  WEB_SOCKET_OPCODE,
  encodeWebSocketCloseFrame,
} from "../network/websocket-protocol.ts";

export const NETWORK_COMMAND_PROTOCOL_VERSION = 1 as const;
export const NETWORK_SEND_HEADER_BYTES = 3;

export const NETWORK_SEND_KIND = Object.freeze({
  TCP: 0,
  WEBSOCKET: 1,
} as const);

export type NetworkCommandWebSocketOpcode =
  | typeof WEB_SOCKET_OPCODE.TEXT
  | typeof WEB_SOCKET_OPCODE.BINARY
  | typeof WEB_SOCKET_OPCODE.CLOSE
  | typeof WEB_SOCKET_OPCODE.PING
  | typeof WEB_SOCKET_OPCODE.PONG;

export type NetworkSendOpcode = 0 | NetworkCommandWebSocketOpcode;

export interface NetworkSendCommandPayload {
  readonly protocolVersion: typeof NETWORK_COMMAND_PROTOCOL_VERSION;
  readonly protocol: RuntimeProtocol;
  readonly opcode: NetworkSendOpcode;
  readonly data: Readonly<Buffer>;
}

export interface EncodeNetworkSendCommandPayloadOptions {
  readonly protocol: RuntimeProtocol;
  readonly data: Uint8Array | string;
  readonly opcode?: number;
}

export interface NetworkCloseCommandPayload {
  readonly protocolVersion: typeof NETWORK_COMMAND_PROTOCOL_VERSION;
  readonly code: number;
  readonly reason: string;
}

type IpcJsonObject = Readonly<Record<string, IpcJsonValue>>;

const CLOSE_COMMAND_KEYS = Object.freeze(["protocolVersion", "code", "reason"] as const);
const strictTextDecoder = new TextDecoder("utf-8", { fatal: true });

function isAllowedWebSocketOpcode(
  opcode: number,
): opcode is NetworkCommandWebSocketOpcode {
  return opcode === WEB_SOCKET_OPCODE.TEXT ||
    opcode === WEB_SOCKET_OPCODE.BINARY ||
    opcode === WEB_SOCKET_OPCODE.CLOSE ||
    opcode === WEB_SOCKET_OPCODE.PING ||
    opcode === WEB_SOCKET_OPCODE.PONG;
}

function encodeData(data: Uint8Array | string): Buffer {
  return typeof data === "string"
    ? Buffer.from(data, "utf8")
    : Buffer.from(data.buffer, data.byteOffset, data.byteLength);
}

function assertPayloadLimit(name: string, actual: number, maximum: number): void {
  if (actual <= maximum) {
    return;
  }
  throw new FrameworkError(
    FRAMEWORK_ERROR_CODE.MESSAGE_TOO_LARGE,
    `${name} payload size ${actual} exceeds ${maximum} bytes`,
    { byteLength: actual, maxPayloadBytes: maximum },
  );
}

function validateWebSocketData(
  opcode: NetworkCommandWebSocketOpcode,
  data: Buffer,
): void {
  assertPayloadLimit(
    "WebSocket NET_SEND",
    data.byteLength,
    DEFAULT_WEB_SOCKET_MAX_MESSAGE_BYTES,
  );
  if (opcode === WEB_SOCKET_OPCODE.PING || opcode === WEB_SOCKET_OPCODE.PONG) {
    assertPayloadLimit("WebSocket control", data.byteLength, 125);
  }
  if (opcode === WEB_SOCKET_OPCODE.CLOSE) {
    assertPayloadLimit("WebSocket close reason", data.byteLength, 123);
  }
  if (opcode === WEB_SOCKET_OPCODE.TEXT || opcode === WEB_SOCKET_OPCODE.CLOSE) {
    strictTextDecoder.decode(data);
  }
}

function validateTcpData(data: Buffer): void {
  if (data.byteLength === 0) {
    throw new TypeError("TCP NET_SEND data must not be empty");
  }
}

function requireSendOpcode(kind: RuntimeProtocol, opcode: number | undefined): NetworkSendOpcode {
  if (kind === "tcp") {
    if (opcode !== undefined && opcode !== 0) {
      throw new TypeError("TCP NET_SEND opcode must be zero");
    }
    return 0;
  }

  const resolved = opcode ?? WEB_SOCKET_OPCODE.TEXT;
  if (!isAllowedWebSocketOpcode(resolved)) {
    throw new TypeError(
      "WebSocket NET_SEND opcode must be TEXT, BINARY, CLOSE, PING, or PONG",
    );
  }
  return resolved;
}

function decodeKind(value: number): RuntimeProtocol {
  if (value === NETWORK_SEND_KIND.TCP) {
    return "tcp";
  }
  if (value === NETWORK_SEND_KIND.WEBSOCKET) {
    return "websocket";
  }
  throw new TypeError("NET_SEND payload contains an unknown kind");
}

export function encodeNetworkSendCommandPayload(
  options: EncodeNetworkSendCommandPayloadOptions,
): Buffer {
  if (options.protocol !== "tcp" && options.protocol !== "websocket") {
    throw new TypeError("NET_SEND protocol must be tcp or websocket");
  }
  if (typeof options.data !== "string" && !(options.data instanceof Uint8Array)) {
    throw new TypeError("NET_SEND data must be a string or Uint8Array");
  }

  const opcode = requireSendOpcode(options.protocol, options.opcode);
  const data = encodeData(options.data);
  if (options.protocol === "websocket") {
    validateWebSocketData(opcode as NetworkCommandWebSocketOpcode, data);
  } else {
    validateTcpData(data);
  }
  const payload = Buffer.allocUnsafe(NETWORK_SEND_HEADER_BYTES + data.byteLength);
  payload[0] = NETWORK_COMMAND_PROTOCOL_VERSION;
  payload[1] = options.protocol === "tcp"
    ? NETWORK_SEND_KIND.TCP
    : NETWORK_SEND_KIND.WEBSOCKET;
  payload[2] = opcode;
  payload.set(data, NETWORK_SEND_HEADER_BYTES);
  return payload;
}

export function decodeNetworkSendCommandPayload(
  value: unknown,
): Readonly<NetworkSendCommandPayload> {
  if (!(value instanceof Uint8Array) || value.byteLength < NETWORK_SEND_HEADER_BYTES) {
    throw new TypeError("NET_SEND payload must contain a complete binary header");
  }

  const payload = Buffer.from(value.buffer, value.byteOffset, value.byteLength);
  if (payload[0] !== NETWORK_COMMAND_PROTOCOL_VERSION) {
    throw new TypeError("NET_SEND payload has an unsupported version");
  }

  const protocol = decodeKind(payload[1]!);
  const opcode = requireSendOpcode(protocol, payload[2]);
  const data = Buffer.from(payload.subarray(NETWORK_SEND_HEADER_BYTES));
  if (protocol === "websocket") {
    validateWebSocketData(opcode as NetworkCommandWebSocketOpcode, data);
  } else {
    validateTcpData(data);
  }
  return Object.freeze({
    protocolVersion: NETWORK_COMMAND_PROTOCOL_VERSION,
    protocol,
    opcode,
    data,
  });
}

export type NetworkSendPayload = NetworkSendCommandPayload;
export type EncodeNetworkSendPayloadOptions = EncodeNetworkSendCommandPayloadOptions;
export const encodeNetworkSendPayload = encodeNetworkSendCommandPayload;
export const decodeNetworkSendPayload = decodeNetworkSendCommandPayload;

function requireExactDataRecord(
  value: unknown,
  keys: readonly string[],
  name: string,
): Readonly<Record<string, unknown>> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError(`${name} must be a plain object`);
  }

  let prototype: object | null;
  let ownKeys: readonly PropertyKey[];
  try {
    prototype = Object.getPrototypeOf(value);
    ownKeys = Reflect.ownKeys(value);
  } catch {
    throw new TypeError(`${name} must be an inspectable plain object`);
  }
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError(`${name} must be a plain object`);
  }
  if (
    ownKeys.length !== keys.length ||
    ownKeys.some((key) => typeof key !== "string" || !keys.includes(key))
  ) {
    throw new TypeError(`${name} must contain exactly: ${keys.join(", ")}`);
  }

  const snapshot: Record<string, unknown> = {};
  for (const key of keys) {
    let descriptor: PropertyDescriptor | undefined;
    try {
      descriptor = Object.getOwnPropertyDescriptor(value, key);
    } catch {
      throw new TypeError(`${name}.${key} must be an inspectable data field`);
    }
    if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
      throw new TypeError(`${name}.${key} must be an enumerable data field`);
    }
    snapshot[key] = descriptor.value;
  }
  return snapshot;
}

export function encodeNetworkCloseCommandPayload(
  code = 1000,
  reason = "",
): Readonly<NetworkCloseCommandPayload> &
  IpcJsonObject {
  encodeWebSocketCloseFrame(code, reason);
  return Object.freeze({
    protocolVersion: NETWORK_COMMAND_PROTOCOL_VERSION,
    code,
    reason,
  });
}

export function decodeNetworkCloseCommandPayload(
  value: unknown,
): Readonly<NetworkCloseCommandPayload> {
  const record = requireExactDataRecord(
    value,
    CLOSE_COMMAND_KEYS,
    "NET_CLOSE_COMMAND payload",
  );
  if (record.protocolVersion !== NETWORK_COMMAND_PROTOCOL_VERSION) {
    throw new TypeError("NET_CLOSE_COMMAND payload has an unsupported version");
  }
  if (typeof record.code !== "number" || typeof record.reason !== "string") {
    throw new TypeError("NET_CLOSE_COMMAND code and reason are invalid");
  }
  return encodeNetworkCloseCommandPayload(record.code, record.reason);
}
