export const PROCESS_ROLES = Object.freeze([
  "MASTER",
  "WORKER",
  "TASK_WORKER",
  "USER_TASK_WORKER",
] as const);

export type ProcessRole = (typeof PROCESS_ROLES)[number];

export const PROCESS_ROLE = Object.freeze({
  MASTER: "MASTER",
  WORKER: "WORKER",
  TASK_WORKER: "TASK_WORKER",
  USER_TASK_WORKER: "USER_TASK_WORKER",
} as const satisfies Record<ProcessRole, ProcessRole>);

export function isProcessRole(value: unknown): value is ProcessRole {
  return typeof value === "string" && PROCESS_ROLES.includes(value as ProcessRole);
}
