import { AsyncLocalStorage } from "node:async_hooks";
import { resolve } from "node:path";

import { loadRuntimeSettings } from "../config/runtime-settings.ts";
import { rustTcpDataPlaneEnabled } from "../network/rust-data-plane-path.ts";
import {
  FRAMEWORK_ERROR_CODE,
  FrameworkError,
  type FrameworkErrorCode,
} from "../errors/framework-error.ts";
import {
  createDefaultNetworkServer,
  MasterRuntime,
} from "../lifecycle/master-runtime.ts";
import { hasActiveParentProcessChannel } from "../process/node-parent-process-adapter.ts";
import { ProcessSupervisor } from "../process/process-supervisor.ts";
import { runWorkerEntry } from "../process/worker-entry.ts";
import type { SessionId } from "../protocol/session-id.ts";
import {
  createProcessPid,
  type ProcessPid,
  type TaskWorkerId,
  type WorkerGeneration,
  type WorkerId,
} from "../protocol/worker-id.ts";
import {
  bindWorkerRuntimeCallbacks,
  MasterRuntimeServerFacade,
  normalizeRuntimeCallbacks,
  WorkerRuntimeServerFacade,
} from "./runtime-server-facade.ts";
import type {
  RuntimeCallbacks,
  RuntimeConnectionInfo,
  RuntimeConnectionView,
  RuntimeServerContract,
  RuntimeSettings,
  RuntimeStats,
} from "./runtime-server.ts";
import { EMPTY_RUNTIME_CAPACITY_STATS } from "./runtime-server.ts";
import { createRuntimeStateKey } from "../shared-state/shared-runtime-state.ts";

const RUNTIME_CHILD_ENVIRONMENT_KEY = "TS_SWOOLE_RUNTIME_CHILD";
const RUNTIME_SERVER_SHARED_STATE_IDENTITY = "ts-swoole-runtime-server-endpoint-v1";

const EMPTY_CONNECTIONS: RuntimeConnectionView = Object.freeze({
  size: 0,
  *[Symbol.iterator](): IterableIterator<SessionId> {},
});

interface Deferred {
  readonly promise: Promise<void>;
  readonly resolve: () => void;
  readonly reject: (reason?: unknown) => void;
}

function createDeferred(): Deferred {
  let resolve!: () => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<void>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function defaultEntrypoint(): string {
  const entrypoint = process.argv[1];
  if (entrypoint === undefined || entrypoint.length === 0) {
    throw new FrameworkError(
      FRAMEWORK_ERROR_CODE.INVALID_STATE,
      "RuntimeServer requires an explicit entrypoint outside a main module",
    );
  }
  return resolve(entrypoint);
}

function normalizeEntrypoint(entrypoint: URL | string): URL | string {
  return typeof entrypoint === "string" && entrypoint.startsWith("file:")
    ? new URL(entrypoint)
    : entrypoint;
}

export function createRuntimeServerStateKey(
  settings: Readonly<RuntimeSettings>,
  _entrypoint: URL | string,
): string | undefined {
  return settings.port === 0
    ? undefined
    : createRuntimeStateKey(settings, RUNTIME_SERVER_SHARED_STATE_IDENTITY);
}

function isRuntimeChild(): boolean {
  return process.env[RUNTIME_CHILD_ENVIRONMENT_KEY] === "1";
}

export interface RuntimeServerOptions {
  readonly settings: unknown;
  readonly callbacks?: RuntimeCallbacks;
  readonly entrypoint?: URL | string;
  readonly reservedTaskWorkerIds?: Iterable<TaskWorkerId>;
  readonly parentSignal?: AbortSignal;
  readonly readyTimeoutMs?: number;
  readonly gracefulShutdownTimeoutMs?: number;
  readonly terminateTimeoutMs?: number;
}

export class RuntimeServer implements RuntimeServerContract, AsyncDisposable {
  readonly stopped: Promise<void>;

  readonly #settings: Readonly<RuntimeSettings>;
  readonly #callbacks: Readonly<RuntimeCallbacks>;
  readonly #entrypoint: URL | string | undefined;
  readonly #reservedTaskWorkerIds: readonly TaskWorkerId[] | undefined;
  readonly #parentSignal: AbortSignal | undefined;
  readonly #readyTimeoutMs: number | undefined;
  readonly #gracefulShutdownTimeoutMs: number | undefined;
  readonly #terminateTimeoutMs: number | undefined;
  readonly #runtimeChild: boolean;
  readonly #initialMasterPid: ProcessPid;
  readonly #stopped = createDeferred();
  readonly #detachedErrorCounts = new Map<FrameworkErrorCode, number>();
  readonly #activeCallback = new AsyncLocalStorage<keyof RuntimeCallbacks>();
  #facade: RuntimeServerContract | null = null;
  #runtime: MasterRuntime | null = null;
  #startPromise: Promise<this> | null = null;
  #disposePromise: Promise<void> | null = null;
  #detachedLastError: FrameworkErrorCode | null = null;
  #terminal = false;

  constructor(options: RuntimeServerOptions) {
    if (typeof options !== "object" || options === null) {
      throw new TypeError("RuntimeServer options must be an object");
    }
    this.#settings = loadRuntimeSettings(options.settings);
    this.#callbacks = normalizeRuntimeCallbacks(options.callbacks);
    this.#entrypoint = options.entrypoint === undefined
      ? undefined
      : normalizeEntrypoint(options.entrypoint);
    this.#reservedTaskWorkerIds = options.reservedTaskWorkerIds === undefined
      ? undefined
      : Object.freeze([...options.reservedTaskWorkerIds]);
    this.#parentSignal = options.parentSignal;
    this.#readyTimeoutMs = options.readyTimeoutMs;
    this.#gracefulShutdownTimeoutMs = options.gracefulShutdownTimeoutMs;
    this.#terminateTimeoutMs = options.terminateTimeoutMs;
    this.#runtimeChild = isRuntimeChild();
    this.#initialMasterPid = createProcessPid(
      this.#runtimeChild ? process.ppid : process.pid,
    );
    this.stopped = this.#stopped.promise;
    void this.stopped.catch(() => undefined);
  }

  get worker_id(): WorkerId | null {
    return this.#facade?.worker_id ?? null;
  }

  get worker_pid(): ProcessPid | null {
    return this.#facade?.worker_pid ?? null;
  }

  get taskworker(): boolean {
    return this.#facade?.taskworker ?? false;
  }

  get setting(): Readonly<RuntimeSettings> {
    return this.#facade?.setting ?? this.#settings;
  }

  get master_pid(): ProcessPid {
    return this.#facade?.master_pid ?? this.#initialMasterPid;
  }

  get generation(): WorkerGeneration | null {
    return this.#facade?.generation ?? null;
  }

  get connections(): RuntimeConnectionView {
    return this.#facade?.connections ?? EMPTY_CONNECTIONS;
  }

  start(): Promise<this> {
    const activeCallback = this.#activeCallback.getStore();
    if (activeCallback !== undefined) {
      return Promise.reject(new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        `RuntimeServer cannot start from ${activeCallback}`,
      ));
    }
    if (this.#terminal || this.#disposePromise !== null) {
      return Promise.reject(new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        "RuntimeServer cannot start after stopping or disposal",
      ));
    }
    if (this.#startPromise !== null) {
      return this.#startPromise;
    }
    this.#startPromise = this.#runtimeChild
      ? this.#startWorker()
      : this.#startMaster();
    return this.#startPromise;
  }

  task(data: unknown, taskWorkerId?: TaskWorkerId): number | false {
    return this.#delegate((facade) => taskWorkerId === undefined
      ? facade.task(data)
      : facade.task(data, taskWorkerId));
  }

  finish(data: unknown): boolean {
    return this.#delegate((facade) => facade.finish(data));
  }

  sendMessage(message: unknown, targetWorkerId: WorkerId): boolean {
    return this.#delegate((facade) => facade.sendMessage(message, targetWorkerId));
  }

  requestMessage(
    message: unknown,
    targetWorkerId: WorkerId,
    timeoutMs?: number,
  ): Promise<unknown> {
    const facade = this.#facade;
    if (facade === null) {
      return Promise.reject(new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        "RuntimeServer is not started",
      ));
    }
    return facade.requestMessage(message, targetWorkerId, timeoutMs);
  }

  push(fd: SessionId, data: Uint8Array | string, opcode?: number): boolean {
    return this.#delegate((facade) => opcode === undefined
      ? facade.push(fd, data)
      : facade.push(fd, data, opcode));
  }

  send(fd: SessionId, data: Uint8Array | string): boolean {
    return this.#delegate((facade) => facade.send(fd, data));
  }

  close(fd: SessionId, code?: number, reason?: string): boolean {
    return this.#delegate((facade) => facade.close(fd, code, reason));
  }

  exist(fd: SessionId): boolean {
    return this.#delegate((facade) => facade.exist(fd));
  }

  connection_info(fd: SessionId): Readonly<RuntimeConnectionInfo> | false {
    return this.#delegate((facade) => facade.connection_info(fd));
  }

  connection_owner(fd: SessionId): WorkerId | false {
    return this.#delegate((facade) => facade.connection_owner(fd));
  }

  workers() {
    return this.#facade?.workers() ?? Object.freeze([]);
  }

  addStat(metricId: number, delta?: number): number | false {
    return this.#delegate((facade) =>
      delta === undefined ? facade.addStat(metricId) : facade.addStat(metricId, delta)
    );
  }

  snapshotStats(): readonly number[] {
    return this.#facade?.snapshotStats() ?? Object.freeze([]);
  }

  atomicGet(atomicId: number): number | false {
    return this.#delegate((facade) => facade.atomicGet(atomicId));
  }

  atomicAdd(atomicId: number, delta: number): number | false {
    return this.#delegate((facade) => facade.atomicAdd(atomicId, delta));
  }

  atomicSet(atomicId: number, value: number): number | false {
    return this.#delegate((facade) => facade.atomicSet(atomicId, value));
  }

  atomicCompareSet(atomicId: number, expected: number, value: number): boolean {
    return this.#delegate((facade) => facade.atomicCompareSet(atomicId, expected, value));
  }

  lockTry(lockId: number, ownerToken?: number): boolean {
    return this.#delegate((facade) =>
      ownerToken === undefined ? facade.lockTry(lockId) : facade.lockTry(lockId, ownerToken)
    );
  }

  lockAcquire(lockId: number, ownerToken?: number, timeoutMs?: number): Promise<boolean> {
    const facade = this.#facade;
    if (facade === null) return Promise.resolve(false);
    return facade.lockAcquire(lockId, ownerToken, timeoutMs);
  }

  lockRelease(lockId: number, ownerToken?: number): boolean {
    return this.#delegate((facade) =>
      ownerToken === undefined ? facade.lockRelease(lockId) : facade.lockRelease(lockId, ownerToken)
    );
  }

  stop(workerId?: WorkerId): boolean {
    return this.#delegate((facade) =>
      workerId === undefined ? facade.stop() : facade.stop(workerId)
    );
  }

  reload(onlyTaskWorker?: boolean): boolean {
    return this.#delegate((facade) => onlyTaskWorker === undefined
      ? facade.reload()
      : facade.reload(onlyTaskWorker));
  }

  shutdown(): boolean {
    return this.#delegate((facade) => facade.shutdown());
  }

  stats(): Readonly<RuntimeStats> {
    const base = this.#facade?.stats() ?? Object.freeze({
      connections: 0,
      workers: 0,
      taskWorkers: 0,
      invalidSessions: 0,
      staleGenerations: 0,
      capacity: EMPTY_RUNTIME_CAPACITY_STATS,
      errors: Object.freeze({}),
    });
    if (this.#detachedErrorCounts.size === 0) {
      return base;
    }
    const errors = new Map<FrameworkErrorCode, number>();
    for (const [code, count] of Object.entries(base.errors)) {
      if (count !== undefined) {
        errors.set(code as FrameworkErrorCode, count);
      }
    }
    for (const [code, count] of this.#detachedErrorCounts) {
      errors.set(code, (errors.get(code) ?? 0) + count);
    }
    return Object.freeze({
      ...base,
      errors: Object.freeze(
        Object.fromEntries(errors) as Partial<Record<FrameworkErrorCode, number>>,
      ),
    });
  }

  getLastError(): FrameworkErrorCode | null {
    return this.#detachedLastError;
  }

  dispose(reason?: unknown): Promise<void> {
    const activeCallback = this.#runtimeChild
      ? this.#activeCallback.getStore()
      : undefined;
    if (activeCallback !== undefined) {
      return Promise.reject(new FrameworkError(
        FRAMEWORK_ERROR_CODE.INVALID_STATE,
        `Worker RuntimeServer cannot dispose from ${activeCallback}`,
      ));
    }
    if (!this.#runtimeChild && this.#runtime !== null) {
      const currentJoin = this.#runtime.stop(reason);
      this.#disposePromise ??= this.#runtime.stopped;
      return currentJoin;
    }
    if (this.#disposePromise !== null) {
      return this.#disposePromise;
    }
    if (this.#runtimeChild) {
      if (this.#startPromise === null) {
        this.#disposePromise = Promise.resolve();
        this.#resolveStopped();
        return this.#disposePromise;
      }
      this.#disposePromise = this.stopped;
      return this.#disposePromise;
    }
    this.#disposePromise = Promise.resolve();
    this.#resolveStopped();
    return this.#disposePromise;
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await this.dispose("RuntimeServer async disposal");
  }

  async #startMaster(): Promise<this> {
    try {
      const entrypoint = this.#entrypoint ?? defaultEntrypoint();
      const runtimeKey = createRuntimeServerStateKey(this.#settings, entrypoint);
      let facade!: MasterRuntimeServerFacade;
      const runtime = new MasterRuntime({
        settings: this.#settings,
        ...(runtimeKey === undefined ? {} : { runtimeKey }),
        ...(this.#parentSignal === undefined
          ? {}
          : { parentSignal: this.#parentSignal }),
        hooks: {
          onManagerStart: () => this.#invokeCallback(
            "onManagerStart",
            () => this.#callbacks.onManagerStart?.(this),
          ),
          onStart: () => this.#invokeCallback(
            "onStart",
            () => this.#callbacks.onStart?.(this),
          ),
          onManagerStop: () => this.#invokeCallback(
            "onManagerStop",
            () => this.#callbacks.onManagerStop?.(this),
          ),
          onShutdown: () => this.#invokeCallback(
            "onShutdown",
            () => this.#callbacks.onShutdown?.(this),
          ),
        },
        processSupervisorFactory: (context, sharedState) => {
          const supervisor = new ProcessSupervisor({
            context,
            compactIpcEnvelopes: true,
            sharedRuntime: sharedState.descriptor,
            sharedWorkers: sharedState,
            entrypoint,
            ...(this.#readyTimeoutMs === undefined ? {} : { readyTimeoutMs: this.#readyTimeoutMs }),
            ...(this.#gracefulShutdownTimeoutMs === undefined
              ? {}
              : { gracefulShutdownTimeoutMs: this.#gracefulShutdownTimeoutMs }),
            ...(this.#terminateTimeoutMs === undefined
              ? {}
              : { terminateTimeoutMs: this.#terminateTimeoutMs }),
            childEnvironment: {
              [RUNTIME_CHILD_ENVIRONMENT_KEY]: "1",
              ...(rustTcpDataPlaneEnabled(context.settings.protocol)
                ? { ALLOY_CORE_RUST_DATA_PLANE: "1" }
                : {}),
            },
            ...(this.#reservedTaskWorkerIds === undefined
              ? {}
              : { reservedTaskWorkerIds: this.#reservedTaskWorkerIds }),
            onWorkerError: (workerId, workerPid, exitCode, signal) =>
              this.#invokeCallback("onWorkerError", async () => {
                sharedState.clearLocks?.(workerPid);
                await this.#callbacks.onWorkerError?.(
                  this,
                  workerId,
                  workerPid,
                  exitCode,
                  signal,
                );
              }),
            onBeforeReload: () => this.#invokeCallback(
              "onBeforeReload",
              () => this.#callbacks.onBeforeReload?.(this),
            ),
          });
          facade.attachSupervisor(supervisor);
          return supervisor;
        },
        networkServerFactory: (context, supervisor, sharedState) => {
          const network = createDefaultNetworkServer(
            context,
            supervisor,
            sharedState,
          );
          facade.attachNetwork(network.network, network.commands);
          return network;
        },
      });
      facade = new MasterRuntimeServerFacade(runtime.context, runtime.sharedState);
      this.#runtime = runtime;
      this.#facade = facade;
      void runtime.stopped.then(
        () => this.#resolveStopped(),
        (error: unknown) => this.#rejectStopped(error),
      );
      await runtime.start();
      return this;
    } catch (error) {
      if (this.#runtime === null) {
        this.#rejectStopped(error);
      }
      throw error;
    }
  }

  async #startWorker(): Promise<this> {
    if (!hasActiveParentProcessChannel()) {
      const error = new FrameworkError(
        FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
        "Runtime child marker requires an active parent IPC channel",
      );
      this.#rejectStopped(error);
      throw error;
    }
    const ready = createDeferred();
    let readyObserved = false;
    const runPromise = runWorkerEntry({
      initialize: async (runtime) => {
        const facade = new WorkerRuntimeServerFacade({
          context: runtime.context,
          bus: runtime.bus,
          networkCommands: runtime.networkCommands,
          tasks: runtime.tasks,
          processMessages: runtime.processMessages,
          lifecycle: runtime.lifecycle,
          sharedState: runtime.sharedState,
        });
        this.#facade = facade;
        const disposeCallbacks = bindWorkerRuntimeCallbacks({
          server: this,
          callbacks: this.#callbacks,
          facade,
          networkEvents: runtime.networkEvents,
          tasks: runtime.tasks,
          processMessages: runtime.processMessages,
          invoke: (name, callback) => this.#invokeCallback(name, callback),
        });
        runtime.context.deferResource(
          "worker.public-runtime-callbacks",
          disposeCallbacks,
        );
        await this.#invokeCallback(
          "onWorkerStart",
          () => this.#callbacks.onWorkerStart?.(this, runtime.context.worker_id),
        );
      },
      onReady: () => {
        readyObserved = true;
        ready.resolve();
      },
      onWorkerStop: async (runtime) => {
        await this.#invokeCallback(
          "onWorkerStop",
          () => this.#callbacks.onWorkerStop?.(this, runtime.context.worker_id),
        );
      },
      onWorkerExit: async (runtime) => {
        await this.#invokeCallback(
          "onWorkerExit",
          () => this.#callbacks.onWorkerExit?.(this, runtime.context.worker_id),
        );
      },
    });
    void runPromise.then(
      () => this.#resolveStopped(),
      (error: unknown) => this.#rejectStopped(error),
    );
    await Promise.race([
      ready.promise,
      runPromise.then(() => {
        if (!readyObserved) {
          throw new FrameworkError(
            FRAMEWORK_ERROR_CODE.INVALID_STATE,
            "Worker RuntimeServer stopped before becoming READY",
          );
        }
      }),
    ]);
    if (readyObserved) {
      return this;
    }
    throw new FrameworkError(
      FRAMEWORK_ERROR_CODE.INVALID_STATE,
      "Worker RuntimeServer stopped before becoming READY",
    );
  }

  #detachedFailure(): false {
    this.#detachedLastError = FRAMEWORK_ERROR_CODE.INVALID_STATE;
    const count = this.#detachedErrorCounts.get(FRAMEWORK_ERROR_CODE.INVALID_STATE) ?? 0;
    this.#detachedErrorCounts.set(FRAMEWORK_ERROR_CODE.INVALID_STATE, count + 1);
    return false;
  }

  #delegate<Result>(operation: (facade: RuntimeServerContract) => Result): Result | false {
    const facade = this.#facade;
    if (facade === null) {
      return this.#detachedFailure();
    }
    const result = operation(facade);
    this.#detachedLastError = facade.getLastError();
    return result;
  }

  #invokeCallback<Result>(
    name: keyof RuntimeCallbacks,
    callback: () => Result | Promise<Result>,
  ): Result | Promise<Result> {
    return this.#activeCallback.run(name, callback);
  }

  #resolveStopped(): void {
    this.#terminal = true;
    this.#stopped.resolve();
  }

  #rejectStopped(error: unknown): void {
    this.#terminal = true;
    this.#stopped.reject(error);
  }
}
