import { AsyncLocalStorage } from "node:async_hooks";

export interface RuntimeResource {
  close(reason?: unknown): void | Promise<void>;
}

export type RuntimeDisposer = (reason?: unknown) => void | Promise<void>;

interface ResourceEntry {
  readonly name: string;
  readonly close: RuntimeDisposer;
}

interface ResourceDisposerInvocation {
  active: boolean;
  readonly joinedClose: Promise<void>;
  readonly scope: ResourceScope;
}

const activeResourceDisposer = new AsyncLocalStorage<ResourceDisposerInvocation>();

type ResourceScopeState = "open" | "closing" | "closed";

function assertResourceName(name: string): void {
  if (name.length === 0) {
    throw new TypeError("resource name must not be empty");
  }
}

function closeFailure(name: string, cause: unknown): Error {
  return new Error(`failed to close runtime resource ${name}`, { cause });
}

export class ResourceScope implements RuntimeResource {
  readonly #entries: ResourceEntry[] = [];
  readonly #onSizeChange: ((size: number) => void) | undefined;
  #state: ResourceScopeState = "open";
  #closePromise: Promise<void> | undefined;

  constructor(onSizeChange?: (size: number) => void) {
    this.#onSizeChange = onSizeChange;
  }

  get size(): number {
    return this.#entries.length;
  }

  get closed(): boolean {
    return this.#state === "closed";
  }

  use<Resource extends RuntimeResource>(name: string, resource: Resource): Resource {
    assertResourceName(name);
    this.#assertOpen();
    this.#entries.push({
      name,
      close: (reason) => resource.close(reason),
    });
    this.#notifyRegistered();
    return resource;
  }

  defer(name: string, disposer: RuntimeDisposer): void {
    assertResourceName(name);
    this.#assertOpen();
    this.#entries.push({ name, close: disposer });
    this.#notifyRegistered();
  }

  close(reason?: unknown): Promise<void> {
    const invocation = activeResourceDisposer.getStore();
    if (invocation?.active === true && invocation.scope === this) {
      return invocation.joinedClose;
    }

    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }

    this.#state = "closing";
    this.#closePromise = Promise.resolve().then(() =>
      this.#closeEntries(reason),
    );
    return this.#closePromise;
  }

  [Symbol.asyncDispose](): Promise<void> {
    return this.close();
  }

  #assertOpen(): void {
    if (this.#state !== "open") {
      throw new Error(`resource scope is ${this.#state}`);
    }
  }

  #notifyRegistered(): void {
    try {
      this.#onSizeChange?.(this.size);
    } catch (error) {
      this.#entries.pop();
      try {
        this.#onSizeChange?.(this.size);
      } catch {
        // The resource remains owned by the caller when registration observation fails.
      }
      throw error;
    }
  }

  #notifyCleanup(failures: Error[]): void {
    try {
      this.#onSizeChange?.(this.size);
    } catch (error) {
      failures.push(closeFailure("ResourceScope.onSizeChange", error));
    }
  }

  async #closeEntries(reason: unknown): Promise<void> {
    const failures: Error[] = [];

    try {
      while (this.#entries.length > 0) {
        const entry = this.#entries.at(-1);
        if (entry === undefined) {
          break;
        }

        const invocation: ResourceDisposerInvocation = {
          active: true,
          joinedClose: Promise.resolve(),
          scope: this,
        };
        try {
          await activeResourceDisposer.run(invocation, () =>
            entry.close(reason),
          );
        } catch (error) {
          failures.push(closeFailure(entry.name, error));
        } finally {
          invocation.active = false;
          this.#entries.pop();
          this.#notifyCleanup(failures);
        }
      }
    } finally {
      if (this.#entries.length > 0) {
        this.#entries.length = 0;
        this.#notifyCleanup(failures);
      }
      this.#state = "closed";
    }

    if (failures.length > 0) {
      throw new AggregateError(failures, "failed to close runtime resources");
    }
  }
}
