import { FrameworkError, FRAMEWORK_ERROR_CODE } from "../errors/framework-error.ts";

export const MASTER_STATES = Object.freeze([
  "CREATED",
  "INITIALIZING",
  "SPAWNING_CHILDREN",
  "WAITING_READY",
  "LISTENING",
  "RUNNING",
  "RELOADING",
  "DRAINING",
  "STOPPING",
  "STOPPED",
] as const);
export type MasterState = (typeof MASTER_STATES)[number];

export const WORKER_STATES = Object.freeze([
  "SPAWNING",
  "BOOTING",
  "READY",
  "RUNNING",
  "DRAINING",
  "EXITED",
  "FAILED",
] as const);
export type WorkerState = (typeof WORKER_STATES)[number];

export const CONNECTION_STATES = Object.freeze([
  "ACCEPTED",
  "HANDSHAKING",
  "OPEN",
  "CLOSING",
  "CLOSED",
] as const);
export type ConnectionState = (typeof CONNECTION_STATES)[number];

export const MASTER_STATE = Object.freeze(
  Object.fromEntries(MASTER_STATES.map((state) => [state, state])) as {
    readonly [State in MasterState]: State;
  },
);
export const WORKER_STATE = Object.freeze(
  Object.fromEntries(WORKER_STATES.map((state) => [state, state])) as {
    readonly [State in WorkerState]: State;
  },
);
export const CONNECTION_STATE = Object.freeze(
  Object.fromEntries(CONNECTION_STATES.map((state) => [state, state])) as {
    readonly [State in ConnectionState]: State;
  },
);

const MASTER_TRANSITIONS: Readonly<Record<MasterState, readonly MasterState[]>> = {
  CREATED: ["INITIALIZING", "STOPPING"],
  INITIALIZING: ["SPAWNING_CHILDREN", "STOPPING"],
  SPAWNING_CHILDREN: ["WAITING_READY", "STOPPING"],
  WAITING_READY: ["LISTENING", "STOPPING"],
  LISTENING: ["RUNNING", "STOPPING"],
  RUNNING: ["RELOADING", "DRAINING", "STOPPING"],
  RELOADING: ["RUNNING", "DRAINING", "STOPPING"],
  DRAINING: ["STOPPING"],
  STOPPING: ["STOPPED"],
  STOPPED: [],
};

const WORKER_TRANSITIONS: Readonly<Record<WorkerState, readonly WorkerState[]>> = {
  SPAWNING: ["BOOTING", "FAILED"],
  BOOTING: ["READY", "FAILED"],
  READY: ["RUNNING", "DRAINING", "FAILED"],
  RUNNING: ["DRAINING", "FAILED"],
  DRAINING: ["EXITED", "FAILED"],
  EXITED: ["SPAWNING"],
  FAILED: ["SPAWNING"],
};

const CONNECTION_TRANSITIONS: Readonly<Record<ConnectionState, readonly ConnectionState[]>> = {
  ACCEPTED: ["HANDSHAKING", "OPEN", "CLOSING", "CLOSED"],
  HANDSHAKING: ["OPEN", "CLOSING", "CLOSED"],
  OPEN: ["CLOSING", "CLOSED"],
  CLOSING: ["CLOSED"],
  CLOSED: [],
};

function assertTransition<State extends string>(
  machine: string,
  transitions: Readonly<Record<State, readonly State[]>>,
  from: State,
  to: State,
): void {
  if (!transitions[from].includes(to)) {
    throw new FrameworkError(
      FRAMEWORK_ERROR_CODE.INVALID_STATE,
      `${machine} cannot transition from ${from} to ${to}`,
      { machine, from, to },
    );
  }
}

export function canMasterTransition(from: MasterState, to: MasterState): boolean {
  return MASTER_TRANSITIONS[from].includes(to);
}

export function assertMasterTransition(from: MasterState, to: MasterState): void {
  assertTransition("Master", MASTER_TRANSITIONS, from, to);
}

export function canWorkerTransition(from: WorkerState, to: WorkerState): boolean {
  return WORKER_TRANSITIONS[from].includes(to);
}

export function assertWorkerTransition(from: WorkerState, to: WorkerState): void {
  assertTransition("Worker", WORKER_TRANSITIONS, from, to);
}

export function canConnectionTransition(from: ConnectionState, to: ConnectionState): boolean {
  return CONNECTION_TRANSITIONS[from].includes(to);
}

export function assertConnectionTransition(from: ConnectionState, to: ConnectionState): void {
  assertTransition("Connection", CONNECTION_TRANSITIONS, from, to);
}
