declare const sessionIdBrand: unique symbol;

export type SessionId = number & { readonly [sessionIdBrand]: "SessionId" };

export const SESSION_ID_LAYOUT = Object.freeze({
  gatewayBits: 8,
  masterGenerationBits: 13,
  slotIndexBits: 20,
  sessionGenerationBits: 12,
  maxGatewayId: 2 ** 8 - 1,
  maxMasterGeneration: 2 ** 13 - 1,
  maxSlotIndex: 2 ** 20 - 1,
  maxSessionGeneration: 2 ** 12 - 1,
  localSequenceRange: 2 ** 32,
} as const);

const SESSION_GENERATION_RANGE = 2 ** SESSION_ID_LAYOUT.sessionGenerationBits;
const MASTER_GENERATION_RANGE = 2 ** SESSION_ID_LAYOUT.masterGenerationBits;

export interface SessionIdParts {
  readonly gatewayId: number;
  readonly masterGeneration: number;
  readonly slotIndex: number;
  readonly sessionGeneration: number;
}

export interface DecodedSessionId extends SessionIdParts {
  readonly localSequence: number;
}

function assertIntegerInRange(name: string, value: number, min: number, max: number): void {
  if (!Number.isSafeInteger(value) || value < min || value > max) {
    throw new RangeError(`${name} must be a safe integer in [${min}, ${max}], got ${value}`);
  }
}

export function encodeSessionId(parts: SessionIdParts): SessionId {
  assertIntegerInRange("gatewayId", parts.gatewayId, 0, SESSION_ID_LAYOUT.maxGatewayId);
  assertIntegerInRange(
    "masterGeneration",
    parts.masterGeneration,
    0,
    SESSION_ID_LAYOUT.maxMasterGeneration,
  );
  assertIntegerInRange("slotIndex", parts.slotIndex, 0, SESSION_ID_LAYOUT.maxSlotIndex);
  assertIntegerInRange(
    "sessionGeneration",
    parts.sessionGeneration,
    1,
    SESSION_ID_LAYOUT.maxSessionGeneration,
  );

  const localSequence =
    parts.slotIndex * SESSION_GENERATION_RANGE + parts.sessionGeneration;
  const value =
    (parts.gatewayId * MASTER_GENERATION_RANGE + parts.masterGeneration) *
      SESSION_ID_LAYOUT.localSequenceRange +
    localSequence;

  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`encoded SessionId is outside the JavaScript safe integer range: ${value}`);
  }
  return value as SessionId;
}

export function decodeSessionId(sessionId: SessionId): DecodedSessionId {
  if (!isSessionId(sessionId)) {
    throw new RangeError(`invalid SessionId: ${sessionId}`);
  }

  const localSequence = sessionId % SESSION_ID_LAYOUT.localSequenceRange;
  const upper = Math.floor(sessionId / SESSION_ID_LAYOUT.localSequenceRange);
  const masterGeneration = upper % MASTER_GENERATION_RANGE;
  const gatewayId = Math.floor(upper / MASTER_GENERATION_RANGE);
  const sessionGeneration = localSequence % SESSION_GENERATION_RANGE;
  const slotIndex = Math.floor(localSequence / SESSION_GENERATION_RANGE);

  return Object.freeze({
    gatewayId,
    masterGeneration,
    localSequence,
    slotIndex,
    sessionGeneration,
  });
}

export function isSessionId(value: unknown): value is SessionId {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) {
    return false;
  }

  const localSequence = value % SESSION_ID_LAYOUT.localSequenceRange;
  const sessionGeneration = localSequence % SESSION_GENERATION_RANGE;
  return sessionGeneration !== 0;
}

export function isSameSessionSlot(left: SessionId, right: SessionId): boolean {
  const leftParts = decodeSessionId(left);
  const rightParts = decodeSessionId(right);
  return (
    leftParts.gatewayId === rightParts.gatewayId &&
    leftParts.slotIndex === rightParts.slotIndex
  );
}

export function isStaleSessionId(candidate: SessionId, current: SessionId): boolean {
  return isSameSessionSlot(candidate, current) && candidate !== current;
}
