import {
  FRAMEWORK_ERROR_CODE,
  FrameworkError,
  type FrameworkErrorCode,
} from "../errors/framework-error.ts";
import { WEB_SOCKET_OPCODE } from "../network/websocket-protocol.ts";
import {
  IPC_MESSAGE_TYPE,
  type IpcMessageType,
} from "../protocol/ipc-envelope.ts";
import { PROCESS_ROLE } from "../protocol/process-role.ts";
import { isSessionId, type SessionId } from "../protocol/session-id.ts";
import type { ProcessBus } from "../process/process-bus.ts";
import {
  encodeNetworkCloseCommandPayload,
  encodeNetworkSendCommandPayload,
  NETWORK_SEND_HEADER_BYTES,
} from "./network-command-protocol.ts";
import {
  SHARED_RUNTIME_STAT_METRIC,
  type SharedConnectionAdmissionProbe,
  type SharedConnectionProbe,
  type SharedRuntimeStateReader,
} from "../shared-state/shared-runtime-state.ts";
import type { RustWorkerDataPlane } from "../network/rust-worker-data-plane.ts";

export const DEFAULT_NETWORK_COMMAND_MAX_PAYLOAD_BYTES = 2 * 1024 * 1024;

export type WorkerNetworkCommandBus = Pick<
  ProcessBus,
  "localIdentity" | "enqueue"
>;

export interface WorkerNetworkCommandSenderOptions {
  readonly bus: WorkerNetworkCommandBus;
  readonly sharedState?: Pick<SharedRuntimeStateReader, "probeConnection"> &
    Partial<Pick<
      SharedRuntimeStateReader,
      "addStat" | "probeConnectionAdmission"
    >>;
  readonly onDeliveryError?: (error: unknown) => void;
  readonly maxPayloadBytes?: number;
  readonly nativeDataPlane?: Pick<RustWorkerDataPlane, "send" | "closeSession">;
}

export interface WorkerNetworkCommandSenderStats {
  readonly sealed: boolean;
  readonly acceptedCommands: number;
  readonly rejectedCommands: number;
  readonly deliveryErrors: number;
  readonly overflowSessions: number;
  readonly overflowRejections: number;
  readonly lastError: FrameworkErrorCode | null;
}

function invalidSessionError(sessionId: unknown): FrameworkError {
  let rendered = "<unprintable>";
  try {
    rendered = String(sessionId);
  } catch {
    // Invalid runtime values must still remain inside the boolean facade.
  }
  return new FrameworkError(
    FRAMEWORK_ERROR_CODE.INVALID_SESSION,
    `invalid Session ID: ${rendered}`,
  );
}

function invalidArgumentError(message: string): FrameworkError {
  return new FrameworkError(FRAMEWORK_ERROR_CODE.INVALID_STATE, message);
}

function asCommandErrorCode(error: unknown): FrameworkErrorCode {
  try {
    if (error instanceof FrameworkError) {
      return error.code;
    }
  } catch {
    // Hostile thrown values must not escape push/send/close boolean semantics.
  }
  return FRAMEWORK_ERROR_CODE.INVALID_STATE;
}

export class WorkerNetworkCommandSender {
  readonly #bus: WorkerNetworkCommandBus;
  readonly #onDeliveryError: ((error: unknown) => void) | undefined;
  readonly #maxPayloadBytes: number;
  readonly #nativeDataPlane:
    | Pick<RustWorkerDataPlane, "send" | "closeSession">
    | undefined;
  readonly #sharedState:
    | (Pick<SharedRuntimeStateReader, "probeConnection"> &
      Partial<Pick<
        SharedRuntimeStateReader,
        "addStat" | "probeConnectionAdmission"
      >>)
    | undefined;
  readonly #overflowSessions = new Set<SessionId>();
  #sealed = false;
  #acceptedCommands = 0;
  #rejectedCommands = 0;
  #deliveryErrors = 0;
  #overflowRejections = 0;
  #lastError: FrameworkErrorCode | null = null;

  constructor(options: WorkerNetworkCommandSenderOptions) {
    const identity = options.bus.localIdentity;
    if (
      (identity.role !== PROCESS_ROLE.WORKER &&
        identity.role !== PROCESS_ROLE.TASK_WORKER &&
        identity.role !== PROCESS_ROLE.USER_TASK_WORKER) ||
      identity.workerId === null ||
      identity.generation === null
    ) {
      throw new TypeError(
        "WorkerNetworkCommandSender requires a supervised Worker ProcessBus",
      );
    }
    this.#bus = options.bus;
    this.#sharedState = options.sharedState;
    this.#onDeliveryError = options.onDeliveryError;
    this.#nativeDataPlane = options.nativeDataPlane;
    this.#maxPayloadBytes = options.maxPayloadBytes ??
      DEFAULT_NETWORK_COMMAND_MAX_PAYLOAD_BYTES;
    if (!Number.isSafeInteger(this.#maxPayloadBytes) || this.#maxPayloadBytes < 1) {
      throw new RangeError("maxPayloadBytes must be a positive safe integer");
    }
  }

  push(
    sessionId: SessionId,
    data: Uint8Array | string,
    opcode: number = WEB_SOCKET_OPCODE.TEXT,
  ): boolean {
    return this.#admit(sessionId, () =>
      encodeNetworkSendCommandPayload({
        protocol: "websocket",
        data: this.#requireData(data, true),
        opcode,
      })
    );
  }

  send(sessionId: SessionId, data: Uint8Array | string): boolean {
    try {
      const value = this.#requireData(data, false);
      return this.#admit(
        sessionId,
        () => encodeNetworkSendCommandPayload({
          protocol: "tcp",
          data: value,
        }),
        IPC_MESSAGE_TYPE.NET_SEND,
        typeof value === "string" ? Buffer.from(value) : value,
      );
    } catch (error) {
      this.#rejectedCommands += 1;
      this.#recordSharedRejection();
      this.#lastError = asCommandErrorCode(error);
      return false;
    }
  }

  close(sessionId: SessionId, code = 1000, reason = ""): boolean {
    return this.#admit(
      sessionId,
      () => encodeNetworkCloseCommandPayload(code, reason),
      IPC_MESSAGE_TYPE.NET_CLOSE_COMMAND,
      null,
    );
  }

  getLastError(): FrameworkErrorCode | null {
    return this.#lastError;
  }

  stats(): Readonly<WorkerNetworkCommandSenderStats> {
    return Object.freeze({
      sealed: this.#sealed,
      acceptedCommands: this.#acceptedCommands,
      rejectedCommands: this.#rejectedCommands,
      deliveryErrors: this.#deliveryErrors,
      overflowSessions: this.#overflowSessions.size,
      overflowRejections: this.#overflowRejections,
      lastError: this.#lastError,
    });
  }

  seal(_reason?: unknown): void {
    this.#sealed = true;
  }

  setOutputOverflow(sessionId: SessionId, overflow: boolean): void {
    if (!isSessionId(sessionId)) {
      throw invalidSessionError(sessionId);
    }
    if (overflow) {
      this.#overflowSessions.add(sessionId);
    } else {
      this.#overflowSessions.delete(sessionId);
    }
  }

  forgetSession(sessionId: SessionId): void {
    this.#overflowSessions.delete(sessionId);
  }

  #admit(
    sessionId: SessionId,
    createPayload: () => ReturnType<typeof encodeNetworkSendCommandPayload> |
      ReturnType<typeof encodeNetworkCloseCommandPayload>,
    messageType: IpcMessageType = IPC_MESSAGE_TYPE.NET_SEND,
    nativePayload?: Uint8Array | null,
  ): boolean {
    try {
      if (this.#sealed) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
          "Worker network command sender is sealed",
        );
      }
      if (!isSessionId(sessionId)) {
        throw invalidSessionError(sessionId);
      }
      const sharedProbe: Readonly<SharedConnectionAdmissionProbe> |
        Readonly<SharedConnectionProbe> | undefined =
          this.#sharedState?.probeConnectionAdmission?.(sessionId) ??
          this.#sharedState?.probeConnection(sessionId);
      if (sharedProbe !== undefined && sharedProbe.status !== "open") {
        const code = sharedProbe.status === "stale"
          ? FRAMEWORK_ERROR_CODE.STALE_GENERATION
          : sharedProbe.status === "closed"
          ? FRAMEWORK_ERROR_CODE.SESSION_CLOSED
          : sharedProbe.status === "unknown"
          ? FRAMEWORK_ERROR_CODE.INVALID_SESSION
          : FRAMEWORK_ERROR_CODE.INVALID_STATE;
        throw new FrameworkError(
          code,
          `Session ${sessionId} failed shared network command precheck: ${sharedProbe.status}`,
          { sessionId, sharedStatus: sharedProbe.status },
        );
      }
      const outputOverflow = (sharedProbe !== undefined && "overflow" in sharedProbe
        ? sharedProbe.overflow
        : sharedProbe?.record?.overflow) ??
        (this.#sharedState === undefined && this.#overflowSessions.has(sessionId));
      if (messageType === IPC_MESSAGE_TYPE.NET_SEND && outputOverflow) {
        this.#overflowRejections += 1;
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.OUTPUT_BUFFER_OVERFLOW,
          `Session ${sessionId} output buffer is overflowed`,
          { sessionId },
        );
      }
      if (
        this.#nativeDataPlane !== undefined &&
        nativePayload !== undefined
      ) {
        if (
          nativePayload !== null &&
          nativePayload.byteLength > this.#maxPayloadBytes
        ) {
          throw new FrameworkError(
            FRAMEWORK_ERROR_CODE.MESSAGE_TOO_LARGE,
            `network command payload exceeds buffer_output_size ${this.#maxPayloadBytes}`,
            {
              byteLength: nativePayload.byteLength,
              maxPayloadBytes: this.#maxPayloadBytes,
            },
          );
        }
        const result = nativePayload === null
          ? this.#nativeDataPlane.closeSession(sessionId)
          : this.#nativeDataPlane.send(sessionId, nativePayload);
        if (!result.accepted) {
          throw new FrameworkError(
            result.backpressured
              ? FRAMEWORK_ERROR_CODE.IPC_QUEUE_FULL
              : FRAMEWORK_ERROR_CODE.IPC_CHANNEL_CLOSED,
            result.backpressured
              ? "Rust Worker data-plane queue is full"
              : "Rust Worker data-plane channel is unavailable",
            { sessionId },
          );
        }
        this.#acceptedCommands += 1;
        this.#lastError = null;
        return true;
      }
      const payload = createPayload();
      if (
        messageType === IPC_MESSAGE_TYPE.NET_SEND &&
        payload instanceof Uint8Array &&
        payload.byteLength - NETWORK_SEND_HEADER_BYTES > this.#maxPayloadBytes
      ) {
        throw new FrameworkError(
          FRAMEWORK_ERROR_CODE.MESSAGE_TOO_LARGE,
          `network command payload exceeds buffer_output_size ${this.#maxPayloadBytes}`,
          {
            byteLength: payload.byteLength - NETWORK_SEND_HEADER_BYTES,
            maxPayloadBytes: this.#maxPayloadBytes,
          },
        );
      }
      const receipt = this.#bus.enqueue({
        messageType,
        targetRole: PROCESS_ROLE.MASTER,
        targetWorkerId: null,
        sessionId,
        payload,
        ownsPayload: true,
      });
      void receipt.completion.catch((error: unknown) => {
        this.#deliveryErrors += 1;
        try {
          this.#onDeliveryError?.(error);
        } catch {
          // Delivery observers cannot alter the already-returned admission result.
        }
      });
      this.#acceptedCommands += 1;
      this.#lastError = null;
      return true;
    } catch (error) {
      this.#rejectedCommands += 1;
      this.#recordSharedRejection();
      this.#lastError = asCommandErrorCode(error);
      return false;
    }
  }

  #recordSharedRejection(): void {
    const addStat = this.#sharedState?.addStat;
    if (typeof addStat !== "function") {
      return;
    }
    try {
      addStat.call(
        this.#sharedState,
        SHARED_RUNTIME_STAT_METRIC.NETWORK_OUTPUT_REJECTION,
      );
    } catch {
      // A diagnostic counter cannot replace the command's stable boolean result.
    }
  }

  #requireData(
    data: Uint8Array | string,
    allowEmpty: boolean,
  ): Uint8Array | string {
    if (typeof data !== "string" && !(data instanceof Uint8Array)) {
      throw invalidArgumentError("network command data must be a string or Uint8Array");
    }
    if (
      !allowEmpty &&
      (typeof data === "string" ? data.length === 0 : data.byteLength === 0)
    ) {
      throw invalidArgumentError("network command data must not be empty");
    }
    return data;
  }
}
