import type {
  IpcJsonValue,
  IpcScalar,
} from "../protocol/ipc-envelope.ts";
import {
  createWorkerId,
  type WorkerId,
} from "../protocol/worker-id.ts";
import type { ConnectionPeerInfo } from "../connection/connection-registry.ts";
import type { RuntimeProtocol } from "../runtime/runtime-server.ts";
import {
  WEB_SOCKET_OPCODE,
  type WebSocketDataOpcode,
  type WebSocketHandshakeRequest,
} from "../network/websocket-protocol.ts";
import {
  NETWORK_BUFFER_STATE,
  type NetworkBufferState,
} from "./network-buffer-protocol.ts";

export const NETWORK_EVENT_PROTOCOL_VERSION = 1 as const;
export const NETWORK_RESUME_PROTOCOL_VERSION = 2 as const;
export const NETWORK_MESSAGE_HEADER_BYTES = 4;

const NETWORK_PROTOCOL_CODE = Object.freeze({
  TCP: 0,
  WEBSOCKET: 1,
} as const);
const MAX_CLOSE_CAUSE_FIELDS = 16;
const MAX_CLOSE_CAUSE_STRING_LENGTH = 1_024;
const strictTextDecoder = new TextDecoder("utf-8", { fatal: true });

const CONNECT_KEYS = Object.freeze([
  "version",
  "ownerWorkerId",
  "protocol",
  "connectedAt",
  "peerInfo",
  "request",
] as const);
const RESUME_KEYS = Object.freeze([
  "version",
  "ownerWorkerId",
  "protocol",
  "connectedAt",
  "lastActiveAt",
  "peerInfo",
  "request",
  "inputSequence",
  "outputBufferedBytes",
  "outputBufferState",
] as const);
const PEER_INFO_KEYS = Object.freeze([
  "remoteAddress",
  "remotePort",
  "localAddress",
  "localPort",
] as const);
const HANDSHAKE_REQUEST_KEYS = Object.freeze([
  "method",
  "target",
  "httpVersion",
  "headers",
  "key",
  "protocols",
  "extensions",
] as const);
const CLOSE_KEYS = Object.freeze([
  "version",
  "ownerWorkerId",
  "protocol",
  "inputSequence",
  "outputSequence",
  "cause",
] as const);

type IpcJsonObject = Readonly<Record<string, IpcJsonValue>>;

export interface NetworkConnectPayload {
  readonly version: typeof NETWORK_EVENT_PROTOCOL_VERSION;
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly connectedAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly request: WebSocketHandshakeRequest | null;
}

export interface NetworkResumePayload {
  readonly version: typeof NETWORK_RESUME_PROTOCOL_VERSION;
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly connectedAt: number;
  readonly lastActiveAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly request: WebSocketHandshakeRequest | null;
  readonly inputSequence: number;
  readonly outputBufferedBytes: number;
  readonly outputBufferState: NetworkBufferState;
}

export type NetworkConnectEventPayload = NetworkConnectPayload | NetworkResumePayload;

export interface NetworkMessagePayload {
  readonly protocol: RuntimeProtocol;
  readonly opcode?: WebSocketDataOpcode;
  readonly finish: true;
  readonly data: Buffer | string;
}

export type NetworkCloseCauseSummary = Readonly<Record<string, IpcScalar>>;

export interface NetworkClosePayload {
  readonly version: typeof NETWORK_EVENT_PROTOCOL_VERSION;
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly inputSequence: number;
  readonly outputSequence: number;
  readonly cause: NetworkCloseCauseSummary | null;
}

export interface EncodeNetworkConnectPayloadOptions {
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly connectedAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly request?: WebSocketHandshakeRequest;
}

export interface EncodeNetworkResumePayloadOptions {
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly connectedAt: number;
  readonly lastActiveAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly request?: WebSocketHandshakeRequest;
  readonly inputSequence: number;
  readonly outputBufferedBytes: number;
  readonly outputBufferState: NetworkBufferState;
}

export interface EncodeNetworkMessagePayloadOptions {
  readonly protocol: RuntimeProtocol;
  readonly data: Uint8Array | string;
  readonly opcode?: number;
  readonly finish: true;
}

export interface EncodeNetworkClosePayloadOptions {
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly inputSequence: number;
  readonly outputSequence: number;
  readonly cause: unknown;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function requireExactRecord(
  value: unknown,
  keys: readonly string[],
  name: string,
): Record<string, unknown> {
  if (!isPlainObject(value)) {
    throw new TypeError(`${name} must be a plain object`);
  }
  const ownKeys = Reflect.ownKeys(value);
  if (
    ownKeys.length !== keys.length ||
    ownKeys.some((key) => typeof key !== "string" || !keys.includes(key))
  ) {
    throw new TypeError(`${name} must contain exactly: ${keys.join(", ")}`);
  }
  for (const key of keys) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
      throw new TypeError(`${name}.${key} must be an enumerable data field`);
    }
  }
  return value;
}

function requireWorkerId(value: unknown, name: string): WorkerId {
  try {
    return createWorkerId(value as number);
  } catch {
    throw new TypeError(`${name} must be a non-negative safe integer`);
  }
}

function requireProtocol(value: unknown, name: string): RuntimeProtocol {
  if (value !== "tcp" && value !== "websocket") {
    throw new TypeError(`${name} must be tcp or websocket`);
  }
  return value;
}

function requireNonNegativeSequence(value: unknown, name: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 0) {
    throw new TypeError(`${name} must be a non-negative safe integer`);
  }
  return value as number;
}

function requireFiniteTimestamp(value: unknown, name: string): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be finite`);
  }
  return value;
}

function requireNetworkBufferState(value: unknown): NetworkBufferState {
  if (
    value !== NETWORK_BUFFER_STATE.EMPTY &&
    value !== NETWORK_BUFFER_STATE.FULL &&
    value !== NETWORK_BUFFER_STATE.OVERFLOW
  ) {
    throw new TypeError("NET_CONNECT resume outputBufferState is invalid");
  }
  return value;
}

function requirePort(value: unknown, name: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 0 || (value as number) > 65_535) {
    throw new TypeError(`${name} must be an integer in [0, 65535]`);
  }
  return value as number;
}

function parsePeerInfo(value: unknown): Readonly<ConnectionPeerInfo> {
  const record = requireExactRecord(value, PEER_INFO_KEYS, "network peerInfo");
  if (typeof record.remoteAddress !== "string" || typeof record.localAddress !== "string") {
    throw new TypeError("network peerInfo addresses must be strings");
  }
  return Object.freeze({
    remoteAddress: record.remoteAddress,
    remotePort: requirePort(record.remotePort, "network peerInfo.remotePort"),
    localAddress: record.localAddress,
    localPort: requirePort(record.localPort, "network peerInfo.localPort"),
  });
}

function parseStringArray(value: unknown, name: string): readonly string[] {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
    throw new TypeError(`${name} must be an array of strings`);
  }
  return Object.freeze([...value] as string[]);
}

function parseHeaders(value: unknown): Readonly<Record<string, string>> {
  if (!isPlainObject(value)) {
    throw new TypeError("network request.headers must be a plain object");
  }
  const entries: [string, string][] = [];
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string") {
      throw new TypeError("network request.headers cannot contain symbol keys");
    }
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (
      descriptor === undefined ||
      !descriptor.enumerable ||
      !("value" in descriptor) ||
      typeof descriptor.value !== "string"
    ) {
      throw new TypeError("network request.headers values must be enumerable strings");
    }
    entries.push([key, descriptor.value]);
  }
  return Object.freeze(Object.fromEntries(entries));
}

function parseHandshakeRequest(value: unknown): WebSocketHandshakeRequest {
  const record = requireExactRecord(
    value,
    HANDSHAKE_REQUEST_KEYS,
    "network WebSocket request",
  );
  if (
    record.method !== "GET" ||
    typeof record.target !== "string" ||
    record.target.length === 0 ||
    record.httpVersion !== "1.1" ||
    typeof record.key !== "string"
  ) {
    throw new TypeError("network WebSocket request contains invalid scalar fields");
  }
  return Object.freeze({
    method: "GET",
    target: record.target,
    httpVersion: "1.1",
    headers: parseHeaders(record.headers),
    key: record.key,
    protocols: parseStringArray(record.protocols, "network request.protocols"),
    extensions: parseStringArray(record.extensions, "network request.extensions"),
  });
}

function parseConnectCommon(record: Record<string, unknown>): Readonly<{
  readonly ownerWorkerId: WorkerId;
  readonly protocol: RuntimeProtocol;
  readonly connectedAt: number;
  readonly peerInfo: Readonly<ConnectionPeerInfo>;
  readonly request: WebSocketHandshakeRequest | null;
}> {
  const protocol = requireProtocol(record.protocol, "NET_CONNECT protocol");
  const request = record.request === null ? null : parseHandshakeRequest(record.request);
  if ((protocol === "tcp" && request !== null) || (protocol === "websocket" && request === null)) {
    throw new TypeError("NET_CONNECT request must match its protocol");
  }
  return Object.freeze({
    ownerWorkerId: requireWorkerId(record.ownerWorkerId, "NET_CONNECT ownerWorkerId"),
    protocol,
    connectedAt: requireFiniteTimestamp(record.connectedAt, "NET_CONNECT connectedAt"),
    peerInfo: parsePeerInfo(record.peerInfo),
    request,
  });
}

function requirePayloadVersion(value: unknown): unknown {
  if (!isPlainObject(value)) {
    throw new TypeError("NET_CONNECT payload must be a plain object");
  }
  const descriptor = Object.getOwnPropertyDescriptor(value, "version");
  if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
    throw new TypeError("NET_CONNECT payload.version must be an enumerable data field");
  }
  return descriptor.value;
}

export function decodeNetworkConnectPayload(
  value: unknown,
): Readonly<NetworkConnectEventPayload> {
  const version = requirePayloadVersion(value);
  if (version === NETWORK_EVENT_PROTOCOL_VERSION) {
    const record = requireExactRecord(value, CONNECT_KEYS, "NET_CONNECT payload");
    return Object.freeze({
      version: NETWORK_EVENT_PROTOCOL_VERSION,
      ...parseConnectCommon(record),
    });
  }
  if (version === NETWORK_RESUME_PROTOCOL_VERSION) {
    const record = requireExactRecord(value, RESUME_KEYS, "NET_CONNECT resume payload");
    const common = parseConnectCommon(record);
    const inputSequence = requireNonNegativeSequence(
      record.inputSequence,
      "NET_CONNECT resume inputSequence",
    );
    if (inputSequence >= Number.MAX_SAFE_INTEGER) {
      throw new TypeError(
        "NET_CONNECT resume inputSequence must leave room for the next event",
      );
    }
    return Object.freeze({
      version: NETWORK_RESUME_PROTOCOL_VERSION,
      ownerWorkerId: common.ownerWorkerId,
      protocol: common.protocol,
      connectedAt: common.connectedAt,
      lastActiveAt: requireFiniteTimestamp(
        record.lastActiveAt,
        "NET_CONNECT resume lastActiveAt",
      ),
      peerInfo: common.peerInfo,
      request: common.request,
      inputSequence,
      outputBufferedBytes: requireNonNegativeSequence(
        record.outputBufferedBytes,
        "NET_CONNECT resume outputBufferedBytes",
      ),
      outputBufferState: requireNetworkBufferState(record.outputBufferState),
    });
  }
  throw new TypeError("NET_CONNECT payload has an unsupported version");
}

export function encodeNetworkConnectPayload(
  options: EncodeNetworkConnectPayloadOptions,
): Readonly<NetworkConnectPayload> & IpcJsonObject {
  return decodeNetworkConnectPayload({
    version: NETWORK_EVENT_PROTOCOL_VERSION,
    ownerWorkerId: options.ownerWorkerId,
    protocol: options.protocol,
    connectedAt: options.connectedAt,
    peerInfo: options.peerInfo,
    request: options.request ?? null,
  }) as Readonly<NetworkConnectPayload> & IpcJsonObject;
}

export function encodeNetworkResumePayload(
  options: EncodeNetworkResumePayloadOptions,
): Readonly<NetworkResumePayload> & IpcJsonObject {
  return decodeNetworkConnectPayload({
    version: NETWORK_RESUME_PROTOCOL_VERSION,
    ownerWorkerId: options.ownerWorkerId,
    protocol: options.protocol,
    connectedAt: options.connectedAt,
    lastActiveAt: options.lastActiveAt,
    peerInfo: options.peerInfo,
    request: options.request ?? null,
    inputSequence: options.inputSequence,
    outputBufferedBytes: options.outputBufferedBytes,
    outputBufferState: options.outputBufferState,
  }) as Readonly<NetworkResumePayload> & IpcJsonObject;
}

export function isNetworkResumePayload(
  payload: Readonly<NetworkConnectEventPayload>,
): payload is Readonly<NetworkResumePayload> {
  return payload.version === NETWORK_RESUME_PROTOCOL_VERSION;
}

function protocolCode(protocol: RuntimeProtocol): number {
  return protocol === "tcp"
    ? NETWORK_PROTOCOL_CODE.TCP
    : NETWORK_PROTOCOL_CODE.WEBSOCKET;
}

export function encodeNetworkMessagePayload(
  options: EncodeNetworkMessagePayloadOptions,
): Buffer {
  if (options.finish !== true) {
    throw new TypeError("NET_MESSAGE finish must be true");
  }
  let opcode = 0;
  let data: Buffer;
  if (options.protocol === "tcp") {
    if (options.opcode !== undefined || typeof options.data === "string") {
      throw new TypeError("TCP NET_MESSAGE requires binary data and no opcode");
    }
    data = Buffer.from(options.data.buffer, options.data.byteOffset, options.data.byteLength);
  } else {
    if (
      options.opcode !== WEB_SOCKET_OPCODE.TEXT &&
      options.opcode !== WEB_SOCKET_OPCODE.BINARY
    ) {
      throw new TypeError("WebSocket NET_MESSAGE requires a text or binary opcode");
    }
    opcode = options.opcode;
    if (opcode === WEB_SOCKET_OPCODE.TEXT) {
      if (typeof options.data !== "string") {
        throw new TypeError("WebSocket text NET_MESSAGE requires string data");
      }
      data = Buffer.from(options.data, "utf8");
    } else {
      if (typeof options.data === "string") {
        throw new TypeError("WebSocket binary NET_MESSAGE requires Uint8Array data");
      }
      data = Buffer.from(options.data.buffer, options.data.byteOffset, options.data.byteLength);
    }
  }

  const payload = Buffer.allocUnsafe(NETWORK_MESSAGE_HEADER_BYTES + data.byteLength);
  payload[0] = NETWORK_EVENT_PROTOCOL_VERSION;
  payload[1] = protocolCode(options.protocol);
  payload[2] = opcode;
  payload[3] = 1;
  payload.set(data, NETWORK_MESSAGE_HEADER_BYTES);
  return payload;
}

export function decodeNetworkMessagePayload(value: unknown): Readonly<NetworkMessagePayload> {
  if (!(value instanceof Uint8Array) || value.byteLength < NETWORK_MESSAGE_HEADER_BYTES) {
    throw new TypeError("NET_MESSAGE payload must be a binary network event");
  }
  const payload = Buffer.from(value.buffer, value.byteOffset, value.byteLength);
  if (payload[0] !== NETWORK_EVENT_PROTOCOL_VERSION || payload[3] !== 1) {
    throw new TypeError("NET_MESSAGE payload has an invalid version or finish marker");
  }
  const data = Buffer.from(payload.subarray(NETWORK_MESSAGE_HEADER_BYTES));
  if (payload[1] === NETWORK_PROTOCOL_CODE.TCP) {
    if (payload[2] !== 0) {
      throw new TypeError("TCP NET_MESSAGE cannot carry a WebSocket opcode");
    }
    return Object.freeze({ protocol: "tcp", finish: true, data });
  }
  if (payload[1] !== NETWORK_PROTOCOL_CODE.WEBSOCKET) {
    throw new TypeError("NET_MESSAGE payload contains an unknown protocol code");
  }
  const opcode = payload[2];
  if (opcode === WEB_SOCKET_OPCODE.TEXT) {
    let text: string;
    try {
      text = strictTextDecoder.decode(data);
    } catch {
      throw new TypeError("WebSocket NET_MESSAGE text contains invalid UTF-8");
    }
    return Object.freeze({ protocol: "websocket", opcode, finish: true, data: text });
  }
  if (opcode === WEB_SOCKET_OPCODE.BINARY) {
    return Object.freeze({ protocol: "websocket", opcode, finish: true, data });
  }
  throw new TypeError("WebSocket NET_MESSAGE contains an invalid data opcode");
}

function truncate(value: string): string {
  return value.length <= MAX_CLOSE_CAUSE_STRING_LENGTH
    ? value
    : value.slice(0, MAX_CLOSE_CAUSE_STRING_LENGTH);
}

function safeString(value: unknown): string {
  try {
    return truncate(String(value));
  } catch {
    return "<unprintable>";
  }
}

function safeReadString(read: () => unknown, fallback: string): string {
  try {
    return safeString(read());
  } catch {
    return fallback;
  }
}

export function summarizeNetworkCloseCause(
  cause: unknown,
): NetworkCloseCauseSummary | null {
  if (cause === undefined || cause === null) {
    return null;
  }
  if (cause instanceof Error) {
    return Object.freeze({
      kind: "error",
      errorName: safeReadString(() => cause.name, "Error"),
      errorMessage: safeReadString(() => cause.message, "<unreadable error message>"),
    });
  }
  if (isPlainObject(cause)) {
    const entries: [string, IpcScalar][] = [];
    for (const key of Object.keys(cause).slice(0, MAX_CLOSE_CAUSE_FIELDS)) {
      const descriptor = Object.getOwnPropertyDescriptor(cause, key);
      if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
        continue;
      }
      const value = descriptor.value;
      if (
        value === null ||
        typeof value === "boolean" ||
        (typeof value === "number" && Number.isFinite(value))
      ) {
        entries.push([key, value]);
      } else if (typeof value === "string") {
        entries.push([key, truncate(value)]);
      }
    }
    if (entries.length !== 0) {
      return Object.freeze(Object.fromEntries(entries));
    }
  }
  return Object.freeze({ kind: "value", value: safeString(cause) });
}

function parseCloseCause(value: unknown): NetworkCloseCauseSummary | null {
  if (value === null) {
    return null;
  }
  if (!isPlainObject(value)) {
    throw new TypeError("NET_CLOSE cause must be null or a plain object");
  }
  const keys = Reflect.ownKeys(value);
  if (keys.length > MAX_CLOSE_CAUSE_FIELDS || keys.some((key) => typeof key !== "string")) {
    throw new TypeError("NET_CLOSE cause contains too many or invalid fields");
  }
  const entries: [string, IpcScalar][] = [];
  for (const key of keys as string[]) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
      throw new TypeError("NET_CLOSE cause fields must be enumerable data fields");
    }
    const field = descriptor.value;
    if (
      field !== null &&
      typeof field !== "boolean" &&
      typeof field !== "string" &&
      !(typeof field === "number" && Number.isFinite(field))
    ) {
      throw new TypeError("NET_CLOSE cause fields must be JSON scalars");
    }
    if (typeof field === "string" && field.length > MAX_CLOSE_CAUSE_STRING_LENGTH) {
      throw new TypeError("NET_CLOSE cause string exceeds its limit");
    }
    entries.push([key, field]);
  }
  return Object.freeze(Object.fromEntries(entries));
}

export function decodeNetworkClosePayload(value: unknown): Readonly<NetworkClosePayload> {
  const record = requireExactRecord(value, CLOSE_KEYS, "NET_CLOSE payload");
  if (record.version !== NETWORK_EVENT_PROTOCOL_VERSION) {
    throw new TypeError("NET_CLOSE payload has an unsupported version");
  }
  return Object.freeze({
    version: NETWORK_EVENT_PROTOCOL_VERSION,
    ownerWorkerId: requireWorkerId(record.ownerWorkerId, "NET_CLOSE ownerWorkerId"),
    protocol: requireProtocol(record.protocol, "NET_CLOSE protocol"),
    inputSequence: requireNonNegativeSequence(record.inputSequence, "NET_CLOSE inputSequence"),
    outputSequence: requireNonNegativeSequence(record.outputSequence, "NET_CLOSE outputSequence"),
    cause: parseCloseCause(record.cause),
  });
}

export function encodeNetworkClosePayload(
  options: EncodeNetworkClosePayloadOptions,
): Readonly<NetworkClosePayload> & IpcJsonObject {
  return decodeNetworkClosePayload({
    version: NETWORK_EVENT_PROTOCOL_VERSION,
    ownerWorkerId: options.ownerWorkerId,
    protocol: options.protocol,
    inputSequence: options.inputSequence,
    outputSequence: options.outputSequence,
    cause: summarizeNetworkCloseCause(options.cause),
  }) as Readonly<NetworkClosePayload> & IpcJsonObject;
}
