import { AsyncLocalStorage } from "node:async_hooks";

import type { RuntimeResource } from "./resource-scope.ts";

export const MIN_TIMER_DELAY_MS = 1;
export const MAX_TIMER_DELAY_MS = 0x7fffffff;

export type TimerCallback = () => void | Promise<void>;
export type TimerCallbackErrorHandler = (error: unknown) => void;

export interface Clock {
  wallTimeMs(): number;
  monotonicTimeMs(): number;
}

export interface RuntimeTimer extends RuntimeResource {
  readonly active: boolean;
  readonly done: Promise<void>;
  cancel(reason?: unknown): boolean;
}

export interface TimerScheduler extends RuntimeResource {
  readonly size: number;
  setTimeout(delayMs: number, callback: TimerCallback): RuntimeTimer;
  setInterval(intervalMs: number, callback: TimerCallback): RuntimeTimer;
  cancelAll(reason?: unknown): number;
  close(reason?: unknown): Promise<void>;
  // Owner cleanup awaits the full close; callbacks use a local join to avoid self-wait.
  closeGlobally(reason?: unknown): Promise<void>;
  joinCloseFromCallback(): Promise<void> | undefined;
}

export function assertTimerDelay(delayMs: number, name = "delayMs"): void {
  if (
    !Number.isSafeInteger(delayMs) ||
    delayMs < MIN_TIMER_DELAY_MS ||
    delayMs > MAX_TIMER_DELAY_MS
  ) {
    throw new RangeError(
      `${name} must be a safe integer in [${MIN_TIMER_DELAY_MS}, ${MAX_TIMER_DELAY_MS}], got ${delayMs}`,
    );
  }
}

export class SystemClock implements Clock {
  wallTimeMs(): number {
    return Date.now();
  }

  monotonicTimeMs(): number {
    return performance.now();
  }
}

class SystemRuntimeTimer implements RuntimeTimer {
  readonly done: Promise<void>;
  readonly #clock: Clock;
  readonly #callback: TimerCallback;
  readonly #intervalMs: number | null;
  readonly #onCallbackError: TimerCallbackErrorHandler;
  readonly #onSettled: () => void;
  readonly #resolveDone: () => void;
  readonly #rejectDone: (reason?: unknown) => void;
  #active = true;
  #running = false;
  #settled = false;
  #dueTimeMs: number;
  #handle: ReturnType<typeof globalThis.setTimeout> | undefined;

  constructor(
    clock: Clock,
    delayMs: number,
    intervalMs: number | null,
    callback: TimerCallback,
    onCallbackError: TimerCallbackErrorHandler,
    onSettled: () => void,
  ) {
    this.#clock = clock;
    this.#callback = callback;
    this.#intervalMs = intervalMs;
    this.#onCallbackError = onCallbackError;
    this.#onSettled = onSettled;
    this.#dueTimeMs = clock.monotonicTimeMs() + delayMs;

    let resolveDone!: () => void;
    let rejectDone!: (reason?: unknown) => void;
    this.done = new Promise<void>((resolve, reject) => {
      resolveDone = resolve;
      rejectDone = reject;
    });
    this.#resolveDone = resolveDone;
    this.#rejectDone = rejectDone;
    void this.done.catch(() => undefined);
  }

  get active(): boolean {
    return this.#active;
  }

  start(): void {
    this.#schedule();
  }

  cancel(reason?: unknown): boolean {
    void reason;
    if (!this.#active) {
      return false;
    }

    this.#active = false;
    this.#clearHandle();
    if (!this.#running) {
      this.#settleSuccess();
    }
    return true;
  }

  close(reason?: unknown): Promise<void> {
    this.cancel(reason);
    return this.done;
  }

  [Symbol.asyncDispose](): Promise<void> {
    return this.close();
  }

  #schedule(): void {
    if (!this.#active || this.#settled) {
      return;
    }

    const remainingMs = this.#dueTimeMs - this.#clock.monotonicTimeMs();
    const nativeDelayMs = Math.min(
      MAX_TIMER_DELAY_MS,
      Math.max(MIN_TIMER_DELAY_MS, Math.ceil(remainingMs)),
    );
    this.#handle = globalThis.setTimeout(() => this.#onNativeTimeout(), nativeDelayMs);
  }

  #onNativeTimeout(): void {
    this.#handle = undefined;
    if (!this.#active || this.#settled) {
      return;
    }

    if (this.#clock.monotonicTimeMs() < this.#dueTimeMs) {
      this.#schedule();
      return;
    }

    this.#running = true;
    let result: void | Promise<void>;
    try {
      result = this.#callback();
    } catch (error) {
      this.#finishFailure(error);
      return;
    }

    void Promise.resolve(result).then(
      () => this.#finishSuccess(),
      (error: unknown) => this.#finishFailure(error),
    );
  }

  #finishSuccess(): void {
    this.#running = false;
    if (!this.#active) {
      this.#settleSuccess();
      return;
    }

    if (this.#intervalMs === null) {
      this.#active = false;
      this.#settleSuccess();
      return;
    }

    const now = this.#clock.monotonicTimeMs();
    const elapsedIntervals = Math.floor(Math.max(0, now - this.#dueTimeMs) / this.#intervalMs);
    this.#dueTimeMs += (elapsedIntervals + 1) * this.#intervalMs;
    this.#schedule();
  }

  #finishFailure(error: unknown): void {
    this.#running = false;
    this.#active = false;
    this.#clearHandle();
    try {
      this.#onCallbackError(error);
    } catch {
      // Error reporting must not replace the callback failure exposed by done.
    }
    this.#settleFailure(error);
  }

  #clearHandle(): void {
    if (this.#handle !== undefined) {
      globalThis.clearTimeout(this.#handle);
      this.#handle = undefined;
    }
  }

  #settleSuccess(): void {
    if (this.#settled) {
      return;
    }
    this.#settled = true;
    this.#active = false;
    this.#clearHandle();
    this.#onSettled();
    this.#resolveDone();
  }

  #settleFailure(error: unknown): void {
    if (this.#settled) {
      return;
    }
    this.#settled = true;
    this.#active = false;
    this.#clearHandle();
    this.#onSettled();
    this.#rejectDone(error);
  }
}

type TimerSchedulerState = "open" | "closing" | "closed";

interface CallbackCloseSignal {
  readonly declared: Promise<void>;
  declare(): void;
}

function createCallbackCloseSignal(): CallbackCloseSignal {
  let declare!: () => void;
  const declared = new Promise<void>((resolve) => {
    declare = resolve;
  });
  return { declared, declare };
}

const activeSystemTimer = new AsyncLocalStorage<SystemRuntimeTimer>();

export interface SystemTimerSchedulerOptions {
  readonly clock?: Clock;
  readonly onCallbackError: TimerCallbackErrorHandler;
}

export class SystemTimerScheduler implements TimerScheduler {
  readonly #clock: Clock;
  readonly #onCallbackError: TimerCallbackErrorHandler;
  readonly #timers = new Set<SystemRuntimeTimer>();
  readonly #callbackCloseSignals = new WeakMap<SystemRuntimeTimer, CallbackCloseSignal>();
  readonly #reentrantClosePromises = new WeakMap<SystemRuntimeTimer, Promise<void>>();
  #state: TimerSchedulerState = "open";
  #closingTimers: readonly SystemRuntimeTimer[] | undefined;
  #closePromise: Promise<void> | undefined;

  constructor(options: SystemTimerSchedulerOptions) {
    this.#clock = options.clock ?? new SystemClock();
    this.#onCallbackError = options.onCallbackError;
  }

  get size(): number {
    return this.#timers.size;
  }

  get closed(): boolean {
    return this.#state === "closed";
  }

  setTimeout(delayMs: number, callback: TimerCallback): RuntimeTimer {
    assertTimerDelay(delayMs);
    return this.#createTimer(delayMs, null, callback);
  }

  setInterval(intervalMs: number, callback: TimerCallback): RuntimeTimer {
    assertTimerDelay(intervalMs, "intervalMs");
    return this.#createTimer(intervalMs, intervalMs, callback);
  }

  cancelAll(reason?: unknown): number {
    let cancelled = 0;
    for (const timer of [...this.#timers]) {
      if (timer.cancel(reason)) {
        cancelled += 1;
      }
    }
    return cancelled;
  }

  close(reason?: unknown): Promise<void> {
    if (this.#hasActiveCallback()) {
      this.closeGlobally(reason);
      const callbackClose = this.joinCloseFromCallback();
      if (callbackClose !== undefined) {
        return callbackClose;
      }
    }
    return this.closeGlobally(reason);
  }

  closeGlobally(reason?: unknown): Promise<void> {
    return this.#beginClose(reason);
  }

  joinCloseFromCallback(): Promise<void> | undefined {
    const callingTimer = activeSystemTimer.getStore();
    if (
      callingTimer === undefined ||
      (!this.#timers.has(callingTimer) &&
        this.#closingTimers?.includes(callingTimer) !== true)
    ) {
      return undefined;
    }

    // This local join never replaces the owner promise returned by closeGlobally.
    this.#callbackCloseSignal(callingTimer).declare();
    const existing = this.#reentrantClosePromises.get(callingTimer);
    if (existing !== undefined) {
      return existing;
    }
    const closingTimers = this.#closingTimers;
    if (closingTimers === undefined) {
      const joined = Promise.resolve();
      this.#reentrantClosePromises.set(callingTimer, joined);
      return joined;
    }

    const closeWithoutReentrantCallbacks = this.#waitForTimersUnlessReentrant(
      closingTimers.filter((timer) => timer !== callingTimer),
    );
    this.#reentrantClosePromises.set(callingTimer, closeWithoutReentrantCallbacks);
    return closeWithoutReentrantCallbacks;
  }

  [Symbol.asyncDispose](): Promise<void> {
    return this.closeGlobally();
  }

  #beginClose(reason?: unknown): Promise<void> {
    if (this.#closePromise !== undefined) {
      return this.#closePromise;
    }

    this.#state = "closing";
    const timers = [...this.#timers];
    this.#closingTimers = timers;
    for (const timer of timers) {
      this.#callbackCloseSignal(timer);
      timer.cancel(reason);
    }
    const closePromise = this.#finishClose(timers);
    this.#closePromise = closePromise;
    void closePromise.catch(() => undefined);
    return closePromise;
  }

  #hasActiveCallback(): boolean {
    const callingTimer = activeSystemTimer.getStore();
    return (
      callingTimer !== undefined &&
      (this.#timers.has(callingTimer) ||
        this.#closingTimers?.includes(callingTimer) === true)
    );
  }

  #assertOpen(): void {
    if (this.#state !== "open") {
      throw new Error(`timer scheduler is ${this.#state}`);
    }
  }

  #createTimer(
    delayMs: number,
    intervalMs: number | null,
    callback: TimerCallback,
  ): RuntimeTimer {
    this.#assertOpen();
    let timer!: SystemRuntimeTimer;
    timer = new SystemRuntimeTimer(
      this.#clock,
      delayMs,
      intervalMs,
      () => activeSystemTimer.run(timer, callback),
      this.#onCallbackError,
      () => {
        this.#timers.delete(timer);
      },
    );
    this.#timers.add(timer);
    timer.start();
    return timer;
  }

  async #finishClose(timers: readonly SystemRuntimeTimer[]): Promise<void> {
    try {
      await this.#waitForTimers(timers);
    } finally {
      this.#timers.clear();
      this.#state = "closed";
      this.#closingTimers = undefined;
    }
  }

  #callbackCloseSignal(timer: SystemRuntimeTimer): CallbackCloseSignal {
    const existing = this.#callbackCloseSignals.get(timer);
    if (existing !== undefined) {
      return existing;
    }
    const signal = createCallbackCloseSignal();
    this.#callbackCloseSignals.set(timer, signal);
    return signal;
  }

  async #waitForTimersUnlessReentrant(
    timers: readonly SystemRuntimeTimer[],
  ): Promise<void> {
    const results = await Promise.all(timers.map((timer) => {
      const callbackClose = this.#callbackCloseSignal(timer).declared.then(
        (): undefined => undefined,
      );
      const settled = timer.done.then(
        (): PromiseSettledResult<void> => ({ status: "fulfilled", value: undefined }),
        (reason: unknown): PromiseSettledResult<void> => ({ status: "rejected", reason }),
      );
      return Promise.race([callbackClose, settled]);
    }));
    const failures = results.flatMap((result) =>
      result?.status === "rejected" ? [result.reason] : [],
    );
    if (failures.length > 0) {
      throw new AggregateError(failures, "timer scheduler callbacks failed during close");
    }
  }

  async #waitForTimers(timers: readonly SystemRuntimeTimer[]): Promise<void> {
    const results = await Promise.allSettled(timers.map((timer) => timer.done));
    const failures = results.flatMap((result) =>
      result.status === "rejected" ? [result.reason] : [],
    );
    if (failures.length > 0) {
      throw new AggregateError(failures, "timer scheduler callbacks failed during close");
    }
  }
}
